(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("demosthenes-private-2-e", [{"sp": "HDR", "t": "Λόγοι ἰδιωτικοί ΜΑʹ–ΜΘʹ"}, {"sp": "HDR", "t": "Πρὸς Σπουδίαν ὑπὲρ προικός", "st": "41"}, {"sp": "N", "t": "ἀδελφὰς ἔχομεν, ὦ ἄνδρες δικασταί, γυναῖκας ἐγὼ καὶ Σπουδίας οὑτοσί, Πολυεύκτου θυγατέρας. ἄπαιδος δ’ ἐκείνου τελευτήσαντος ἀρρένων παίδων, ἀναγκάζομαι πρὸς τουτονὶ περὶ τῶν καταλειφθέντων δικάζεσθαι. καὶ εἰ μέν, ὦ ἄνδρες δικασταί, μὴ πᾶσαν σπουδὴν καὶ προθυμίαν ἐποιησάμην βουλόμενος διαλύεσθαι καὶ τοῖς φίλοις ἐπιτρέπειν, ἐμαυτὸν ἂν ᾐτιώμην, εἰ μᾶλλον ᾑρούμην δίκας καὶ πράγματ’ ἔχειν ἢ μίκρ’ ἐλαττωθεὶς ἀνέχεσθαι·", "st": "41.1"}, {"sp": "N", "t": "νῦν δ’ ὅσῳ πραότερον ἐγὼ καὶ φιλανθρωπότερον τούτῳ διελεγόμην, τοσούτῳ μᾶλλόν μου κατεφρόνει. καὶ νῦν κινδυνεύω μὲν οὐδὲν ὁμοίως τούτῳ πρὸς τουτονὶ τὸν ἀγῶν’ ἔχειν, ἀλλ’ οὗτος μὲν ῥᾳδίως φέρει πολλάκις εἰθισμένος ἐνταῦθ’ εἰς ὑμᾶς παριέναι, ἐγὼ δ’ αὐτὸ τοῦτο φοβοῦμαι, μὴ διὰ τὴν ἀπειρίαν οὐ δυνηθῶ δηλῶσαι περὶ τῶν πραγμάτων ὑμῖν· ὅμως δ’, ὦ ἄνδρες δικασταί, προσέχετε τὸν νοῦν.", "st": "41.2"}, {"sp": "N", "t": "Πολύευκτος γὰρ ἦν τις Θριάσιος, ὃν ἴσως οὐδ’ ὑμῶν τινες ἀγνοοῦσιν. οὗτος ὁ Πολύευκτος, ἐπειδὴ οὐκ ἦσαν αὐτῷ παῖδες ἄρρενες, ποιεῖται Λεωκράτη τὸν ἀδελφὸν τῆς ἑαυτοῦ γυναικός. οὐσῶν δ’ αὐτῷ δύο θυγατέρων ἐκ τῆς τοῦ Λεωκράτους ἀδελφῆς, τὴν μὲν πρεσβυτέραν ἐμοὶ δίδωσιν καὶ τετταράκοντα μνᾶς προῖκα, τὴν δὲ νεωτέραν τῷ Λεωκράτει.", "st": "41.3"}, {"sp": "N", "t": "τούτων δ’ οὕτως ἐχόντων, διαφορᾶς γενομένης τῷ Πολυεύκτῳ πρὸς τὸν Λεωκράτη, περὶ ἧς οὐκ οἶδ’ ὅ τι δεῖ λέγειν, ἀφελόμενος ὁ Πολύευκτος τὴν θυγατέρα δίδωσι Σπουδίᾳ τουτῳί. μετὰ δὲ ταῦτ’ ἠγανάκτει ⟨θ’⟩ ὁ Λεωκράτης, καὶ δίκας ἐλάγχανε Πολυεύκτῳ καὶ τουτῳὶ Σπουδίᾳ, καὶ περὶ πάντων ἠναγκάζοντ’ εἰς λόγον καθίστασθαι. καὶ τὸ τελευταῖον διελύθησαν, ἐφ’ ᾧτε κομισάμενον τὸν Λεωκράτην ἅπερ ἦν εἰς τὴν οὐσίαν εἰσενηνεγμένος, μήτε κακόνουν εἶναι τῷ Πολυεύκτῳ, τῶν τε πρὸς ἀλλήλους ἐγκλημάτων ἀπηλλάχθαι πάντων.", "st": "41.4"}, {"sp": "N", "t": "τίνος οὖν ἕνεχ’ ὑμῖν, ὦ ἄνδρες δικασταί, ταῦτ’ εἶπον; ὅτι τὴν προῖκ’ οὐ κομισάμενος ἅπασαν, ἀλλ’ ὑπολειφθεισῶν χιλίων δραχμῶν καὶ ὁμολογηθεισῶν ἀπολαβεῖν ὅταν Πολύευκτος ἀποθάνῃ, ἕως μὲν ὁ Λεωκράτης ἦν κληρονόμος τῶν Πολυεύκτου, πρὸς ἐκεῖνον ἦν μοι τὸ συμβόλαιον· ἐπειδὴ δ’ ὅ τε Λεωκράτης ἐξεκεχωρήκει ὅ τε Πολύευκτος μοχθηρῶς εἶχεν, τηνικαῦτ’, ὦ ἄνδρες δικασταί, τὴν οἰκίαν ταύτην ἀποτιμῶμαι πρὸς τὰς δέκα μνᾶς, ἐξ ἧς διακωλύει με τὰς μισθώσεις κομίζεσθαι Σπουδίας.", "st": "41.5"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ὑμῖν μάρτυρας παρέξομαι τοὺς παραγενομένους ὅτ’ ἠγγύα μοι Πολύευκτος τὴν θυγατέρ’ ἐπὶ τετταράκοντα μναῖς· ἔπειθ’ ὡς ἔλαττον ταῖς χιλίαις ἐκομισάμην· ἔτι δ’ ὡς ἅπαντα τὸν χρόνον ὀφείλειν ὡμολόγει μοι Πολύευκτος, καὶ τὸν Λεωκράτην συνέστησε, καὶ ὡς τελευτῶν διέθεθ’ ὅρους ἐπιστῆσαι χιλίων δραχμῶν ἐμοὶ τῆς προικὸς ἐπὶ τὴν οἰκίαν. καί μοι κάλει τοὺς μάρτυρας.", "st": "41.6"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "41.6"}, {"sp": "N", "t": "ἓν μὲν τοίνυν, ὦ ἄνδρες δικασταί, τοῦτ’ ἔστιν ὧν ἐγκαλῶ Σπουδίᾳ. καὶ περὶ τούτου τί ἂν ἔτι μεῖζον ἢ ἰσχυρότερον ἔχων εἰς ὑμᾶς κατέστην ἢ τὸν νόμον, ὃς οὐκ ἐᾷ διαρρήδην, ὅσα τις ἀπετίμησεν, εἶναι δίκας, οὔτ’ αὐτοῖς οὔτε τοῖς κληρονόμοις; ἀλλ’ ὅμως πρὸς τοῦτο τὸ δίκαιον ἥκει Σπουδίας ἀμφισβητήσων.", "st": "41.7"}, {"sp": "N", "t": "ἕτερον δ’, ὦ ἄνδρες δικασταί, δύο μὲν μνᾶς, ⟨ἃς⟩ ἐμαρτύρησεν Ἀριστογένης ἐγκαλεῖν ἀποθνῄσκοντα Πολύευκτον ὀφειλομένας αὑτῷ παρὰ Σπουδίᾳ καὶ τὸν τόκον (τοῦτο δ’ ἐστὶν οἰκέτου τιμή, ὃν ἐωνημένος οὗτος παρὰ τοῦ Πολυεύκτου, τὴν τιμὴν οὔτ’ ἐκείνῳ διέλυσεν οὔτε νῦν εἰς τὸ κοινὸν ἀνενήνοχεν), ὀκτακοσίας δὲ καὶ χιλίας, περὶ ὧν οὐδ’ ἔγωγ’ οἶδα τί ποθ’ ἕξει δίκαιον λέγειν.", "st": "41.8"}, {"sp": "N", "t": "ἦν μὲν γὰρ τὸ ἀργύριον παρὰ τῆς Πολυεύκτου δεδανεισμένος γυναικός, γράμματα δ’ ἔστιν ἃ κατέλιπεν ἀποθνῄσκουσ’ ἐκείνη, μάρτυρες δ’ οἱ τῆς γυναικὸς ἀδελφοὶ παρόντες ἅπασιν καὶ καθ’ ἕκαστον ἐπερωτῶντες, ἵνα μηδὲν δυσχερὲς ἡμῖν εἴη πρὸς ἀλλήλους. οὔκουν δεινόν, ὦ ἄνδρες δικασταί, καὶ σχέτλιον ἐμὲ μὲν ἁπάντων, ὧν ἢ παρὰ Πολυεύκτου ζῶντος ἦν ἐωνημένος ἢ παρὰ τῆς γυναικὸς εἶχον αὐτοῦ, καὶ τόκον τιθέναι καὶ τὴν τιμὴν ἀποδεδωκέναι, καὶ νῦν ἅπερ ὤφειλον πάντ’ εἰς τὸ κοινὸν φέρειν,", "st": "41.9"}, {"sp": "N", "t": "τοῦτον δὲ μήτε τῶν νόμων τῶν ὑμετέρων φροντίζειν μήθ’ ὧν διέθετο Πολύευκτος μήτε τῶν καταλειφθέντων γραμμάτων μήτε τῶν συνειδότων, ἀλλὰ πρὸς ἅπαντα ταῦθ’ ἥκειν ἀντιδικήσοντα;", "st": "41.10"}, {"sp": "N", "t": "λαβὲ δή μοι πρῶτον μὲν τὸν νόμον, ὃς οὐκ ἐᾷ τῶν ἀποτιμηθέντων ἔτι δίκην εἶναι πρὸς τοὺς ἔχοντας, ἔπειτα τὰ γράμματα τὰ καταλειφθέντα καὶ τὴν μαρτυρίαν τὴν Ἀριστογένους.", "st": "41.10"}, {"sp": "N", "t": "ΝΟΜΟΣ. ΓΡΑΜΜΑΤΑ. ΜΑΡΤΥΡΙΑ.", "st": "41.10"}, {"sp": "N", "t": "βούλομαι τοίνυν, ὦ ἄνδρες δικασταί, καὶ περὶ τῶν ἄλλων ὧν ἐγκαλῶ καθ’ ἕκαστον ὑμᾶς διδάξαι. φιάλην μὲν γὰρ λαβόντες παρὰ τῆς Πολυεύκτου γυναικὸς καὶ θέντες ἐνέχυρα μετὰ χρυσίων, οὐκ ἀνενηνόχασιν κεκομισμένοι ταύτην, ὡς ὑμῖν Δημόφιλος ὁ θέμενος μαρτυρήσει· σκηνὴν δ’ ἣν ἔχουσιν, οὐδέ γε ταύτην λαβόντες ἀναφέρουσιν· ἄλλα δὲ πόσα τοιαῦτα; τὸ δὲ τελευταῖον εἰσενεγκούσης τῆς ἐμῆς γυναικὸς εἰς τὰ Νεμέσεια τῷ πατρὶ μνᾶν ἀργυρίου καὶ προαναλωσάσης, οὐδὲ ταύτης ἀξιοῖ συμβαλέσθαι τὸ μέρος, ἀλλὰ τὰ μὲν ἔχει προλαβών, τῶν δὲ τὰ μέρη κομίζεται, τὰ δ’ οὕτω φανερῶς οὐκ ἀποδίδωσιν. ἵνα τοίνυν μηδὲ ταῦτ’ ᾖ παραλελειμμένα, λαβέ μοι πάντων αὐτῶν τὰς μαρτυρίας.", "st": "41.11"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "41.11"}, {"sp": "N", "t": "ἴσως τοίνυν, ὦ ἄνδρες δικασταί, πρὸς μὲν ταῦτ’ οὐδὲν ἀντερεῖ Σπουδίας (οὐδὲ γὰρ ἕξει, καίπερ δεινὸς ὤν)· αἰτιάσεται δὲ Πολύευκτον καὶ τὴν γυναῖκ’ αὐτοῦ, καὶ φήσει πάντα ταῦθ’ ὑπ’ ἐμοῦ πεισθέντας καταχαρίσασθαι, καὶ νὴ Δί’ ἕτερα πολλὰ καὶ μεγάλα βλάπτεσθαι, καὶ δίκην εἰληχέναι μοι· ταῦτα γὰρ καὶ πρὸς τῷ διαιτητῇ λέγειν ἐπεχείρει.", "st": "41.12"}, {"sp": "N", "t": "ἐγὼ δ’, ὦ ἄνδρες δικασταί, πρῶτον μὲν οὐχ ἡγοῦμαι δικαίαν εἶναι τὴν ἀπολογίαν τὴν τοιαύτην, οὐδὲ προσήκειν, ὅταν τις φανερῶς ἐξελέγχηται, μεταστρέψαντα τὰς αἰτίας ἐγκαλεῖν καὶ διαβάλλειν· ἀλλ’ ἐκείνων μέν, εἴπερ ἀδικεῖται, δῆλον ὅτι δίκην λήψεται, τούτων δὲ δώσει· πῶς γὰρ ἂν ἐγὼ νῦν ταῖς τούτων διαβολαῖς ἀντιδικοίην, ἀφεὶς ὑπὲρ ὧν ὑμεῖς μέλλετε τὴν ψῆφον οἴσειν;", "st": "41.13"}, {"sp": "N", "t": "ἔπειτα θαυμάζω τί δήποτε, εἴπερ ἀληθῆ καὶ δίκαι’ εἶχεν ἐγκαλεῖν, βουλομένων ἡμᾶς τῶν φίλων διαλύειν καὶ πολλῶν λόγων γενομένων οὐχ οἷος ἦν ἐμμένειν οἷς ἐκεῖνοι γνοῖεν. καίτοι τίνες ἂν ἄμεινον καὶ τῶν τούτου καὶ τῶν ἐμῶν ἐγκλημάτων τὰ μηδὲν ὄντ’ ἐξήλεγξαν τῶν παραγεγενημένων ἅπασι τούτοις, τῶν εἰδότων οὐδὲν ἧττον ἡμῶν τὰ γενόμενα, τῶν κοινῶν ἀμφοτέροις καὶ φίλων ὄντων;", "st": "41.14"}, {"sp": "N", "t": "ἀλλὰ δῆλον ὅτι τούτῳ ταῦτ’ οὐκ ἐλυσιτέλει, φανερῶς ὑπ’ αὐτῶν ἐξελεγχομένῳ τοῦτον τὸν τρόπον λαβεῖν διάλυσιν· μὴ γὰρ οἴεσθ’, ὦ ἄνδρες δικασταί, τοὺς εἰδότας ἅπαντα ταῦτα νυνὶ μὲν ὑποκινδύνους αὑτοὺς καθιστάντας ἐμοὶ μαρτυρεῖν, τότε δ’ ⟨ἂν⟩ ὀμόσαντας ἄλλο τι γνῶναι περὶ αὐτῶν. οὐ μὴν ἀλλ’ εἰ καὶ μηδὲν τούτων ὑπῆρχεν ὑμῖν, οὐδ’ ὣς χαλεπόν ἐστιν γνῶναι περὶ αὐτῶν, ὁπότεροι τἀληθῆ λέγουσιν.", "st": "41.15"}, {"sp": "N", "t": "περὶ μὲν γὰρ τῆς οἰκίας, εἰ φησὶν ὑπ’ ἐμοῦ πεισθέντα Πολύευκτον προστάξαι τοὺς ὅρους στῆσαι τῶν χιλιῶν, ἀλλ’ οὐ δήπου καὶ τοὺς μάρτυρας ἔπεισα, ὦ Σπουδία, ψευδῆ μοι μαρτυρεῖν, τοὺς παραγενομένους ὅτ’ ἠγγύα μοι, τοὺς εἰδότας ἔλαττόν με κομισάμενον, τοὺς ἀκούοντας ὁμολογοῦντος ὀφείλειν ἐμοὶ συστήσαντος ἀποδοῦναι, τοὺς τὸ τελευταῖον ταῖς διαθήκαις παραγενομένους· τούτοις γὰρ ἅπασιν οὐκέτι καταχαρίσασθαι ταῦθ’ ὑπῆρχεν, ἀλλὰ κινδυνεύειν τῶν ψευδομαρτυρίων, εἰ μηδὲν τῶν γενομένων μαρτυροῖεν. ἀφῶμεν τοίνυν τοῦτ’ ἤδη.", "st": "41.16"}, {"sp": "N", "t": "πρὸς ἐκεῖνο δὲ τί ἂν λέγοις; ἀκριβῶς γὰρ ὅπως τούτους διδάξεις· εἰ δὲ μή, πάντες ὑμεῖς ἀπαιτεῖτ’ αὐτόν. ὅτε γὰρ Πολύευκτος διετίθετο ταῦτα, παρῆν μὲν ἡ τούτου γυνή, καὶ δῆλον ὅτι τὰς τοῦ πατρὸς διαθήκας ἀνήγγειλεν, ἄλλως τ’ εἰ καὶ μηδὲν ἴσον εἶχεν ἀλλ’ ἐν ἅπασιν ἠλαττοῦτο, παρεκλήθη δ’ αὐτὸς οὗτος, ὥστε μηδὲ τοῦτ’ εἶναι λέγειν, ὡς λάθρᾳ καὶ διακρυψάμενοι τούτους ἐπράττομεν ταῦτα· παρακαλούμενος γὰρ ἔφησεν αὐτὸς μὲν ἀσχολίαν ἄγειν, τὴν δὲ γυναῖκ’ ἐξαρκεῖν τὴν αὑτοῦ παροῦσαν.", "st": "41.17"}, {"sp": "N", "t": "τί ἔτι λοιπόν; ἀπαγγείλαντος Ἀριστογένους αὐτῷ περὶ ἁπάντων τούτων ἀκριβῶς, οὐδ’ ἐνταῦθ’ οὐδένα φαίνεται λόγον ποιησάμενος, ἀλλ’ ἐπιβιόντος μετὰ ταῦτα τοῦ Πολυεύκτου πλέον ἢ πένθ’ ἡμέρας, οὔτ’ ἠγανάκτησεν εἰσελθὼν οὔτ’ ἀντεῖπεν οὐδέν, οὐδ’ ἡ γυνή, παροῦσ’ ἐξ ἀρχῆς ἅπασιν τούτοις. ὥστ’ οὐκέτι Πολύευκτος αὐτὰ πεισθεὶς ἐμοὶ κατεχαρίζετο, ὡς ἔοικεν, ἀλλ’ ὑμεῖς αὐτοί. ταῦτα τοίνυν, ὦ ἄνδρες δικασταί, μεμνημένοι σαφῶς, ἐὰν ἄρα τι περὶ αὐτῶν ἐγχειρῇ νυνὶ διαβάλλειν, ἀντίθετε. πρῶτον δ’ ἵν’ εἰδῆτ’ ἀκριβῶς ὅτι τοῦτον τὸν τρόπον ἔχει, τῶν μαρτύρων ἀκούσατε. λέγε.", "st": "41.18"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "41.18"}, {"sp": "N", "t": "οὐκοῦν, ὦ ἄνδρες δικασταί, τῶν μὲν χιλίων δραχμῶν ὡς δικαίως καὶ προσοφειλομένων ἀπετίμησέ μοι τὴν οἰκίαν ὁ Πολύευκτος, αὐτὸς οὗτός μοι μαρτυρεῖ καὶ ἡ τούτου γυνὴ πρὸς τοῖς ἄλλοις τούτοις τοῖς μεμαρτυρηκόσι, συγχωροῦντες τότε καὶ οὔτε πρὸς τὸν Πολύευκτον ἀντειπόντες ἐπιβιόντα τοσαύτας ἡμέρας, οὔτε πρὸς τὸν Ἀριστογένη, ἐπεὶ τάχιστ’ ἤκουσαν. ἀλλὰ μὴν εἴ γε δικαίως ἀπετιμήθη, μεμνημένοις τοῦ νόμου κατὰ μὲν τοῦθ’ ὑμῖν οὐκ ἔστιν ἀποψηφίσασθαι Σπουδίου.", "st": "41.19"}, {"sp": "N", "t": "σκέψασθε δὲ καὶ περὶ τῶν εἴκοσι μνῶν, ἃς οὐκ ἐπαναφέρει· καὶ γὰρ ἐνταυθοῖ πάλιν αὐτὸς οὗτός μοι μέγιστος ἔσται μάρτυς, οὐ λόγῳ μὰ Δί’ ὥσπερ νῦν ἀντιδικῶν (τουτὶ μὲν γὰρ οὐδὲν τεκμήριόν ἐστιν), ἀλλ’ ἔργῳ περιφανεῖ. τί ποιῶν, ὦ ἄνδρες δικασταί; τούτῳ γὰρ ἤδη προσέχετε τὸν νοῦν, ἵν’ ἐὰν ἄρα τολμᾷ τι καὶ περὶ τῆς μητρὸς τῶν γυναικῶν βλασφημεῖν ἢ περὶ τῶν γραμμάτων, εἰδότας ὑμᾶς μὴ δύνηται λέγων ἐξαπατᾶν.", "st": "41.20"}, {"sp": "N", "t": "ταυτὶ γὰρ τὰ γράμματα κατέλιπεν μὲν ἡ Πολυεύκτου γυνή, καθάπερ εἶπον ὀλίγῳ πρότερον· ὁμολογουμένων δὲ τῶν σημείων καὶ παρὰ τῆς τούτου γυναικὸς καὶ παρὰ τῆς ἐμῆς, ἀμφότεροι παρόντες ἀνοίξαντες ἀντίγραφά τ’ ἐλάβομεν, κἀκεῖνα πάλιν κατασημηνάμενοι παρ’ Ἀριστογένει κατεθέμεθα.", "st": "41.21"}, {"sp": "N", "t": "τοῦτο δή, τοῦτ’, ὦ ἄνδρες δικασταί, μάθετε πρὸς θεῶν. ἐνῆσαν μὲν γὰρ αἱ δύο μναῖ, ἡ τιμὴ τοῦ οἰκέτου, καὶ οὐ μόνον ὁ Πολύευκτος ἀποθνῄσκων ταύτας ἐνεκεκλήκει, ἐνῆσαν δ’ αἱ χίλιαι καὶ ὀκτακόσιαι δραχμαί. ταῦτα δ’ ἀναγνούς, εἰ μὲν αὐτῷ μηδὲν προσῆκεν μηδ’ ἀληθῆ τὰ γεγραμμέν’ ἦν, τί δή ποτ’ οὐκ εὐθὺς ἠγανάκτει περὶ αὐτῶν; τί δὲ συνεσημαίνετο πάλιν τὰ μηδὲν ὑγιὲς ὄντα μηδ’ ἀληθῆ γράμματα; τουτὶ γὰρ οὐδ’ ἂν εἷς δήπου μὴ πᾶσιν ὁμολογῶν τοῖς γεγραμμένοις ποιήσειεν.", "st": "41.22"}, {"sp": "N", "t": "ἀλλὰ μήν, ὦ ἄνδρες δικασταί, τοῦτό γε δεινὸν δήπου, εἰ πρὸς τὰ συγκεχωρημέν’ ὑπ’ αὐτῶν τούτων ἐξέσται νῦν ἀντιλέγειν, καὶ μηδὲν σημεῖον ὑμῖν ἔσται, διότι πάντες ἄνθρωποι πρὸς τὰ μήτ’ ἀληθῆ μήτε δίκαια τῶν ἐγκλημάτων οὐ κατασιωπᾶν, ἀλλὰ παραχρῆμ’ ἀμφισβητεῖν εἰώθαμεν, μὴ ποιήσαντες δὲ ταῦτα, ἂν ὕστερον ἀντιδικῶσιν, πονηροὶ καὶ συκοφάνται δοκοῦσιν εἶναι.", "st": "41.23"}, {"sp": "N", "t": "ταῦτα μὲν τοίνυν Σπουδίας οὐδὲν ἧττον ἐμοῦ γιγνώσκων, ἀλλ’ οἶμαι μὲν καὶ ἀκριβέστερον, ὅσῳ καὶ πυκνότερον ἐνταυθοῖ παρέρχεται, πᾶσιν ἐναντία τοῖς πεπραγμένοις αὑτῷ λέγων οὐκ αἰσχύνεται. καίτοι πολλάκις ὑμεῖς ἓν μόνον σκευώρημα συνιδόντες, τούτῳ κατὰ τῶν ἄλλων τῶν ἐγκαλουμένων ἐχρήσασθε τεκμηρίῳ· τούτῳ δ’ ἅπανθ’ ὑφ’ αὑτοῦ συμβέβηκεν ἐξελέγχεσθαι. καί μοι λαβὲ τὴν μαρτυρίαν ὡς ὡμολογεῖτο τότε τὰ σημεῖα τῶν γραμμάτων ὑπὸ τῆς τούτου γυναικός, καὶ νῦν ὑπὸ Σπουδίου κατασημανθέντα κεῖται.", "st": "41.24"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "41.24"}, {"sp": "N", "t": "τούτων τοίνυν οὕτως σαφῶς ἀποδεδειγμένων, ἡγοῦμαι μὲν οὐδὲν ἔτι δεῖν πλείω λέγειν· ὁπότε γὰρ καὶ νόμους ἔχω παρέχεσθαι καὶ μάρτυρας ἁπάντων τῶν εἰρημένων, καὶ τὸν ἀντίδικον αὐτὸν ὁμολογοῦντά μοι, τί δεῖ μακρῶν ἔτι λόγων; ὅμως δ’ ἂν ἄρα περὶ τῆς προικὸς ἀγανακτῇ καὶ φάσκῃ πλεονεκτεῖσθαι ταῖς χιλίαις δραχμαῖς, ψεύσεται· οὐδὲν γὰρ ἔχων ἔλαττον ἀμφισβητεῖ πρὸς αὐτάς, ἀλλὰ πλέον, ὡς αὐτίχ’ ὑμῖν ἔσται φανερόν.", "st": "41.25"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ εἰ πάντα ταῦθ’ ὡς ἀληθῶς συνέβη, οὐ δήπου δίκαιον ἐμὲ τὴν ὁμολογηθεῖσαν προῖκα μὴ λαβεῖν, εἴπερ ὄφελός τι τῶν νόμων ἐστίν, οὐδέ γε τὸν Πολύευκτον, εἰ τῶν θυγατέρων ἐβούλετο τῇ μὲν ἐλάττω, τῇ δὲ πλείω προῖκ’ ἐπιδοῦναι, διακωλυθῆναι νῦν· σοὶ γὰρ αὐτῷ μὴ λαμβάνειν ἐξῆν, ὦ Σπουδία, μὴ προστιθεμένων ὥσπερ ἐμοὶ τῶν χιλιῶν. ἀλλ’ οὐδὲν ἔλαττον εἶχες, ὡς ἐγὼ διδάξω. πρῶτον δ’ ἐφ’ οἷς ἐξέδοτο τούτῳ, λαβέ μοι τὴν μαρτυρίαν.", "st": "41.26"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "41.26"}, {"sp": "N", "t": "πῶς οὖν οὐδὲν ἔλαττον ἔχει, φήσει τις, εἰ τούτῳ μὲν ἐν ταῖς τετταράκοντα μναῖς ἐνετιμᾶτο τὰ χρυσία καὶ τὰ ἱμάτια τῶν χιλιῶν, ἐμοὶ δ’ αἱ δέκα μναῖ χωρὶς προσαπεδίδοντο; τοῦτο δὴ καὶ μέλλω λέγειν. ὁ μὲν γὰρ Σπουδίας, ὦ ἄνδρες δικασταί, παρὰ τοῦ Λεωκράτους ἔχουσαν τὰ χρυσία καὶ τὰ ἱμάτια τὴν γυναῖκ’ ἔλαβεν, ὧν ὁ Πολύευκτος προσαπέτεισεν τῷ Λεωκράτει πλεῖν ἢ χιλίας· ἐγὼ δ’, ἅπερ ἔπεμψέ μοι χωρὶς τῆς προικός, ὅσ’ ἔχω μόνον, πρὸς τὰ τούτῳ δοθέντ’ ἐὰν ἀντιθῇ τις, εὑρήσει παραπλήσια, χωρὶς τῶν εἰς τὰς χιλίας ἀποτιμηθέντων.", "st": "41.27"}, {"sp": "N", "t": "ὥστ’ εἰκότως ἐν ταῖς τετταράκοντα μναῖς ἐνετιμᾶτο ταῦτα, ἅπερ ἀπετετείκει τῷ Λεωκράτει καὶ πλείω τῶν ἐμοὶ δοθέντων ἦν. καί μοι λαβὲ πρῶτον μὲν τὴν ἀπογραφὴν ταύτην καὶ λέγ’ αὐτοῖς ἅπερ ἑκάτερος ἡμῶν ἔχει, μετὰ δὲ ταῦτα τὴν τῶν διαιτητῶν μαρτυρίαν, ἵν’ ἴδωσιν ὅτι καὶ πολλῷ πλείω χρήματ’ ἔχει, καὶ περὶ τούτων ὁ Λεωκράτης ἐνεκάλει, καὶ κατὰ ταῦτ’ ἔγνωσαν οἱ διαιτηταί. λέγε.", "st": "41.28"}, {"sp": "N", "t": "ΑΠΟΓΡΑΦΗ. ΜΑΡΤΥΡΙΑ.", "st": "41.28"}, {"sp": "N", "t": "ἆρ’ οὖν οὐ φανερῶς οὗτος μὲν ἔχει τετταράκοντα μνᾶς πάλαι τὴν προῖκα, ἐγὼ δὲ τὰς μὲν τριάκοντα καθάπερ οὗτος, τὰς δὲ χιλίας οὐ μόνον ὕστερον οὐκ ἐκομισάμην, ἀλλὰ καὶ νυνὶ κινδυνεύω περὶ αὐτῶν ὡς ἀδίκως ἔχων; διὰ ταῦτα μέντοι Σπουδίας, ὦ ἄνδρες δικασταί, τοῖς φίλοις οὐκ ἐβούλετ’ ἐπιτρέψας ἀπαλλαγῆναι τῶν πρὸς ἔμ’ ἐγκλημάτων, ὅτι συνέβαινεν αὐτῷ πάντα ταῦτ’ ἐξελέγχεσθαι· πᾶσιν γὰρ τούτοις παραγεγενημένοι καὶ σαφῶς εἰδότες οὐκ ἐπέτρεπον αὐτῷ λέγειν ὅ τι τύχοι· παρ’ ὑμῖν δ’ οἴεται ψευδόμενος ἐμοῦ τἀληθῆ λέγοντος περιγενήσεσθαι.", "st": "41.29"}, {"sp": "N", "t": "καίτοι περὶ ὧν ἐγκαλῶ, πάνθ’ ὑμῖν ἀπέδειξα σαφῶς, ὡς οἷός τ’ ἦν αὐτός. τοὺς δ’ εἰδότας οὗτος ἔφευγεν, οὐχ ἡγούμενος εἶναι παραλογίσασθαι. μὴ τοίνυν, ὦ ἄνδρες δικασταί, μηδ’ ὑμεῖς ἐπιτρέπετ’ αὐτῷ ψεύδεσθαι καὶ διαβάλλειν, μεμνημένοι τῶν εἰρημένων· ἴστε γὰρ πάνθ’ ὡς ἐγένετο, πλὴν εἴ τι παρέλιπον ἐγὼ πρὸς ὀλίγον ὕδωρ ἀναγκαζόμενος λέγειν.", "st": "41.30"}, {"sp": "HDR", "t": "Πρὸς Φαίνιππον περὶ ἀντιδόσεως", "st": "42"}, {"sp": "N", "t": "πολλὰ κἀγαθὰ γένοιτο, ὦ ἄνδρες δικασταί, πρῶτον μὲν ὑμῖν ἅπασιν, ἔπειτα δὲ καὶ Σόλωνι τῷ νομοθετήσαντι τὸν περὶ τῶν ἀντιδόσεων νόμον. εἰ μὴ γὰρ οὗτος ἡμῖν σαφῶς διώρισεν, τί πρῶτον δεῖ ποιεῖν τοὺς ἀντιδεδωκότας καὶ τί δεύτερον καὶ τἄλλα δ’ ἐφεξῆς, οὐκ οἶδ’ ὅποι προῆλθεν ἂν ἡ τουτουὶ Φαινίππου τόλμα, ὅπου γε καὶ νῦν ἅπαντα ταῦτα προλέγοντος ἡμῖν τοῦ νόμου, ὅμως οὐδὲν φροντίσας τῶν ἐν αὐτῷ γεγραμμένων δικαίων, ἀντὶ μὲν τοῦ τριῶν ἡμερῶν ἀφ’ ἧς ὤμοσε τὴν ἀπόφασιν δοῦναί μοι τῆς οὐσίας τῆς αὑτοῦ κατὰ τὸν νόμον, ἢ εἰ μὴ τότ’ ἐβούλετο, τῇ γ’ ἕκτῃ ⟨φθίνοντος⟩ δοῦναι τοῦ βοηδρομιῶνος μηνός, ἣν δεηθείς μου ἔθετο καὶ ἐν ᾗ ὡμολόγησε δώσειν τὴν ἀπόφασιν, οὐδέτερα τούτων ἐποίησεν,", "st": "42.1"}, {"sp": "N", "t": "ἀλλὰ καταφρονήσας ἀμφοτέρων, καὶ ἡμῶν καὶ τοῦ νόμου, δευτέρῳ μηνὶ ἔδωκεν, δυοῖν ἢ τρισὶν ἡμέραις πρότερον τῆς εἰς τὸ δικαστήριον εἰσόδου, τὸν δ’ ἄλλον ἅπαντ’ ἐκποδὼν ἦν χρόνον· ἀντὶ δὲ τοῦ τὰ σημεῖα ἐᾶν τῶν οἰκημάτων ἃ παρεσημηνάμην, ἐλθὼν εἰς ἀγρὸν ἀνέῳξε καὶ τὰς κριθὰς ἐξεφόρησεν καὶ τἄλλα, ὥσπερ ἐξουσίαν δεδωκότος αὐτῷ τοῦ νόμου ποιεῖν ὅ τι ἂν βούληται καὶ μὴ ὡς δίκαιόν ἐστιν.", "st": "42.2"}, {"sp": "N", "t": "ἐγὼ δ’, ὦ ἄνδρες δικασταί, ἥδιστα μὲν ἂν ἐμαυτὸν εἶδον εὐτυχοῦντα ὥσπερ πρότερον τῇ οὐσίᾳ καὶ μένοντα ἐν τοῖς τριακοσίοις· ἐπειδὴ δὲ τὰ μὲν τῆς κοινῆς ἀτυχίας μετασχὼν τοῖς ἄλλοις τοῖς ἐργαζομένοις ἐν τοῖς ἔργοις, τὰ δ’ ἰδίᾳ μεγάλαις περιπεπτωκὼς ζημίαις ἀπολώλεκα τὴν οὐσίαν, καὶ τὸ τελευταῖον νυνί με δεῖ τῇ πόλει τρία τάλαντα καταθεῖναι, τάλαντον κατὰ τὴν μερίδα (μετέσχον γάρ, ὡς μή ποτ’ ὤφελον, κἀγὼ τοῦ δημευθέντος μετάλλου), ἀναγκαῖόν ἐστιν εἰς τὴν ἐμὴν τάξιν πειρᾶσθαι καθιστάναι τὸν οὐ μόνον ἐμοῦ νῦν ὄντα πλουσιώτερον, ἀλλὰ καὶ πρότερον, καὶ οὐδεπώποτ’ οὐδὲν λελῃτουργηκότα ὑμῖν οὐδ’ εἰσενηνοχότα τῇ πόλει.", "st": "42.3"}, {"sp": "N", "t": "δέομαι οὖν ὑμῶν ἁπάντων, ὦ ἄνδρες δικασταί, ἐὰν ἐπιδεικνύω Φαίνιππον τουτονὶ καὶ παραβεβηκότα τὰ ἐν τοῖς νόμοις δίκαια καὶ πλουσιώτερον ὄντα ἐμαυτοῦ, βοηθῆσαί μοι καὶ τοῦτον εἰς τοὺς τριακοσίους ἀντ’ ἐμοῦ καταστῆσαι· διὰ τοῦτο γὰρ οἱ νόμοι καθ’ ἕκαστον ἔτος ποιοῦσιν τὰς ἀντιδόσεις, ὅτι τὸ διευτυχεῖν συνεχῶς τῇ οὐσίᾳ οὐ πολλοῖς τῶν πολιτῶν διαμένειν εἴθισται. ἐξ ἀρχῆς δ’ ὑμῖν τὰ γενόμενα περὶ τὴν ἀντίδοσιν διηγήσομαι.", "st": "42.4"}, {"sp": "N", "t": "τοῦ γὰρ μεταγειτνιῶνος, ὦ ἄνδρες δικασταί, τῇ δευτέρᾳ ἱσταμένου ἐποίουν οἱ στρατηγοὶ τοῖς τριακοσίοις τὰς ἀντιδόσεις. ἐν ταύταις ἐκάλεσα κατὰ τὸν νόμον Φαίνιππον τουτονί. καλέσας δὲ καὶ παραλαβὼν τῶν οἰκείων τινὰς καὶ φίλων, ἐπορευόμην Κύθηρόνδε εἰς τὴν ἐσχατιὰν αὐτοῦ. καὶ πρῶτον μὲν περιαγαγὼν τὴν ἐσχατιὰν πλέον ἢ σταδίων οὖσαν τετταράκοντα κύκλῳ, ἔδειξα καὶ διεμαρτυράμην ἐναντίον Φαινίππου, ὅτι οὐδεὶς ὅρος ἔπεστιν ἐπὶ τῇ ἐσχατιᾷ· εἰ δέ φησιν, εἰπεῖν ἐκέλευον αὐτὸν ἤδη καὶ δεῖξαι, ὅπως μὴ ὕστερον ἐνταῦθα χρέως γενόμενον [ἐπὶ τῷ χωρίῳ] ἀναφανήσεται.", "st": "42.5"}, {"sp": "N", "t": "ἔπειτα παρεσημηνάμην τὰ οἰκήματα, καὶ τοῦτον ἐκέλευον εἰς τἀμὰ βαδίζειν. μετὰ δὲ ταῦτα ἠρόμην ὅπου ὁ σῖτος εἴη ὁ ἀπηλοημένος· ἦσαν γὰρ νὴ τοὺς θεοὺς καὶ τὰς θεάς, ἄνδρες δικασταί, δύο ἅλως αὐτόθι, μικροῦ πλέθρου ἑκατέρα. ὁ δὲ ἀπεκρίνατό μοι, ὅτι ὁ μὲν πεπραμένος εἴη τοῦ σίτου, ὁ δ’ ἔνδον ἀποκείμενος.", "st": "42.6"}, {"sp": "N", "t": "τέλος δέ, ἵνα μὴ μακρολογῶ, καταστήσας φυλάττειν ἔνδον τινάς, καὶ νὴ Δί’ ἀπειπὼν καὶ κωλύσας τοὺς ὀνηλάτας μὴ ἐξάγειν τὴν ὕλην ἐκ τῆς ἐσχατιᾶς (πρὸς γὰρ τῇ ἄλλῃ οὐσίᾳ τῇ Φαινίππου, ὦ ἄνδρες δικασταί, καὶ αὕτη πρόσοδος μεγάλη ἐστὶν αὐτῷ· ἓξ ὄνοι δι’ ἐνιαυτοῦ ὑλαγωγοῦσιν, καὶ λαμβάνει οὗτος πλέον ἢ δώδεκα δραχμὰς τῆς ἡμέρας) τούτοις ἀπειπών, ὥσπερ λέγω, τῆς ὕλης μὴ ἅπτεσθαι, καὶ ἐπαγγείλας ἐπὶ τὰ ἱερὰ Φαινίππῳ κατὰ τὸν νόμον ἀπαντᾶν, ᾠχόμην ἀπιὼν εἰς ἄστυ.", "st": "42.7"}, {"sp": "N", "t": "πρῶτον μὲν οὖν τῶν εἰρημένων τὰς μαρτυρίας ὑμῖν παρέξομαι, ἔπειτα καὶ περὶ τῶν ἄλλων ἀκούσεσθε πάσας τὰς ἀληθείας· τουτονὶ γάρ, ὦ ἄνδρες δικασταί, Φαίνιππον εὑρήσετ’ εὐθὺς ἀπὸ τῆς πρώτης ἡμέρας ἀρξάμενον τοῦ μηδὲν δίκαιον ποιεῖν. παρεσημηνάμην τὰ οἰκήματα, τοῦ νόμου μοι δεδωκότος· οὗτος ἀνέῳξεν. καὶ τὸ μὲν ἀφελεῖν τὸ σημεῖον ὁμολογεῖ, τὸ δ’ ἀνοῖξαι τὴν θύραν οὐχ ὁμολογεῖ, ὥσπερ ἄλλου τινὸς ἕνεκα τὰ σημεῖα ἀφαιροῦντας ἢ τοῦ τὰς θύρας ἀνοῖξαι.", "st": "42.8"}, {"sp": "N", "t": "ἔπειτ’ ἀπεῖπον τὴν ὕλην μὴ ἐξάγειν· ἐξῆγεν οὗτος ἁπάσας τὰς ἡμέρας, πλὴν ἐκείνης ἐν ᾗ ἐγὼ ἀπεῖπον. χρέως οὐδ’ ὁτιοῦν ὠφείλετ’ ἐπὶ τῇ ἐσχατιᾷ· νῦν οὗτος ἀποφαίνει πολλά. ἁπλῶς ποιεῖ ὅ τι ἂν βούληται, οὐχ ὅ τι οἱ νόμοι κελεύουσιν. λέγε τὰς μαρτυρίας, πρῶτον μὲν τὰς περὶ τοῦ μετάλλου, ἔπειτα καὶ τὰς ἄλλας.", "st": "42.9"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "42.9"}, {"sp": "N", "t": "ἃ μὲν τοίνυν εὐθὺς τῇ πρώτῃ ἡμέρᾳ μετὰ τὰς ἀντιδόσεις ἤρξατό με Φαίνιππος ἀδικεῖν, ἀκηκόατε, ὦ ἄνδρες Ἀθηναῖοι, καὶ ἐμοῦ καὶ τῶν μαρτύρων. τὰ δὲ μετὰ ταῦτα γεγενημένα οὐκέτι εἰς ἐμὲ μόνον αὐτῷ ἡμάρτηται, ἀλλὰ καὶ εἰς τοὺς νόμους, ὑπὲρ ὧν ὑμῖν ἅπασι σπουδαστέον ἐστίν.", "st": "42.10"}, {"sp": "N", "t": "ὀμόσας γὰρ τῇ ἑνδεκάτῃ τοῦ βοηδρομιῶνος μηνὸς ἀποφανεῖν ὀρθῶς καὶ δικαίως τὴν οὐσίαν, καὶ τοῦ νόμου διαρρήδην λέγοντος τριῶν ἡμερῶν ἀφ’ ἧς ἂν ὀμόσῃ διδόναι τὴν ἀπόφασιν, ἐδεῖτό μου προσελθὼν πρόσθε τῶν δικαστηρίων μετὰ Πολυεύκτου τοῦ Κριωέως καὶ ἑτέρων τινῶν, πρῶτον μὲν περὶ διαλύσεως συνελθεῖν αὑτῷ· πάντα γάρ μοι τὰ δίκαια ποιήσειν· ἔπειτα τὴν ἀπόφασιν τῆς οὐσίας ἀναβαλέσθαι μὴ πολλὰς ἡμέρας· οὐ γὰρ ἀγνοεῖν μου τὰ πράγματα.", "st": "42.11"}, {"sp": "N", "t": "ἡγησάμενος δ’ ἐγὼ καὶ μετρίου καὶ ἀπράγμονος εἶναι πολίτου μὴ εὐθὺς ἐπὶ κεφαλὴν εἰς τὸ δικαστήριον βαδίζειν, ἐπείσθην (τί γὰρ δεῖ μακρολογεῖν;) τὴν μὲν σύνοδον τὴν περὶ τῶν διαλύσεων τῇ ὀγδόῃ φθίνοντος τοῦ βοηδρομιῶνος μηνὸς ὁμολογῆσαι ποιήσασθαι, τὴν δὲ ἀπόφασιν τῆς οὐσίας τῇ ἕκτῃ φθίνοντος. τυχὼν δὲ τούτων ἀμφοτέρων παρ’ ἐμοῦ Φαίνιππος οὐδ’ εἰς ἑτέραν τῶν ἡμερῶν ἀπήντησεν· ἀλλ’ ἀνθ’ ἑνὸς δύο νόμους ἥκει πρὸς ὑμᾶς παραβεβηκώς, ἕνα μὲν τὸν κελεύοντα τριῶν ἡμερῶν ἀφ’ ἧς ἂν ὀμόσῃ τὴν οὐσίαν ἀποφαίνειν, ἕτερον δὲ τὸν κελεύοντα κυρίας εἶναι τὰς πρὸς ἀλλήλους ὁμολογίας, ἃς ἂν ἐναντίον ποιήσωνται μαρτύρων.", "st": "42.12"}, {"sp": "N", "t": "καίτοι, ὦ ἄνδρες δικασταί, τίς οὐκ οἶδεν ὑμῶν, ὅτι ὁμοίως ἥ τε ἐν τῷ νόμῳ γεγραμμένη κυρία ἐστὶν ἡμέρα καὶ ἡ ὑπὸ τῶν ἀντιδίκων συγχωρηθεῖσα; πολλάκις γὰρ ἔν τε τοῖς νόμοις γεγραμμένης τριακοστῆς ἡμέρας ἑτέραν ἡμῖν αὐτοῖς συγχωρήσαντες ἐθέμεθα, παρά τε ταῖς ἀρχαῖς ἁπάσαις καὶ δίκας καὶ κρίσεις ἀναβάλλονται τοῖς ἀντιδίκοις οἱ ἄρχοντες συγχωρησάντων ἐκείνων ἀλλήλοις· ὧν εἴ τις ἄκυρον ἡγήσαιτο δεῖν εἶναι τὴν πρὸς ἀλλήλους ὁμολογίαν, μισήσαιτ’ ἂν αὐτὸν ὡς ὑπερβάλλοντα συκοφαντίᾳ.", "st": "42.13"}, {"sp": "N", "t": "Φαίνιππος τοίνυν, ὥσπερ τοῦ νόμου προστάττοντος μηδὲν ποιεῖν ὧν ἂν ὁμολογήσῃ τις, ἀπ’ ἐκείνης τῆς ἡμέρας, ἀφ’ ἧς ὡμολόγησεν ἐπί τε τὰς διαλύσεις ἀπαντήσεσθαι καὶ τὴν ἀπόφασίν μοι τὴν αὑτοῦ δώσειν καὶ τὴν παρ’ ἐμοῦ λήψεσθαι, οὐδεπώποτ’ ἀπήντησεν· ἀλλ’ ἐγὼ μὲν ἐπειδὴ τοῦτον ἑώρων οὐ προσέχοντά μοι τὸν νοῦν οὐδὲ τοῖς νόμοις, εἰς τὸ στρατήγιον ἔδωκα τὴν ἀπόφασιν, οὗτος δέ, ὅπερ καὶ μικρῷ πρότερον εἶπον, πρῴην ἔδωκέ μοι βιβλίον, οὐδὲν ἄλλο βουλόμενος ἢ δοκεῖν μὲν δεδωκέναι τὴν ἀπόφασιν, μὴ ἔχειν δέ με τοῖς ἐν αὐτῷ γεγραμμένοις ὅ τι χρήσομαι.", "st": "42.14"}, {"sp": "N", "t": "χρὴ δ’, ὦ ἄνδρες δικασταί, μὴ τοῖς ἰσχυροτέραν νομίζουσι τῶν νόμων τὴν αὑτῶν βδελυρίαν εἶναι, πλέον τούτοις τοῦ δικαίου νέμειν (εἰ δὲ μή, πολλοὺς ποιήσετε τοὺς καταγελῶντας τῶν ἐν τοῖς νόμοις δικαίων γεγραμμένων), ἀλλ’ ἐκείνοις βοηθεῖν, οἵτινες ἂν τὴν τῶν νόμων φωνὴν ὑμετέραν εἶναι νομίζωσι, καὶ τὴν ἡμέραν ταύτην, τὴν εἰς τὸ δικαστήριον, ὑπὲρ τῶν ἠδικημένων εἶναι [νομίζωσιν], μὴ τῶν ἠδικηκότων.", "st": "42.15"}, {"sp": "N", "t": "λέγε τῶν ἀρτίως εἰρημένων τὰς μαρτυρίας καὶ τοὺς νόμους.", "st": "42.16"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ. ΝΟΜΟΙ.", "st": "42.16"}, {"sp": "N", "t": "τοιαῦτα τοίνυν, ὦ ἄνδρες δικασταί, πεπονθὼς ἐγὼ ὑπὸ Φαινίππου ἀπεγραψάμην πρὸς τοὺς στρατηγοὺς ταύτην τὴν [ἀπο]γραφήν. λέγε.", "st": "42.16"}, {"sp": "N", "t": "[ΑΠΟ]ΓΡΑΦΗ.", "st": "42.16"}, {"sp": "N", "t": "πῶς οὖν ἄλλως πρὸς τῶν θεῶν καὶ δαιμόνων, ὦ ἄνδρες δικασταί, ἐπιδεικνύειν ὑμῖν δεῖ Φαίνιππον ἔνοχον ὄντα τοῖς ἀνεγνωσμένοις ἢ ὅνπερ τρόπον ἐγὼ νῦν ἐπιδεικνύω; ἀλλ’ ὅμως ἐμὲ ἀντεγράψατο Φαίνιππος μὴ δικαίως ἀποφαίνειν τὴν οὐσίαν· οὕτω τὸ πρὸς ὑμᾶς ψεύδεσθαι τοῖς τοιούτοις ῥᾴδιόν ἐστιν· καὶ κατηγορεῖ τοῦ ὅρκου ὃν ὤμοσα πρὸ τῆς ἀποφάσεως, λέγων ὅτι πλὴν τῶν ἐν τοῖς ἔργοις ὑπεσχόμην ἀποφαίνειν τὴν ἄλλην οὐσίαν, ὥσπερ τὸ κατὰ τοὺς νόμους ὀμνύειν, τοῦτ’ ἄξιον κατηγορίας ὄν.", "st": "42.17"}, {"sp": "N", "t": "ὑμεῖς δ’ ἴστε, ὦ ἄνδρες δικασταί (ὑμεῖς γὰρ ἔθεσθε) τὸν νόμον, ὃς διαρρήδην οὕτω λέγει, “τοὺς δ’ ἀντιδιδόντας ἀλλήλοις, ὅταν ὀμόσαντες ἀποφαίνωσι τὴν οὐσίαν, προσομνύειν τόνδε τὸν ὅρκον ‘ἀποφαίνω τὴν οὐσίαν τὴν ἐμαυτοῦ ὀρθῶς καὶ δικαίως, πλὴν τῶν ἐν τοῖς ἔργοις τοῖς ἀργυρείοις, ὅσα οἱ νόμοι ἀτελῆ πεποιήκασι’.”", "st": "42.18"}, {"sp": "N", "t": "μᾶλλον δὲ λέγε τὸν νόμον αὐτόν. μικρὸν μὲν οὖν ἱκετεύω ἐπίσχες. ἐγὼ γὰρ καὶ πρότερον προὐκαλεσάμην Φαίνιππον, καὶ νῦν, ὦ ἄνδρες δικασταί, δίδωμι αὐτῷ δωρεὰν καὶ ἀφίσταμαι μετὰ τῆς ἄλλης οὐσίας καὶ τῶν ἐν τοῖς ἔργοις, ἐάν μοι τὴν ἐσχατιὰν μόνην ἐλευθέραν παραδῷ, ὥσπερ ἦν ὅτ’ ἐγὼ τὸ πρῶτον ἦλθον εἰς αὐτὴν μετὰ μαρτύρων, καὶ ἐάν, ὃν ἐξῆχεν ἐκ τῶν οἰκημάτων σῖτον καὶ οἶνον καὶ τἄλλα, ἀφελὼν ἀπὸ τῶν θυρῶν τὰ σημεῖα, ταῦτα πάλιν εἰς ταὐτὸ καταστήσῃ.", "st": "42.19"}, {"sp": "N", "t": "καὶ τί λέγεις ἔτι καὶ βοᾷς; πόλλ’ ἐκ τῶν ἔργων τῶν ἀργυρείων ἐγώ, Φαίνιππε, πρότερον αὐτὸς τῷ ἐμαυτοῦ σώματι πονῶν καὶ ἐργαζόμενος συνελεξάμην· ὁμολογῶ. νυνὶ δὲ πλὴν ὀλίγων ἅπαντ’ ἀπολώλεκα. σὺ δ’ ἐκ τῆς ἐσχατιᾶς νῦν πωλῶν τὰς κριθὰς ὀκτωκαιδεκαδράχμους καὶ τὸν οἶνον δωδεκάδραχμον πλουτεῖς εἰκότως, ἐπειδὰν ποιῇς σίτου μὲν μεδίμνους πλέον ἢ χιλίους, οἴνου δὲ μετρήτας ὑπὲρ ὀκτακοσίους.", "st": "42.20"}, {"sp": "N", "t": "ἔτ’ οὖν τὴν αὐτὴν ἡμᾶς τάξιν ἔχειν δεῖ, μὴ τῆς αὐτῆς τύχης ἡμῖν παρακολουθούσης νῦν τε καὶ πρότερον; μηδαμῶς· οὐ γὰρ δίκαιον. ἀλλὰ διάδεξαι καὶ σὺ καὶ μετάλαβε μικρὸν χρόνον τῆς τοῦ λῃτουργοῦντος τάξεως, ἐπειδὴ οἱ μὲν ἐν τοῖς ἔργοις ἠτυχήκασιν, ὑμεῖς δ’ οἱ γεωργοῦντες εὐπορεῖτε μᾶλλον ἢ προσῆκεν. ἱκανὸν γὰρ χρόνον δύ’ οὐσίας καρπούμενος διατελεῖς, τὴν μὲν τοῦ φύσει πατρὸς Καλλίππου, τὴν δὲ τοῦ ποιησαμένου σε, Φιλοστράτου τοῦ ῥήτορος, καὶ οὐδὲν πώποτε τουτοισὶ πεποίηκας.", "st": "42.21"}, {"sp": "N", "t": "καίτοι ὁ μὲν ἐμὸς πατὴρ πέντε καὶ τετταράκοντα μνῶν μόνων ἑκατέρῳ, ἐμοὶ καὶ τῷ ἀδελφῷ, τὴν οὐσίαν κατέλιπεν, ἀφ’ ἧς ζῆν οὐ ῥᾴδιόν ἐστιν· οἱ δὲ σοὶ πατέρες τοσούτων ἦσαν κύριοι χρημάτων, ὥσθ’ ἑκατέρου τρίπους ἀνάκειται, νικησάντων αὐτῶν Διονύσια χορηγούντων. καὶ οὐ φθονῶ· δεῖ γὰρ τοὺς εὐπόρους χρησίμους αὑτοὺς παρέχειν τοῖς πολίταις. σὺ τοίνυν δεῖξον χαλκοῦν ἕνα μόνον εἰς τὴν πόλιν ἀνηλωκώς, ὁ τὰς δύο λῃτουργούσας οὐσίας παρειληφώς.", "st": "42.22"}, {"sp": "N", "t": "ἀλλ’ οὐ δείξεις· ἀποκρύπτεσθαι γὰρ καὶ διαδύεσθαι καὶ πάντα ποιεῖν ἐξ ὧν μὴ λῃτουργήσεις τουτοισὶ μεμάθηκας. ἀλλ’ ἐγὼ δείξω πόλλ’ ἀνηλωκώς, ὁ τὴν μικρὰν οὐσίαν παραλαβὼν παρὰ τοῦ πατρός. πρῶτον δέ μοι τὸν νόμον ἐκεῖνον ἀνάγνωθι τὸν οὐκ ἐῶντα τῶν ἐν τοῖς ἔργοις οὐδὲν ἀποφαίνειν καὶ τὴν πρόκλησιν, ἔπειτα τὰς μαρτυρίας ὡς δύ’ οἴκων λῃτουργούντων οὑτοσὶ Φαίνιππος κεκληρονόμηκεν.", "st": "42.23"}, {"sp": "N", "t": "ΝΟΜΟΣ. ΠΡΟΚΛΗΣΙΣ. ΜΑΡΤΥΡΙΑΙ.", "st": "42.23"}, {"sp": "N", "t": "ἓν μόνον ἄν τις ἔχοι δεῖξαι τουτονὶ Φαίνιππον πεφιλοτιμημένον εἰς ὑμᾶς, ἄνδρες δικασταί· ἱπποτρόφος ἀγαθός ἐστιν καὶ φιλότιμος, ἅτε νέος καὶ πλούσιος καὶ ἰσχυρὸς ὤν. τί τούτου μέγα σημεῖον; ἀποδόμενος τὸν πολεμιστήριον ἵππον καταβέβηκεν ἀπὸ τῶν ἵππων, καὶ ἀντ’ ἐκείνου ὄχημ’ αὑτῷ τηλικοῦτος ὢν ἐώνηται, ἵνα μὴ πεζῇ πορεύηται· τοσαύτης οὗτος τρυφῆς ἐστι μεστός. καὶ τοῦτ’ ἀπογέγραφέν μοι, τῶν δὲ κριθῶν καὶ τοῦ οἴνου καὶ τῶν ἄλλων τῶν ἐκ τῆς ἐσχατιᾶς γιγνομένων οὐδὲ τὸ δέκατον μέρος.", "st": "42.24"}, {"sp": "N", "t": "ἄξιον ἀφεῖναι νῦν αὐτόν ἐστιν, ἐπειδὴ χρήσιμος καὶ φιλότιμος καὶ τῇ οὐσίᾳ καὶ τῷ σώματι; πολλοῦ γε καὶ δεῖ. καλῶν γὰρ κἀγαθῶν ἐστι δικαστῶν τοὺς μὲν τῶν πολιτῶν ἐθελοντάς, ὅταν εὐπορῶσι, λῃτουργοῦντας καὶ ἐν τοῖς τριακοσίοις ὄντας ἀναπαύειν, ὅταν τούτου δεόμενοι τυγχάνωσιν, τοὺς δὲ νομίζοντας ἀπολλύειν, ὅταν εἰς τὸ κοινόν τι δαπανήσωσιν, ἄγειν εἰς τοὺς προεισφέροντας καὶ μὴ ἐπιτρέπειν δραπετεύειν. λέγε πρῶτον μὲν τὴν μαρτυρίαν, ἔπειτα τὴν ἀπόφασιν αὐτοῦ.", "st": "42.25"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ. ΑΠΟΦΑΣΙΣ.", "st": "42.25"}, {"sp": "N", "t": "ἔα ταῦτα. καίτοι πολλὰ τῶν ἔνδοθεν ἐκφορήσας, ὦ ἄνδρες δικασταί, Φαίνιππος, ἀνοίξας τὰ παρασεσημασμένα τῶν οἰκημάτων, ὡς ὑμῖν μεμαρτύρηται, καὶ καταλιπὼν ὅσα ἔδοξεν αὐτῷ, δευτέρῳ μηνὶ τὴν ἀπόφασιν ἔδωκέ μοι τῆς οὐσίας. ἀλλ’ ὅμως ἔα ταῦτα. λέγε δ’ ἐντευθενί “ἐπὶ τούτοις τάδε ὀφείλω”.", "st": "42.26"}, {"sp": "N", "t": "ΑΠΟΦΑΣΙΣ.", "st": "42.26"}, {"sp": "N", "t": "ἐπίσχες. αὕτη ἐστίν, ὦ ἄνδρες δικασταί, ἡ Ἀριστονόη τοῦ Φιλοστράτου θυγάτηρ, μήτηρ δὲ τουτουί. ταύτῃ χρέως φησὶν ὀφείλεσθαι Φαίνιππος τὴν προῖκα, ἧς οἱ νόμοι κύριον τοῦτον ποιοῦσιν, ψευδόμενος καὶ οὐ δικαίως χρώμενος τῇ ἀποφάσει. διὰ τί γὰρ ἐγώ, Φαίνιππε, μενούσης μοι τῆς μητρὸς ἐν τῷ οἴκῳ καὶ ζώσης καὶ προῖκα ἐπενεγκαμένης, οὐκ ἀπογράφω τὴν προῖκα χρέως αὐτῇ, οὐδὲ παρακρούομαι τοὺς δικαστάς, ἀλλ’ ἐῶ μετέχειν τῶν ἐμαυτοῦ τὴν μητέρα, ἄν τε τὴν Φαινίππου ἄν τε τὴν ἐμαυτοῦ ἔχω οὐσίαν; ὅτι οἱ νόμοι ταῦτα κελεύουσιν, ὦ βέλτιστε· σὺ δὲ πάντα ποιεῖς παρὰ τοὺς νόμους. λέγ’ ἕτερον.", "st": "42.27"}, {"sp": "N", "t": "ΑΠΟΦΑΣΙΣ.", "st": "42.27"}, {"sp": "N", "t": "ἀκούετε, ὦ ἄνδρες δικασταί· Παμφίλῳ φησὶν καὶ Φειδόλεῳ Ῥαμνουσίοις κοινῇ τάλαντον ἐνοφείλειν καὶ Αἰαντίδῃ Φλυεῖ τετρακισχιλίας καὶ Ἀριστομένει Ἀναγυρασίῳ τέτταρας καὶ δέκα μνᾶς. διὰ τί οὖν, Φαίνιππε, ὅτε μὲν ἐγὼ μάρτυρας ἔχων ἠρώτων σε, εἴ τι ὀφείλεις ἐπὶ τῇ ἐσχατιᾷ, καὶ ἐκέλευον δεῖξαι ὅρον εἴ που ἔπεστι, καὶ διεμαρτυρόμην ὅπως μή μοι ὕστερον κατεσκευασμένοι δανεισταὶ φανήσονται, τότε μὲν οὐδὲν ἀπέφηνας τῶν χρεῶν, ἐπειδὴ δὲ δευτέρῳ μηνὶ τὴν ἀπόφασιν ἔδωκάς μοι, τοῦ νόμου κελεύοντος τριῶν ἡμερῶν, νῦν ἥκουσι δανεισταὶ καὶ ὀφειλήματα πλέον ἢ τριῶν ταλάντων;", "st": "42.28"}, {"sp": "N", "t": "ὅτι, ὦ βέλτιστε, οὐδὲν ἄλλο κατασκευάζεις ἢ ὅσονπερ κοινῇ γέγονέ μοι πρὸς τὴν πόλιν ὄφλημα, τοσοῦτο καὶ σοὶ ἰδίᾳ νῦν εἶναι. ὅτι δ’, ὦ Φαίνιππε, ψεύδει καὶ ἐπιωρκηκὼς ἥκεις πρὸς τούτους, ἤδη φανερῶς ἐλέγξω. λαβέ μοι, γραμματεῦ, τὴν τοῦ Αἰαντίδου καὶ Θεοτέλους μαρτυρίαν, οἷς οὗτος ἀπογέγραφεν ὀφείλονθ’ αὑτὸν τετρακισχιλίας δραχμὰς ψευδόμενος καὶ πάλαι ἀποδεδωκώς, οὐχ ἑκών, ἀλλὰ δίκην ὀφλών. λέγε.", "st": "42.29"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "42.29"}, {"sp": "N", "t": "ἔπειτ’, ἄνδρες δικασταί, τὸν οὕτω καταφανῶς ἐν ἅπασιν ἀδίκως πεποιημένον τὴν ἀπόφασιν, καὶ μήτε τῶν νόμων φροντίσαντα μηδέν, οἳ διωρίκασιν ἐν οἷς δεῖ τὴν ἀπόφασιν ποιεῖσθαι χρόνοις, μήτε τῶν ἰδίων ὁμολογιῶν, ἃς ὁμοίως ὑπολαμβάνομεν ἰσχυράς, χωρὶς δὲ τούτων ἀνεῳχότα τὰ σημεῖα τῶν οἰκημάτων καὶ ἐκπεφορηκότα τὸν σῖτον καὶ τὸν οἶνον ἔνδοθεν, πρὸς δὲ τούτοις τὴν ὕλην τὴν τετμημένην πεπρακότα μετὰ τὴν ἀντίδοσιν, πλέον ἢ τριάκοντα μνῶν οὖσαν ἀξίαν, καὶ τὸ πάντων μέγιστον, χρέα ψευδῆ κατεσκευακότα τῆς ἀντιδόσεως ἕνεκα, τοῦτον δικαίως ψηφιεῖσθε πεποιῆσθαι τὴν ἀπόφασιν; μηδαμῶς, ὦ ἄνδρες δικασταί.", "st": "42.30"}, {"sp": "N", "t": "ποῖ γὰρ τραπέσθαι δεήσει διαμαρτόντα τῆς ὑμετέρας γνώμης, ὅταν οἱ πλούσιοι καὶ μηδὲν ὑμῖν πώποτε χρήσιμοι γεγενημένοι, πολὺν καὶ σῖτον καὶ οἶνον ποιοῦντες καὶ τοῦτον τριπλασίας τιμῆς ἢ πρότερον διατιθέμενοι, πλεονεκτῶσιν παρ’ ὑμῖν; ὃ μηδαμῶς νυνὶ γενέσθω, ἀλλ’ ὥσπερ καὶ κοινῇ πᾶσιν βεβοηθήκατε τοῖς ἐν τοῖς ἔργοις ἐργαζομένοις, οὕτω καὶ ἰδίᾳ βοηθήσατέ μοι νῦν.", "st": "42.31"}, {"sp": "N", "t": "καὶ γὰρ εἰ οἰκέτης ὑμῶν, μὴ πολίτης ἦν, ὁρῶντες ἄν μου τὴν φιλεργίαν καὶ τὴν εἰς ὑμᾶς εὔνοιαν, ἀνεπαύσατ’ ἄν με τῶν ἀναλωμάτων καὶ ἐπὶ τὸν δραπετεύοντα τῶν ἄλλων ἤλθετε. τὸν αὐτὸν τρόπον καὶ νῦν, ἐπειδὰν ἀποτείσω τὰ τρία τάλανθ’ ἃ ὦφλον καὶ ἀναλάβω ἐμαυτόν, πάλιν ἀναπαύσαντες τῶν τεταλαιπωρηκότων ἕτερον ἐπ’ ἔμ’ ἥξετε· νῦν δ’ ἄφετε, ἱκετεύω πάντας ὑμᾶς, ἄνδρες δικασταί, καὶ τὰ δίκαι’ εἰρηκὼς δέομαι βοηθῆσαί μοι καὶ μή με περιελαθέντα περιιδεῖν ὑπὸ τούτων.", "st": "42.32"}, {"sp": "HDR", "t": "Πρὸς Μακάρτατον περὶ Ἁγνίου κλήρου", "st": "43"}, {"sp": "N", "t": "ἐπειδὴ καὶ πρότερον ἀγῶνες ἐγένοντο ἡμῖν, ὦ ἄνδρες δικασταί, πρὸς τοὺς αὐτοὺς τούτους περὶ τοῦ κλήρου τοῦ Ἁγνίου, καὶ οὐδὲν παύονται παρανομοῦντες καὶ βιαζόμενοι ὥστε ἐκ παντὸς τρόπου τὰ μὴ προσήκονθ’ ἑαυτοῖς ἔχειν, ἀνάγκη ἴσως ἐστὶν τὰ πραχθέντα ἐξ ἀρχῆς διηγήσασθαι·", "st": "43.1"}, {"sp": "N", "t": "ὑμεῖς τε γάρ, ὦ ἄνδρες δικασταί, ῥᾷον παρακολουθήσετε ἅπασι τοῖς λεγομένοις, καὶ οὗτοι ἐπιδειχθήσονται οἷοί εἰσιν ἄνθρωποι, καὶ ὅτι πάλαι ἤδη ἀρξάμενοι οὐδὲν παύονται κακοτεχνοῦντες καὶ οἰόμενοι δεῖν διαπράττεσθαι ὅ τι ἂν ἐπέλθῃ τούτοις. δεόμεθα οὖν ὑμῶν, ὦ ἄνδρες δικασταί, εὐνοϊκῶς ἀκροάσασθαι τῶν λεγομένων καὶ παρακολουθεῖν προσέχοντας τὸν νοῦν. πειράσομαι δὲ κἀγὼ διδάσκειν ὡς ἂν οἷός τε ὦ σαφέστατα περὶ τῶν πεπραγμένων.", "st": "43.2"}, {"sp": "N", "t": "τουτουὶ γὰρ τοῦ παιδὸς ἡ μήτηρ, ὦ ἄνδρες δικασταί, γένει οὖσα ἐγγυτάτω Ἁγνίᾳ τῷ ἐξ Οἴου, ἐπεδικάσατο τοῦ κλήρου τοῦ Ἁγνίου κατὰ τοὺς νόμους τοὺς ὑμετέρους· καὶ τῶν τότε ἀμφισβητησάντων αὐτῇ τοῦ κλήρου τουτουί, γένει μὲν ὡς ἐγγυτέρω τις εἴη αὐτῶν τῆς γυναικός, οὐδ’ ἐπεχείρησεν οὐδεὶς ἀντομόσαι (ὡμολογεῖτο γὰρ παρὰ πάντων τῆς γυναικὸς εἶναι ἡ κληρονομία κατὰ τὴν ἀγχιστείαν),", "st": "43.3"}, {"sp": "N", "t": "διαθήκας δὲ ψευδεῖς ἧκον κατασκευάσαντες Γλαῦκός τε ὁ ἐξ Οἴου καὶ Γλαύκων ὁ ἀδελφὸς αὐτοῦ. καὶ Θεόπομπος ὁ τουτουὶ πατὴρ Μακαρτάτου ἐκείνοις συγκατεσκεύαζεν ἅπαντα ταῦτα καὶ ἐμαρτύρει τὰς πλείστας μαρτυρίας. αἱ δὲ διαθῆκαι, ἃς τότε παρέσχοντο, ἐξηλέγχθησαν ψευδεῖς οὖσαι· καὶ οὐ μόνον ἡττήθησαν, ἀλλὰ καὶ πονηρότατοι δόξαντες εἶναι ἀπηλλάττοντο ἀπὸ τοῦ δικαστηρίου.", "st": "43.4"}, {"sp": "N", "t": "καὶ ἐπιδημῶν τότε Θεόπομπος ὁ τουτουὶ πατὴρ Μακαρτάτου, καὶ τοῦ κήρυκος κηρύττοντος, εἴ τις ἀμφισβητεῖν ἢ παρακαταβάλλειν βούλεται τοῦ κλήρου τοῦ Ἁγνίου ἢ κατὰ γένος ἢ κατὰ διαθήκας, οὐκ ἐτόλμησεν παρακαταβαλεῖν, ἀλλ’ αὐτὸς ἑαυτῷ ἐδίκασεν ὅτι οὐδαμόθεν αὐτῷ προσῆκεν οὐδὲν τοῦ κλήρου τοῦ Ἁγνίου.", "st": "43.5"}, {"sp": "N", "t": "ἐχούσης δὲ τῆς μητρὸς τοῦ παιδὸς τουτουὶ τὸν κλῆρον, ἐπειδὴ ἐνίκησεν ἐν τῷ δικαστηρίῳ ἅπαντας τοὺς ἀμφισβητήσαντας ἑαυτῇ, οὕτως εἰσὶν μιαροὶ οὗτοι, καὶ οὐκ οἴονται δεῖν οὔτε τοῖς νόμοις τοῖς ὑμετέροις πείθεσθαι οὔτε τοῖς γνωσθεῖσιν ἐν τῷ δικαστηρίῳ, ἀλλὰ πάντα τρόπον ἐπιχειροῦντες ἀφελέσθαι πάλιν τὴν γυναῖκα τὸν κλῆρον ὃν ὑμεῖς αὐτῇ ἐψηφίσασθε,", "st": "43.6"}, {"sp": "N", "t": "συνομόσαντες καὶ συνθήκας γράψαντες πρὸς ἀλλήλους καὶ καταθέμενοι παρὰ Μηδείῳ Ἁγνουσίῳ, Θεόπομπος ὁ τουτουὶ πατὴρ Μακαρτάτου καὶ Γλαύκων καὶ Γλαῦκος ὁ ἡττηθεὶς τὸ πρότερον, καὶ ἕτερόν τινα τῶν ἐπιτηδείων τέταρτον προσλαβόντες (Εὐπόλεμος ἦν αὐτῷ ὄνομα), οὗτοι ἅπαντες κοινῇ ἐπιβουλεύσαντες προσεκαλέσαντο τὴν γυναῖκα πρὸς τὸν ἄρχοντα εἰς διαδικασίαν τοῦ κλήρου τοῦ Ἁγνίου, φάσκοντες τὸν νόμον κελεύειν παρὰ τοῦ ἐπιδεδικασμένου καὶ ἔχοντος τὸν κλῆρον προσκαλεῖσθαι, ἐάν τις βούληται ἀμφισβητεῖν.", "st": "43.7"}, {"sp": "N", "t": "καὶ ἐπειδὴ ἦγεν ὁ ἄρχων εἰς τὸ δικαστήριον καὶ ἔδει ἀγωνίζεσθαι, τά τε ἄλλα ἦν αὐτοῖς ἅπαντα κατεσκευασμένα εἰς τὸν ἀγῶνα, καὶ τὸ ὕδωρ, πρὸς ὃ ἔδει ἀγωνίζεσθαι, τετραπλάσιον ἡμῶν ἔλαβον. ἐξ ἀνάγκης γὰρ ἦν, ὦ ἄνδρες δικασταί, τῷ ἄρχοντι ἀμφορέα ἑκάστῳ ἐγχέαι τῶν ἀμφισβητούντων, καὶ τρεῖς χοᾶς τῷ ὑστέρῳ λόγῳ.", "st": "43.8"}, {"sp": "N", "t": "ὥστε συνέβαινεν ἐμοὶ τῷ ὑπὲρ τῆς γυναικὸς ἀγωνιζομένῳ, μὴ ὅτι περὶ τοῦ γένους καὶ τῶν ἄλλων ὧν μοι προσῆκεν διηγήσασθαι τοῖς δικασταῖς ὡς ἐγὼ ἐβουλόμην, ἀλλ’ οὐδ’ ἀπολογήσασθαί μοι ἐξεγένετο οὐδὲ ⟨πρὸς⟩ πολλοστὸν μέρος ὧν κατεψεύδοντο ἡμῶν· πέμπτον γὰρ μέρος εἶχον τοῦ ὕδατος. καὶ τὸ σόφισμα ἦν τοῦτο, αὐτοὺς μὲν ἑαυτοῖς συναγωνίζεσθαι καὶ ὁμολογεῖν ἅπαντα, περὶ ἡμῶν δὲ λέγειν τὰ οὐδεπώποτε γενόμενα.", "st": "43.9"}, {"sp": "N", "t": "καὶ τοῦτον τὸν τρόπον ἐπιβουλευσάντων καὶ συναγωνιζομένων ἀλλήλοις ἐφ’ ἡμᾶς, καδίσκων τεττάρων τεθέντων κατὰ τὸν νόμον, εἰκότως οἶμαι οἱ δικασταὶ ἐξηπατήθησαν καὶ ἐστασίασαν ἀλλήλοις καὶ παρακρουσθέντες ὑπὸ τῆς παρασκευῆς ἐψηφίζοντο ὅ τι ἔτυχεν ἕκαστος. καὶ αἱ ψῆφοι ὀλίγαις πάνυ ἐγένοντο πλείους, ἢ τρισὶν ἢ τέτταρσιν, ἐν τῷ Θεοπόμπου καδίσκῳ ἢ ἐν τῷ τῆς γυναικός.", "st": "43.10"}, {"sp": "N", "t": "καὶ τότε μὲν ταῦτα, ὦ ἄνδρες δικασταί, ἦν τὰ πραχθέντα. ἐπειδὴ δ’ οὑτοσὶ ὁ παῖς ἐγένετο καὶ ἐδόκει καιρὸς εἶναι, οὐκ ὀργισθεὶς ἐγὼ τοῖς γενομένοις, ἀλλ’ ἡγούμενος εἰκός τι παθεῖν τοὺς τότε δικάζοντας, εἰσήγαγον εἰς τοὺς φράτερας τοὺς τοῦ Ἁγνίου Εὐβουλίδῃ τὸν παῖδα τουτονί, ἐκ τῆς θυγατρὸς ὄντα τῆς ἐκείνου, ἵνα μὴ ἐξερημωθῇ ὁ οἶκος.", "st": "43.11"}, {"sp": "N", "t": "ἐκεῖνος γάρ, ὦ ἄνδρες δικασταί, ὁ Εὐβουλίδης, ὁ τῷ Ἁγνίᾳ γένει ὢν ἐγγυτάτω, μάλιστα μὲν ηὔχετο τοῖς θεοῖς υἱὸν αὑτῷ γενέσθαι, ὥσπερ καὶ ἡ θυγάτηρ ἡ τουτουὶ μήτηρ τοῦ παιδὸς αὐτῷ ἐγένετο· ἐπειδὴ δὲ τούτου ἀπέτυχεν καὶ οὐκ ἐγένετο παῖς ἄρρην αὐτῷ οὐδὲ εἷς, μετὰ ταῦτ’ ἤδη ἐσπούδαζεν ὅπως ἐκ τῆς θυγατρὸς εἰσποιηθῇ αὑτῷ υἱὸς εἰς τὸν οἶκον τὸν ἑαυτοῦ καὶ τὸν Ἁγνίου, καὶ εἰς τοὺς φράτερας εἰσαχθῇ τοὺς ἐκείνου, ἡγούμενος, ὦ ἄνδρες δικασταί, ἐκ τῶν ὑπολοίπων τοῦτον εἶναι ἑαυτῷ οἰκειότατον, καὶ οὕτως ἂν μάλιστα τὸν οἶκον τὸν ἑαυτῶν διασῴζεσθαι καὶ οὐκ ἂν ἐξερημωθῆναι.", "st": "43.12"}, {"sp": "N", "t": "καὶ ἐγὼ ταῦτα ὑπηρέτησα αὐτῷ, ὁ τὴν Εὐβουλίδου θυγατέρα ἔχων ἐπιδικασάμενος ὡς γένει ὢν ἐγγυτάτω, καὶ εἰσήγαγον τὸν παῖδα τουτονὶ εἰς τοὺς Ἁγνίου καὶ Εὐβουλίδου φράτερας, μεθ’ ὧν καὶ Θεόπομπος ὁ τουτουὶ πατὴρ Μακαρτάτου, ἕως ἔζη, ἐφράτριζε καὶ αὐτὸς οὗτος.", "st": "43.13"}, {"sp": "N", "t": "καὶ οἱ φράτερες, ὦ ἄνδρες δικασταί, οἱ τουτουὶ Μακαρτάτου, οἱ ἄριστα εἰδότες περὶ τοῦ γένους, ὁρῶντες αὐτὸν μὲν τοῦτον οὐ ’θέλοντα κινδυνεύειν οὐδὲ ἀπάγοντα τὸ ἱερεῖον ἀπὸ τοῦ βωμοῦ, εἰ μὴ προσηκόντως εἰσήγετο ὁ παῖς οὑτοσί, αὐτοὺς δ’ ἀξιοῦντα ἐπιορκεῖν, λαβόντες τὴν ψῆφον καομένων τῶν ἱερείων, ἀπὸ τοῦ βωμοῦ φέροντες τοῦ Διὸς τοῦ φρατρίου, παρόντος τουτουὶ Μακαρτάτου, ἐψηφίσαντο τὰ δίκαια, ὦ ἄνδρες δικασταί, ὀρθῶς καὶ προσηκόντως τὸν παῖδα τουτονὶ εἰσάγεσθαι Εὐβουλίδῃ υἱὸν εἰς τὸν οἶκον τὸν Ἁγνίου.", "st": "43.14"}, {"sp": "N", "t": "ψηφισαμένων δὲ ταῦτα τῶν φρατέρων τῶν τουτουὶ Μακαρτάτου, υἱὸς ὢν Εὐβουλίδου ὁ παῖς οὑτοσὶ προσεκαλέσατο Μακάρτατον τοῦ κλήρου τοῦ Ἁγνίου εἰς διαδικασίαν, καὶ ἔλαχε πρὸς τὸν ἄρχοντα, κύριον ἐπιγραψάμενος τὸν ἀδελφὸν τὸν ἑαυτοῦ· ἐμοὶ γὰρ οὐκέτι οἷόν τ’ ἦν, ὦ ἄνδρες δικασταί, κυρίῳ ἐπιγεγράφθαι, εἰσπεποιηκότι τὸν παῖδα εἰς τὸν οἶκον τὸν Εὐβουλίδου. καὶ ἡ πρόσκλησις ἐγένετο τῷ παιδὶ τουτῳὶ κατὰ τὸν νόμον, καθ’ ὅνπερ καὶ οὗτοι προσεκαλέσαντο τὴν τουτουὶ μητέρα, τὴν νενικηκυῖαν πρότερον ἐν τῷ δικαστηρίῳ καὶ ἔχουσαν τὸν κλῆρον τὸν Ἁγνίου.", "st": "43.15"}, {"sp": "N", "t": "καί μοι ἀνάγνωθι τὸν νόμον, καθ’ ὃν ἡ πρόσκλησίς ἐστιν παρὰ τοῦ ἔχοντος τὸν κλῆρον.", "st": "43.16"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "43.16"}, {"sp": "N", "t": "ἐὰν δ’ ἐπιδεδικασμένου ἀμφισβητῇ τοῦ κλήρου ἢ τῆς ἐπικλήρου, προσκαλείσθω τὸν ἐπιδεδικασμένον πρὸς τὸν ἄρχοντα, καθάπερ ἐπὶ τῶν ἄλλων δικῶν· παρακαταβολὰς δ’ εἶναι τῷ ἀμφισβητοῦντι. ἐὰν δὲ μὴ προσκαλεσάμενος ἐπιδικάσηται, ἀτελὴς ἔσται ἡ ἐπιδικασία τοῦ κλήρου. ἐὰν δὲ μὴ ζῇ ὁ ἐπιδικασάμενος τοῦ κλήρου, προσκαλείσθω κατὰ ταὐτά, ᾧ ⟨ἂν⟩ ἡ προθεσμία μήπω ἐξήκῃ. τὴν δ’ ἀμφισβήτησιν εἶναι τῷ ἔχοντι, καθότι ἐπεδικάσατο οὗ ἂν ἔχῃ τὰ χρήματα.", "st": "43.16"}, {"sp": "N", "t": "τοῦ μὲν νόμου ἀκηκόατε, δέομαι δ’ ὑμῶν δικαίαν δέησιν, ὦ ἄνδρες δικασταί.", "st": "43.16"}, {"sp": "N", "t": "ἐὰν γὰρ ἐπιδείξω Θεοπόμπου τοῦ πατρὸς τοῦ Μακαρτάτου γένει ὄντας Ἁγνίᾳ ἐγγυτέρω Εὐβουλίδην τε τὸν παῖδα τουτονὶ καὶ Φυλομάχην, ἥ ἐστιν μήτηρ τῷ παιδί, Εὐβουλίδου δὲ θυγάτηρ, καὶ οὐ μόνον γένει ἐγγυτάτω ὄντας, ἀλλὰ τὸ παράπαν οὐδὲ ὄντα οὐδένα ἀνθρώπων ἐν τῷ οἴκῳ τῷ Ἁγνίου ἄλλον ἢ τὴν μητέρα τοῦ παιδὸς τουτουὶ καὶ αὐτὸν τοῦτον τὸν παῖδα, ταῦτ’ ἐὰν ἐπιδείξω, δέομαι ὑμῶν, ὦ ἄνδρες δικασταί, βοηθεῖν ἡμῖν.", "st": "43.17"}, {"sp": "N", "t": "τὸ μὲν οὖν πρῶτον διενοήθην, ὦ ἄνδρες δικασταί, γράψας ἐν πίνακι ἅπαντας τοὺς συγγενεῖς τοὺς Ἁγνίου, οὕτως ἐπιδεικνύειν ὑμῖν καθ’ ἕκαστον· ἐπειδὴ δὲ ἐδόκει οὐκ ⟨ἂν⟩ εἶναι ἐξ ἴσου ἡ θεωρία ἅπασι τοῖς δικασταῖς, ἀλλ’ οἱ πόρρω καθήμενοι ἀπολείπεσθαι, ἀναγκαῖον ἴσως ἐστὶν τῷ λόγῳ διδάσκειν ὑμᾶς· τοῦτο γὰρ ἅπασι κοινόν ἐστιν. πειρασόμεθα δὲ καὶ ἡμεῖς ὡς ἂν μάλιστα δυνώμεθα διὰ βραχυτάτων ἐπιδεῖξαι περὶ τοῦ γένους τοῦ Ἁγνίου.", "st": "43.18"}, {"sp": "N", "t": "Βούσελος γὰρ ἦν ἐξ Οἴου, ὦ ἄνδρες δικασταί, καὶ τούτῳ ἐγένοντο πέντε υἱεῖς, Ἁγνίας καὶ Εὐβουλίδης καὶ Στρατίος καὶ Ἅβρων καὶ Κλεόκριτος. καὶ οὗτοι ἅπαντες οἱ τοῦ Βουσέλου υἱεῖς ἄνδρες ἐγένοντο, καὶ διένειμεν αὐτοῖς τὴν οὐσίαν ὁ πατὴρ Βούσελος ἅπασιν καλῶς καὶ δικαίως, ὥσπερ προσῆκεν. νειμάμενοι δὲ τὴν οὐσίαν, γυναῖκα αὐτῶν ἕκαστος ἔγημεν κατὰ τοὺς νόμους τοὺς ὑμετέρους, καὶ παῖδες ἐγένοντο αὐτοῖς ἅπασιν καὶ παίδων παῖδες, καὶ ἐγένοντο πέντε οἶκοι ἐκ τοῦ Βουσέλου οἴκου ἑνὸς ὄντος, καὶ χωρὶς ἕκαστος ᾤκει τὸν ἑαυτοῦ ἔχων καὶ ἐγγόνους ἑαυτοῦ ποιούμενος.", "st": "43.19"}, {"sp": "N", "t": "περὶ μὲν οἶν τῶν τριῶν ἀδελφῶν τῶν τοῦ Βουσέλου υἱέων, καὶ τῶν ἐγγόνων τῶν τούτοις γενομένων, τί ἂν ἐγὼ ⟨ἢ⟩ ὑμῖν, ὦ ἄνδρες δικασταί, πράγματα παρέχοιμι ἢ ἐμαυτῷ, ἐξηγούμενος περὶ ἑκάστου; ὄντες γὰρ ἐν τῷ αὐτῷ γένει Θεοπόμπῳ καὶ προσήκοντες ὁμοίως τῷ Ἁγνίᾳ, οὗ ἐστιν ὁ κλῆρος, οὐδεὶς αὐτῶν οὔτε πρότερον πώποτε οὔτε νῦν ἠνώχλησεν ἡμῖν, οὐδ’ ἠμφεσβήτησεν οὔτε τοῦ κλήρου τοῦ Ἁγνίου οὔτε τῆς γυναικὸς τῆς ἐπικλήρου, ἣν ἐγὼ ἔχω ἐπιδικασάμενος, ἡγούμενοι οὐδ’ ὁτιοῦν προσήκειν ἑαυτοῖς οὐδενὸς τῶν Ἁγνίου.", "st": "43.20"}, {"sp": "N", "t": "περίεργον δή μοι δοκεῖ εἶναι λέγειν τι περὶ τούτων, πλὴν ὅσα ἐξ ἀνάγκης ἐστὶν ἐπιμνησθῆναι. περὶ δὲ Θεοπόμπου τοῦ πατρὸς τοῦ Μακαρτάτου καὶ αὐτοῦ τουτουὶ Μακαρτάτου, περὶ τούτων μοί ἐστιν ἐξ ἀνάγκης λέγειν. ἔστιν δὲ βραχὺς ὁ λόγος, ὦ ἄνδρες δικασταί. ὥσπερ γὰρ ὀλίγον τι πρότερον ἀκηκόατε ὅτι τῷ Βουσέλῳ πέντε υἱεῖς ἐγένοντο, τούτων εἷς ἦν Στρατίος ὁ τουτουὶ πρόγονος Μακαρτάτου, καὶ ἕτερος Ἁγνίας ὁ τουτουὶ πρόγονος τοῦ παιδός.", "st": "43.21"}, {"sp": "N", "t": "ἐγένετο δὴ υἱὸς τῷ Ἁγνίᾳ Πολέμων καὶ θυγάτηρ Φυλομάχη, ἀδελφὴ τοῦ Πολέμωνος ὁμοπατρία καὶ ὁμομητρία· τοῦ δὲ Στρατίου ἐγένοντο τοῦ ἀδελφοῦ τοῦ Ἁγνίου Φανόστρατος καὶ Χαρίδημος ὁ τουτουὶ πάππος Μακαρτάτου. ἐρωτῶ δὴ ὑμᾶς, ὦ ἄνδρες δικασταί, πότερος οἰκειότερός ἐστιν καὶ προσήκει μᾶλλον τῷ Ἁγνίᾳ, ὁ υἱὸς ὁ Πολέμων καὶ ἡ θυγάτηρ ἡ Φυλομάχη, ἢ Χαρίδημος ὁ υἱὸς Στρατίου, ἀδελφιδοῦς δ’ Ἁγνίου; ἐγὼ μὲν γὰρ ἡγοῦμαι τὸν υἱὸν καὶ τὴν θυγατέρα οἰκειότερον εἶναι ἑκάστῳ ἡμῶν μᾶλλον ἢ τὸν ἀδελφιδοῦν· καὶ οὐ μόνον παρ’ ἡμῖν τοῦτο νενόμισται, ἀλλὰ καὶ παρὰ τοῖς ἄλλοις ἅπασι καὶ Ἕλλησι καὶ βαρβάροις.", "st": "43.22"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν τοῦτο ὁμολογεῖται, ῥᾳδίως ἤδη τοῖς ἄλλοις, ὦ ἄνδρες δικασταί, παρακολουθήσετε, καὶ αἰσθήσεσθε τούτους ὅτι εἰσὶ βίαιοι καὶ ἀσελγεῖς ἄνθρωποι. τοῦ Πολέμωνος γὰρ τοῦ υἱέος τοῦ Ἁγνίου ἐγένετο υἱὸς Ἁγνίας, τὸ τοῦ πάππου τοῦ ἑαυτοῦ ὄνομ’ ἔχων, τοῦ Ἁγνίου. καὶ οὗτος μὲν ἄπαις ἐτελεύτησεν ὁ Ἁγνίας ὁ ὕστερος.", "st": "43.23"}, {"sp": "N", "t": "τῆς Φυλομάχης δὲ τῆς ἀδελφῆς τῆς Πολέμωνος, καὶ Φιλάγρου, ᾧ ἔδωκεν αὐτὴν ὁ ἀδελφὸς Πολέμων ἀνεψιῷ ὄντι ἑαυτοῦ (ὁ γὰρ Φίλαγρος υἱὸς ἦν Εὐβουλίδου τοῦ ἀδελφοῦ τοῦ Ἁγνίου), τοῦ δὴ Φιλάγρου τοῦ ἀνεψιοῦ τοῦ Πολέμωνος καὶ τῆς Φυλομάχης τῆς ἀδελφῆς τῆς Πολέμωνος ἐγένετο υἱὸς Εὐβουλίδης, ὁ πατὴρ ὁ τῆς μητρὸς τοῦ παιδὸς τουτουί. καὶ οὗτοι μὲν υἱεῖς ἐγένοντο Πολέμωνι καὶ τῇ ἀδελφῇ τῇ Πολέμωνος Φυλομάχῃ. τοῦ δὲ Χαριδήμου ἐγένετο, τοῦ υἱέος τοῦ Στρατίου, Θεόπομπος ὁ τουτουὶ πατὴρ Μακαρτάτου.", "st": "43.24"}, {"sp": "N", "t": "πάλιν δὴ ἐρωτῶ, ὦ ἄνδρες δικασταί, πότερος οἰκειότερός ἐστιν καὶ προσήκει μᾶλλον Ἁγνίᾳ τῷ πρώτῳ ἐκείνῳ, ὁ Πολέμωνος υἱὸς Ἁγνίας καὶ Εὐβουλίδης ὁ Φυλομάχης υἱὸς καὶ Φιλάγρου, ἢ Θεόπομπος ὁ Χαριδήμου υἱός, Στρατίου δὲ ὑϊδοῦς; ἐγὼ μὲν γὰρ οἶμαι, ὦ ἄνδρες δικασταί, εἴπερ καὶ ὁ υἱὸς οἰκειότατός ἐστιν καὶ ἡ θυγάτηρ, πάλιν ὁ ὑϊδοῦς καὶ ὁ ἐκ τῆς θυγατρὸς υἱός, οὗτοι οἰκειότεροί εἰσι μᾶλλον ἢ ὁ τοῦ ἀδελφιδοῦ υἱὸς καὶ ὁ ἐξ ἑτέρου ὢν οἴκου.", "st": "43.25"}, {"sp": "N", "t": "τῷ μὲν οὖν Θεοπόμπῳ ἐγένετο υἱὸς Μακάρτατος οὑτοσί, τῷ δὲ Εὐβουλίδῃ τῷ τῆς Φυλομάχης υἱεῖ, ἀνεψιῷ δὲ Ἁγνίου ὄντι πρὸς πατρός, οὑτοσὶ ὁ παῖς, ἀνεψιοῦ παῖς ὢν Ἁγνίᾳ πρὸς πατρός, ἐπειδὴ ἡ Φυλομάχη ἡ μήτηρ ἡ Εὐβουλίδου καὶ ὁ Πολέμων ὁ πατὴρ ὁ Ἁγνίου ἀδελφοὶ ἦσαν ὁμοπάτριοι καὶ ὁμομήτριοι. τῷ δέ γε Μακαρτάτῳ τῳδί, τῷ υἱεῖ τῷ Θεοπόμπου, οὐδὲν ἐγένετο ἔκγονον ὅ τι ἐστὶν ἐν τῷ οἴκῳ τῷ τούτου καὶ τῷ Στρατίου.", "st": "43.26"}, {"sp": "N", "t": "τούτων δ’ οὕτως ἐχόντων, τῷ μὲν παιδὶ τουτῳί ἐστιν ὄνομα τῶν ἐν τῷ νόμῳ εἰρημένων, καὶ μέχρι ὧν ὁ νόμος κελεύει τὴν ἀγχιστείαν εἶναι· ἀνεψιοῦ γὰρ Ἁγνίου παῖς ἐστιν· ὁ γὰρ πατὴρ αὐτοῦ Εὐβουλίδης ἀνεψιὸς ἦν Ἁγνίᾳ, οὗ ἐστιν ὁ κλῆρος. ὁ δέ γε Θεόπομπος ὁ τουτουὶ πατὴρ Μακαρτάτου οὐκ ἂν εἶχεν ὄνομα θέσθαι αὑτῷ τῶν ἐν τῷ νόμῳ εἰρημένων οὐδέν· ἐξ ἑτέρου γὰρ οἴκου ἦν, τοῦ Στρατίου.", "st": "43.27"}, {"sp": "N", "t": "οὐ προσήκει δέ, ὦ ἄνδρες δικασταί, οὐδένα ἀνθρώπων ἔχειν τὸν κλῆρον τὸν Ἁγνίου ἐξ ἑτέρου οἴκου ὄντα, ἕως ἄν τις λείπηται τῶν γενομένων ἐν τῷ οἴκῳ τῷ Ἁγνίου, οὐδ’ ἐκβάλλειν βίᾳ, ὅπερ οὗτοι διαπράττονται, γένει τε ἀπωτέρω ὄντες καὶ οὐκ ἐν τῷ αὐτῷ οἴκῳ. τοῦτο γάρ ἐστιν, ὦ ἄνδρες δικασταί, ᾧ παρεκρούσατο Θεόπομπος ὁ τουτουὶ πατὴρ Μακαρτάτου.", "st": "43.28"}, {"sp": "N", "t": "τίνες οὖν οἱ λοιποί; οἱ ἔτι νῦν ὄντες ἐν τῷ οἴκῳ τῷ Ἁγνίου, Φυλομάχη τε ἡ ἐμὴ γυνή, Εὐβουλίδου δὲ θυγάτηρ οὖσα τοῦ ἀνεψιοῦ τοῦ Ἁγνίου, καὶ οὑτοσὶ ὁ παῖς ὁ εἰσηγμένος εἰς τὸν οἶκον τὸν Εὐβουλίδου καὶ Ἁγνίου. Θεόπομπος δὲ ὁ τουτουὶ πατὴρ Μακαρτάτου, οὐκ ὢν τοῦ οἴκου τοῦ Ἁγνίου, ἐψεύσατο πρὸς τοὺς δικαστὰς ὑπερμέγεθες ψεῦδος περί τε τῆς Φυλομάχης τῆς τοῦ Πολέμωνος ἀδελφῆς, τηθίδος δὲ Ἁγνίου, ὅτι οὐκ ἦν τῷ Πολέμωνι τῷ τοῦ Ἁγνίου υἱεῖ ὁμοπατρία καὶ ὁμομητρία ἀδελφή, καὶ πάλιν προσποιούμενος τοῦ αὐτοῦ οἴκου εἶναι Ἁγνίᾳ, ὁ οὐδεπώποτε γενόμενος.", "st": "43.29"}, {"sp": "N", "t": "ταῦτα δὲ πάντα ἀδεῶς ἔλεγεν ὁ Θεόπομπος, μάρτυρα μὲν οὐδένα παρασχόμενος, ὅστις ἔμελλεν ὑπεύθυνος ἡμῖν ἔσεσθαι, συνομολογοῦντας δ’ ἑαυτῷ ἔχων τοὺς κοινωνούς, οἳ ἦσαν ἀλλήλοις συναγωνισταὶ καὶ ἅπαντα ἔπραττον κοινῇ, ὅπως ἀφέλωνται τὴν γυναῖκα τὴν τουτουὶ μητέρα τοῦ παιδὸς τὸν κλῆρον, ὃν αὐτῇ ὑμεῖς ἐψηφίσασθε.", "st": "43.30"}, {"sp": "N", "t": "βούλομαι οὖν, ὦ ἄνδρες δικασταί, περὶ ὧν εἴρηκα πρὸς ὑμᾶς, μαρτυρίας παρασχέσθαι, πρῶτον μὲν ὡς ἐνίκησεν τοῦ κλήρου τοῦ Ἁγνίου ἡ Εὐβουλίδου θυγάτηρ Φυλομάχη, γένει οὖσα ἐγγυτάτω, ἔπειτα περὶ τῶν ἄλλων ἁπάντων. ἀναγίγνωσκε τὴν μαρτυρίαν.", "st": "43.31"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "43.31"}, {"sp": "N", "t": "μαρτυροῦσι παρεῖναι πρὸς τῷ διαιτητῇ ἐπὶΝικοφήμου ἄρχοντος, ὅτε ἐνίκησε Φυλομάχη ἡ Εὐβουλίδου θυγάτηρ τοῦ κλήρου τοῦ Ἁγνίου τοὺς ἀμφισβητοῦντας αὐτῇ πάντας.", "st": "43.31"}, {"sp": "N", "t": "ὅτι μὲν ἐνίκησεν ἡ Εὐβουλίδου θυγάτηρ τοῦ κλήρου τοῦ Ἁγνίου, ἀκηκόατε, ὦ ἄνδρες δικασταί. καὶ αὕτη ἐνίκησεν οὐδεμιᾷ παρασκευῇ ἀδίκῳ οὐδὲ συνωμοσίᾳ, ἀλλ’ ὡς οἷόν τε δικαιότατα, ἐπιδειξάντων ἡμῶν ὅτι γένει ἐγγυτάτω ἦν Ἁγνίᾳ, οὗ ἐστιν ὁ κλῆρος, ἀνεψιοῦ παῖς οὖσα πρὸς πατρὸς καὶ ἐκ τοῦ οἴκου οὖσα τοῦ Ἁγνίου.", "st": "43.32"}, {"sp": "N", "t": "ἐπειδὰν οὖν λέγῃ Μακάρτατος, ὅτι ἐνίκησεν ὁ πατὴρ αὐτοῦ Θεόπομπος τοῦ κλήρου τούτου, ὑπολαμβάνετε αὐτῷ ὑμεῖς, ὦ ἄνδρες δικασταί, ὅτι καὶ ἡ γυνὴ ἐνίκησεν πρότερον ἢ Θεόπομπος ὁ τουτουὶ πατήρ, καὶ ὅτι δικαίως ἐνίκησεν ἡ γυνὴ ἐκ τοῦ οἴκου οὖσα τοῦ Ἁγνίου, Εὐβουλίδου θυγάτηρ οὖσα, τοῦ ἀνεψιοῦ τοῦ Ἁγνίου, ὁ δὲ Θεόπομπος ὅτι οὐκ ἐνίκησεν, ἀλλὰ παρεκρούσατο, οὐκ ὢν ἐκ τοῦ οἴκου τὸ παράπαν τοῦ Ἁγνίου.", "st": "43.33"}, {"sp": "N", "t": "ταῦτα αὐτῷ ὑμεῖς, ὦ ἄνδρες δικασταί, ὑπολαμβάνετε, καὶ ὅτι τὸν παῖδα τουτονὶ Εὐβουλίδην, τὸν Εὐβουλίδου υἱόν, Ἁγνίου δέ, οὗ ἐστιν ὁ κλῆρος, ἀνεψιοῦ παῖδα πρὸς πατρός, οὔτε Θεόπομπος ὁ Μακαρτάτου πατὴρ οὔτε ἄλλος οὐδεὶς πώποτε ἀνθρώπων ἐνίκησεν. νυνὶ δ’ ἐστὶν ὁ ἀγὼν καὶ ἡ διαδικασία περὶ τοῦ κλήρου τοῦ Ἁγνίου τῷ Εὐβουλίδου υἱεῖ τούτῳ καὶ Μακαρτάτῳ τουτῳὶ τῷ Θεοπόμπου υἱεῖ· καὶ ὁπότερος τούτων δικαιότερα λέγειν δόξει καὶ κατὰ τοὺς νόμους μᾶλλον, δῆλον ὅτι τούτῳ ὑμεῖς οἱ δικασταὶ προσθήσεσθε.", "st": "43.34"}, {"sp": "N", "t": "ἀναγίγνωσκε τὰς μαρτυρίας τὰς ὑπολοίπους, πρῶτον μὲν ὅτι ἡ Φυλομάχη ἡ τοῦ Ἁγνίου τηθὶς ἀδελφὴ ἦν ὁμοπατρία καὶ ὁμομητρία τῷ Πολέμωνι τῷ Ἁγνίου πατρί· ἔπειτα τὰς ἄλλας ἁπάσας ἀναγνώσεται ⟨τὰς⟩ περὶ τοῦ γένους.", "st": "43.35"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "43.35"}, {"sp": "N", "t": "μαρτυροῦσι δημόται εἶναι Φιλάγρῳ τῷ Εὐβουλίδου πατρὶ καὶ Πολέμωνι τῷ πατρὶ τῷ Ἁγνίου, καὶ εἰδέναι Φυλομάχην τὴν μητέρα τὴν Εὐβουλίδου νομιζομένην ἀδελφὴν εἶναι Πολέμωνος τοῦ πατρὸς τοῦ Ἁγνίου ὁμοπατρίαν καὶ ὁμομητρίαν, καὶ μηδενὸς πώποτ’ ἀκοῦσαι ὡς γένοιτο ἀδελφὸς Πολέμωνι τῷ Ἁγνίου.", "st": "43.35"}, {"sp": "N", "t": "ΑΛΛΗ.", "st": "43.35"}, {"sp": "N", "t": "μαρτυροῦσιν Οἰνάνθην, τὴν μητέρα τοῦ πάππου τοῦ ἑαυτῶν Στρατωνίδου, ἀνεψιὰν εἶναι ἐκ πατραδέλφων Πολέμωνι τῷ πατρὶ τῷ Ἁγνίου, καὶ ἀκούειν τοῦ πατρὸς τοῦ ἑαυτῶν, ὅτι Πολέμωνι ἀδελφὸς οὐδεὶς γένοιτο πώποτε, τῷ πατρὶ τῷ Ἁγνίου, ἀδελφὴ δὲ Φυλομάχη ὁμοπατρία καὶ ὁμομητρία, ἡ μήτηρ ἡ Εὐβουλίδου τοῦ πατρὸς τοῦΦυλομάχης τῆς Σωσιθέου γυναικός.", "st": "43.36"}, {"sp": "N", "t": "ΑΛΛΗ.", "st": "43.36"}, {"sp": "N", "t": "μαρτυρεῖ συγγενὴς εἶναι καὶ φράτηρ καὶ δημότης Ἁγνίᾳ καὶ Εὐβουλίδῃ, καὶ ἀκούειν τοῦ πατρὸς τοῦ ἑαυτῶν καὶ τῶν ἄλλων συγγενῶν, ὅτι ἀδελφὸς οὐδεὶς ἐγένετο Πολέμωνι τῷ πατρὶ τῷ Ἁγνίου, ἀδελφὴ δ’ ὁμοπατρία καὶ ὁμομητρία Φυλομάχη ἡ μήτηρ ἡ Εὐβουλίδου τοῦ πατρὸς τοῦ Φυλομάχης τῆς Σωσιθέου γυναικός.", "st": "43.36"}, {"sp": "N", "t": "ΑΛΛΗ.", "st": "43.36"}, {"sp": "N", "t": "μαρτυρεῖ πάππον εἶναι ἑαυτοῦ Ἀρχίμαχον καὶ ποιήσασθαι ἑαυτὸν υἱόν, καὶ εἶναι αὐτὸν συγγενῆ Πολέμωνι τῷ πατρὶ τῷ Ἁγίου, καὶ ἀκούειν Ἀρχιμάχου καὶ τῶν ἄλλων συγγενῶν, ὅτι ἀδελφὸς οὐδεὶς πώποτ’ ἐγένετο Πολέμωνι τῷ πατρὶ τῷ Ἁγνίου, ἀδελφὴ δ’ ὁμοπατρία καὶ ὁμομητρία Φυλομάχη ἡ μήτηρ ἡ Εὐβουλίδου τοῦ πατρὸς τοῦ Φυλομάχης τῆς Σωσιθέου γυναικός.", "st": "43.37"}, {"sp": "N", "t": "ΑΛΛΗ.", "st": "43.37"}, {"sp": "N", "t": "μαρτυρεῖ τὸν πατέρα τῆς ἑαυτοῦ γυναικὸς Καλλίστρατον ἀνεψιὸν εἶναι ἐκ πατραδέλφων Πολέμωνι τῷ πατρὶ τῷ Ἁγνίου καὶ Χαριδήμῳ τῷ πατρὶ τῷ Θεοπόμπου, τὴν δὲ μητέρα τὴν ἑαυτοῦ ἀνεψιοῦ παῖδα εἶναι Πολέμωνι, καὶ λέγειν τὴν μητέρα τὴν αὑτῶν πρὸς αὑτοὺς πολλάκις, ὅτι Φυλομάχη ἡ μήτηρ ἡ Εὐβουλίδου ἀδελφὴ ἦν Πολέμωνος τοῦ πατρὸς τοῦ Ἁγνίου ὁμοπατρία καὶ ὁμομητρία, καὶ ὅτι ἀδελφὸς οὐδεὶς πώποτε γένοιτο Πολέμωνι τῷ πατρὶ τῷ Ἁγνίου.", "st": "43.37"}, {"sp": "N", "t": "τὸ πρότερον, ὦ ἄνδρες δικασταί, ὅτε συνώμοσαν ἀλλήλοις οὗτοι καὶ συστάντες ἠγωνίζοντο πολλοὶ ὄντες πρὸς τὴν γυναῖκα, ἡμεῖς μέν, ὦ ἄνδρες δικασταί, οὔτε μαρτυρίας ἐγράψαμεν περὶ τῶν ὁμολογουμένων, οὔτε μάρτυρας προσεκαλεσάμεθα, ἀλλ’ ᾠόμεθα ταῦτά γε ἀδεῶς ὑπάρχειν ἡμῖν· οὗτοι δὲ τά τε ἄλλα πολλὰ καὶ ἀναίσχυντα παρεσκευάσαντο εἰς τὸν ἀγῶνα, καὶ ἔμελεν αὐτοῖς οὐδὲν πλὴν τοῦ ἐξαπατῆσαι ἐν τῷ παρόντι τότε καιρῷ τοὺς δικαστάς,", "st": "43.38"}, {"sp": "N", "t": "οἵτινες κατεχρῶντο ὡς τῷ Πολέμωνι τῷ πατρὶ τῷ Ἁγνίου τὸ παράπαν οὐδεμία γένοιτο ἀδελφὴ ὁμοπατρία καὶ ὁμομητρία· οὕτως ἦσαν ἀναίσχυντοι καὶ βδελυροί, τηλικουτονὶ πρᾶγμα παρακρουόμενοι τοὺς δικαστὰς καὶ οὑτωσὶ περιφανές, καὶ ἐσπούδαζον καὶ ἠγωνίζοντο περὶ τούτου μάλιστα. ἡμεῖς δέ γε νυνὶ μάρτυρας ὑμῖν τοσουτουσὶ παρεσχήμεθα περὶ τῆς Πολέμωνος ἀδελφῆς, τηθίδος δὲ Ἁγνίου.", "st": "43.39"}, {"sp": "N", "t": "τούτῳ δ’ ὁ βουλόμενος μαρτυρησάτω, ἢ ὡς οὐκ ἦσαν ἀδελφοὶ ὁμοπάτριοι καὶ ὁμομήτριοι Πολέμων καὶ Φυλομάχη, ἢ ὅτι οὐκ ἦν ὁ μὲν Πολέμων υἱός, ἡ δὲ Φυλομάχη θυγάτηρ Ἁγνίου τοῦ Βουσέλου υἱέος, ἢ ὅτι ὁ Πολέμων οὐκ ἦν πατὴρ Ἁγνίου, οὗ ἐστιν ὁ κλῆρος, οὐδ’ ἡ ἀδελφὴ ἡ Πολέμωνος Φυλομάχη τηθίς,", "st": "43.40"}, {"sp": "N", "t": "ἢ ὡς Εὐβουλίδης οὐκ ἦν Φυλομάχης υἱὸς οὐδὲ Φιλάγρου τοῦ ἀνεψιοῦ τοῦ Ἁγνίου, ἢ ἐκεῖνο ὅτι Εὐβουλίδου τοῦ ἀνεψιοῦ τοῦ Ἁγνίου οὐκ ἔστι Φυλομάχη θυγάτηρ ἡ νῦν ἔτι οὖσα, οὐδ’ υἱὸς οὑτοσὶ ὁ παῖς, εἰσπεποιημένος κατὰ τοὺς νόμους τοὺς ὑμετέρους εἰς τὸν Εὐβουλίδου οἶκον, ἢ ὡς ὁ Θεόπομπος ὁ τουτουὶ πατὴρ Μακαρτάτου ἐκ τοῦ οἴκου ἦν τοῦ Ἁγνίου. τούτων ὅ τι βούλεταί τις μαρτυρησάτω αὐτῷ. ἀλλ’ εὖ οἶδ’ ὅτι οὐδεὶς οὕτω τολμηρὸς ἔσται οὐδὲ ἀπονενοημένος ἄνθρωπος.", "st": "43.41"}, {"sp": "N", "t": "ὡς δὲ καταφανὲς ὑμῖν ἔσται, ὦ ἄνδρες δικασταί, ὅτι τὸ πρότερον ἀναισχυντοῦντες περιεγένοντο, δίκαιον δὲ οὐδὲν ἔλεγον, ἀναγίγνωσκε τὰς μαρτυρίας, ὅσαι εἰσὶν ἔτι ὑπόλοιποι.", "st": "43.42"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "43.42"}, {"sp": "N", "t": "μαρτυρεῖ συγγενὴς εἶναι Πολέμωνι τῷ Ἁγνίου πατρί, καὶ ἀκούειν τοῦ πατρὸς τοῦ ἑαυτοῦ ἀνεψιοὺς εἶναι ἐκ πατραδέλφων Πολέμωνι Φίλαγρόν τε τὸν Εὐβουλίδου πατέρα καὶ Φανόστρατον τὸν Στρατίου πατέρα καὶ Καλλίστρατον τὸν πατέρα τῆς Σωσίου γυναικὸς καὶ Εὐκτήμονα τὸν βασιλεύσαντα καὶ Χαρίδημον τὸν πατέρα τὸν Θεοπόμπου καὶ Στρατοκλέους, καὶ εἶναι τοῖς τούτων υἱέσι καὶ Ἁγνίᾳ ἐν τῷ αὐτῷ γένει Εὐβουλίδην κατὰ τὸν πατέρα τὸν ἑαυτοῦ Φίλαγρον, κατὰ δὲ τὴν μητέρα τὴν ἑαυτοῦ Φυλομάχην νομιζόμενον ἀνεψιὸν εἶναι Εὐβουλίδην Ἁγνίᾳ πρὸς πατρός, ἐκ τηθίδος γεγονότα Ἁγνίᾳ τῆς πρὸς πατρός.", "st": "43.42"}, {"sp": "N", "t": "ΑΛΛΗ.", "st": "43.42"}, {"sp": "N", "t": "μαρτυροῦσι συγγενεῖς εἶναι Πολέμωνι τῷ πατρὶ τῷ Ἁγνίου καὶ Φιλάγρῳ τῷ πατρὶ τῷ Εὐβουλίδου καὶ Εὐκτήμονι τῷ βασιλεύσαντι, καὶ εἰδέναι Εὐκτήμονα ἀδελφὸν ὄντα ὁμοπάτριον Φιλάγρῳ τῷ πατρὶ τῷ Εὐβουλίδου· καὶ ὁπότε ἡ ἐπιδικασία ἦν τοῦ κλήρου τοῦ Ἁγνίου Εὐβουλίδῃ πρὸς Γλαύκωνα, ἔτι ζῆν Εὐκτήμονα, ἐκ πατραδέλφων ἀνεψιὸν ὄντα Πολέμωνι τῷ πατρὶ ⟨τῷ⟩ Ἁγνίου, καὶ μὴ ἀμφισβητῆσαι Εὐκτήμονα Εὐβουλίδῃ τοῦ κλήρου τοῦ Ἁγνίου, μηδ’ ἄλλον μηδένα κατὰ γένος τότε.", "st": "43.43"}, {"sp": "N", "t": "ΑΛΛΗ.", "st": "43.43"}, {"sp": "N", "t": "μαρτυροῦσι τὸν πατέρα τὸν ἑαυτῶν Στράτωνα συγγενῆ εἶναι Πολέμωνι τῷ πατρὶ τῷ Ἁγνίου καὶ Χαριδήμῳ τῷ πατρὶ τῷ Θεοπόμπου καὶ Φιλάγρῳ τῷ πατρὶ τῷ Εὐβουλίδου, καὶ ἀκούειν τοῦ ἑαυτῶν πατρός, ὅτι Φίλαγρος λάβοι γυναῖκα πρώτην μὲν Φυλομάχην ἀδελφὴν Πολέμωνος τοῦ πατρὸς τοῦ Ἁγνίου ὁμοπατρίαν καὶ ὁμομητρίαν, καὶ γενέσθαι Φιλάγρῳ ἐκ μὲν τῆς Φυλομάχης Εὐβουλίδην, ἀποθανούσης δὲ Φυλομάχης ἑτέραν λαβεῖν γυναῖκα Φίλαγρον Τελεσίππην, καὶ γενέσθαι ὁμοπάτριον μὲν ἀδελφὸν Εὐβουλίδῃ Μενεσθέα, ὁμομήτριον δὲ μή· καὶ Εὐβουλίδου ἀμφισβητήσαντος τοῦ κλήρου τοῦ Ἁγνίου κατὰ γένος, Μενεσθέα μὴ ἀμφισβητῆσαι τοῦ κλήρου τοῦ Ἁγνίου, μηδ’ Εὐκτήμονα τὸν ἀδελφὸν τὸν Φιλάγρου, μηδ’ ἄλλον μηδένα κατὰ γένος πρὸς Εὐβουλίδην τότε.", "st": "43.44"}, {"sp": "N", "t": "ΑΛΛΗ.", "st": "43.44"}, {"sp": "N", "t": "μαρτυρεῖ τὸν πατέρα τὸν ἑαυτοῦ Ἀρχίμαχον συγγενῆ εἶναι Πολέμωνι τῷ πατρὶ τῷ Ἁγνίου καὶ Χαριδήμῳ τῷ πατρὶ τῷ Θεοπόμπου καὶ Φιλάγρῳ τῷ πατρὶ τῷ Εὐβουλίδου, καὶ ἀκούειν τοῦ πατρὸς τοῦ ἑαυτῶν, ὅτι Φίλαγρος λάβοι γυναῖκα πρώτην μὲν Φυλομάχην ἀδελφὴν Πολέμωνος τοῦ πατρὸς τοῦ Ἁγνίου ὁμοπατρίαν καὶ ὁμομητρίαν, καὶ γενέσθαι ἐκ μὲν Φυλομάχης Εὐβουλίδην, ἀποθανούσης δὲ Φυλομάχης ἑτέραν λαβεῖν γυναῖκα Φίλαγρον Τελεσίππην, καὶ γενέσθαι Φιλάγρῳ ἐκ Τελεσίππης Μενεσθέα, ὁμοπάτριον μὲν ἀδελφὸν Εὐβουλίδῃ, ὁμομήτριον δὲ μή· ἀμφισβητήσαντος δὲ ⟨Εὐβουλίδου τοῦ κλήρου⟩ τοῦ Ἁγνίου κατὰ γένος, Μενεσθέα μὴ ἀμφισβητῆσαι τοῦ κλήρου, μηδ’ Εὐκτήμονα τὸν ἀδελφὸν ⟨τὸν⟩ Φιλάγρου, μηδ’ ἄλλον μηδένα κατὰ γένος πρὸς Εὐβουλίδην τότε.", "st": "43.45"}, {"sp": "N", "t": "ΑΛΛΗ.", "st": "43.45"}, {"sp": "N", "t": "μαρτυρεῖ τὸν πατέρα τῆς ἑαυτοῦ μητρὸς Καλλίστρατον ἀδελφὸν εἶναι Εὐκτήμονι τῷ βασιλεύσαντι καὶ Φιλάγρῳ τῷ πατρὶ τῷ Εὐβουλίδου, ἀνεψιοὺς δ’ εἶναι τούτους Πολέμωνι τῷ πατρὶ τῷ Ἁγνίου καὶ Χαριδήμῳ τῷ πατρὶ τῷ Θεοπόμπου, καὶ ἀκούειν τῆς μητρὸς τῆς ἑαυτοῦ, ὅτι ἀδελφὸς οὐ γένοιτο Πολέμωνι τῷ πατρὶ ⟨τῷ⟩ Ἁγνίου, ἀδελφὴ δὲ γένοιτο ὁμοπατρία καὶ ὁμομητρία Φυλομάχη, καὶ ταύτην λάβοι τὴν Φυλομάχην Φίλαγρος, καὶ γένοιτο ἐξ αὐτῶν Εὐβουλίδης ὁ πατὴρ ὁ Φυλομάχης τῆς Σωσιθέου γυναικός.", "st": "43.46"}, {"sp": "N", "t": "ἀναγνῶναι μὲν τὰς μαρτυρίας ταύτας ἐξ ἀνάγκης ἦν, ὦ ἄνδρες δικασταί, ἵνα μὴ τὸ αὐτὸ πάθοιμεν ὅπερ τὸ πρότερον, ἀπαράσκευοι ληφθέντες ὑπὸ τούτων. πολὺ δὲ σαφέστερον ἔτι αὐτὸς ἑαυτοῦ Μακάρτατος οὑτοσὶ καταμαρτυρήσει, ὅτι οὔτε Θεοπόμπῳ τῷ πατρὶ τῷ αὑτοῦ οὔτε αὐτῷ τούτῳ προσήκει οὐδενὸς κληρονομεῖν τῶν Ἁγνίου, γένει ἀπωτέρω ὄντος τοῦ Θεοπόμπου καὶ οὐδ’ ἐκ τοῦ αὐτοῦ οἴκου τὸ παράπαν.", "st": "43.47"}, {"sp": "N", "t": "εἰ γάρ τις ἀνακρίνοι, ὦ ἄνδρες δικασταί, οὑτοσὶ τίς ἐστιν ὁ ἀμφισβητῶν τῷ παιδὶ τούτῳ τοῦ κλήρου τοῦ Ἁγνίου; εὖ οἶδ’ ὅτι ἀποκρίναιτ’ ἄν, Μακάρτατος. τίνος ὢν πατρός; Θεοπόμπου. μητρὸς δὲ τίνος; Ἀπολήξιδος θυγατρὸς Προσπαλτίου, ἀδελφῆς δὲ Μακαρτάτου Προσπαλτίου. ὁ δὲ Θεόπομπος τίνος ἦν πατρός; Χαριδήμου. ὁ δὲ Χαρίδημος τίνος; Στρατίου. ὁ δὲ Στρατίος τίνος; Βουσέλου. οὑτοσί, ὦ ἄνδρες δικασταί, ἐστιν ὁ Στρατίου οἶκος, ἑνὸς τῶν Βουσέλου υἱέων, καὶ ἔκγονοι οὗτοί εἰσιν Στρατίου, οὓς ὑμεῖς ἀκηκόατε· καὶ ἐνταῦθα οὐδαμοῦ ἐστιν οὐδὲν ὄνομα τῶν ἐκ τοῦ οἴκου τοῦ Ἁγνίου, ἀλλ’ οὐδὲ παραπλήσιον.", "st": "43.48"}, {"sp": "N", "t": "πάλιν δὴ ἀνακρίνω τὸν παῖδα τουτονί, τίς ὢν ἀμφισβητεῖ Μακαρτάτῳ τοῦ κλήρου τοῦ Ἁγνίου. οὐκ ἂν ἔχοι, ὦ ἄνδρες δικασταί, ἄλλ’ οὐδ’ ὁτιοῦν ἀποκρίνασθαι ὁ παῖς, ἢ ὅτι Εὐβουλίδης. τίνος ὢν πατρός; Εὐβουλίδου τοῦ Ἁγνίου ἀνεψιοῦ. μητρὸς δὲ τίνος; Φυλομάχης, ἣ ἦν Ἁγνίᾳ ἀνεψιοῦ παῖς πρὸς πατρός. ὁ Εὐβουλίδης δὲ τίνος ἦν πατρός; Φιλάγρου τοῦ ἀνεψιοῦ τοῦ Ἁγνίου. μητρὸς δὲ τίνος; Φυλομάχης τῆς τηθίδος τῆς Ἁγνίου. ὁ δ’ Ἁγνίας τίνος ἦν υἱός; Πολέμωνος. ὁ δὲ Πολέμων τίνος; Ἁγνίου. ὁ δ’ Ἁγνίας τίνος; Βουσέλου.", "st": "43.49"}, {"sp": "N", "t": "οὑτοσὶ ἕτερος οἶκός ἐστιν ὁ Ἁγνίου, ἑνὸς τῶν Βουσέλου υἱέων, καὶ ἐνταῦθ’ οὐδ’ ὁτιοῦν ἔνεστι τὸ αὐτὸ ὄνομα τῶν ἐν τῷ Στρατίου οἴκῳ ὄντων ἐκγόνων, ἀλλ’ οὐδὲ παραπλήσιον· ἀλλ’ αὐτοὶ δι’ αὑτῶν πορεύονται ἐν τῷ οἴκῳ τῷ Ἁγνίου, τὰ ὀνόματα παρ’ ἀλλήλων παραλαμβάνοντες. πανταχῇ δὴ καὶ πάντα τρόπον ἐξελέγχονται ἐξ ἑτέρου οἴκου καὶ γένει ἀπωτέρω ὄντες, καὶ οὐ προσῆκον αὐτοῖς κληρονομεῖν οὐδενὸς τῶν Ἁγνίου. οἷς γὰρ δίδωσιν ὁ νομοθέτης τὴν ἀγχιστείαν καὶ τὴν κληρονομίαν, τούτους ἀναγνώσεται ὑμῖν τοὺς νόμους.", "st": "43.50"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "43.50"}, {"sp": "N", "t": "ὅστις ἂν μὴ διαθέμενος ἀποθάνῃ, ἐὰν μὲν παῖδας καταλίπῃ θηλείας, σὺν ταύτῃσιν, ἐὰν δὲ μή, τούσδε κυρίους εἶναι τῶν χρημάτων. ἐὰν μὲν ἀδελφοὶ ὦσιν ὁμοπάτορες· καὶ ἐὰν παῖδες ἐξ ἀδελφῶν γνήσιοι, τὴν τοῦ πατρὸς μοῖραν λαγχάνειν· ἐὰν δὲ μὴ ἀδελφοὶ ὦσιν ἢ ἀδελφῶν παῖδες, … ἐξ αὐτῶν κατὰ ταὐτὰ λαγχάνειν· κρατεῖν δὲ τοὺς ἄρρενας καὶ τοὺς ἐκ τῶν ἀρρένων, ἐὰν ἐκ τῶν αὐτῶν ὦσι, καὶ ἐὰν γένει ἀπωτέρω. ἐὰν δὲ μὴ ὦσι πρὸς πατρὸς μέχρι ἀνεψιῶν παίδων, τοὺς πρὸς μητρὸς τοῦ ἀνδρὸς κατὰ ταὐτὰ κυρίους εἶναι. ἐὰν δὲ μηδετέρωθεν ᾖ ἐντὸς τούτων, τὸν πρὸς πατρὸς ἐγγυτάτω κύριον εἶναι. νόθῳ δὲ μηδὲ νόθῃ μὴ εἶναι ἀγχιστείαν μήθ’ ἱερῶν μήθ’ ὁσίων ἀπ’ Εὐκλείδου ἄρχοντος.", "st": "43.51"}, {"sp": "N", "t": "διαρρήδην λέγει ὁ νόμος, ὦ ἄνδρες δικασταί, οἷς δεῖ τὴν κληρονομίαν εἶναι· οὐ μὰ Δί’ οὐ Θεοπόμπῳ οὐδὲ Μακαρτάτῳ τῷ Θεοπόμπου υἱεῖ, τοῖς μηδὲ τὸ παράπαν ἐν τῷ οἴκῳ οὖσι τῷ Ἁγνίου. ἀλλὰ τίνι καὶ δίδωσιν; τοῖς ἐκγόνοις τοῖς Ἁγνίου, τοῖς οὖσιν ἐν τῷ οἴκῳ τῷ ἐκείνου. ταῦτα καὶ ὁ νόμος λέγει, καὶ τὸ δίκαιον οὕτως ἔχει.", "st": "43.52"}, {"sp": "N", "t": "οὐ τοίνυν, ὦ ἄνδρες δικασταί, ταῦτα μὲν ἔδωκεν ὁ νομοθέτης τοῖς προσήκουσιν, ἕτερα δὲ οὐ προσέταξεν πολλὰ πάνυ ἐν τῷ νόμῳ, ἃ δεῖ ποιεῖν τοὺς προσήκοντας ἐπάναγκες· ἀλλὰ πολλὰ πάνυ ἐστὶν ἃ προστάττει ποιεῖν τοῖς προσήκουσιν, καὶ πρόφασιν οὐδεμίαν δίδωσιν, ἀλλ’ ἐξ ἀνάγκης δεῖ ποιεῖν. μᾶλλον δὲ λέγε αὐτὸν τὸν νόμον τὸν πρῶτον.", "st": "43.53"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "43.53"}, {"sp": "N", "t": "τῶν ἐπικλήρων ὅσαι θητικὸν τελοῦσιν, ἐὰν μὴ βούληται ἔχειν ὁ ἐγγύτατα γένους, ἐκδιδότω ἐπιδοὺς ὁ μὲν πεντακοσιομέδιμνος πεντακοσίας δραχμάς, ὁ δ’ ἱππεὺς τριακοσίας, ὁ δὲ ζευγίτης ἑκατὸν πεντήκοντα, πρὸς οἷς αὐτῆς. ἐὰν δὲ πλείους ὦσιν ἐν τῷ αὐτῷ γένει, τῇ ἐπικλήρῳ πρὸς μέρος ἐπιδιδόναι ἕκαστον. ἐὰν δ’ αἱ γυναῖκες πλείους ὦσι, μὴ ἐπάναγκες εἶναι πλέον ἢ μίαν ἐκδοῦναι τῷ γ’ ἑνί, ἀλλὰ τὸν ἐγγύτατα ἀεὶ ἐκδιδόναι ἢ αὐτὸν ἔχειν. ἐὰν δὲ μὴ ἔχῃ ὁ ἐγγυτάτω γένους ἢ μὴ ἐκδῷ, ὁ ἄρχων ἐπαναγκαζέτω ἢ αὐτὸν ἔχειν ἢ ἐκδοῦναι. ἐὰν δὲ μὴ ἐπαναγκάσῃ ὁ ἄρχων, ὀφειλέτω χιλίας δραχμὰς ἱερὰς τῇ Ἥρᾳ. ἀπογραφέτω δὲ τὸν μὴ ποιοῦντα ταῦτα ὁ βουλόμενος πρὸς τὸν ἄρχοντα.", "st": "43.54"}, {"sp": "N", "t": "ἃ μὲν λέγει ὁ νόμος, ὦ ἄνδρες δικασταί, ἀκούετε. ὅτε δὲ τῆς ἐπικλήρου ἔδει ἐπιδικάζεσθαι Φυλομάχης τῆς τουτουὶ μητρὸς τοῦ παιδός, Ἁγνίου δὲ ἀνεψιοῦ παιδὸς οὔσης πρὸς πατρός, ἐγὼ μὲν ἧκον φοβούμενος τὸν νόμον καὶ ἐπεδικαζόμην γένει ὢν ἐγγυτάτω, Θεόπομπος δὲ ὁ Μακαρτάτου πατὴρ οὐδὲ προσῆλθεν τὸ παράπαν οὐδὲ ἠμφεσβήτησεν διὰ τὸ μηδ’ ὁτιοῦν αὐτῷ προσήκειν, καὶ ταῦτα ἐν τῇ ἡλικίᾳ ὢν τῇ αὐτῇ.", "st": "43.55"}, {"sp": "N", "t": "καίτοι πῶς οἴεσθε, ὦ ἄνδρες δικασταί, ἄτοπον εἶναι, τῆς μὲν ἐπικλήρου, ἣ ἦν Ἁγνίᾳ ἀνεψιοῦ παῖς πρὸς πατρός, ταύτης μὲν μηδεπώποτε ἀμφισβητῆσαι Θεόπομπον, τὸν δὲ κλῆρον τὸν Ἁγνίου ἀξιοῦν ἔχειν παρὰ τοὺς νόμους; τούτων γένοιντ’ ἂν ἄνθρωποι ἀναισχυντότεροι ἢ μιαρώτεροι; ἀναγίγνωσκε καὶ τοὺς ἑτέρους νόμους.", "st": "43.56"}, {"sp": "N", "t": "ΝΟΜΟΙ.", "st": "43.56"}, {"sp": "N", "t": "προειπεῖν τῷ κτείναντι ἐν ἀγορᾷ ἐντὸς ἀνεψιότητος καὶ ἀνεψιοῦ, συνδιώκειν δὲ καὶ ἀνεψιοὺς καὶ ἀνεψιῶν παῖδας καὶ γαμβροὺς καὶ πενθεροὺς καὶ φράτερας. αἰδέσασθαι δέ, ἐὰν μὲν πατὴρ ᾖ ἢ ἀδελφὸς ἢ υἱεῖς, ἅπαντας, ἢ τὸν κωλύοντα κρατεῖν. ἐὰν δὲ τούτων μηδεὶς ᾖ, κτείνῃ δὲ ἄκων, γνῶσι δὲ οἱ πεντήκοντα καὶ εἷς, οἱ ἐφέται, ἄκοντα κτεῖναι, ἐσέσθων οἱ φράτερες, ἐὰν ἐθέλωσι, δέκα· τούτους δὲ οἱ πεντήκοντα καὶ εἷς ἀριστίνδην αἱρείσθων. καὶ οἱ πρότερον κτείναντες ἐν τῷδε τῷ θεσμῷ ἐνεχέσθων. —τοὺς δ’ ἀπογιγνομένους ἐν τοῖς δήμοις, οὓς ἂν μηδεὶς ἀναιρῆται, ἐπαγγελλέτω ὁ δήμαρχος τοῖς προσήκουσιν ἀναιρεῖν καὶ θάπτειν καὶ καθαίρειν τὸν δῆμον, τῇ ἡμέρᾳ ᾗ ἂν ἀπογένηται ἕκαστος αὐτῶν.", "st": "43.57"}, {"sp": "N", "t": "ἐπαγγέλλειν δὲ περὶ μὲν τῶν δούλων τῷ δεσπότῃ, περὶ δὲ τῶν ἐλευθέρων τοῖς τὰ χρήματ’ ἔχουσιν· ἐὰν δὲ μὴ ᾖ χρήματα τῷ ἀποθανόντι, τοῖς προσήκουσι τοῦ ἀποθανόντος ἐπαγγέλλειν. ἐὰν δὲ τοῦ δημάρχου ἐπαγγείλαντος μὴ ἀναιρῶνται οἱ προσήκοντες, ὁ μὲν δήμαρχος ἀπομισθωσάτω ἀνελεῖν καὶ καταθάψαι καὶ καθῆραι τὸν δῆμον αὐθημερόν, ὅπως ἂν δύνηται ὀλιγίστου· ἐὰν δὲ μὴ ἀπομισθώσῃ, ὀφειλέτω χιλίας δραχμὰς τῷ δημοσίῳ. ὅ τι δ’ ἂν ἀναλώσῃ, διπλάσιον πραξάσθω παρὰ τῶν ὀφειλόντων· ἐὰν δὲ μὴ πράξῃ, αὐτὸς ὀφειλέτω τοῖς δημόταις.—τοὺς δὲ μὴ ἀποδιδόντας τὰς μισθώσεις τῶν τεμενῶν τῶν τῆς θεοῦ καὶ τῶν ἄλλων θεῶν καὶ τῶν ἐπωνύμων ἀτίμους εἶναι καὶ αὐτοὺς καὶ γένος καὶ κληρονόμους τοὺς τούτων, ἕως ἂν ἀποδῶσιν.", "st": "43.58"}, {"sp": "N", "t": "ταῦτα πάντα, ὅσα οἱ νόμοι προστάττουσιν τοὺς προσήκοντας ποιεῖν, ἡμῖν προστάττουσιν καὶ ἀναγκάζουσιν ποιεῖν, ὦ ἄνδρες δικασταί. Μακαρτάτῳ δὲ τουτῳὶ οὐδὲν διαλέγονται οὐδὲ Θεοπόμπῳ τῷ πατρὶ τῷ τούτου· οὐδὲ γάρ εἰσιν ἐκ τοῦ οἴκου τοῦ Ἁγνίου τὸ παράπαν· πῶς ἂν οὖν τούτοις τι προστάττοιεν;", "st": "43.59"}, {"sp": "N", "t": "ἀλλ’ οὗτος, ὦ ἄνδρες δικασταί, πρὸς μὲν τοὺς νόμους καὶ τὰς μαρτυρίας, ἃς ἡμεῖς παρεχόμεθα, δίκαιον οὐδ’ ὁτιοῦν ἔχει λέγειν, ἀγανακτεῖ δὲ καὶ δεινά φησι πάσχειν, ὅτι τοῦ πατρὸς τετελευτηκότος ἀγωνίζεται. ἐκεῖνο δ’ οὐκ ἐνθυμεῖται Μακάρτατος, ὦ ἄνδρες δικασταί, ὅτι ὁ πατὴρ αὐτοῦ ἄνθρωπος ἦν θνητός, καὶ τετελεύτηκεν μετ’ ἄλλων πολλῶν καὶ νεωτέρων καὶ πρεσβυτέρων. ἀλλ’ εἰ Θεόπομπος τετελεύτηκεν ὁ τουτουὶ πατήρ, οἱ νόμοι οὐ τετελευτήκασιν, οὐδὲ τὸ δίκαιον [τετελεύτηκεν], οὐδ’ οἱ δικασταὶ οἱ τὴν ψῆφον ἔχοντες.", "st": "43.60"}, {"sp": "N", "t": "ἔστιν δ’ ὁ νῦν ἀγὼν καὶ ἡ διαδικασία οὐκ εἴ τις ἕτερος ἑτέρου πρότερος ἢ ὕστερος τετελεύτηκεν, ἀλλ’ εἰ μὴ προσήκει ἐξελαθῆναι ἐκ τοῦ οἴκου τοῦ Ἁγνίου τοὺς οἰκείους τοὺς Ἁγνίου, ἀνεψιοὺς ὄντας καὶ ἀνεψιῶν παῖδας Ἁγνίᾳ πρὸς πατρός, ὑπὸ τῶν ἐκ τοῦ Στρατίου οἴκου καὶ μηδὲν προσηκόντων ὥστε κληρονομεῖν τῶν Ἁγνίου, ἀλλὰ γένει ἀπωτέρω ὄντων. περὶ τούτου νῦν ἐσθ’ ὁ ἀγών.", "st": "43.61"}, {"sp": "N", "t": "ἔτι δὲ σαφέστερον γνώσεσθε, ὦ ἄνδρες δικασταί, καὶ ἐκ τοῦδε τοῦ νόμου, ὅτι Σόλων ὁ νομοθέτης σπουδάζει περὶ τοὺς οἰκείους, καὶ οὐ μόνον δίδωσιν τὰ καταλειφθέντα, ἀλλὰ καὶ προστάγματα ποιεῖται τὰ δυσχερῆ ἅπαντα τοῖς προσήκουσι. λέγε τὸν νόμον.", "st": "43.62"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "43.62"}, {"sp": "N", "t": "τὸν ἀποθανόντα προτίθεσθαι ἔνδον, ὅπως ἂν βούληται. ἐκφέρειν δὲ τὸν ἀποθανόντα τῇ ὑστεραίᾳ ᾗ ἂν προθῶνται, πρὶν ἥλιον ἐξέχειν. βαδίζειν δὲ τοὺς ἄνδρας πρόσθεν, ὅταν ἐκφέρωνται, τὰς δὲ γυναῖκας ὄπισθεν. γυναῖκα δὲ μὴ ἐξεῖναι εἰσιέναι εἰς τὰ τοῦ ἀποθανόντος μηδ’ ἀκολουθεῖν ἀποθανόντι, ὅταν εἰς τὰ σήματα ἄγηται, ἐντὸς ἑξήκοντ’ ἐτῶν γεγονυῖαν, πλὴν ὅσαι ἐντὸς ἀνεψιαδῶν εἰσι· μηδ’ εἰς τὰ τοῦ ἀποθανόντος εἰσιέναι, ἐπειδὰν ἐξενεχθῇ ὁ νέκυς, γυναῖκα μηδεμίαν πλὴν ὅσαι ἐντὸς ἀνεψιαδῶν εἰσίν.", "st": "43.62"}, {"sp": "N", "t": "οὐκ ἐᾷ εἰσιέναι οὗ ἂν ᾖ ὁ τετελευτηκώς, οὐδεμίαν γυναῖκα ἄλλην ἢ τὰς προσηκούσας μέχρι ἀνεψιότητος, καὶ πρὸς τὸ μνῆμα ἀκολουθεῖν τὰς αὐτὰς ταύτας. Φυλομάχη τοίνυν ἡ Πολέμωνος ἀδελφὴ τοῦ πατρὸς τοῦ Ἁγνίου οὐκ ἀνεψιὰ ἦν Ἁγνίᾳ, ἀλλὰ τηθίς· ἀδελφὴ γὰρ ἦν Πολέμωνος τοῦ πατρὸς τοῦ Ἁγνίου. Εὐβουλίδης δὲ ὁ υἱὸς ταύτης τῆς γυναικὸς ἀνεψιὸς ἦν πρὸς πατρὸς Ἁγνίᾳ, οὗ ἐστιν ὁ κλῆρος. τοῦ δ’ Εὐβουλίδου ἦν θυγάτηρ ἡ τούτου τοῦ παιδὸς μήτηρ.", "st": "43.63"}, {"sp": "N", "t": "ταύτας κελεύει τὰς προσηκούσας καὶ παρεῖναι τῇ προθέσει τοῦ τετελευτηκότος καὶ ἐπὶ τὸ μνῆμα ἀκολουθεῖν, οὐ τὴν Μακαρτάτου μητέρα οὐδὲ τὴν Θεοπόμπου γυναῖκα· οὐδὲν γὰρ προσήκουσα Ἁγνίᾳ αὕτη, ἀλλ’ ἐξ ἑτέρας φυλῆς, Ἀκαμαντίδος, καὶ ἐξ ἑτέρου δήμου, Προσπαλτόθεν, ὥστε τὸ παράπαν οὐδ’ ᾔσθετο, ὅτε ἦν τετελευτηκὼς Ἁγνίας.", "st": "43.64"}, {"sp": "N", "t": "ὑπεραναίσχυντον δὴ οὗτοι κατασκευάζουσι πρᾶγμα, ὡς ἄρα δεῖ ἡμᾶς καὶ τὰς γυναῖκας τὰς ἡμετέρας τοῦ μὲν σώματος τοῦ Ἁγνίου, ὅτε ἐτετελευτήκει, κληρονόμους εἶναι καὶ ποιεῖν ἅπαντα τὰ νομιζόμενα, ὡς προσήκοντας καὶ γένει ὄντας ἐγγυτάτω, τὸν δὲ κλῆρον οἴεσθαι δεῖν ἔχειν τὸν Ἁγνίου τοῦ τετελευτηκότος Μακάρτατον, ἐκ τοῦ Στρατίου οἴκου ὄντα καὶ ἐκ τῆς Ἀπολήξιδος τοῦ Προσπαλτίου θυγατρός, Μακαρτάτου δὲ ἀδελφῆς. ἀλλ’ οὔτε δίκαιον οὔθ’ ὅσιον τοῦτ’ ἔστιν, ὦ ἄνδρες δικασταί.", "st": "43.65"}, {"sp": "N", "t": "ἀνάγνωθι δέ μοι τὰ ἐκ τῆς μαντείας τῆς ἐκ Δελφῶν κομισθείσης παρὰ τοῦ θεοῦ, ἵνα αἴσθησθε ὅτι ταὐτὰ λέγει περὶ τῶν προσηκόντων τοῖς νόμοις τοῖς τοῦ Σόλωνος.", "st": "43.66"}, {"sp": "N", "t": "ΜΑΝΤΕΙΑ.", "st": "43.66"}, {"sp": "N", "t": "ἀγαθῇ τύχῃ. ἐπερωτᾷ ὁ δῆμος ὁ Ἀθηναίων περὶ τοῦ σημείου τοῦ ἐν τῷ οὐρανῷ γενομένου, ὅ τι ἂν δρῶσιν Ἀθηναίοις ἢ ὅτῳ θεῷ θύουσιν ἢ εὐχομένοις εἴη ἐπὶ τὸ ἄμεινον ἀπὸ τοῦ σημείου. συμφέρει Ἀθηναίοις περὶ τοῦ σημείου τοῦ ἐν τῷ οὐρανῷ γενομένου θύοντας καλλιερεῖν Διὶ ὑπάτῳ, Ἀθηνᾷ ὑπάτῃ, Ἡρακλεῖ, Ἀπόλλωνι σωτῆρι, καὶ ἀποπέμπειν Ἀμφιόνεσσι· περὶ τύχας ἀγαθᾶς Ἀπόλλωνι ἀγυιεῖ, Λατοῖ, Ἀρτέμιδι, καὶ τὰς ἀγυιὰς κνισῆν, καὶ κρατῆρας ἱστάμεν καὶ χορούς, καὶ στεφαναφορεῖν καττὰ πάτρια· θεοῖς Ὀλυμπίοις καὶ Ὀλυμπίαις πάντεσσι καὶ πάσαις, δεξιὰς καὶ ἀριστερὰς ἀνίσχοντας, μνασιδωρεῖν καττὰ πάτρια· ἥρῳ ἀρχαγέτᾳ, οὗ ἐπώνυμοί ἐστε, θύειν καὶ δωροτελεῖν καττὰ πάτρια· τοῖς ἀποφθιμένοις ἐν ἱκνουμένᾳ ἁμέρᾳ τελεῖν τοὺς ποθίκοντας καττὰ ἁγημένα.", "st": "43.66"}, {"sp": "N", "t": "ἀκούετε, ἄνδρες δικασταί, ὅτι ταὐτὰ λέγει ὅ τε Σόλων ἐν τοῖς νόμοις καὶ ὁ θεὸς ἐν τῇ μαντείᾳ, κελεύων τοῖς κατοιχομένοις ποιεῖν τοὺς προσήκοντας ἐν ταῖς καθηκούσαις ἡμέραις. ἀλλὰ τούτων οὐδὲν ἔμελεν Θεοπόμπῳ οὐδὲ Μακαρτάτῳ τουτῳί, ἀλλὰ τοῦτο μόνον, τὰ μὴ προσήκοντα ἑαυτοῖς ἔχειν, καὶ ἐγκαλεῖν ὅτι πολὺν χρόνον ἐχόντων ἑαυτῶν τὸν κλῆρον νυνὶ ἀγωνίζονται. ἐγὼ δὲ ᾤμην, ὦ ἄνδρες δικασταί, προσήκειν τὸν τἀλλότρια ἀδίκως ἔχοντα οὐκ ἐγκαλεῖν, εἰ πλείω χρόνον εἶχεν, ἀλλὰ χάριν εἰδέναι, μὴ ἡμῖν, ἀλλὰ τῇ τύχῃ, ὅτι πολλαὶ καὶ ἀναγκαῖαι διατριβαὶ ἐγένοντο ἐν τῷ μεταξὺ χρόνῳ, ὥστε νῦν περὶ τούτων ἀγωνίζεσθαι.", "st": "43.67"}, {"sp": "N", "t": "οὗτοι μὲν οὖν τοιοῦτοί εἰσιν ἄνθρωποι, ὦ ἄνδρες δικασταί, καὶ μέλει αὐτοῖς οὐδὲν οὔτε τοῦ οἴκου ἐξερημουμένου τοῦ Ἁγνίου οὔτε τῶν ἄλλων ὅσα παρανομοῦσιν· οἵτινές γε, ὦ Ζεῦ καὶ θεοί, τὰ μὲν ἄλλα τί ἄν τις λέγοι περὶ τούτων; πολλὰ γὰρ ἂν εἴη λέγειν· ἓν δὲ ὃ παρανομώτατον καὶ μιαρώτατον διαπεπραγμένοι εἰσίν, καὶ μάλιστα ἐνδεικνύμενοι ὅτι οὐδὲν αὐτοῖς μέλει πλὴν τοῦ πλεονεκτεῖν·", "st": "43.68"}, {"sp": "N", "t": "οὐ γὰρ ἔφθη Θεόπομπος τὴν ἐπιδικασίαν ποιησάμενος τοῦ κλήρου τοῦ Ἁγνίου τὸν τρόπον τοῦτον ὃν ὑμεῖς ἀκηκόατε, καὶ εὐθὺς ἐνεδείξατο ὅτι τὰ οὐδὲν προσήκοντα ἑαυτῷ ἔχειν ἐνόμιζεν. ὃ γὰρ ἦν πλείστου ἄξιον ἐν τοῖς χωρίοις τοῖς Ἁγνίου καὶ ἐθαυμάζετο μάλιστα ὑπὸ τῶν προσχώρων καὶ ὑπὸ τῶν ἄλλων ἀνθρώπων, αἱ ἐλᾶαι, ταύτας ἐξώρυττον καὶ ἐξεπρέμνιζον, πλέον ἢ χίλια στελέχη, ὅθεν ἔλαιον πολὺ ἐγίγνετο. ταύτας οὗτοι ἀπέδοντο ἐκπρεμνίσαντες, καὶ ἀργύριον ὑπέρπολυ ἔλαβον. καὶ ταῦτ’ ἐποίουν οὗτοι ἐπιδίκου ὄντος τοῦ κλήρου τοῦ Ἁγνίου κατὰ τὸν νόμον, καθ’ ὅνπερ οὗτοι τὴν τουτουὶ μητέρα προσεκαλέσαντο.", "st": "43.69"}, {"sp": "N", "t": "ὅτι δὲ ταῦτ’ ἀληθῆ λέγω, καὶ ἐξεπρέμνισαν οὗτοι τὰς ἐλάας ἐκ τῶν χωρίων ὧν Ἁγνίας κατέλιπεν, μάρτυρας ὑμῖν τούτων παρεξόμεθα τούς τε προσχώρους καὶ τῶν ἄλλων οὓς παρεκαλέσαμεν, ὅτ’ ἐπεμαρτυρόμεθα περὶ τούτων. λέγε τὴν μαρτυρίαν.", "st": "43.70"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ", "st": "43.70"}, {"sp": "N", "t": "μαρτυροῦσιν ἀκολουθῆσαι Ἀραφῆνάδε παρακληθέντες ὑπὸ Σωσιθέου εἰς τοὺς Ἁγνίου ἀγρούς, ἐπειδὴ Θεόπομπος ἐπεδικάσατο τοῦ κλήρου τοῦ Ἁγνίου, καὶ ἐπιδεικνύναι αὑτοῖς Σωσίθεον τὰς ἐλάας πρεμνιζομένας ἐκ τοῦ Ἁγνίου ἀγροῦ.", "st": "43.70"}, {"sp": "N", "t": "εἰ μὲν τοίνυν, ὦ ἄνδρες δικασταί, τὸν τετελευτηκότα μόνον ὕβριζον ταῦτα διαπραξάμενοι, δεινὰ μὲν ⟨ἂν⟩ ἐποίουν, ἧττον δέ· νῦν δὲ καὶ εἰς ὅλην τὴν πόλιν ταυτὶ ὑβρίκασι καὶ παρανενομήκασιν. γνώσεσθε δέ, ἐπειδὰν τοῦ νόμου ἀκούσητε. ἀναγίγνωσκε τὸν νόμον.", "st": "43.71"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "43.71"}, {"sp": "N", "t": "ἐάν τις ἐλάαν Ἀθήνησιν ἐξορύττῃ, ἐὰν μὴ εἰς ἱερὸν Ἀθηναίων δημόσιον ἢ δημοτικόν, ἢ ἑαυτῷ χρῆσθαι μέχρι δυοῖν ἐλάαιν τοῦ ἐνιαυτοῦ ἑκάστου, ἢ ἐπὶ ἀποθανόντα δέῃ χρήσασθαι, ὀφείλειν ἑκατὸν δραχμὰς τῷ δημοσίῳ τῆς ἐλάας ἑκάστης, τὸ δὲ ἐπιδέκατον τούτου τῆς θεοῦ εἶναι. ὀφειλέτω δὲ καὶ τῷ ἰδιώτῃ τῷ ἐπεξιόντι ἑκατὸν δραχμὰς καθ’ ἑκάστην ἐλάαν. τὰς δὲ δίκας εἶναι περὶ τούτων πρὸς τοὺς ἄρχοντας, ὧν ἕκαστοι δικασταί εἰσι. πρυτανεῖα δὲ τιθέτω ὁ διώκων τοῦ αὑτοῦ μέρους. ὅτου δ’ ἂν καταγνωσθῇ, ἐγγραφόντων οἱ ἄρχοντες, πρὸς οὓς ἂν ᾖ ἡ δίκη, τοῖς πράκτορσιν, ὃ τῷ δημοσίῳ γίγνεται· ⟨ὃ δὲ τῇ θεῷ γίγνεται⟩, τοῖς ταμίαις τῶν τῆς θεοῦ. ἐὰν δὲ μὴ ἐγγράφωσιν, αὐτοὶ ὀφειλόντων.", "st": "43.71"}, {"sp": "N", "t": "ὁ μὲν νόμος οὗτος οὕτως ἰσχυρός. ἐκεῖνο δ’ ἐνθυμεῖσθε πρὸς ὑμᾶς αὐτούς, ὦ ἄνδρες δικασταί, τί ποτ’ οἴεσθ’ ἡμᾶς πάσχειν ἐν τῷ παρεληλυθότι χρόνῳ ὑπὸ τούτων καὶ ὑπὸ τῆς ὕβρεως τῆς τούτων, ὅπου ὑμῶν, πόλεως τηλικαυτησί, κατεφρόνησαν καὶ τῶν νόμων τῶν ὑμετέρων, καὶ ἃ διαρρήδην ἀπαγορεύουσιν οἱ νόμοι μὴ ποιεῖν, οὑτωσὶ καταφρονητικῶς ᾐκίσαντο τὰ χωρία ἃ κατέλιπεν Ἁγνίας. ὁ δὲ νόμος ἀπαγορεύει μηδ’ ἐκ τοῦ αὑτοῦ χωρίου τοῦ πατρῴου μηδὲν τούτων ποιεῖν. πολύ γε αὐτοῖς μέλει ἢ τοῖς νόμοις τοῖς ὑμετέροις πείθεσθαι, ἢ ὅπως μὴ ἐξερημωθήσεται ὁ οἶκος ὁ Ἁγνίου.", "st": "43.72"}, {"sp": "N", "t": "ἐγὼ δέ, ὦ ἄνδρες δικασταί, βούλομαι περὶ ἐμαυτοῦ πρὸς ὑμᾶς εἰπεῖν διὰ βραχέων, καὶ ἐπιδεῖξαι ὅτι οὐχ ὁμοίως τούτοις ἐπιμέλειαν ἐποιησάμην τοῦ οἴκου τοῦ Ἁγνίου, ὅπως μὴ ἐξερημωθήσεται. καὶ αὐτὸς γάρ εἰμι τοῦ γένους τοῦ Βουσέλου. Ἅβρωνος γὰρ τοῦ Βουσέλου υἱέος ἔλαβεν τὴν θυγατριδῆν Καλλίστρατος, Εὐβουλίδου μὲν υἱὸς ὤν, Βουσέλου δ’ ὑϊδοῦς· καὶ ἐκ τῆς Ἅβρωνος θυγατριδῆς καὶ ἐκ Καλλιστράτου τοῦ ἀδελφιδοῦ τοῦ Ἅβρωνος ἐγένετο ἡ μήτηρ ἡ ἡμετέρα.", "st": "43.73"}, {"sp": "N", "t": "ἐγὼ δὲ ἐπειδὴ ἐπεδικασάμην τῆς τούτου μητρὸς καὶ ἐγένοντό μοι υἱεῖς μὲν τέτταρες, θυγάτηρ δὲ μία, τὰ ὀνόματα ἐθέμην τούτοις, ὦ ἄνδρες δικασταί, τῷ μὲν πρεσβυτάτῳ τὸ τοῦ πατρὸς τοῦ ἐμαυτοῦ ὄνομα, Σωσίαν, ὥσπερ καὶ δίκαιόν ἐστιν, καὶ ἀπέδωκα τῷ πρεσβυτάτῳ τοῦτο τὸ ὄνομα· τῷ δὲ μετ’ αὐτὸν γενομένῳ τούτῳ ἐθέμην Εὐβουλίδην, ὅπερ ἦν ὄνομα τῷ πατρὶ τῷ τῆς μητρὸς τοῦ παιδὸς τουτουί· τῷ δὲ μετὰ τοῦτον Μενεσθέα ἐθέμην (καὶ γὰρ ὁ Μενεσθεὺς οἰκεῖος ἦν τῆς ἐμῆς γυναικός)· τῷ δὲ νεωτάτῳ ἐθέμην ὄνομα Καλλίστρατον, ὃ ἦν ὄνομα τῷ πατρὶ τῆς ἐμῆς μητρός. ἔτι δὲ πρὸς τούτοις καὶ τὴν θυγατέρα ἔδωκα οὐδαμόσε ἔξω, ἀλλὰ τῷ ἀδελφιδῷ τῷ ἐμαυτοῦ, ὅπως, ἐὰν ὑγιαίνωσιν, καὶ οἱ ἐκ τούτων ἐκ τοῦ αὐτοῦ γένους ὦσιν Ἁγνίᾳ.", "st": "43.74"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν τοῦτον τὸν τρόπον διῴκησα, ὅπως ἂν διασῴζωνται ὅτι μάλιστα οἱ οἶκοι οἱ ἀπὸ τοῦ Βουσέλου· τούτους δὲ ἐξετάσωμεν πάλιν. καὶ πρώτιστον μὲν τὸν νόμον τουτονὶ ἀνάγνωθι.", "st": "43.75"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "43.75"}, {"sp": "N", "t": "ὁ ἄρχων ἐπιμελείσθω τῶν ὀρφανῶν καὶ τῶν ἐπικλήρων καὶ τῶν οἴκων τῶν ἐξερημουμένων καὶ τῶν γυναικῶν, ὅσαι μένουσιν ἐν τοῖς οἴκοις τῶν ἀνδρῶν τῶν τεθνηκότων φάσκουσαι κυεῖν. τούτων ἐπιμελείσθω καὶ μὴ ἐάτω ὑβρίζειν μηδένα περὶ τούτους. ἐὰν δέ τις ὑβρίζῃ ἢ ποιῇ τι παράνομον, κύριος ἔστω ἐπιβάλλειν κατὰ τὸ τέλος. ἐὰν δὲ μείζονος ζημίας δοκῇ ἄξιος εἶναι, προσκαλεσάμενος πρόπεμπτα καὶ τίμημα ἐπιγραψάμενος, ὅ τι ἂν δοκῇ αὐτῷ, εἰσαγέτω εἰς τὴν ἡλιαίαν. ἐὰν δ’ ἁλῷ, τιμάτω ἡ ἡλιαία περὶ τοῦ ἁλόντος, ὅ τι χρὴ αὐτὸν παθεῖν ἢ ἀποτεῖσαι.", "st": "43.75"}, {"sp": "N", "t": "πῶς ἂν μᾶλλον ἐξερημώσαιεν ἄνθρωποι οἶκον, ἢ εἴ τινες τούς τε γένει ὄντας ἐγγυτάτω Ἁγνίᾳ, τούτους ἐξελαύνοιεν ἐξ ἑτέρου οἴκου ὄντες, τοῦ Στρατίου, καὶ πάλιν εἰ τὸν μὲν κλῆρον ἀξιοῖ ἔχειν τὸν Ἁγνίου ὡς γένει προσήκων, τὸ δ’ ὄνομα, ὅ ἐστιν αὐτῷ, μὴ ὅτι ἐκ τοῦ Ἁγνίου οἴκου, ἀλλ’ οὐδ’ ἐκ τοῦ Στρατίου ἐστὶν τοῦ ἑαυτοῦ προγόνου, οὐδὲ τῶν ἄλλων ἀπογόνων τῶν Βουσέλου, τοσούτων γενομένων, οὐδενὸς ἔχει τὸ ὄνομα;", "st": "43.76"}, {"sp": "N", "t": "ἀλλὰ πόθεν δή ἐστι τὸ ὄνομα ὁ Μακάρτατος; ἐκ τῶν πρὸς μητρός. εἰσεποιήθη γὰρ οὗτος εἰς τὸν οἶκον τὸν Μακαρτάτου τοῦ Προσπαλτίου, ἀδελφοῦ ὄντος τῆς μητρὸς τῆς τούτου, καὶ ἔχει καὶ ἐκεῖνον τὸν οἶκον. καὶ οὕτως ἐστὶν ὑβριστής, ὥστε γενομένου αὐτῷ υἱέος τοῦ μὲν εἰσαγαγεῖν εἰς τὸν οἶκον τὸν Ἁγνίου υἱὸν τῷ Ἁγνίᾳ ἐπελάθετο, καὶ ταῦτα ἔχων τὸν κλῆρον τὸν Ἁγνίου καὶ φάσκων πρὸς ἀνδρῶν αὐτῷ προσήκειν·", "st": "43.77"}, {"sp": "N", "t": "τοῦτον δὲ τὸν υἱὸν τὸν γενόμενον τῷ Μακαρτάτῳ εἰσπεποίηκεν τῷ πρὸς μητρὸς εἰς τοὺς Προσπαλτίους, τὸν δὲ Ἁγνίου οἶκον εἴακεν ἔρημον εἶναι τὸ τούτου μέρος· φησὶ δὲ τὸν πατέρα τὸν ἑαυτοῦ Θεόπομπον προσήκειν Ἁγνίᾳ. ὁ δὲ νόμος κελεύει ὁ τοῦ Σόλωνος κρατεῖν τοὺς ἄρρενας καὶ τοὺς ἐκ τῶν ἀρρένων· οὗτος δὲ οὑτωσὶ ῥᾳδίως κατεφρόνησεν καὶ τῶν νόμων καὶ τοῦ Ἁγνίου, καὶ εἰσεποίησεν τὸν υἱὸν εἰς τὸν οἶκον τὸν πρὸς μητρός. πῶς ἂν γένοιντο τούτων ἄνθρωποι παρανομώτεροι ἢ βιαιότεροι;", "st": "43.78"}, {"sp": "N", "t": "οὐ τοίνυν ταῦτα μόνον, ὦ ἄνδρες δικασταί, ἀλλὰ καὶ μνήματος ὄντος κοινοῦ ἅπασιν τοῖς ἀπὸ τοῦ Βουσέλου γενομένοις (καὶ καλεῖται τὸ μνῆμα Βουσελιδῶν, πολὺς τόπος περιβεβλημένος, ὥσπερ οἱ ἀρχαῖοι ἐνόμιζον), ἐν τούτῳ τῷ μνήματι οἱ μὲν ἄλλοι ἅπαντες οἱ ἀπὸ τοῦ Βουσέλου κεῖνται, καὶ ὁ Ἁγνίας καὶ ὁ Εὐβουλίδης καὶ ὁ Πολέμων καὶ οἱ ἄλλοι ἅπαντες τοσοῦτοι ὄντες συγγενεῖς, οἱ ἀπὸ τοῦ Βουσέλου, ἅπαντες οὗτοι κοινωνοῦσιν τοῦ μνήματος τούτου·", "st": "43.79"}, {"sp": "N", "t": "ὁ δὲ τουτουὶ πατὴρ Μακαρτάτου καὶ ὁ πάππος οὐ κεκοινωνήκασιν τούτου, ἀλλ’ αὑτοῖς ἰδίᾳ ἐποιήσαντο μνῆμα ἄπωθεν τοῦ Βουσελιδῶν μνήματος. δοκοῦσιν ὑμῖν, ὦ ἄνδρες δικασταί, προσήκειν τι τῷ οἴκῳ τῷ Ἁγνίου, πλὴν τοῦ ἔχειν ἁρπάσαντες τὰ μὴ προσήκοντα; εἰ δ’ ἐξερημωθήσεται ἢ ἀνώνυμος ἔσται ὁ οἶκος ὁ Ἁγνίου καὶ ὁ Εὐβουλίδου τοῦ ἀνεψιοῦ τοῦ Ἁγνίου, οὐδὲ κατὰ τοὐλάχιστον πώποτ’ αὐτοῖς ἐμέλησεν.", "st": "43.80"}, {"sp": "N", "t": "ἐγὼ δ’, ὦ ἄνδρες δικασταί, βοηθῶ μὲν ὡς οἷός τ’ εἰμὶ μάλιστα τοῖς τετελευτηκόσιν ἐκείνοις· οὐ πάνυ δ’ ἐστὶ ῥᾴδιον ταῖς τούτων παρασκευαῖς ἀνταγωνίζεσθαι. παραδίδωμι οὖν ὑμῖν τὸν παῖδα τουτονί, ὦ ἄνδρες δικασταί, ἐπιμεληθῆναι, ὅπως ὑμῖν δοκεῖ δικαιότατον εἶναι. οὗτος εἰσπεποίηται εἰς τὸν οἶκον τὸν Εὐβουλίδου, καὶ εἰσῆκται εἰς τοὺς φράτερας, οὐκ εἰς τοὺς ἐμούς, ἀλλ’ εἰς τοὺς Εὐβουλίδου καὶ Ἁγνίου καὶ Μακαρτάτου τουτουί.", "st": "43.81"}, {"sp": "N", "t": "καὶ ὅτε εἰσήγετο, οἱ μὲν ἄλλοι φράτερες κρύβδην ἔφερον τὴν ψῆφον, οὑτοσὶ δὲ Μακάρτατος φανερᾷ τῇ ψήφῳ ἐψηφίσατο ὀρθῶς εἰσάγεσθαι Εὐβουλίδῃ υἱὸν τὸν παῖδα τουτονί, οὐκ ἐθελήσας ἅψασθαι τοῦ ἱερείου οὐδὲ ἀπαγαγεῖν ἀπὸ τοῦ βωμοῦ ὑπεύθυνον αὑτὸν ποιήσας, ἀλλὰ καὶ τὴν μερίδα τῶν κρεῶν ᾤχετο λαβὼν παρὰ τοῦ παιδὸς τουτουί, ὥσπερ καὶ οἱ ἄλλοι φράτερες.", "st": "43.82"}, {"sp": "N", "t": "νομίζετε δὴ τὸν παῖδα τοῦτον, ὦ ἄνδρες δικασταί, ἱκετηρίαν ὑμῖν προκεῖσθαι ὑπὲρ τῶν τετελευτηκότων Ἁγνίου καὶ Εὐβουλίδου καὶ τῶν ἄλλων τῶν ἀπὸ τοῦ Ἁγνίου, καὶ ἱκετεύειν αὐτοὺς ὑμᾶς τοὺς δικαστάς, ὅπως μὴ ἐξερημωθήσεται αὐτῶν ὁ οἶκος ὑπὸ τῶν μιαρῶν τούτων θηρίων, οἵ εἰσιν ἐκ τοῦ Στρατίου οἴκου, ἐν δὲ τῷ Ἁγνίου οὐδεπώποτ’ ἐγένοντο· μηδ’ ἐπιτρέψητε τούτοις ἔχειν τὰ μὴ προσήκοντα, ἀλλ’ ἀποδοῦναι ἀναγκάσατε εἰς τὸν Ἁγνίου οἶκον τοῖς προσήκουσιν τοῖς Ἁγνίου.", "st": "43.83"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν ἐκείνοις τε βοηθῶ τοῖς τετελευτηκόσιν καὶ τοῖς νόμοις τοῖς περὶ τούτων κειμένοις, δέομαι δὲ καὶ ὑμῶν, ὦ ἄνδρες δικασταί, καὶ ἱκετεύω καὶ ἀντιβολῶ, μὴ περιίδητε μήτε τὸν παῖδα τουτονὶ ὑβρισθέντα ὑπὸ τούτων, μήτε τοὺς προγόνους τοὺς τούτου ἔτι μᾶλλον καταφρονουμένους ἢ νῦν καταπεφρόνηνται, ἐὰν διαπράξωνται οὗτοι ἃ βούλονται· ἀλλὰ τοῖς τε νόμοις βοηθεῖτε καὶ τῶν τετελευτηκότων ἐπιμελεῖσθε, ὅπως μὴ ἐξερημωθῇ αὐτῶν ὁ οἶκος. καὶ ταῦτα ποιοῦντες τά τε δίκαια ψηφιεῖσθε καὶ τὰ εὔορκα καὶ τὰ ὑμῖν αὐτοῖς συμφέροντα.", "st": "43.84"}, {"sp": "HDR", "t": "Πρὸς Λεωκάρη περὶ τοῦ Ἀρχιάδου κλήρου", "st": "44"}, {"sp": "N", "t": "αἴτιος μέν ἐστι Λεωχάρης οὑτοσί, ὦ ἄνδρες δικασταί, τοῦ καὶ αὐτὸς κρίνεσθαι καὶ ἐμὲ νεώτερον ὄντα λέγειν ἐν ὑμῖν, ἀξιῶν κληρονομεῖν ὧν οὐ προσῆκεν αὐτῷ, καὶ ὑπὲρ τούτων ψευδῆ διαμαρτυρίαν πρὸς τῷ ἄρχοντι ποιησάμενος.", "st": "44.1"}, {"sp": "N", "t": "ἡμῖν μὲν γὰρ ἀναγκαῖον ἦν, τοῦ νόμου τὰς ἀγχιστείας τοῖς ἐγγυτάτω γένους ἀποδιδόντος, οὖσιν οἰκείοις Ἀρχιάδου τοῦ ἐξ ἀρχῆς καταλιπόντος τὸν κλῆρον, μήτε τὸν οἶκον ἐξερημωθέντα τὸν ἐκείνου περιιδεῖν μήτε τῆς οὐσίας ἑτέρους κληρονομήσαντας, οἷς οὐδ’ ὁτιοῦν προσήκει· οὑτοσὶ δὲ οὔτε γόνῳ τοῦ τετελευτηκότος υἱὸς ὢν οὔτ’ εἰσποιηθεὶς κατὰ τοὺς νόμους, ὡς ἐγὼ δείξω, διαμεμαρτύρηκεν οὕτως τὰ ψευδῆ προπετῶς, ἀφαιρούμενος ἡμῶν τὴν κληρονομίαν.", "st": "44.2"}, {"sp": "N", "t": "δέομαι δ’ ὑμῶν, ὦ ἄνδρες δικασταί, βοηθῆσαι τῷ τε πατρὶ τούτῳ καὶ ἐμοί, ἐὰν λέγωμεν τὰ δίκαια, καὶ μὴ περιιδεῖν πένητας ἀνθρώπους καὶ ἀσθενεῖς καταστασιασθέντας ὑπὸ παρατάξεως ἀδίκου. ἡμεῖς μὲν γὰρ ταῖς ἀληθείαις πιστεύοντες εἰσεληλύθαμεν, καὶ ἀγαπῶντες, ἄν τις ἡμᾶς ἐᾷ τῶν νόμων τυγχάνειν· οὗτοι δὲ τῇ παρασκευῇ καὶ τοῖς ἀναλώμασιν ἰσχυριζόμενοι διατετελέκασιν, εἰκότως οἶμαι· ἐκ γὰρ τῶν ἀλλοτρίων ῥᾳδίως ἀναλίσκουσιν, ὥστε καὶ τοὺς συνεροῦντας ὑπὲρ αὑτῶν καὶ τοὺς μαρτυρήσοντας τὰ ψευδῆ πολλοὺς πεπορίσθαι.", "st": "44.3"}, {"sp": "N", "t": "ὁ δὲ πατὴρ οὗτος (εἰρήσεται γάρ) ἅμα τῆς πενίας ἧς ὑμεῖς ἅπαντες ἴστε, καὶ τοῦ ἰδιώτης εἶναι φανερὰς ἔχων τὰς μαρτυρίας ἀγωνίζεται· διατελεῖ γὰρ ἐν Πειραιεῖ κηρύττων· τοῦτο δ’ ἐστὶν οὐ μόνον ἀπορίας ἀνθρωπίνης τεκμήριον, ἀλλὰ καὶ ἀσχολίας τῆς ἐπὶ τὸ πραγματεύεσθαι· ἀνάγκη γὰρ ἡμερεύειν ἐν τῇ ἀγορᾷ τὸν τοιοῦτον. ἃ δεῖ λογιζομένους ἐνθυμεῖσθαι ὅτι, εἰ μὴ τῷ δικαίῳ ἐπιστεύομεν, οὐκ ἄν ποτ’ εἰσήλθομεν εἰς ὑμᾶς.", "st": "44.4"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν τοιούτων καὶ προϊόντος τοῦ λόγου σαφέστερον ἀκούσεσθε· ὑπὲρ αὐτῆς δὲ τῆς διαμαρτυρίας καὶ τοῦ ἀγῶνος ἤδη νομίζω δεῖν διδάσκειν. εἰ μὲν οὖν, ὦ ἄνδρες δικασταί, ἐκ τῆς διαμαρτυρίας αὐτῆς Λεωχάρης ἔμελλεν ἀπολογούμενος δείξειν ὡς ἔστιν υἱὸς γνήσιος Ἀρχιάδου, οὐδὲν ἂν ἔδει πολλῶν λόγων, οὐδ’ ἄνωθεν ὑμᾶς ἐξετάζειν τὸ γένος τὸ ἡμέτερον·", "st": "44.5"}, {"sp": "N", "t": "ἐπειδὴ δὲ τὰ μὲν διαμεμαρτυρημένα ἕτερον τρόπον ἔχει, ὁ δὲ πολὺς τοῦ λόγου τουτοισὶ ἔσται ὡς εἰσεποιήθησαν, καὶ κατὰ τὴν ἀγχιστείαν γνήσιοι ὄντες δικαίως ἂν τῆς οὐσίας κληρονομοῖεν, ἀναγκαῖον, ὦ ἄνδρες δικασταί, διὰ ταῦτα μικρῷ ἄνωθεν τὰ περὶ τοῦ γένους ὑμῖν διεξελθεῖν· ἐὰν γὰρ τοῦτο σαφῶς μάθητε, οὐ μὴ παρακρουσθῆτε ὑπ’ αὐτῶν τῷ λόγῳ.", "st": "44.6"}, {"sp": "N", "t": "ἔστιν γὰρ ὁ μὲν ἀγὼν οὑτοσὶ κλήρου διαδικασία, ἀμφισβητεῖται δὲ παρὰ μὲν ἡμῶν κατὰ γένος ἡ ἀγχιστεία, παρὰ δὲ τούτων κατὰ ποίησιν· ὁμολογοῦμεν δ’ ἐναντίον ὑμῶν δεῖν τὰς ποιήσεις κυρίας εἶναι, ὅσαι ἂν κατὰ τοὺς νόμους δικαίως γένωνται. ὥστε ταύτας τὰς ὑποθέσεις μεμνημένοι, ἂν δείξωσιν ὑμῖν διδόντας τοὺς νόμους αὑτοῖς ἃ διαμεμαρτυρήκασιν, ψηφίσασθε αὐτοῖς τὸν κλῆρον.", "st": "44.7"}, {"sp": "N", "t": "καὶ ἐὰν ἐκ μὲν τῶν νόμων μὴ ὑπάρχῃ, δίκαια δὲ καὶ φιλάνθρωπα φαίνωνται λέγοντες, καὶ ὣς συγχωροῦμεν. ἵνα δὲ εἰδῆτε ὅτι κατὰ γένος ἐγγύτατα ὄντες οὐ μόνον τούτῳ ἐνισχυριζόμεθα, ἀλλὰ καὶ τοῖς ἄλλοις ἅπασιν, πρῶτον μὲν ὑπὲρ αὐτοῦ τοῦ γένους ὑμᾶς διδάξομεν, ὅθεν ἐστὶν ὁ κλῆρος· νομίζω γάρ, ἂν τούτῳ τῷ μέρει τοῦ ἀγῶνος σαφῶς παρακολουθήσητε, καὶ τῶν ἄλλων ὑμᾶς οὐδενὸς ἀπολειφθήσεσθαι.", "st": "44.8"}, {"sp": "N", "t": "τὸ γὰρ ἐξ ἀρχῆς, ὦ ἄνδρες δικασταί, γίγνονται Εὐθυμάχῳ τῷ Ὀτρυνεῖ υἱεῖς τρεῖς, Μειδυλίδης καὶ Ἄρχιππος καὶ Ἀρχιάδης, καὶ θυγάτηρ ᾗ ὄνομα ἦν Ἀρχιδίκη. τελευτήσαντος δὲ τοῦ πατρὸς αὐτοῖς, τὴν μὲν Ἀρχιδίκην ἐκδιδόασιν Λεωστράτῳ Ἐλευσινίῳ, αὐτῶν δὲ τριῶν ὄντων ὁ μὲν Ἄρχιππος τριηραρχῶν ἐτελεύτησεν τὸν βίον ἐν Μηθύμνῃ, ὁ δὲ Μειδυλίδης οὐ πολλῷ χρόνῳ γαμεῖ ὕστερον Μνησιμάχην Λυσίππου τοῦ Κριωέως θυγατέρα.", "st": "44.9"}, {"sp": "N", "t": "καὶ γίγνεται αὐτῷ θυγάτηρ ὄνομα Κλειτομάχη, ἣν ἐβουλήθη μὲν ἐκεῖνος ἀγάμῳ τῷ ἀδελφῷ ὄντι τῷ ἑαυτοῦ ἐκδοῦναι· ἐπειδὴ δὲ ὁ Ἀρχιάδης οὐκ ἔφη προαιρεῖσθαι γαμεῖν, ἀλλὰ καὶ τὴν οὐσίαν ἀνέμητον διὰ ταῦτα συγχωρήσας εἶναι ᾤκει καθ’ αὑτὸν ἐν τῇ Σαλαμῖνι, οὕτως ἤδη ὁ Μειδυλίδης ἐκδίδωσι τὴν αὑτοῦ θυγατέρα Ἀριστοτέλει Παλληνεῖ, τῷ πάππῳ τῷ ἐμῷ. καὶ γίγνονται ἐξ αὐτοῦ υἱεῖς τρεῖς, Ἀριστόδημός τε οὑτοσὶ ὁ πατὴρ ὁ ἐμὸς καὶ Ἁβρώνιχος ὁ θεῖος καὶ Μειδυλίδης, ὃς νῦν τετελευτηκὼς τυγχάνει.", "st": "44.10"}, {"sp": "N", "t": "καὶ ἡ μὲν τοῦ γένους ἀγχιστεία τοῦ ἡμετέρου, ἐν ᾧ ἐστιν ὁ κλῆρος, σχεδὸν οὕτως ἔχει, ὦ ἄνδρες δικασταί. Ἀρχιάδῃ γὰρ πρὸς ἀνδρῶν ἡμεῖς μὲν γένει ἐγγυτάτω, καὶ κατὰ τοῦτον τὸν νόμον ἀξιοῦντες τῆς ἐκείνου οὐσίας κληρονομεῖν καὶ τὸ γένος μὴ περιιδεῖν ἐξερημωθέν, ἐλάχομεν πρὸς τὸν ἄρχοντα τοῦ κλήρου· οὗτοι δὲ ἔχοντες οὐ δικαίως τὰ χρήματα διαμεμαρτυρήκασι νυνί, τὸ μὲν ὅλον ἰσχυριζόμενοι ποιήσει, φάσκοντες δὲ καὶ συγγενεῖς εἶναι.", "st": "44.11"}, {"sp": "N", "t": "περὶ μὲν οὖν ταύτης τῆς ποιήσεως, ὃν τρόπον ἔχει, σαφῶς ὑμᾶς ὕστερον διδάξομεν· περὶ δὲ τοῦ γένους, ὡς οὐκ εἰσὶν ἡμῶν ἐγγυτέρω, τοῦτο δεῖ μαθεῖν ὑμᾶς. ἓν μὲν οὖν ὁμολογεῖται, τὸ κρατεῖν τῶν κληρονόμων τοὺς ἄρρενας καὶ τοὺς ἐκ τῶν ἀρρένων· ἁπλῶς γὰρ τοῖς ἐγγυτάτω πρὸς ἀνδρῶν, ὅταν μὴ παῖδες ὦσιν, ὁ νόμος τὰς κληρονομίας ἀποδίδωσιν. οὗτοι δ’ ἐσμὲν ἡμεῖς· ἄπαις μὲν γὰρ ὁ Ἀρχιάδης ὁμολογεῖται τετελευτηκέναι, τούτῳ δὲ πρὸς ἀνδρῶν ἡμεῖς ἐσμεν ἐγγυτάτω.", "st": "44.12"}, {"sp": "N", "t": "[πρὸς δὲ καὶ ἐκ γυναικῶν οἱ αὐτοὶ οὗτοι·] ὁ γὰρ Μειδυλίδης ἀδελφὸς ἦν τοῦ Ἀρχιάδου, τοῦ δὲ Μειδυλίδου θυγάτηρ ἡ τοῦ ἐμοῦ πατρὸς μήτηρ, ὥστε γίγνεται Ἀρχιάδης, ὑπὲρ οὗ τοῦ κλήρου τὴν ἐπιδικασίαν ποιούμεθα νυνί, θεῖος τῇ τοῦ πατρὸς τοῦ ἐμοῦ μητρὶ ἐκ πατραδέλφων, πρὸς ἀνδρῶν ἔχων τὴν συγγένειαν ταύτην καὶ οὐ πρὸς γυναικῶν. Λεώστρατος δ’ οὑτοσὶ γένει τε ἀπωτέρω ἐστὶν καὶ πρὸς γυναικῶν οἰκεῖος Ἀρχιάδῃ· ἡ γὰρ [τοῦ] Λεωκράτους μήτηρ τοῦ τούτου πατρὸς ἀδελφιδῆ ἦν τῷ Ἀρχιάδῃ ἐκείνῳ καὶ τῷ Μειδυλίδῃ, ἀφ’ ὧν ἡμεῖς ὄντες ἀξιοῦμεν τῆς κληρονομίας τυχεῖν.", "st": "44.13"}, {"sp": "N", "t": "πρῶτον μὲν οὖν, ὦ ἄνδρες δικασταί, τὸ γένος ἡμῶν ὅτι οὕτως ἔχει ὥσπερ καὶ λέγομεν, ἀναγνώσεται ὑμῖν τὰς μαρτυρίας, ἔπειτα μετὰ ταῦτα τὸν νόμον αὐτὸν ⟨τὸν⟩ τοῖς τε γένεσι καὶ τοῖς ἐγγυτάτω πρὸς ἀνδρῶν τὰς κληρονομίας ἀποδιδόντα· τὰ γὰρ κεφάλαια τοῦ ἀγῶνος, καὶ ὑπὲρ ὧν ὀμωμοκότες οἴσετε τὴν ψῆφον, σχεδόν τι ταῦτ’ ἔστιν. καί μοι κάλει τούς τε μάρτυρας δευρὶ καὶ τὸν νόμον ἀναγίγνωσκε.", "st": "44.14"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ. ΝΟΜΟΣ.", "st": "44.14"}, {"sp": "N", "t": "τὰ μὲν τοίνυν περὶ τὸ γένος τό τε τούτων καὶ τὸ ἡμέτερον οὕτως ἔχει, ὦ ἄνδρες δικασταί, ὥστε τοὺς ἐπιδεδειχότας ἐξ αὐτῶν τῶν μαρτυριῶν ὡς εἰσὶν γένει ἐγγυτέρω προσήκει κληρονομεῖν, καὶ μὴ τὴν τοῦ διαμαρτυρήσαντος ἀπόνοιαν κρείττω τῶν ὑμετέρων νόμων γενέσθαι. καὶ γὰρ εἰ τῇ ποιήσει ἰσχυρίζονται, ἣν ὡς ἐγένετο ἡμεῖς δείξομεν, τετελευτηκότος γε τοῦ εἰσποιηθέντος δήπου ἄπαιδος καὶ τοῦ οἴκου μέχρι τῆς ἡμετέρας λήξεως ἐξηρημωμένου, πῶς οὐ προσήκει τοὺς ἐγγυτάτω γένει ὄντας, τούτους τὴν κληρονομίαν κομίσασθαι, καὶ ὑμᾶς μὴ τοῖς δυναμένοις ἄριστα παρασκευάσασθαι, ἀλλὰ τοῖς ἀδικουμένοις τῶν πολιτῶν βοηθεῖν;", "st": "44.15"}, {"sp": "N", "t": "εἰ μὲν γὰρ ἐφ’ ἡμῖν ἦν ὥστε δείξασιν τὰ περὶ τοῦ γένους καὶ τῆς διαμαρτυρίας αὐτῆς καταβῆναι καὶ μηδενὸς ἔτι πλείονος λόγου προσδεῖσθαι, σχεδόν τι τῶν μεγίστων εἰρημένων οὐκ ἂν ἠνωχλοῦμεν τὰ πλείω. ἐπειδὴ δὲ οὗτοι τοῖς μὲν νόμοις οὐκ ἐνισχυριοῦνται, τῷ δὲ προειληφέναι τι τῶν πραγμάτων ἐκ τοῦ ἄνωθεν χρόνου καὶ τῷ ἐμβεβατευκέναι εἰς τὴν οὐσίαν, τούτοις τεκμηρίοις χρώμενοι φήσουσι κληρονομεῖν, ἀναγκαῖον ἴσως καὶ περὶ τούτων ἐστὶν εἰπεῖν καὶ δεῖξαι τούτους πάντων ἀνθρώπων βιαιοτάτους ὄντας.", "st": "44.16"}, {"sp": "N", "t": "τὸ γὰρ ἐξ ἀρχῆς, ὦ ἄνδρες δικασταί, ἐκδιδόασιν τὴν ἀδελφὴν τὴν ἑαυτῶν ὁ Μειδυλίδης καὶ ὁ Ἀρχιάδης Λεωστράτῳ Ἐλευσινίῳ· μετὰ δὲ ταῦτα ἐκ θυγατρὸς τῆς ἐκδοθείσης ἀδελφῆς ταύτης αὐτῶν γίγνεται Λεωκράτης ὁ πατὴρ Λεωστράτου τουτουί, σκέψασθε ὡς πολλοστὸς εἰς τὴν τοῦ Ἀρχιάδου συγγένειαν προσήκων, ὑπὲρ οὗ τὴν διαμαρτυρίαν πεποίηται. τούτων δ’ οὕτως ἐχόντων ὁ μὲν Ἀρχιάδης οὐκ ἐγάμει, ὁ δὲ Μειδυλίδης ὁ ἀδελφὸς αὐτοῦ, πάππος δὲ τουτουὶ ἔγημε.", "st": "44.17"}, {"sp": "N", "t": "καὶ οὐδέπω τὴν οὐσίαν ἐνέμοντο, ἀλλ’ ἑκάτερος ἔχων τὰ ἱκανὰ ὁ μὲν Μειδυλίδης ἐν τῷ ἄστει διέμενεν, ὁ δὲ Ἀρχιάδης ἐν Σαλαμῖνι ᾤκει. οὐ πολλῷ δὲ χρόνῳ ὕστερον ἀποδημίας τινὸς εἰς τὴν ὑπερορίαν συμβάσης τῷ Μειδυλίδῃ τῷ πάππῳ τῷ τοῦ πατρός, ἠρρώστησεν ὁ Ἀρχιάδης, καὶ τελευτᾷ τὸν βίον ἀπόντος τοῦ Μειδυλίδου ἄγαμος ὤν. τί τούτου σημεῖον; λουτροφόρος ἐφέστηκεν ἐπὶ τῷ τοῦ Ἀρχιάδου τάφῳ.", "st": "44.18"}, {"sp": "N", "t": "ἐν δὲ τούτῳ τῷ καιρῷ ἔχων τὴν τῆς συγγενείας τῆς πρὸς γυναικῶν πρόφασιν Λεωκράτης ὁ τουτουὶ πατὴρ Λεωστράτου εἰσποιεῖ αὑτὸν υἱὸν τῷ Ἀρχιάδῃ, καὶ ἐνεβάτευσεν οὕτως εἰς τὴν οὐσίαν ὡς ὑπ’ ἐκείνου ζῶντος ἔτι εἰσποιηθείς. ἀφικόμενος δὲ ὁ Μειδυλίδης ἠγανάκτει τε τῷ γεγενημένῳ καὶ οἷος ἦν ἐπεξιέναι τῷ Λεωκράτει· πειθόντων δὲ τῶν οἰκείων καὶ δεομένων ἐᾶν ἐν τῷ οἴκῳ εἶναι τὸν Λεωκράτην υἱὸν εἰσποιητὸν τῷ Ἀρχιάδῃ, συνεχώρησεν ὁ Μειδυλίδης, οὐχ ἡττηθεὶς ἐν δικαστηρίῳ, ἀλλὰ τὸ μὲν ὅλον ὑπὸ τούτων ἀπατηθείς, ἔπειτα μέντοι καὶ τοῖς οἰκείοις πειθόμενος.", "st": "44.19"}, {"sp": "N", "t": "καὶ ὁ μὲν Μειδυλίδης ταῦτα πράξας τελευτᾷ τὸν βίον, ὁ δὲ Λεωκράτης εἶχεν τὴν τοῦ Ἀρχιάδου οὐσίαν καὶ ἐκληρονόμει πολλὰ ἔτη ὡς ἂν ἐκείνου υἱὸς ποιητός· ἡμεῖς δὲ παρὰ τὸ τὸν Μειδυλίδην ταῦτα συγχωρῆσαι ἡσυχίαν εἴχομεν. χρόνῳ δ’ ὕστερον οὐ πολλῷ—τοῖς γὰρ μετὰ ταῦτα λόγοις ἤδη σφόδρα τὸν νοῦν προσέχετε, ὦ ἄνδρες δικασταί·", "st": "44.20"}, {"sp": "N", "t": "ὁ γὰρ Λεωκράτης ὁ εἰσποιητὸς γενόμενος τῷ Ἀρχιάδῃ, ἐγκαταλιπὼν τουτονὶ Λεώστρατον ἐν τῷ οἴκῳ υἱὸν γνήσιον, ἐπανῆλθεν αὐτὸς εἰς τοὺς Ἐλευσινίους, ὅθεν ἦν τὸ ἐξ ἀρχῆς. καὶ οὐδ’ ἐνταῦθα οὐδέπω ἡμεῖς οὐδὲν τῶν πραγμάτων ⟨τῶν⟩ περὶ τὸν κλῆρον ἐκινοῦμεν, ἀλλ’ ἐμένομεν ἐπὶ τῶν αὐτῶν.", "st": "44.21"}, {"sp": "N", "t": "πάλιν τοίνυν Λεώστρατος αὐτὸς οὑτοσί, εἰσποιητὸς ὢν υἱὸς καὶ ἐγκαταλειφθεὶς ἐν τῷ τοῦ Ἀρχιάδου οἴκῳ, ἐπανέρχεται, ὥσπερ ὁ πατὴρ αὐτοῦ, ἐπὶ τοὺς Ἐλευσινίους, ἐγκαταλιπὼν υἱὸν γνήσιον καὶ διὰ τριῶν σωμάτων κυρίαν τὴν ἐξ ἀρχῆς ποίησιν παρὰ τοὺς νόμους καταστήσας.", "st": "44.22"}, {"sp": "N", "t": "πῶς γὰρ οὐ παρὰ τοὺς νόμους, ὁπότ’ εἰσποιητὸς αὐτὸς ὢν εἰσποιητοὺς υἱοὺς ἐγκαταλείπων ἐπανῄει; καὶ τοῦτο διατετέλεκε ποιῶν μέχρι ταύτης τῆς ἡμέρας, καὶ διὰ τούτου τοῦ τρόπου τὴν κληρονομίαν ἡμῶν ἀποστερήσειν οἴονται, ἐνεργαζόμενοι μὲν καὶ ἐμπαιδοτροφούμενοι τῇ τοῦ Ἀρχιάδου οὐσίᾳ, ἐπανιόντες δὲ ἐπὶ τὴν πατρῴαν οὐσίαν ἐκεῖθεν ἀεί, κἀκείνην μὲν ἀκέραιον φυλάττοντες, ταύτην δ’ ἀναλίσκοντες.", "st": "44.23"}, {"sp": "N", "t": "ἀλλ’ ὅμως τούτων τοιούτων ὄντων, ὅπερ εἶπον, ἡμεῖς ὑπεμένομεν ἅπαντα. μέχρι τίνος; ἕως ὁ Λεωκράτης ὁ ὑπὸ Λεωστράτου ἐν τῷ οἴκῳ τῷ Ἀρχιάδου ἐγκαταλειφθεὶς υἱὸς τετελεύτηκεν ἄπαις. τούτου δὲ ἄπαιδος τετελευτηκότος, ἀξιοῦμεν ἡμεῖς οἱ γένει ἐγγυτάτω ὄντες Ἀρχιάδῃ κληρονομεῖν τῆς οὐσίας, καὶ μὴ τῷ τετελευτηκότι τῷ αὐτῷ εἰσποιητῷ ὄντι υἱὸν εἰσποιεῖν ἐπ’ ἀποστερήσει τῶν ἡμετέρων.", "st": "44.24"}, {"sp": "N", "t": "εἰ μὲν γὰρ αὐτὸς ζῶν ἐποιήσατο, καίπερ ὄντος παρὰ τὸν νόμον τοῦ ἔργου, οὐκ ἀντιλέγομεν· ἐπειδὴ δὲ οὔτε γόνῳ ἦν αὐτῷ υἱὸς οὐδεὶς οὔτ’ ἐποιήσατο ζῶν, ὁ δὲ νόμος τοῖς ἐγγύτατα γένους τὰς κληρονομίας ἀποδίδωσι, πῶς οὐ δίκαιοί ἐσμεν ἡμεῖς τούτων μὴ ἀποστερηθῆναι κατ’ ἀμφότερα;", "st": "44.25"}, {"sp": "N", "t": "καὶ γὰρ τῷ Ἀρχιάδῃ, οὗ ἦν ἡ οὐσία τὸ ἐξ ἀρχῆς, ἐγγυτάτω γένει ἐσμὲν καὶ τῷ εἰσποιητῷ Λεωκράτει· τοῦ μὲν γὰρ ὁ πατὴρ ἐπανεληλυθὼς εἰς τοὺς Ἐλευσινίους οὐκέτι τὴν κατὰ τὸν νόμον οἰκειότητα ἔλιπεν αὑτῷ, ἡμεῖς δέ, παρ’ οἷς ἦν ἐν τῷ γένει, τὴν ἀναγκαιοτάτην συγγένειαν εἴχομεν, ὄντες ἀνεψιαδοῖ ἐκείνῳ. ὥστ’ εἰ μὲν βούλει, τοῦ Ἀρχιάδου συγγενεῖς ὄντες ἀξιοῦμεν κληρονομεῖν, εἰ δὲ βούλει, τοῦ Λεωκράτους· τετελευτηκότος γὰρ ἄπαιδος αὐτοῦ, οὐδεὶς ἡμῶν γένει ἐγγυτέρω ἐστί.", "st": "44.26"}, {"sp": "N", "t": "καὶ διὰ μὲν σέ, ὦ Λεώστρατε, ὁ οἶκος ἐξηρήμωται· τῆς γὰρ οὐσίας τὴν οἰκειότητα, οὐ τῶν ἀνδρῶν τῶν ποιησαμένων διετήρεις. ἕως μέν γε τελευτήσαντος τούτου οὐδεὶς ἠμφεσβήτει τοῦ κλήρου, οὐδένα εἰσεποίεις τῷ Ἀρχιάδῃ υἱόν· ἐπειδὴ δὲ ἡμεῖς συγγενεῖς ὄντες ἥκομεν εἰς τὸ μέσον, τηνικαῦτα εἰσποιεῖς, ἵνα τὴν οὐσίαν κατάσχῃς. καὶ φὴς μὲν οὐδὲν εἶναι τῷ Ἀρχιάδῃ, πρὸς ὃν εἰσεποιήθης, διαμαρτυρεῖς δὲ πρὸς ἡμᾶς, τὸ ὁμολογούμενον γένος ἐξελαύνων· εἰ γὰρ μηδέν ἐστιν ἐν τῷ οἴκῳ, τί σὺ ἐλαττοῖ τοῦ μηδενὸς ἡμῶν κληρονομησάντων;", "st": "44.27"}, {"sp": "N", "t": "ἀλλὰ γὰρ ἡ ἀναίδεια καὶ ἡ πλεονεξία τοιαύτη ἐστὶν αὐτοῦ, ὦ ἄνδρες δικασταί, ὥσθ’ ἡγεῖσθαι δεῖν ἐν Ἐλευσινίοις τε τὴν πατρῴαν οὐσίαν ἐπανελθὼν ἔχειν, ἐφ’ ἅ τ’ εἰσεποιήθη μὴ ὄντος ἐν τῷ οἴκῳ υἱοῦ, καὶ τούτων κύριος γενέσθαι. καὶ ταῦτα πάντα ῥᾳδίως διοικεῖται· πρὸς γὰρ ἀνθρώπους ἡμᾶς πένητας καὶ ἀδυνάτους ἔχων ἀναλίσκειν ἐκ τῶν ἀλλοτρίων πολὺ περίεστιν. διόπερ οἶμαι ὑμᾶς δεῖν βοηθεῖν τοῖς μὴ πλεονεκτῆσαί τι βουλομένοις, ἀλλ’ ἀγαπῶσιν ἐάν τις ἡμᾶς τῶν νόμων ἐᾷ τυγχάνειν.", "st": "44.28"}, {"sp": "N", "t": "τί γὰρ δεῖ ποιεῖν ἡμᾶς, ὦ ἄνδρες δικασταί; διὰ τριῶν τῆς ποιήσεως ἐμμενούσης, καὶ τοῦ τελευταίου ἐγκαταλειφθέντος, τούτου ἄπαιδος τετελευτηκότος, μὴ κομίσασθαι τὰ ἡμέτερ’ αὐτῶν χρόνῳ ποτέ; τοῦτο τοίνυν ἔχοντες τὸ δίκαιον ἐλάχομεν τοῦ κλήρου πρὸς τὸν ἄρχοντα. οὑτοσὶ δὲ Λεωχάρης προπετῶς διαμαρτυρήσας τὰ ψευδῆ, οἴεται δεῖν παρὰ πάντας τοὺς νόμους ἀποστερῆσαι ἡμᾶς τῆς κληρονομίας.", "st": "44.29"}, {"sp": "N", "t": "πρῶτον μὲν οὖν, ὅτι τά τε περὶ τὰς ποιήσεις καὶ τὸ γένος τὸ τούτων ἀληθῆ εἰρήκαμεν, καὶ ἡ λουτροφόρος ἐφέστηκεν ἐπὶ τῷ τοῦ Ἀρχιάδου μνήματι, ταύτας ὑμῖν τὰς μαρτυρίας βουλόμεθ’ ἀναγνῶναι· ἔπειτ’ ἤδη καὶ τὰ λοιπὰ σαφῶς διδάξομεν ὑμᾶς, ὥστ’ ἐξελέγξαι τούτους τὰ ψευδῆ διαμεμαρτυρηκότας. καί μοι λαβὲ τὰς μαρτυρίας ἃς λέγω.", "st": "44.30"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "44.30"}, {"sp": "N", "t": "ὁ μὲν τοίνυν τοῦ πράγματος λόγος καὶ τὸ ἁπλοῦν δίκαιον περὶ τῆς κληρονομίας οὕτως ἔχει, ὦ ἄνδρες δικασταί, τῶν τε πεπραγμένων ἐξ ἀρχῆς αὐτὰ τὰ κεφάλαια σχεδόν τι ἀκηκόατε. ἃ δὲ μετὰ τὴν τοῦ κλήρου λῆξιν πεποιήκασι καὶ ὃν τρόπον ἡμῖν κεχρημένοι εἰσίν, ἀναγκαῖον νομίζω εἰπεῖν· οἴομαι γὰρ περὶ κλήρου ἀγῶνα μηδένας ἄλλους παρανενομῆσθαι τοιαῦτα οἷα ἡμᾶς.", "st": "44.31"}, {"sp": "N", "t": "ἐπειδὴ γὰρ ἐτελεύτησεν ὁ Λεωκράτης καὶ ἡ ταφὴ ἐγένετο αὐτῷ, πορευομένων ἡμῶν εἰς τὰ κτήματα διὰ τὸ ἄπαιδά τε τὸν ἄνδρα καὶ ἄγαμον τετελευτηκέναι, ἐξήγαγε Λεώστρατος οὑτοσὶ φάσκων αὑτοῦ εἶναι. καὶ ὅτι μὲν ποιεῖν τι τῶν νομιζομένων ἐκώλυσεν ἡμᾶς τῷ τετελευτηκότι, πατὴρ ὢν αὐτὸς ἐκείνου, ἴσως ἔχει λόγον, καίπερ ὄντος παρανόμου τοῦ ἔργου· τῷ γὰρ φύσει ὄντι πατρὶ τῆς ταφῆς τὴν ἐπιμέλειαν παραδίδοσθαι εἰκός ἐστιν, ἔπειτα μέντοι καὶ τοῖς οἰκείοις ἡμῖν, ὧν ἦν συγγενὴς κατὰ τὴν ποίησιν ὁ τετελευτηκώς.", "st": "44.32"}, {"sp": "N", "t": "ἐπεὶ δὲ τὰ νομιζόμενα ἐγένετο, κατὰ ποῖον νόμον φανεῖται ἐρήμου ὄντος τοῦ οἴκου τοὺς ἐγγυτάτω γένους ἡμᾶς ἐξαγαγὼν ἐκ τῆς οὐσίας; ὅτι νὴ Δία πατὴρ ἦν τοῦ τετελευτηκότος. ἀπεληλυθώς γ’ εἰς τὸν πατρῷον οἶκον καὶ οὐκέτι τῆς οὐσίας ἐφ’ ᾗ ἐγκατέλιπεν τὸ υἱόν, κύριος ὤν· εἰ δὲ μή, τί τῶν νόμων ὄφελος;", "st": "44.33"}, {"sp": "N", "t": "γενομένης οὖν τῆς ἐξαγωγῆς, ἵνα τὰ πλεῖστα παραλίπω, ἐλάχομεν πρὸς τὸν ἄρχοντα τοῦ κλήρου, οὔτε γόνῳ, ὥσπερ εἶπον, ⟨υἱέος⟩ οὐδενὸς ὄντος τῷ τετελευτηκότι, οὔτ’ εἰσποιητοῦ γεγενημένου κατὰ τοὺς νόμους. μετὰ δὲ ταῦτα Λεώστρατος οὑτοσὶ παρακαταβάλλει ὡς υἱὸς Ἀρχιάδου ἐκείνου, οὐκ ἐπιλογισάμενος οὔθ’ ὅτι ἐπανεληλύθει εἰς τοὺς Ἐλευσινίους, οὔθ’ ὅτι οἱ εἰσποιητοὶ οὐκ αὐτοὶ ὑφ’ αὑτῶν, ἀλλ’ ὑπὸ τῶν εἰσποιουμένων καθίστανται·", "st": "44.34"}, {"sp": "N", "t": "ἀλλὰ γὰρ οἶμαι ἁπλοῦν τι διελογίσατο, δεῖν αὑτὸν καὶ δικαίως καὶ ἀδίκως ἀμφισβητεῖν τῶν ἀλλοτρίων. καὶ πρῶτον μὲν ἐλθὼν οἷος ἦν εἰς τὸν Ὀτρυνέων πίνακα τὸν ἐκκλησιαστικὸν ἐγγράφειν αὑτὸν Ἐλευσίνιος ὤν, καὶ τοῦτο διῳκεῖτο, ἔπειτα, πρὶν ἐγγραφῆναι καὶ ἐν τῷ ληξιαρχικῷ γραμματείῳ τῷ τῶν Ὀτρυνέων, μετέχειν τῶν κοινῶν, τηλικαύτην παρανομίαν προαιρούμενος παρανομεῖν ἕνεκα πλεονεξίας.", "st": "44.35"}, {"sp": "N", "t": "αἰσθόμενοι δ’ ἡμεῖς μαρτύρων ἐναντίον ἐκωλύσαμεν τὸ γιγνόμενον, καὶ ᾠόμεθα δεῖν κριθῆναι πρῶτον τὴν κληρονομίαν παρ’ ὑμῖν, πρὶν ἐπὶ τὸ ὄνομά τινα τὸ τοῦ Ἀρχιάδου εἰσποιηθῆναι. κωλυθεὶς δὲ καὶ ἐξελεγχθεὶς πρὸς τῷ πίνακι καὶ ἐν τῇ τῶν ἀρχόντων ἀγορᾷ ὅτι ἠδίκει πολλῶν ἐναντίον, ᾤετο δεῖν μηδὲν ἧττον βιάζεσθαι καὶ κρείττων ταῖς παρασκευαῖς τῶν ὑμετέρων νόμων γενέσθαι.", "st": "44.36"}, {"sp": "N", "t": "τί τούτου τεκμήριον; συναγαγών τινας τῶν Ὀτρυνέων ὀλίγους καὶ τὸν δήμαρχον πείθει, ἐπειδὰν ἀνοιχθῇ τὸ γραμματεῖον, ἐγγράψαι αὑτόν. καὶ μετὰ ταῦτα ἧκε Παναθηναίων ὄντων τῶν μεγάλων τῇ διαδόσει πρὸς τὸ θεωρικόν, καὶ ἐπειδὴ οἱ ἄλλοι δημόται ἐλάμβανον, ἠξίου καὶ αὑτῷ δίδοσθαι καὶ ἐγγραφῆναι εἰς τὸ γραμματεῖον ἐπὶ τὸ τοῦ Ἀρχιάδου ὄνομα. διαμαρτυρομένων δὲ ἡμῶν, καὶ τῶν ἄλλων δεινὸν φασκόντων εἶναι τὸ γιγνόμενον, ἀπῆλθεν οὔτ’ ἐγγραφεὶς οὔτε τὸ θεωρικὸν λαβών.", "st": "44.37"}, {"sp": "N", "t": "τὸν δὲ παρὰ τὸ ψήφισμα τὸ ὑμέτερον ἀξιοῦντα τὸ θεωρικὸν λαμβάνειν πρὶν ἐγγραφῆναι εἰς τοὺς Ὀτρυνέας, ὄντα ἐξ ἑτέρου δήμου, τοῦτον οὐκ οἴεσθε τοῦ κλήρου παρὰ τοὺς νόμους ἀμφισβητεῖν; ἢ τὸν πρὸ τῆς τοῦ δικαστηρίου γνώσεως οὕτως ἀδίκους πλεονεξίας διοικούμενον, τοῦτον πῶς εἰκὸς τῷ πράγματι πιστεύειν; ὁ γὰρ τὸ θεωρικὸν ἀδίκως ἀξιώσας λαμβάνειν καὶ περὶ τοῦ κλήρου τῇ αὐτῇ διανοίᾳ δῆλον ὅτι κέχρηται νυνί.", "st": "44.38"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ τὸν ἄρχοντά γε ἐξηπάτησεν παρακαταβάλλων καὶ ἡμᾶς, καὶ ἀντεγράψατο Ὀτρυνεὺς εἶναι ἐν Ἐλευσινίοις δημοτευόμενος. ἐπειδὴ τοίνυν τούτων πάντων ἀπετύγχανεν, ταῖς παρελθούσαις ἀρχαιρεσίαις ταύταις παρασκευασάμενός τινας τῶν δημοτῶν ἠξίου οὗτος ἐγγράφεσθαι ποιητὸς υἱὸς τῷ Ἀρχιάδῃ.", "st": "44.39"}, {"sp": "N", "t": "ἀντιλεγόντων δ’ ἡμῶν καὶ ἀξιούντων, ἐπειδὰν τοῦ κλήρου ἡ διαδικασία γένηται, τηνικαῦτα τοὺς δημότας τὴν ψῆφον φέρειν, πρότερον δὲ μή, τοῦτο μὲν ἐπείσθησαν οὐ δι’ αὑτούς, ἀλλὰ διὰ τοὺς νόμους· δεινὸν γὰρ ἐδόκει εἶναι τὸν παρακαταβεβληκότα τοῦ κλήρου εἰσποιεῖν αὑτὸν ἔτι τῶν πραγμάτων ἀκρίτων ὄντων· ὃ δὲ μετὰ ταῦτα διοικεῖται Λεώστρατος οὑτοσί, τοῦτο πάντων δεινότατόν ἐστιν.", "st": "44.40"}, {"sp": "N", "t": "ἐπειδὴ γὰρ αὐτὸς ἀπετύγχανεν τοῦ ἐγγραφῆναι, εἰσποιεῖ Λεωχάρην τὸν αὑτοῦ υἱὸν Ἀρχιάδῃ παρὰ πάντας τοὺς νόμους, πρὶν τοῦ δήμου τὴν δοκιμασίαν γενέσθαι· οὐκ εἰσηγμένου δ’ εἰς τοὺς φράτεράς πω τοὺς Ἀρχιάδου, ἀλλ’ ἐπειδὴ ἐνεγράφη, τηνικαῦτα πείσας ἕνα τινὰ τῶν φρατέρων ἐνέγραψεν εἰς τὸ φρατερικὸν γραμματεῖον.", "st": "44.41"}, {"sp": "N", "t": "καὶ μετὰ ταῦτα τῇ διαμαρτυρίᾳ πρὸς τῷ ἄρχοντι τοῦτον ἐπιγράφεται ὡς υἱὸν ὄντα γνήσιον τοῦ τετελευτηκότος ἔτη πολλά, τὸν πρῴην καὶ χθὲς ἐγγραφέντα. καὶ συμβαίνει ἀμφοτέρους αὐτοὺς τῆς κληρονομίας ἀμφισβητεῖν· ὅ τε γὰρ Λεώστρατος οὑτοσὶ παρακατέβαλε τοῦ κλήρου ὡς υἱὸς γνήσιος Ἀρχιάδῃ, ὅ τε Λεωχάρης οὑτοσὶ διαμεμαρτύρηκεν ὡς υἱὸς ὢν γνήσιος τοῦ αὐτοῦ πατρός,", "st": "44.42"}, {"sp": "N", "t": "οὐδέτερος δ’ αὐτῶν ζῶντι, ἀλλὰ τετελευτηκότι εἰσποιεῖ αὑτόν. ἡμεῖς δὲ οἰόμεθα δεῖν, ὦ ἄνδρες δικασταί, ἐπειδὰν περὶ τούτου τοῦ ἀγῶνος ὑμεῖς τὴν ψῆφον ἐνέγκητε, τηνικαῦτα ἐκ τῶν κατὰ γένος ἐγγυτάτω ἡμῶν εἰσποιεῖν υἱὸν τῷ τετελευτηκότι, ὅπως ἂν ὁ οἶκος μὴ ἐξερημωθῇ.", "st": "44.43"}, {"sp": "N", "t": "πρῶτον μὲν οὖν, ὦ ἄνδρες δικασταί, ὡς ἐπανῆλθεν εἰς τοὺς Ἐλευσινίους ἐκ τῶν Ὀτρυνέων Λεώστρατος οὑτοσὶ καταλιπὼν υἱὸν τῷ Ἀρχιάδῃ γνήσιον, καὶ ὅτι ὁ πατὴρ αὐτοῦ ἔτι πρότερον τὸ αὐτὸ τοῦτ’ ἐπεποιήκει, καὶ ὡς ὁ καταλειφθεὶς ἄπαις τετελεύτηκεν, καὶ ὡς ὁ νῦν διαμεμαρτυρηκὼς πρότερον εἰς τοὺς δημότας ἢ εἰς τοὺς φράτερας ἐνεγράφη, τούτων ὑμῖν τὰς τῶν φρατέρων καὶ τὰς τῶν δημοτῶν μαρτυρίας ἀναγνώσεται, καὶ τῶν ἄλλων δὲ τῶν εἰρημένων, ὧν οὗτοι πεποιήκασιν, ἁπάντων ὑμῖν τὰς μαρτυρίας καθ’ ἓν ἕκαστον παρέξομαι. καί μοι κάλει τοὺς μάρτυρας δευρί.", "st": "44.44"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "44.44"}, {"sp": "N", "t": "τῶν μὲν τοίνυν πραγμάτων ἁπάντων ἀκηκόατε, ὦ ἄνδρες δικασταί, καὶ τῶν ἐξ ἀρχῆς γεγενημένων περὶ τὸν κλῆρον τοῦτον καὶ τῶν ὕστερον συμβάντων, ἐπειδὴ τάχιστα τὴν λῆξιν ἡμεῖς ἐποιησάμεθα. λοιπὸν δ’ ἐστὶ περί τε τῆς διαμαρτυρίας αὐτῆς εἰπεῖν καὶ περὶ τῶν νόμων καθ’ οὓς ἀξιοῦμεν κληρονομεῖν· ἔτι δέ, ἂν ἐγχωρῇ τὸ ὕδωρ καὶ μὴ μέλλωμεν ὑμῖν ἐνοχλεῖν, ἐξελέγξαι τὰ ὑπὸ τούτων ῥηθησόμενα, ὅτι οὔτε δίκαια οὔθ’ ὑγιῆ ἐστι. καὶ πρῶτον μὲν τὴν διαμαρτυρίαν ἀναγνώτω, καὶ σφόδρα τὸν νοῦν αὐτῇ προσέχετε· περὶ γὰρ ταύτης ἡ ψῆφος οἰσθήσεται νυνί.", "st": "44.45"}, {"sp": "N", "t": "ΔΙΑΜΑΡΤΥΡΙΑ.", "st": "44.45"}, {"sp": "N", "t": "οὐκοῦν δήπου διαμεμαρτύρηκεν οὑτοσί, ὡς ἀκηκόατε, “μὴ ἐπίδικον εἶναι τὸν κλῆρον τὸν Ἀρχιάδου, ὄντων αὐτῷ παίδων γνησίων κυρίως κατὰ τὸν θεσμόν.” ἐξετάσωμεν τοίνυν, εἰ εἰσὶν ἢ τὰ ψευδῆ διαμεμαρτύρηκεν οὑτοσί. ὁ γὰρ Ἀρχιάδης ἐκεῖνος, οὗ ἐστιν ὁ κλῆρος, ἐποιήσατο υἱὸν τὸν τοῦ διαμεμαρτυρηκότος νυνὶ πάππον· ἐκεῖνος δ’ ἐγκαταλιπὼν υἱὸν γνήσιον τὸν τούτου πατέρα Λεώστρατον ἐπανῆλθεν εἰς τοὺς Ἐλευσινίους.", "st": "44.46"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα αὐτὸς οὑτοσὶ Λεώστρατος πάλιν ἐγκαταλιπὼν υἱὸν ᾤχετο ἀπιὼν εἰς τὸν πατρῷον οἶκον· ὁ δ’ ἐγκαταλειφθεὶς ὑπὸ τούτου τελευταῖος ἁπάντων τῶν εἰσποιηθέντων τετελεύτηκεν ἄπαις, ὥστε γίγνεται ἔρημος ὁ οἶκος, καὶ ἐπανελήλυθεν ἡ κληρονομία πάλιν εἰς τοὺς ἐξ ἀρχῆς ἐγγύτατα γένους ὄντας.", "st": "44.47"}, {"sp": "N", "t": "πῶς ἂν οὖν εἴησαν κατὰ τὴν διαμαρτυρίαν υἱεῖς ἔτι τινὲς τῷ Ἀρχιάδῃ, ᾧ οἱ μὲν εἰσποιηθέντες ὁμολογοῦνται ἐπανεληλυθέναι, ὁ δ’ ἐγκαταλειφθεὶς τελευταῖος ἄπαις τετελεύτηκεν; οὐκοῦν ἀνάγκη τὸν οἶκον ἔρημον εἶναι. ὁπότε δὲ ἔρημος ὁ οἶκος, οὐκ ἂν εἴησαν υἱεῖς ἔτι ἐκείνῳ γνήσιοι. οὑτοσὶ τοίνυν διαμεμαρτύρηκεν τοὺς οὐκ ὄντας εἶναι, καὶ γέγραφεν ἐν τῇ διαμαρτυρίᾳ “ὄντων παίδων”, ἕνα φάσκων αὑτὸν εἶναι.", "st": "44.48"}, {"sp": "N", "t": "ἀλλὰ μὴν “γνησίων” γ’ ὅταν λέγῃ καὶ “κυρίως κατὰ τὸν θεσμόν”, παρακρούεται παρὰ τοὺς νόμους. τὸ μὲν γὰρ γνήσιόν ἐστιν, ὅταν ᾖ γόνῳ γεγονός· καὶ ὁ νόμος ταῦτα μαρτυρεῖ λέγων, “ἣν ἂν ἐγγυήσῃ πατὴρ ἢ ἀδελφὸς ἢ πάππος, ἐκ ταύτης εἶναι παῖδας γνησίους.” τὸ δὲ “κυρίως” κατὰ τῶν ποιήσεων ὁ νομοθέτης ἔλαβεν, ὑπολαμβάνων δεῖν, ὅταν τις ὢν ἄπαις καὶ κύριος τῶν ἑαυτοῦ ποιήσηται υἱόν, ταῦτα κύρια εἶναι. οὗτος τοίνυν γόνῳ μὲν οὐδένα φησὶν Ἀρχιάδῃ γενέσθαι υἱόν, διαμεμαρτύρηται δὲ “γνησίων ὄντων”, ἐναντίαν τῷ πράγματι τὴν διαμαρτυρίαν ποιησάμενος.", "st": "44.49"}, {"sp": "N", "t": "ποιητὸς δὲ ὁμολογῶν εἶναι, φαίνεται οὐκ εἰσποιηθεὶς ὑπὸ τοῦ τετελευτηκότος αὐτοῦ, ὥστε πῶς ἔτι σοι κύρια ταῦτ’ ἂν εἴη κατὰ τὸν θεσμόν; ὅτι νὴ Δία ἐγγέγραπται Ἀρχιάδῃ υἱός. ὑπό γε τουτωνὶ πρῴην βιασαμένων, ἤδη τῆς τοῦ κλήρου διαδικασίας ἐνεστηκυίας· οὐ δὴ δίκαιον ἐν τεκμηρίῳ ποιεῖσθαι τἀδίκημα.", "st": "44.50"}, {"sp": "N", "t": "καὶ γὰρ ἐκεῖνο πῶς οὐ δεινόν ἐστιν, ὦ ἄνδρες δικασταί, ἐπὶ μὲν τοῦ λόγου αὐτίκα μάλα φήσειν ποιητὸν εἶναι, ἐν δὲ τῇ διαμαρτυρίᾳ τοῦτο μὴ τολμῆσαι γράψαι, ἀλλὰ τὰ μὲν ἐν ταύτῃ διαμεμαρτυρημένα εἶναι ὡς ὑπὲρ υἱοῦ γόνῳ γεγονότος, τὰ δ’ αὐτίκα μάλα ῥηθησόμενα ὡς εἰσποιητοῦ; εἰ δὲ τὴν ἀπολογίαν ἐναντίαν τῇ διαμαρτυρίᾳ ποιήσονται, πῶς οὐκ ἢ τὸν λόγον ἀνάγκη ἢ τὴν διαμαρτυρίαν ψευδῆ εἶναι; εἰκότως δ’ οὐ προσέγραψαν τὴν ποίησιν τῇ διαμαρτυρίᾳ. ἔδει γὰρ ἐγγράψαι αὐτοὺς “εἰσποιησαμένου τοῦ δεῖνος”· ὁ δ’ οὐκ εἰσεποιήσατο, ἀλλ’ ἑαυτοὺς εἰσποιοῦντες ἀποστεροῦσιν ἡμᾶς τῆς κληρονομίας.", "st": "44.51"}, {"sp": "N", "t": "τὸ μετὰ ταῦτα τοίνυν πῶς οὐκ ἄτοπον καὶ δεινόν ἐστιν, ἅμα παρακαταβεβληκέναι τοῦ κλήρου πρὸς τῷ ἄρχοντι ὡς ὄντα αὐτὸν Ἀρχιάδου Λεώστρατον τουτονί, τὸν Ἐλευσίνιον τοῦ Ὀτρυνέως, διαμεμαρτυρηκέναι δ’ ἕτερον, ὡς αὐτοὶ ὁρᾶτε, φάσκοντα καὶ τοῦτον Ἀρχιάδου υἱὸν εἶναι; καὶ ποτέρῳ δεῖ προσέχειν ὑμῶν ὡς ἀληθῆ λέγοντι;", "st": "44.52"}, {"sp": "N", "t": "αὐτὸ γὰρ τοῦτο τεκμήριον οὐκ ἐλάχιστόν ἐστι τοῦ ψευδῆ τὴν διαμαρτυρίαν γεγενῆσθαι, τὸ περὶ τοῦ αὐτοῦ πράγματος μὴ τὸν αὐτὸν ἀμφισβητεῖν. εἰκότως· ὅτε γὰρ οἶμαι Λεώστρατος οὑτοσὶ παρακατέβαλλε τοῦ κλήρου πρὸς ἡμᾶς, οὔπω ⟨ὁ⟩ διαμεμαρτυρηκὼς νῦν ἐνεγέγραπτο δημότης εἶναι. ὥστε πάντων ἂν δεινότατα πάθοιμεν, εἰ τῇ ὕστερον τῶν πραγμάτων γεγενημένῃ διαμαρτυρίᾳ πιστεύσετε ὑμεῖς.", "st": "44.53"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ πρεσβύτερά γε αὑτοῦ διαμεμαρτύρηκεν. ὁ γὰρ μήπω ἐν τῷ οἴκῳ τῷ Ἀρχιάδου ὤν, ὅθ’ ἡ λῆξις αὕτη τοῦ κλήρου ἐγένετο, πῶς ἂν εἰδείη τι τούτων; ἔπειτ’ εἰ μὲν αὑτὸν διεμεμαρτυρήκει, εἶχεν ἂν λόγον αὐτῷ τὸ πρᾶγμα· ἀδίκως μὲν ἂν ἔγραφεν, οὐδὲν δ’ ἧττον ὑπὲρ τοῦ κατὰ τὴν ἡλικίαν γ’ ὄντος. νῦν δὲ γνησίους υἱοὺς γέγραφεν τῷ Ἀρχιάδῃ ἐκείνῳ εἶναι, τόν τε αὑτοῦ πατέρα δῆλον ὅτι καὶ τὸν κατὰ τὴν ἐξ ἀρχῆς ποίησιν, οὐκ ἐπιλογισάμενος ὅτι ἐπανεληλυθότες ἦσαν. οὐκοῦν ἀνάγκη πρεσβυτέρας πράξεις αὐτὸν καὶ μὴ τὰς ἐφ’ ἑαυτοῦ γεγενημένας διαμεμαρτυρηκέναι. εἶθ’ ὑμεῖς τῷ τοῦτο τετολμηκότι πιστεύσετε ὡς ἀληθῆ λέγοντι;", "st": "44.54"}, {"sp": "N", "t": "νὴ Δί’, ἀλλ’ ἀκηκοὼς τοῦ αὑτοῦ πατρὸς διαμεμαρτύρηκεν. ὁ δέ γε νόμος ἀκοὴν τῶν τετελευτηκότων κελεύει διαμαρτυρεῖν, ⟨οὐ⟩ ζῶντος τοῦ πατρὸς τὰ ὑπ’ ἐκείνου πραχθέντα. ἐπεὶ κἀκεῖνο· διὰ τί ποτε Λεώστρατος οὑτοσὶ οὐχ αὑτόν, ἀλλὰ τοῦτον ἐπεγράψατο τῇ διαμαρτυρίᾳ; τὰ γὰρ πρεσβύτερα τῶν πραγμάτων τὸν πρεσβύτερον ἔδει διαμαρτυρεῖν. ὅτι νὴ Δί’, ἂν εἴποι, τοῦτον [γὰρ] εἰσπεποίηκα υἱὸν τῷ Ἀρχιάδῃ.", "st": "44.55"}, {"sp": "N", "t": "οὐκοῦν σὲ τὸν εἰσποιοῦντα καὶ κατασκευάζοντα τὰ πράγματα καὶ λόγον ἔδει διδόναι, γενόμενον ὑπεύθυνον ὧν πεποίηκας· πολλή γε ἀνάγκη. ἀλλὰ τοῦτο μὲν ἔφυγες, τῇ διαμαρτυρίᾳ δὲ τοῦτον οὐδὲν εἰδότ’ ἐπεγράψω. ὥστε φανερὸν ὑμῖν ἐστιν, ὦ ἄνδρες δικασταί, τὰ διαμαρτυρούμενα μὴ εἶναι ἀληθῆ, καὶ παρ’ αὐτοῖς γε τούτοις ὁμολογεῖται. καὶ μὴν κἀκεῖνο δίκαιόν ἐστιν, μὴ λέγοντος αὐτίκα μάλ’ ἀκούειν Λεωστράτου τουτουί, ὑπὲρ ὧν γε διαμαρτυρῆσαι οὐκ ἐτόλμησεν.", "st": "44.56"}, {"sp": "N", "t": "ὡς δὲ καὶ τῶν ἀγώνων ἀδικώτατοι καὶ πλείστης ὀργῆς ἄξιοι τοῖς ἀγωνιζομένοις αἱ διαμαρτυρίαι εἰσίν, μάλιστ’ ἄν τις ἐκεῖθεν καταμάθοι. πρῶτον μὲν γὰρ οὐκ ἀναγκαίως ἔχουσιν, ὥσπερ οἱ ἄλλοι, ἀλλ’ ἐκ προαιρέσεως καὶ βουλήσεως τῆς τοῦ διαμαρτυροῦντος γίγνονται. εἰ μὲν γὰρ ὑπὲρ τῶν διαμφισβητουμένων μὴ ἔστιν ἄλλον τρόπον δίκην λαβεῖν ἢ διαμαρτυρήσαντα, ἴσως ἀναγκαῖον τὸ διαμαρτυρεῖν·", "st": "44.57"}, {"sp": "N", "t": "εἰ δὲ καὶ ἄνευ διαμαρτυρίας πρὸς ἅπασι τοῖς συνεδρίοις ἔνεστι λόγου μὴ ἀποστερηθῆναι, πῶς οὐ προπετείας καὶ τῆς μεγίστης ἀπονοίας σημεῖον τὸ διαμαρτυρεῖν ἐστιν; οὐδὲ γὰρ ὁ νομοθέτης ἀναγκαῖον αὐτὸ ἐποίησεν τοῖς ἀντιδίκοις, ἀλλ’ ἂν βούλωνται διαμαρτυρεῖν, ἔδωκεν, ὥσπερ διάπειραν ποιούμενος τῶν τρόπων ἑνὸς ἑκάστου ἡμῶν, πῶς ποτ’ ἔχοιμεν πρὸς τὸ προπετῶς τι πράττειν.", "st": "44.58"}, {"sp": "N", "t": "ἔτι τοίνυν ἐπὶ τὸ τῶν διαμαρτυρούντων μέρος οὔτε δικαστήρια ἦν ἂν οὔτε ἀγῶνες ἐγίγνοντο· κωλύει γὰρ πάντα ταῦτα τὸ τῶν διαμαρτυριῶν γένος καὶ ἀποκλείει εἰσαγωγῆς ἕκαστα τῆς εἰς τὸ δικαστήριον, κατά γε τὴν τοῦ διαμαρτυροῦντος βούλησιν. διόπερ οἶμαι δεῖν κοινοὺς ἐχθροὺς τοὺς τοιούτους ἀνθρώπους ὑπολαμβάνειν πᾶσιν εἶναι, καὶ μηδέποτε τυγχάνειν αὐτοὺς συγγνώμης ἀγωνιζομένους παρ’ ὑμῖν· προελόμενος γὰρ ἕκαστος αὐτῶν τὸν ἐκ τοῦ διαμαρτυρῆσαι κίνδυνον, οὐκ ἀναγκασθεὶς εἰσέρχεται.", "st": "44.59"}, {"sp": "N", "t": "ὅτι μὲν οὖν ἡ διαμαρτυρία ψευδής ἐστιν, καὶ ἐκ τῶν γεγραμμένων καὶ ἐκ τῶν εἰρημένων λόγων σχεδὸν ἀκριβῶς μεμαθήκατε. ὅτι δὲ καὶ οἱ νόμοι, ὦ ἄνδρες δικασταί, ἡμῖν τὴν κληρονομίαν ἀποδιδόασι, τοῦθ’ ὑμᾶς διὰ βραχέων βούλομαι διδάξαι, οὐχ ὡς οὐ μεμαθηκότας καὶ ἐν τοῖς ἐν ἀρχῇ εἰρημένοις, ἀλλ’ ἵνα μᾶλλον πρὸς τὴν τούτων ψευδολογίαν τὰ δίκαια μνημονεύητε.", "st": "44.60"}, {"sp": "N", "t": "τὸ μὲν γὰρ σύνολον, ὄντες Ἀρχιάδῃ, οὗ ἐστιν ὁ κλῆρος οὑτοσί, πρὸς ἀνδρῶν κατὰ γένος ἐγγυτάτω, καὶ τῆς ποιήσεως, ἣν ἐκεῖνος ἐποιήσατο, τῶν μὲν ἐπανεληλυθότων εἰς τὸν πατρῷον οἶκον, τοῦ δ’ ἐγκαταλειφθέντος ἄπαιδος τετελευτηκότος, τούτων δ’ οὕτως ἐχόντων ἀξιοῦμεν κληρονομεῖν,", "st": "44.61"}, {"sp": "N", "t": "οὐδεμίαν οὐσίαν Λεωστράτου ἀφελόμενοι (οὗτοι μὲν γὰρ τὰς ἑαυτῶν ἔχουσιν), τῆς ὑπ’ Ἀρχιάδου δὲ καταλειφθείσης [καὶ] οὔσης ἐκ τῶν νόμων ἡμετέρας. ὁ γὰρ νόμος, ὦ ἄνδρες δικασταί, κελεύει κρατεῖν τοὺς ἄρρενας καὶ τοὺς ἐκ τῶν ἀρρένων· οὗτοι δ’ ἡμεῖς ἐσμεν. οὐκ ἦσαν τοίνυν παῖδες ἐκείνῳ· οἱ δ’ … ὄντες ἡμεῖς ἐσμεν.", "st": "44.62"}, {"sp": "N", "t": "ἔπειτα οὐ δίκαιον δήπου τὸν ποιητὸν υἱὸν ποιητοὺς ἑτέρους εἰσάγειν, ἀλλ’ ἐγκαταλείπειν μὲν γιγνομένους, ὅταν δὲ τοῦτ’ ἐπιλίπῃ, τοῖς γένεσιν ἀποδιδόναι τὰς κληρονομίας· ταῦτα γὰρ οἱ νόμοι κελεύουσιν. ἐπεὶ πῶς οὐκ ἐκκλείεται εἷς ἕκαστος ὑμῶν τῆς κατὰ γένος ἀγχιστείας, ὅταν τοῖς ποιητοῖς ἡ ἄδεια αὕτη δοθῇ; ὁρᾶτε γὰρ ὅτι ταῖς κολακείαις οἱ πλεῖστοι ψυχαγωγούμενοι καὶ ταῖς πρὸς τοὺς οἰκείους διαφοραῖς πολλάκις φιλονικοῦντες ποιητοὺς υἱεῖς ποιοῦνται· εἰ δ’ ἔσται τῷ εἰσποιηθέντι παρὰ τὸν νόμον εἰσποιεῖν ὃν ἂν βούληται, οὐδέποτε τοῖς γένεσιν αἱ κληρονομίαι δοθήσονται.", "st": "44.63"}, {"sp": "N", "t": "ἃ καὶ προνοηθεὶς ὁ νομοθέτης ἀπεῖπεν τῷ ποιητῷ αὐτῷ ὄντι ποιητὸν υἱὸν μὴ ποιεῖσθαι, τίνα τρόπον διορίσας περὶ τούτων; ὅταν εἴπῃ “υἱὸν γνήσιον ἐγκαταλιπόντα ἐπανιέναι”, δηλοῖ δήπου φανερῶς ὅτι οὐ δεῖ ποιεῖσθαι· ἀδύνατον γάρ ἐστιν υἱὸν γνήσιον ἐγκαταλιπεῖν, ἐὰν μὴ γόνῳ γεγονὼς ᾖ τινι. σὺ τοίνυν, ὦ Λεώστρατε, ἀξιοῖς τῷ τετελευτηκότι εἰσποιητῷ εἰς τὸ ἡμέτερον γένος ὄντι ποιητὸν ἐπὶ τὸν κλῆρον εἰσαγαγεῖν, ὥσπερ ἐπὶ τὰ σαυτοῦ κτήματα καὶ οὐκ εἰς τὰ κατὰ νόμον τῷ προσήκοντι δοθησόμενα βαδίζων.", "st": "44.64"}, {"sp": "N", "t": "ἡμεῖς δέ, ὦ ἄνδρες δικασταί, εἰ μὲν ὁ τετελευτηκὼς ἐποιήσατό τινα, καίπερ οὐ διδόντος τοῦ νόμου συνεχωροῦμεν ἂν αὐτῷ, ἢ εἰ διαθήκας κατελελοίπει, καὶ ταύταις ἂν ἐνεμείναμεν, ἐπεὶ καὶ τὸ ἐξ ἀρχῆς τοιοῦτοι ὄντες διετελοῦμεν, οὐκ ἐναντιούμενοι τούτοις ἔχουσι τὴν οὐσίαν καὶ ἐπανιοῦσιν ἄνω, καθ’ ὃν δήποτε τρόπον ἐβούλοντο.", "st": "44.65"}, {"sp": "N", "t": "ἐπεὶ δὲ νυνί ποτε ὑπὸ τούτων αὐτῶν καὶ ὑπὸ τῶν νόμων τὸ πρᾶγμ’ ἐξελήλεγκται, οἰόμεθα δεῖν κληρονομεῖν τῶν Ἀρχιάδου, καὶ παρ’ ἡμῶν εἶναι τὸν υἱὸν τὸν εἰσποιούμενον τῶν μὴ πεποιημένων πρότερον, μὴ παρὰ τούτων. δικαίως γὰρ ὁ νομοθέτης, οἶμαι, ὥσπερ καὶ τὰς ἀτυχίας τῶν οἰκείων καὶ τὰς ἐκδόσεις τῶν γυναικῶν τοῖς ἐγγύτατα γένους προσέταττε [ποιεῖσθαι], οὕτως καὶ τὰς κληρονομίας καὶ τὴν τῶν ἀγαθῶν μετουσίαν τοῖς αὐτοῖς ἀποδέδωκεν.", "st": "44.66"}, {"sp": "N", "t": "τὸ δὲ πάντων μέγιστον καὶ γνωριμώτατον ὑμῖν· ὁ γὰρ τοῦ Σόλωνος νόμος οὐδὲ διαθέσθαι τὸν ποιητὸν ἐᾷ τὰ ἐν τῷ οἴκῳ, οἷ ἂν ποιηθῇ. εἰκότως, οἶμαι· τῷ γὰρ κατὰ νόμον εἰσποιηθέντι ἐπὶ τὰ ἑτέρου οὐχ οὕτως ὡς περὶ τῶν ἰδίων κτημάτων βουλευτέον ἐστίν, ἀλλὰ τοῖς νόμοις ἀκολούθως, περὶ ἑκάστου τῶν γεγραμμένων ὡς ὁ νόμος λέγει.", "st": "44.67"}, {"sp": "N", "t": "“ὅσοι μὴ ἐπεποίηντο” φησίν “ὅτε Σόλων εἰσῄει εἰς τὴν ἀρχήν, ἐξεῖναι αὐτοῖς διαθέσθαι ὅπως ἂν ἐθέλωσιν”, ὡς τοῖς γε ποιηθεῖσιν οὐκ ἐξὸν διαθέσθαι, ἀλλὰ ζῶντας ἐγκαταλιπόντας υἱὸν γνήσιον ἐπανιέναι, ἢ τελευτήσαντας ἀποδιδόναι τὴν κληρονομίαν τοῖς ἐξ ἀρχῆς οἰκείοις οὖσι τοῦ ποιησαμένου.", "st": "44.68"}, {"sp": "HDR", "t": "Κατὰ Στεφάνου ψευδομαρτυριῶν Αʹ", "st": "45"}, {"sp": "N", "t": "καταψευδομαρτυρηθείς, ὦ ἄνδρες Ἀθηναῖοι, καὶ παθὼν ὑπὸ Φορμίωνος ὑβριστικὰ καὶ δεινά, δίκην παρὰ τῶν αἰτίων ἥκω ληψόμενος παρ’ ὑμῖν. δέομαι δὲ πάντων ὑμῶν καὶ ἱκετεύω καὶ ἀντιβολῶ πρῶτον μὲν εὐνοϊκῶς ἀκοῦσαί μου (μέγα γὰρ τοῖς ἠτυχηκόσιν, ὥσπερ ἐγώ, δυνηθῆναι περὶ ὧν πεπόνθασιν εἰπεῖν καὶ εὐμενῶς ἐχόντων ὑμῶν ἀκροατῶν τυχεῖν), εἶτ’ ἐὰν ἀδικεῖσθαι δοκῶ, βοηθῆσαί μοι τὰ δίκαια.", "st": "45.1"}, {"sp": "N", "t": "ἐπιδείξω δ’ ὑμῖν τουτονὶ Στέφανον καὶ μεμαρτυρηκότα ⟨τὰ⟩ ψευδῆ, καὶ δι’ αἰσχροκερδίαν τοῦτο πεποιηκότα, καὶ κατήγορον αὐτὸν αὑτοῦ γιγνόμενον· τοσαύτη περιφάνεια τοῦ πράγματός ἐστιν. ἐξ ἀρχῆς δ’ ὡς ἂν οἷός τ’ ὦ διὰ βραχυτάτων εἰπεῖν πειράσομαι τὰ πεπραγμένα μοι πρὸς Φορμίωνα, ἐξ ὧν ἀκούσαντες τήν τ’ ἐκείνου πονηρίαν καὶ τούτους, ὅτι τὰ ψευδῆ μεμαρτυρήκασιν, γνώσεσθε.", "st": "45.2"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ ἄνδρες δικασταί, πολλῶν χρημάτων ὑπὸ τοῦ πατρὸς καταλειφθέντων μοι, καὶ ταῦτα Φορμίωνος ἔχοντος, καὶ ἔτι πρὸς τούτοις τὴν μητέρα γήμαντος τὴν ἐμὴν ἀποδημοῦντος ἐμοῦ δημοσίᾳ τριηραρχοῦντος ὑμῖν (ὃν τρόπον δέ, οὐκ ἴσως καλὸν υἱεῖ περὶ μητρὸς ἀκριβῶς εἰπεῖν), ἐπειδὴ καταπλεύσας ᾐσθόμην καὶ τὰ πεπραγμέν’ εἶδον, πόλλ’ ἀγανακτήσας καὶ χαλεπῶς ἐνεγκὼν", "st": "45.3"}, {"sp": "N", "t": "δίκην μὲν οὐχ οἷός τ’ ἦν ἰδίαν λαχεῖν (οὐ γὰρ ἦσαν ἐν τῷ τότε καιρῷ δίκαι, ἀλλ’ ἀνεβάλλεσθ’ ὑμεῖς διὰ τὸν πόλεμον), γραφὴν δ’ ὕβρεως γράφομαι πρὸς τοὺς θεσμοθέτας αὐτόν. χρόνου δὲ γιγνομένου, καὶ τῆς μὲν γραφῆς ἐκκρουομένης, δικῶν δ’ οὐκ οὐσῶν, γίγνονται παῖδες ἐκ τούτου τῇ μητρί. καὶ μετὰ ταῦτα (εἰρήσεται γὰρ ἅπασα πρὸς ὑμᾶς ἡ ἀλήθει’, ὦ ἄνδρες δικασταί) πολλοὶ μὲν καὶ φιλάνθρωποι λόγοι παρὰ τῆς μητρὸς ἐγίγνοντο καὶ δεήσεις ὑπὲρ Φορμίωνος τουτουί, πολλοὶ δὲ καὶ μέτριοι καὶ ταπεινοὶ παρ’ αὐτοῦ τούτου.", "st": "45.4"}, {"sp": "N", "t": "ἵνα δ’, ὦ ἄνδρες Ἀθηναῖοι, συντέμω ταῦτα, ἐπειδὴ ποιεῖν τ’ οὐδὲν ᾤετο δεῖν ὧν τόθ’ ὡμολόγησεν, καὶ τὰ χρήματ’ ἀποστερεῖν ἐνεχείρησεν ἃ τῆς τραπέζης εἶχεν ἀφορμήν, δίκην ἠναγκάσθην αὐτῷ λαχεῖν, ἐπειδὴ τάχιστ’ ἐξουσία ἐγένετο. γνοὺς δ’ οὗτος ὅτι πάντ’ ἐξελεγχθήσεται καὶ κάκιστος ἀνθρώπων περὶ ἡμᾶς γεγονὼς ἐπιδειχθήσεται, μηχανᾶται καὶ κατασκευάζει ταῦτα, ἐφ’ οἷς Στέφανος οὑτοσὶ τὰ ψευδῆ μου κατεμαρτύρησε. καὶ πρῶτον μὲν παρεγράψατο τὴν δίκην [ἣν ἔφευγεν Φορμίων] μὴ εἰσαγώγιμον εἶναι· ἔπειτα μάρτυρας, ὡς ἀφῆκ’ αὐτὸν τῶν ἐγκλημάτων, παρέσχετο ψευδεῖς, καὶ μισθώσεώς τινος ἐσκευωρημένης καὶ διαθήκης οὐδεπώποτε γενομένης.", "st": "45.5"}, {"sp": "N", "t": "προλαβὼν δέ μου ὥστε πρότερος λέγειν διὰ τὸ παραγραφὴν εἶναι καὶ μὴ εὐθυδικίᾳ εἰσιέναι, καὶ ταῦτ’ ἀναγνοὺς καὶ τἄλλ’ ὡς αὑτῷ συμφέρειν ἡγεῖτο ψευσάμενος, οὕτω διέθηκε τοὺς δικαστάς, ὥστε φωνὴν μηδ’ ἡντινοῦν ἐθέλειν ἀκούειν ἡμῶν· προσοφλὼν δὲ τὴν ἐπωβελίαν καὶ οὐδὲ λόγου τυχεῖν ἀξιωθείς, ἀλλ’ ὑβρισθεὶς ὡς οὐκ οἶδ’ εἴ τις πώποτ’ ἄλλος ἀνθρώπων, ἀπῄειν βαρέως, ὦ ἄνδρες Ἀθηναῖοι, καὶ χαλεπῶς φέρων.", "st": "45.6"}, {"sp": "N", "t": "λόγον δ’ ἐμαυτῷ διδοὺς εὑρίσκω τοῖς δικάσασι μὲν τότε πολλὴν συγγνώμην οὖσαν (ἐγὼ γὰρ αὐτὸς οὐκ ἂν οἶδ’ ὅ τι ἄλλ’ εἶχον ψηφίσασθαι, τῶν πεπραγμένων μὲν μηδὲν εἰδώς, τὰ δὲ μαρτυρούμεν’ ἀκούων), τούτους δ’ ἀξίους ὄντας ὀργῆς, οἳ τῷ τὰ ψευδῆ μαρτυρεῖν αἴτιοι τούτων ἐγένοντο. περὶ μὲν δὴ τῶν ἄλλων τῶν μεμαρτυρηκότων, ὅταν πρὸς ἐκείνους εἰσίω, τότ’ ἐρῶ· περὶ ὧν δ’ οὑτοσὶ Στέφανος μεμαρτύρηκεν, ἤδη πειράσομαι διδάσκειν ὑμᾶς.", "st": "45.7"}, {"sp": "N", "t": "λαβὲ δ’ αὐτὴν τὴν μαρτυρίαν καὶ ἀνάγνωθί μοι, ἵν’ ἐξ αὐτῆς ἐπιδεικνύω. λέγε· σὺ δ’ ἐπίλαβε τὸ ὕδωρ.", "st": "45.8"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "45.8"}, {"sp": "N", "t": "στέφανος Μενεκλέους Ἀχαρνεύς, Ἔνδιος Ἐπιγένους Λαμπτρεύς, Σκύθης Ἁρματέως Κυδαθηναιεὺς μαρτυροῦσι παρεῖναι πρὸς τῷ διαιτητῇ Τεισίᾳ Ἀχαρνεῖ, ὅτε προὐκαλεῖτο Φορμίων Ἀπολλόδωρον, εἰ μή φησιν ἀντίγραφα εἶναι τῶν διαθηκῶν τῶν Πασίωνος τὸ γραμματεῖον ὃ ἐνεβάλετο Φορμίων εἰς τὸν ἐχῖνον, ἀνοίγειν τὰς διαθήκας τὰς Πασίωνος, ἃς παρεῖχε πρὸς τὸν διαιτητὴν Ἀμφίας ὁ Κηφισοφῶντος κηδεστής· Ἀπολλόδωρον δὲ οὐκ ἐθέλειν ἀνοίγειν· εἶναι δὲ τάδε ἀντίγραφα τῶν διαθηκῶν τῶν Πασίωνος.", "st": "45.8"}, {"sp": "N", "t": "ἠκούσατε μὲν τῆς μαρτυρίας, ὦ ἄνδρες δικασταί, νομίζω δ’ ὑμᾶς, εἰ καὶ μηδὲν τῶν ἄλλων αἰσθάνεσθέ πω, τοῦτό γ’ αὐτὸ θαυμάζειν, τὸ τὴν μὲν ἀρχὴν τῆς μαρτυρίας εἶναι πρόκλησιν, τὴν δὲ τελευτὴν διαθήκην. οὐ μὴν ἀλλ’ ἔγωγ’ οἶμαι δεῖν, ἐπειδάν, ὃ τῶν μεμαρτυρημένων ὡσπερεὶ κεφάλαιόν ἐστιν, ἐπιδείξω ψεῦδος ὄν, τηνικαῦτ’ ἤδη καὶ περὶ τῶν τοιούτων ποιεῖσθαι τοὺς λόγους.", "st": "45.9"}, {"sp": "N", "t": "ἔστι δὴ μεμαρτυρημένον αὐτοῖς προκαλεῖσθαι Φορμίων’ ἀνοίγειν τὰς διαθήκας, ἃς παρέχειν πρὸς τὸν διαιτητὴν Τεισίαν Ἀμφίαν τὸν Κηφισοφῶντος κηδεστήν· ἐμὲ δ’ οὐκ ἐθέλειν ἀνοίγειν· εἶναι δ’ ἃς αὐτοὶ μεμαρτυρήκασιν διαθήκας ἀντιγράφους ἐκείνων. εἶθ’ ἡ διαθήκη γέγραπται.", "st": "45.10"}, {"sp": "N", "t": "ἐγὼ τοίνυν περὶ μὲν τοῦ προκαλεῖσθαί με ἢ μὴ ταῦτα Φορμίωνα, οὐδέν πω λέγω, οὐδ’ ὑπὲρ τοῦ τὰς διαθήκας ἀληθεῖς ἢ ψευδεῖς εἶναι, ἀλλ’ αὐτίχ’ ὑμᾶς περὶ τούτων διδάξω· ἀλλ’ ἃ μεμαρτυρήκασι, μή μ’ ἐθέλειν τὸ γραμματεῖον ἀνοίγειν, ὡδὶ δὴ σκοπεῖτε. τοῦ τις ἂν εἵνεκ’ ἔφευγεν ἀνοίγειν τὸ γραμματεῖον; ἵν’ ἡ διαθήκη νὴ Δία μὴ φανερὰ γένοιτο τοῖς δικασταῖς.", "st": "45.11"}, {"sp": "N", "t": "εἰ μὲν τοίνυν μὴ προσεμαρτύρουν τῇ προκλήσει τὴν διαθήκην οὗτοι, λόγον εἶχέ τιν’ ἂν τὸ φεύγειν ἔμ’ ἀνοίγειν τὸ γραμματεῖον· προσμαρτυρούντων δὲ τούτων καὶ τῶν δικαστῶν ὁμοίως ἀκουσομένων, τί ἦν μοι κέρδος τὸ μὴ ’θέλειν; οὐδὲ ἓν δήπου. αὐτὸ γὰρ τοὐναντίον, ὦ ἄνδρες Ἀθηναῖοι, κἂν εἰ μηδὲν προὐκαλοῦνθ’ οὗτοι, λόγῳ δ’ ἐχρῶντο μόνον, καὶ παρεῖχέν τις αὐτοῖς γραμματεῖον ὡς διαθήκην,", "st": "45.12"}, {"sp": "N", "t": "ἐμὸν ἦν τὸ προκαλεῖσθαι καὶ κελεύειν ἀνοίγειν ταύτην, ἵν’ εἰ μὲν ἄλλ’ ἄττα τῶν ὑπὸ τούτων μεμαρτυρημένων ἦν τἀκεῖ γεγραμμένα, μάρτυρας εὐθὺς τῶν περιεστηκότων πολλοὺς ποιησάμενος τεκμηρίῳ τούτῳ καὶ περὶ τῶν ἄλλων, ὡς κατασκευάζουσιν, ἐχρώμην· εἰ δὲ ταὔτ’ ἐνῆν, τὸν παρασχόντ’ αὐτὸν ἠξίουν μαρτυρεῖν. ἐθελήσαντος μέν γ’ ὑπεύθυνον ἐλάμβανον, εἰ δ’ ἔφευγε, πάλιν αὐτὸ τοῦθ’ ἱκανὸν τεκμήριον ἦν μοι τοῦ πεπλάσθαι τὸ πρᾶγμα. καὶ δὴ καὶ συνέβαινεν ἐκείνως μὲν ἕν’ εἶναι πρὸς ὃν τὰ πράγματ’ ἐγίγνετό μοι, ὡς δ’ οὗτοι μεμαρτυρήκασι, πρὸς πολλούς. ἔστιν οὖν ὅστις ⟨ἂν⟩ ὑμῶν ταῦθ’ εἵλετο; ἐγὼ μὲν οὐδέν’ ἡγοῦμαι.", "st": "45.13"}, {"sp": "N", "t": "οὐ τοίνυν οὐδὲ κατ’ ἄλλου πιστεύειν ἐστὲ δίκαιοι. καὶ γάρ, ὦ ἄνδρες Ἀθηναῖοι, ὅσοις μὲν πρόσεστιν ὀργὴ τῶν πραττομένων ἢ λῆμμά τι κέρδους ἢ παροξυσμὸς ἢ φιλονικία, ταῦτα μὲν ἄλλος ἂν ἄλλως πράξειε πρὸς τὸν αὑτοῦ τρόπον· ὅσοις δὲ τούτων μὲν μηδέν, λογισμὸς δ’ ἐφ’ ἡσυχίας τοῦ συμφέροντος, τίς οὕτως ἄφρων ὅστις ἂν τὰ συνοίσοντ’ ἀφείς, ἐξ ὧν κάκιον ἔμελλεν ἀγωνιεῖσθαι, ταῦτ’ ἔπραξεν; ἃ γὰρ οὔτ’ εἰκότ’ οὔτ’ εὔλογ’ οὔτ’ ἂν ἔπραξεν οὐδείς, ταῦθ’ οὗτοι μεμαρτυρήκασιν περὶ ἡμῶν.", "st": "45.14"}, {"sp": "N", "t": "οὐ τοίνυν μόνον ἐξ ὧν ἐμὲ μὴ ’θέλειν τὸ γραμματεῖον ἀνοίγειν μεμαρτυρήκασι, γνοίη τις ἂν αὐτοὺς ὅτι ψεύδονται, ἀλλὰ καὶ ἐκ τοῦ πρόκλησιν ὁμοῦ διαθήκῃ μαρτυρεῖν. οἶμαι γὰρ ἅπαντας ὑμᾶς εἰδέναι, ὅτι ὅσα μὴ δυνατὸν πρὸς ὑμᾶς ἀγαγεῖν ἐστι τῶν πεπραγμένων, τούτων προκλήσεις ηὑρέθησαν.", "st": "45.15"}, {"sp": "N", "t": "οἷον βασανίζειν οὐκ ἔστιν ἐναντίον ὑμῶν· ἀνάγκη τούτου πρόκλησιν εἶναι. οἷον εἴ τι πέπρακται καὶ γέγονεν ἔξω που τῆς χώρας, ἀνάγκη καὶ τούτου πρόκλησιν εἶναι, πλεῖν ἢ βαδίζειν οὗ τὸ πρᾶγμ’ ἐπράχθη· καὶ τῶν ἄλλων τῶν τοιούτων. ὅπου δ’ αὐτὰ τὰ πράγματ’ ἐφ’ αὑτῶν ἔστιν ὑμῖν ἐμφανῆ ποιῆσαι, τί ἦν ἁπλούστερον ἢ ταῦτ’ ἄγειν εἰς μέσον;", "st": "45.16"}, {"sp": "N", "t": "Ἀθήνησιν μὲν τοίνυν ὁ πατὴρ ἐτελεύτησεν οὑμός, ἐγίγνετο δ’ ἡ δίαιτ’ ἐν τῇ ποικίλῃ στοᾷ, μεμαρτυρήκασι δ’ οὗτοι παρέχειν τὸ γραμματεῖον Ἀμφίαν πρὸς τὸν διαιτητήν. οὐκοῦν εἴπερ ἀληθὲς ἦν, ἐχρῆν αὐτὸ τὸ γραμματεῖον εἰς τὸν ἐχῖνον ἐμβαλεῖν καὶ τὸν παρέχοντα μαρτυρεῖν, ἵν’ ἐκ τῆς ἀληθείας καὶ τοῦ τὰ σημεῖ’ ἰδεῖν οἱ μὲν δικασταὶ τὸ πρᾶγμ’ ἔγνωσαν, ἐγὼ δ’ εἴ τις ἠδίκει με, ἐπὶ τοῦτον ᾖα.", "st": "45.17"}, {"sp": "N", "t": "νῦν δ’ εἷς μὲν οὐδεὶς ὅλον τὸ πρᾶγμ’ ἀνεδέξατο, οὐδὲ μεμαρτύρηκεν ἁπλῶς, ὡς ἄν τις τἀληθῆ μαρτυρήσειεν, μέρος δ’ ἕκαστος, ὡς δὴ σοφὸς καὶ διὰ τοῦτ’ οὐ δώσων δίκην, ὁ μὲν γραμματεῖον ἔχειν ἐφ’ ᾧ γεγράφθαι “διαθήκη Πασίωνος”, ὁ δὲ πεμφθεὶς ὑπὸ τούτου παρέχειν τοῦτο, εἰ δ’ ἀληθὲς ἢ ψεῦδος, οὐδὲν εἰδέναι.", "st": "45.18"}, {"sp": "N", "t": "οἱδὶ δὲ τῇ προκλήσει χρησάμενοι παραπετάσματι διαθήκας ἐμαρτύρησαν, ὡς ἂν μάλισθ’ οἱ ⟨μὲν⟩ δικασταὶ ταύτην τὴν διαθήκην ἐπίστευσαν τοῦ πατρὸς εἶναι, ἐγὼ δ’ ἀπεκλείσθην τοῦ λόγου τυχεῖν ὑπὲρ ὧν ἀδικοῦμαι, οὗτοι δὲ φωραθεῖεν τὰ ψευδῆ μεμαρτυρηκότες. καίτοι τό γ’ ἐναντίον ᾤοντο τούτου. ἵνα δ’ εἰδῆτε ταῦθ’ ὅτι ἀληθῆ λέγω, λαβὲ τὴν τοῦ Κηφισοφῶντος μαρτυρίαν.", "st": "45.19"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "45.19"}, {"sp": "N", "t": "Κηφισοφῶν Κεφαλίωνος Ἀφιδναῖος μαρτυρεῖ καταλειφθῆναι αὑτῷ ὑπὸ τοῦ πατρὸς γραμματεῖον, ἐφ’ ᾧ ἐπιγεγράφθαι “διαθήκη Πασίωνος”.", "st": "45.19"}, {"sp": "N", "t": "οὐκοῦν ἦν ἁπλοῦν, ὦ ἄνδρες δικασταί, τὸν ταῦτα μαρτυροῦντα προσμαρτυρῆσαι “εἶναι δὲ τὸ γραμματεῖον, ὃ αὐτὸς παρέχει, τοῦτο”, καὶ τὸ γραμματεῖον ἐμβαλεῖν. ἀλλὰ τοῦτο μὲν οἶμαι τὸ ψεῦδος ἡγεῖτ’ ὀργῆς ἄξιον, καὶ δίκην ἂν ὑμᾶς παρ’ αὑτοῦ λαβεῖν, γραμματεῖον δ’ αὑτῷ καταλειφθῆναι μαρτυρῆσαι φαῦλον καὶ οὐδέν. ἔστι δὲ τοῦτ’ αὐτὸ τὸ δηλοῦν καὶ κατηγοροῦν ὅτι πᾶν τὸ πρᾶγμα κατεσκευάκασιν.", "st": "45.20"}, {"sp": "N", "t": "εἰ μὲν γὰρ ἐπῆν ἐπὶ τῆς διαθήκης “Πασίωνος καὶ Φορμίωνος”, ἢ “πρὸς Φορμίωνα”, ἢ τοιοῦτό τι, εἰκότως ἂν αὐτὴν ἐτήρει τούτῳ· εἰ δέ, ὥσπερ μεμαρτύρηκεν, ἐπῆν “διαθήκη Πασίωνος”, πῶς οὐκ ἂν ἀνῃρήμην αὐτὴν ἐγώ, συνειδὼς μὲν ἐμαυτῷ μέλλοντι δικάζεσθαι, συνειδὼς δ’ ὑπεναντίαν οὖσαν, εἴπερ ἦν τοιαύτη, τοῖς ἐμαυτῷ συμφέρουσιν, κληρονόμος δ’ ὢν καὶ ταύτης, εἴπερ ἦν τοὐμοῦ πατρός, καὶ τῶν ἄλλων ⟨τῶν⟩ πατρῴων ὁμοίως;", "st": "45.21"}, {"sp": "N", "t": "οὐκοῦν τῷ παρέχεσθαι μὲν Φορμίωνι, γεγράφθαι δὲ Πασίωνος, εἰᾶσθαι δ’ ὑφ’ ἡμῶν, ἐξελέγχεται κατεσκευασμένη μὲν ἡ διαθήκη, ψευδὴς δ’ ἡ τοῦ Κηφισοφῶντος μαρτυρία. ἀλλ’ ἐῶ Κηφισοφῶντα· οὔτε γὰρ νῦν μοι πρὸς ἐκεῖνόν ἐστιν οὔτ’ ἐμαρτύρησεν ἐκεῖνος περὶ τῶν ἐν ταῖς διαθήκαις ἐνόντων οὐδέν.", "st": "45.22"}, {"sp": "N", "t": "καίτοι καὶ τοῦτο σκοπεῖτε, ὅσον ἐστὶ τεκμήριον, ὦ ἄνδρες Ἀθηναῖοι, τοῦ τούτους τὰ ψευδῆ μεμαρτυρηκέναι. εἰ γὰρ ὁ μὲν αὐτὸς ἔχειν τὸ γραμματεῖον μαρτυρῶν οὐκ ἐτόλμησεν ἀντίγραφ’ εἶναι ἃ παρείχετο Φορμίων τῶν παρ’ αὑτῷ μαρτυρῆσαι, οὗτοι δ’ οὔτ’ ἐξ ἀρχῆς ὡς παρῆσαν ἔχοιεν ἂν εἰπεῖν, οὔτ’ ἀνοιχθὲν εἶδον πρὸς τῷ διαιτητῇ τὸ γραμματεῖον, ἀλλὰ καὶ μεμαρτυρήκασιν αὐτοὶ μὴ ’θέλειν ἔμ’ ἀνοίγειν, ταῦθ’ ὡς ἀντίγραφ’ ἐστὶν ἐκείνων μεμαρτυρηκότες τί ἄλλ’ ἢ σφῶν αὐτῶν κατήγοροι γεγόνασιν ὅτι ψεύδονται;", "st": "45.23"}, {"sp": "N", "t": "ἔτι τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, ὡς γέγραπταί τις ἂν ἐξετάσας τὴν μαρτυρίαν γνοίη παντελῶς τοῦτο μεμηχανημένους αὐτούς, ὅπως δικαίως καὶ ἀδίκως δόξει ταῦθ’ ὁ πατὴρ οὑμὸς διαθέσθαι. λαβὲ δ’ αὐτὴν τὴν μαρτυρίαν, καὶ λέγ’ ἐπισχὼν οὗ ἄν σε κελεύω, ἵν’ ἐξ αὐτῆς δεικνύω.", "st": "45.24"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "45.24"}, {"sp": "N", "t": "μαρτυροῦσι παρεῖναι πρὸς τῷ διαιτητῇ Τεισίᾳ, ὅτε προὐκαλεῖτο Φορμίων Ἀπολλόδωρον, εἰ μή φησιν ἀντίγραφα εἶναι τῶν διαθηκῶν τῶν Πασίωνος—", "st": "45.24"}, {"sp": "N", "t": "ἐπίσχες. ἐνθυμεῖσθ’ ὅτι “τῶν διαθηκῶν” γέγραπται “τῶν Πασίωνος”. καίτοι χρῆν τοὺς βουλομένους τἀληθῆ μαρτυρεῖν, εἰ τὰ μάλιστ’ ἐγίγνεθ’ ἡ πρόκλησις, ὡς οὐκ ἐγίγνετο, ἐκείνως μαρτυρεῖν. λέγε τὴν μαρτυρίαν ἀπ’ ἀρχῆς πάλιν.", "st": "45.25"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "45.25"}, {"sp": "N", "t": "μαρτυροῦσι παρεῖναι πρὸς τῷ διαιτητῇ Τεισίᾳ—", "st": "45.25"}, {"sp": "N", "t": "Μαρτυροῦμεν· παρῆμεν γὰρ δή· λέγε.", "st": "45.25"}, {"sp": "N", "t": "ὅτε προὐκαλεῖτο Φορμίων Ἀπολλόδωρον—", "st": "45.25"}, {"sp": "N", "t": "Καὶ τοῦτο, εἴπερ προὐκαλεῖτο, ὀρθῶς ἂν ἐμαρτύρουν.", "st": "45.25"}, {"sp": "N", "t": "εἰ μή φησιν ἀντίγραφα εἶναι τῶν διαθηκῶν τῶν Πασίωνος—", "st": "45.25"}, {"sp": "N", "t": "ἔχ’ αὐτοῦ. οὐδ’ ἂν εἷς ἔτι δήπου τοῦτ’ ἐμαρτύρησεν, εἰ μή τις καὶ παρῆν διατιθεμένῳ τῷ πατρὶ τῷ ἐμῷ· ἀλλ’ εὐθὺς ἂν εἶπε “τί δ’ ἡμεῖς ἴσμεν εἴ τινές εἰσι διαθῆκαι Πασίωνος;” καὶ γράφειν ἂν αὐτὸν ἠξίωσεν, ὥσπερ ἐν ἀρχῇ τῆς προκλήσεως “εἰ μή φημ’ ἐγὼ ἀντίγραφα εἶναι τῶν διαθηκῶν”, οὕτως “ὧν φησι Φορμίων Πασίωνα καταλιπεῖν”, οὐ “τῶν Πασίωνος”. τοῦτο μὲν γὰρ ἦν εἶναι διαθήκας μαρτυρεῖν, ὅπερ ἦν τούτοις βούλημα, ἐκεῖνο δὲ φάσκειν Φορμίωνα· πλεῖστον δὲ δήπου κεχώρισται τό τ’ εἶναι καὶ τὸ τοῦτον φάσκειν.", "st": "45.26"}, {"sp": "N", "t": "ἵνα τοίνυν εἰδῆθ’ ὑπὲρ ἡλίκων καὶ ὅσων ἦν τὸ κατασκεύασμα τὸ τῆς διαθήκης, μίκρ’ ἀκούσατέ μου. ἦν γάρ, ὦ ἄνδρες Ἀθηναῖοι, τοῦτο πρῶτον μὲν ὑπὲρ τοῦ μὴ δοῦναι δίκην ὧν διεφθάρκει, ἣν ἐμοὶ μὲν οὐ καλὸν λέγειν, ὑμεῖς δ’ ἴστε, κἂν ἐγὼ μὴ λέγω, ἔπειθ’ ὑπὲρ τοῦ κατασχεῖν ὅσ’ ἦν τῷ ἡμετέρῳ πατρὶ χρήματα παρὰ τῇ μητρί, πρὸς δὲ τούτοις ὑπὲρ τοῦ καὶ τῶν ἄλλων τῶν ἡμετέρων ἁπάντων κυρίῳ γενέσθαι. ὅτι δ’ οὕτω ταῦτ’ ἔχει, τῆς διαθήκης αὐτῆς ἀκούσαντες γνώσεσθε· φανήσεται γὰρ οὐ πατρὸς ὡς ὑπὲρ υἱέων γράφοντος ἐοικυῖα διαθήκῃ, ἀλλὰ δούλου λελυμασμένου τὰ τῶν δεσποτῶν, ὅπως μὴ δώσει δίκην σκοποῦντος.", "st": "45.27"}, {"sp": "N", "t": "λέγε δ’ αὐτοῖς τὴν διαθήκην αὐτήν, ἣν οὗτοι μετὰ τῆς προκλήσεως μεμαρτυρήκασιν· ὑμεῖς δ’ ἐνθυμεῖσθ’ ἃ λέγω.", "st": "45.28"}, {"sp": "N", "t": "ΔΙΑΘΗΚΗ.", "st": "45.28"}, {"sp": "N", "t": "τάδε διέθετο Πασίων Ἀχαρνεύς· δίδωμι τὴν ἐμαυτοῦ γυναῖκα Ἀρχίππην Φορμίωνι, καὶ προῖκα ἐπιδίδωμι Ἀρχίππῃ τάλαντον μὲν τὸ ἐκ Πεπαρήθου, τάλαντον δὲ τὸ αὐτόθεν, συνοικίαν ἑκατὸν μνῶν, θεραπαίνας καὶ τὰ χρυσία, καὶ τἄλλα ὅσα ἐστὶν αὐτῇ ἔνδον, ἅπαντα ταῦτα Ἀρχίππῃ δίδωμι.", "st": "45.28"}, {"sp": "N", "t": "ἠκούσατ’, ὦ ἄνδρες Ἀθηναῖοι, τὸ πλῆθος τῆς προικός, τάλαντον ἐκ Πεπαρήθου, τάλαντον αὐτόθεν, συνοικίαν ἑκατὸν μνῶν, θεραπαίνας καὶ χρυσία, καὶ τἄλλα, φησίν, ὅσ’ ἔστιν αὐτῇ δίδωμι, τούτῳ τῷ γράμματι καὶ τοῦ ζητῆσαί τι τῶν καταλειφθέντων ἀποκλείων ἡμᾶς.", "st": "45.28"}, {"sp": "N", "t": "φέρε δὴ δείξω τὴν μίσθωσιν ὑμῖν, καθ’ ἣν ἐμεμίσθωτο τὴν τράπεζαν παρὰ τοῦ πατρὸς οὗτος. καὶ γὰρ ἐκ ταύτης καίπερ ἐσκευωρημένης ὄψεσθ’ ὅτι πλάσμ’ ὅλον ἐστὶν ἡ διαθήκη. δείξω δ’ ἣν οὗτος παρέσχετο μίσθωσιν, οὐκ ἄλλην τινά, ἐν ᾗ προσγέγραπται ἕνδεκα τάλανθ’ ὁ πατὴρ ὀφείλων εἰς τὰς παρακαταθήκας τούτῳ. ἔστι δ’ οἶμαι ταῦτα τοιαῦτα.", "st": "45.29"}, {"sp": "N", "t": "τῶν μὲν οἴκοι χρημάτων ὡς ἐπὶ τῇ μητρὶ δοθέντων διὰ τῆς διαθήκης αὑτὸν ἐποίησε κύριον, ὥσπερ ἀκηκόατ’ ἄρτι, τῶν δ’ ἐπὶ τῆς τραπέζης ὄντων, ἃ πάντες ᾔδεσαν καὶ λαθεῖν οὐκ ἦν, διὰ τοῦ προσοφείλοντ’ ἀποφῆναι τὸν πατέρ’ ἡμῶν, ἵνα, ὅσ’ ἐξελέγχοιτ’ ἔχων, κεκομίσθαι φαίη. ὑμεῖς δ’ ἴσως αὐτὸν ὑπειλήφατε, ὅτι σολοικίζει τῇ φωνῇ, βάρβαρον καὶ εὐκαταφρόνητον εἶναι. ἔστι δὲ βάρβαρος οὗτος τῷ μισεῖν οὓς αὐτῷ προσῆκε τιμᾶν· τῷ δὲ κακουργῆσαι καὶ διορύξαι πράγματ’ οὐδενὸς λείπεται.", "st": "45.30"}, {"sp": "N", "t": "λαβὲ δὴ τὴν μίσθωσιν καὶ λέγε, ἣν τὸν αὐτὸν τρόπον διὰ προκλήσεως ἐνεβάλοντο.", "st": "45.31"}, {"sp": "N", "t": "ΜΙΣΘΩΣΙΣ ΤΡΑΠΕΖΗΣ.", "st": "45.31"}, {"sp": "N", "t": "κατὰ τάδε ἐμίσθωσε Πασίων τὴν τράπεζαν Φορμίωνι· μίσθωσιν φέρειν Φορμίωνα τῆς τραπέζης τοῖς παισὶ τοῖς Πασίωνος δύο τάλαντα καὶ τετταράκοντα μνᾶς τοῦ ἐνιαυτοῦ ἑκάστου, χωρὶς τῆς καθ’ ἡμέραν διοικήσεως· μὴ ἐξεῖναι δὲ τραπεζιτεῦσαι χωρὶς Φορμίωνι, ἐὰν μὴ πείσῃ τοὺς παῖδας τοὺς Πασίωνος. ὀφείλει δὲ Πασίων ἐπὶ τὴν τράπεζαν ἕνδεκα τάλαντα εἰς τὰς παρακαταθήκας.", "st": "45.31"}, {"sp": "N", "t": "ἃς μὲν τοίνυν παρέσχετο συνθήκας ὡς κατὰ ταύτας μισθωσάμενος τὴν τράπεζαν, αὗταί εἰσιν, ὦ ἄνδρες δικασταί. ἀκούετε δ’ ἐν ταύταις ἀναγιγνωσκομέναις μίσθωσιν μὲν φέρειν τοῦτον, ἄνευ τῆς καθ’ ἡμέραν διοικήσεως, δύο τάλαντα καὶ τετταράκοντα μνᾶς τοῦ ἐνιαυτοῦ ἑκάστου, μὴ ἐξεῖναι δὲ τραπεζιτεύειν αὐτῷ, ἐὰν μὴ ἡμᾶς πείσῃ. προσγέγραπται δὲ τελευταῖον “ὀφείλει δὲ Πασίων ἕνδεκα τάλαντα εἰς τὰς παρακαταθήκας”.", "st": "45.32"}, {"sp": "N", "t": "ἔστιν οὖν ὅστις ἂν τοῦ ξύλου καὶ τοῦ χωρίου καὶ τῶν γραμματείων τοσαύτην ὑπέμεινε φέρειν μίσθωσιν; ἔστι δ’ ὅστις ἄν, δι’ ὃν ὠφειλήκει τοσαῦτα χρήμαθ’ ἡ τράπεζα, τούτῳ τὰ λοίπ’ ἐπέτρεψεν; εἰ γὰρ ἐνεδέησεν τοσούτων χρημάτων, τούτου διοικοῦντος ἐνεδέησεν. ἴστε γὰρ πάντες, καὶ ὅτ’ ἦν ὁ πατὴρ ἐπὶ τοῦ τραπεζιτεύειν, τοῦτον καθήμενον καὶ διοικοῦντ’ ἐπὶ τῇ τραπέζῃ, ὥστ’ ἐν τῷ μυλῶνι προσῆκεν αὐτὸν εἶναι μᾶλλον ἢ τῶν λοιπῶν κύριον γενέσθαι. ἀλλ’ ἐῶ ταῦτα καὶ τἄλλ’ ὅσ’ ἂν περὶ τῶν ἕνδεκα ταλάντων ἔχοιμ’ εἰπεῖν, ὡς οὐκ ὤφειλεν ὁ πατήρ, ἀλλ’ οὗτος ὑφῄρηται.", "st": "45.33"}, {"sp": "N", "t": "ἀλλ’ οὗ ἀνέγνων εἵνεκα, τοῦ τὴν διαθήκην ψευδῆ δεῖξαι, τοῦθ’ ὑμᾶς ἀναμνήσω. γέγραπται γὰρ αὐτόθι, “μὴ ἐξεῖναι δὲ τραπεζιτεύειν Φορμίωνι, ἐὰν μὴ ἡμᾶς πείσῃ”. τοῦτο τοίνυν τὸ γράμμα παντελῶς δηλοῖ ψευδῆ τὴν διαθήκην οὖσαν. τίς γὰρ ⟨ἂν⟩ ἀνθρώπων, ἃ μὲν ἔμελλεν τραπεζιτεύων οὗτος ἐργάζεσθαι, ταῦθ’ ὅπως ἡμῖν τοῖς αὑτοῦ παισίν, ἀλλὰ μὴ τούτῳ γενήσεται προὐνοήθη, καὶ διὰ τοῦτο μὴ ἐξεῖναι τούτῳ τραπεζιτεύειν ἔγραψεν, ἵνα μὴ ἀφιστῆται ἀφ’ ἡμῶν· ἃ δ’ αὐτὸς εἰργασμένος ἔνδον κατέλειπε, ταῦθ’ ὅπως οὗτος λήψεται παρεσκεύασε;", "st": "45.34"}, {"sp": "N", "t": "καὶ τῆς μὲν ἐργασίας ἐφθόνησεν, ἧς οὐδὲν αἰσχρὸν ἦν μεταδοῦναι· τὴν δὲ γυναῖκ’ ἔδωκεν, οὗ μεῖζον οὐδὲν ἂν κατέλιπεν ὄνειδος, τυχών γε τῆς παρ’ ὑμῶν δωρεᾶς, εἶθ’ ὥσπερ ἂν δοῦλος δεσπότῃ διδούς, ἀλλ’ οὐ τοὐναντίον, εἴπερ ἐδίδου, δεσπότης οἰκέτῃ, προστιθεὶς προῖκα ὅσην οὐδεὶς τῶν ἐν τῇ πόλει φαίνεται;", "st": "45.35"}, {"sp": "N", "t": "καίτοι τούτῳ μὲν αὐτὸ τοῦτ’ ἀγαπητὸν ἦν, τὸ τῆς δεσποίνης ἀξιωθῆναι· τῷ πατρὶ δ’ οὐδὲ λαμβάνοντι τοσαῦτα χρήματα, ὅσα φασὶ διδόνθ’ οὗτοι, εὔλογον ἦν πρᾶξαι ταῦτα. ἀλλ’ ὅμως ἃ τοῖς εἰκόσι, τοῖς χρόνοις, τοῖς πεπραγμένοις ἐξελέγχεται ψευδῆ, ταῦτα μαρτυρεῖν οὐκ ὤκνησεν οὑτοσὶ Στέφανος.", "st": "45.36"}, {"sp": "N", "t": "εἶτα λέγει περιιών, ὡς ἐμαρτύρησε μὲν Νικοκλῆς ἐπιτροπεῦσαι κατὰ τὴν διαθήκην, ἐμαρτύρησε δὲ Πασικλῆς ἐπιτροπευθῆναι κατὰ τὴν διαθήκην. ἐγὼ δ’ αὐτὰ ταῦτ’ οἶμαι τεκμήρι’ εἶναι τοῦ μήτ’ ἐκείνους τἀληθῆ μήτε τούσδε μεμαρτυρηκέναι. ὁ γὰρ ἐπιτροπεῦσαι κατὰ διαθήκας μαρτυρῶν δῆλον ὅτι καθ’ ὁποίας ἂν εἰδείη, καὶ ὁ ἐπιτροπευθῆναι κατὰ διαθήκας μαρτυρῶν δῆλον ὅτι καθ’ ὁποίας ἂν εἰδείη.", "st": "45.37"}, {"sp": "N", "t": "τί οὖν μαθόντες ἐμαρτυρεῖθ’ ὑμεῖς ἐν προκλήσει διαθήκας, ἀλλ’ οὐκ ἐκείνους εἰᾶτε; εἰ γὰρ αὖ μὴ φήσουσιν εἰδέναι τὰ γεγραμμέν’ ἐν αὐταῖς, πῶς ὑμᾶς οἷόν τ’ εἰδέναι τοὺς μηδαμῇ μηδαμῶς τοῦ πράγματος ἐγγύς; τί ποτ’ οὖν οἱ μὲν ἐκεῖνα, οἱ δὲ ταῦτ’ ἐμαρτύρησαν; ὅπερ εἴρηκα καὶ πρότερον, διείλοντο τἀδικήματα, καὶ ἐπιτροπεῦσαι μὲν κατὰ διαθήκην οὐδὲν δεινὸν ἡγεῖτο μαρτυρεῖν ὁ μαρτυρῶν, οὐδ’ ἐπιτροπευθῆναι κατὰ διαθήκην,", "st": "45.38"}, {"sp": "N", "t": "ἀφαιρῶν ἑκάτερος τὸ μαρτυρεῖν τὰ ἐν ταῖς διαθήκαις ὑπὸ τούτου γεγραμμένα, οὐδὲ καταλιπεῖν τὸν πατέρ’ αὑτῷ ἐπιγεγραμμένον γραμματεῖον διαθήκην, οὐδὲ τὰ τοιαῦτα· διαθήκας δὲ μαρτυρεῖν, ἐν αἷς χρημάτων τοσούτων κλοπή, γυναικὸς διαφθορά, γάμοι δεσποίνης, πράγματ’ αἰσχύνην καὶ ὕβριν τοσαύτην ἔχοντα, οὐδεὶς ἤθελε πλὴν οὗτοι, πρόκλησιν κατασκευάσαντες, παρ’ ὧν δίκαιον τῆς ὅλης τέχνης καὶ κακουργίας δίκην λαβεῖν.", "st": "45.39"}, {"sp": "N", "t": "ἵνα τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, μὴ μόνον ἐξ ὧν ἐγὼ κατηγορῶ καὶ ἐλέγχω, δῆλος ὑμῖν γένηται τὰ ψευδῆ μεμαρτυρηκὼς οὑτοσὶ Στέφανος, ἀλλὰ καὶ ἐξ ὧν πεποίηκεν ὁ παρασχόμενος αὐτόν, τὰ πεπραγμέν’ ἐκείνῳ βούλομαι πρὸς ὑμᾶς εἰπεῖν. ὅπερ δ’ εἶπον ἀρχόμενος τοῦ λόγου, δείξω κατηγόρους γιγνομένους αὐτοὺς ἑαυτῶν. τὴν γὰρ δίκην, ἐν ᾗ ταῦτ’ ἐμαρτυρήθη, παρεγράψατο Φορμίων πρὸς ἐμὲ μὴ εἰσαγώγιμον εἶναι, ὡς ἀφέντος ἐμοῦ τῶν ἐγκλημάτων αὐτόν.", "st": "45.40"}, {"sp": "N", "t": "τοῦτο τοίνυν ἐγὼ μὲν οἶδα ψεῦδος ὄν, καὶ ἐλέγξω δέ, ὅταν εἰσίω πρὸς τοὺς ταῦτα μεμαρτυρηκότας· τούτῳ δ’ οὐχ οἷόν τε τοῦτ’ εἰπεῖν. εἰ τοίνυν ἀληθῆ πιστεύσαιτ’ εἶναι τὴν ἄφεσιν, οὕτω καὶ μάλιστ’ ἂν οὗτος φανείη ψευδῆ μεμαρτυρηκὼς καὶ κατεσκευασμένης διαθήκης μάρτυς γεγονώς. τίς γὰρ οὕτως ἄφρων ὥστ’ ἄφεσιν μὲν ἐναντίον μαρτύρων ποιήσασθαι τοῦ βεβαίαν αὑτῷ τὴν ἀπαλλαγὴν εἶναι, τὰς δὲ συνθήκας καὶ τὰς διαθήκας καὶ τἄλλα, ὑπὲρ ὧν ἐποιεῖτο τὴν ἄφεσιν, σεσημασμέν’ ἐᾶσαι καθ’ αὑτοῦ κεῖσθαι;", "st": "45.41"}, {"sp": "N", "t": "οὐκοῦν ἐναντία μὲν ἡ παραγραφὴ πᾶσι τοῖς μεμαρτυρημένοις, ἐναντία δ’ ἣν ἀνέγνων ὑμῖν ἄρτι μίσθωσιν, τῇδε τῇ διαθήκῃ· οὐδὲν δὲ τῶν πεπραγμένων οὔτ’ εὔλογον οὔθ’ ἁπλοῦν οὔθ’ ὁμολογούμενον αὐτὸ ἑαυτῷ φαίνεται. ἐκ δὲ τούτου τοῦ τρόπου πάντα πεπλασμένα καὶ κατεσκευασμέν’ ἐλέγχεται.", "st": "45.42"}, {"sp": "N", "t": "ὡς μὲν τοίνυν ἐστὶν ἀληθῆ τὰ μεμαρτυρημένα, οὔτ’ αὐτὸν τοῦτον οὔτ’ ἄλλον ὑπὲρ τούτου δεῖξαι δυνήσεσθαι νομίζω. ἀκούω δ’ αὐτὸν τοιοῦτόν τι παρεσκευάσθαι λέγειν, ὡς προκλήσεώς ἐστιν ὑπεύθυνος, οὐχὶ μαρτυρίας, καὶ δυοῖν αὐτῷ προσήκει δοῦναι λόγον, οὐ πάντων τῶν γεγραμμένων, εἴ τε προὐκαλεῖτό με ταῦτα Φορμίων ἢ μή, καὶ εἰ μὴ ἐδεχόμην ἐγώ· ταῦτα μὲν γὰρ ἁπλῶς αὐτὸς μεμαρτυρηκέναι φήσει, τὰ δ’ ἄλλ’ ἐκεῖνον προκαλεῖσθαι, εἰ δ’ ἐστὶν ἢ μὴ ταῦτα, οὐδὲν προσήκειν αὑτῷ σκοπεῖν.", "st": "45.43"}, {"sp": "N", "t": "πρὸς δὴ τὸν λόγον τοῦτον καὶ τὴν ἀναίδειαν βέλτιόν ἐστι μικρὰ προειπεῖν ὑμῖν, ἵνα μὴ λάθητ’ ἐξαπατηθέντες. πρῶτον μέν, ὅταν ἐγχειρῇ λέγειν τοῦτο, ὡς ἄρ’ οὐ πάντων ὑπεύθυνός ἐστιν, ἐνθυμεῖσθ’ ὅτι διὰ ταῦθ’ ὁ νόμος μαρτυρεῖν ἐν γραμματείῳ κελεύει, ἵνα μήτ’ ἀφελεῖν ἐξῇ μήτε προσθεῖναι τοῖς γεγραμμένοις μηδέν. τότ’ οὖν αὐτὸν ἔδει ταῦτ’ ἀπαλείφειν κελεύειν ἃ νῦν οὐ φήσει μεμαρτυρηκέναι, οὐ νῦν ἐνόντων ἀναισχυντεῖν.", "st": "45.44"}, {"sp": "N", "t": "ἔπειτα καὶ τόδε σκοπεῖτε, εἰ ἐάσαιτ’ ἂν ἐναντίον ὑμῶν ἐμὲ προσγράψαι τι λαβόντα τὸ γραμματεῖον. οὐ δήπου. οὔκουν οὐδὲ τοῦτον ἀφαιρεῖν τῶν γεγραμμένων ἐᾶν προσήκει. τίς γὰρ ἁλώσεταί ποτε ψευδομαρτυρίων, εἰ μαρτυρήσει θ’ ἃ βούλεται, καὶ λόγον ὧν βούλεται δώσει; ἀλλ’ οὐχ οὕτω ταῦτ’ οὔθ’ ὁ νόμος διεῖλεν οὔθ’ ὑμῖν ἀκούειν προσήκει· ἀλλ’ ἐκεῖν’ ἁπλοῦν καὶ δίκαιον. τί γέγραπται; τί μεμαρτύρηκας; ταῦθ’ ὡς ἀληθῆ δείκνυε. καὶ γὰρ ἀντιγέγραψαι ταῦτα “ἀληθῆ μεμαρτύρηκα, μαρτυρήσας τὰ ἐν τῷ γραμματείῳ γεγραμμένα”, οὐ τὸ καὶ τὸ τῶν ἐν τῷ γραμματείῳ.", "st": "45.45"}, {"sp": "N", "t": "ὅτι δ’ οὕτω ταῦτ’ ἔχει, λαβὲ τὴν ἀντιγραφὴν αὐτήν μοι. λέγε.", "st": "45.46"}, {"sp": "N", "t": "ΑΝΤΙΓΡΑΦΗ.", "st": "45.46"}, {"sp": "N", "t": "Ἀπολλόδωρος Πασίωνος Ἀχαρνεὺς Στεφάνῳ Μενεκλέους Ἀχαρνεῖ ψευδομαρτυρίων, τίμημα τάλαντον. τὰ ψευδῆ μου κατεμαρτύρησε Στέφανος μαρτυρήσας τὰ ἐν τῷ γραμματείῳ γεγραμμένα.", "st": "45.46"}, {"sp": "N", "t": "⟨Στέφανος Μενεκλέους Ἀχαρνεὺς⟩ τἀληθῆ ἐμαρτύρησα μαρτυρήσας τὰ ἐν τῷ γραμματείῳ γεγραμμένα.", "st": "45.46"}, {"sp": "N", "t": "ταῦθ’ οὗτος ἀντεγράψατο, ἃ χρὴ μνημονεύειν ὑμᾶς, καὶ μὴ τοὺς ἐπ’ ἐξαπάτῃ νῦν λόγους ὑπὸ τούτου ῥηθησομένους πιστοτέρους ποιεῖσθαι τῶν νόμων καὶ τῶν ὑπὸ τούτου γραφέντων εἰς τὴν ἀντιγραφήν.", "st": "45.46"}, {"sp": "N", "t": "πυνθάνομαι τοίνυν αὐτοὺς καὶ περὶ ὧν ἔλαχον τὴν ἐξ ἀρχῆς δίκην, ἐρεῖν καὶ κατηγορήσειν, ὡς συκοφαντήματ’ ἦν. ἐγὼ δ’ ὃν μὲν τρόπον ἐσκευωρήσατο τὴν μίσθωσιν, ὅπως τὴν ἀφορμὴν τῆς τραπέζης κατάσχοι, εἶπον καὶ διεξῆλθον ὑμῖν, ὑπὲρ δὲ τῶν ἄλλων οὐκ ἂν οἷός τ’ εἴην λέγειν ἅμα καὶ τούτους ἐλέγχειν περὶ τῆς μαρτυρίας· οὐ γὰρ ἱκανόν μοι τὸ ὕδωρ ἐστίν.", "st": "45.47"}, {"sp": "N", "t": "ὅτι δ’ οὐδ’ ὑμεῖς ἐθέλοιτ’ ἂν εἰκότως ἀκούειν περὶ τούτων αὐτῶν, ἐκεῖθεν εἴσεσθε, ἂν λογίσησθε πρὸς ὑμᾶς αὐτούς, ὅτι οὔτε νῦν ἐστιν χαλεπὸν περὶ ὧν μὴ κατηγόρηται λέγειν, οὔτε ⟨τότε⟩ ψευδεῖς ἀναγνόντα μαρτυρίας ἀποφεύγειν. ἀλλ’ οὐδέτερόν γε δίκαιον τούτων οὐδ’ ἂν εἷς φήσειεν εἶναι, ἀλλ’ ὃ ἐγὼ προκαλοῦμαι νῦν. σκοπεῖτε δ’ ἀκούσαντες.", "st": "45.48"}, {"sp": "N", "t": "ἐγὼ γὰρ ἀξιῶ, οὓς μὲν ἀφείλοντό μ’ ἐλέγχους περὶ τῶν ἐγκλημάτων, οὓς προσῆκον ἦν ῥηθῆναι, μὴ ζητεῖν αὐτοὺς νῦν, αἷς δ’ ἀφείλοντο μαρτυρίαις, ὡς εἰσὶν ἀληθεῖς, δεικνύναι. εἰ δ’ ὅταν μὲν τὴν δίκην εἰσίω, τὰς μαρτυρίας μ’ ἐλέγχειν ἀξιώσουσιν, ὅταν δὲ ταύταις ἐπεξίω, περὶ τῶν ἐξ ἀρχῆς ἐγκλημάτων λέγειν με κελεύσουσιν, οὔτε δίκαι’ οὔθ’ ὑμῖν συμφέροντ’ ἐροῦσιν.", "st": "45.49"}, {"sp": "N", "t": "δικάσειν γὰρ ὀμωμόκαθ’ ὑμεῖς οὐ περὶ ὧν ἂν ὁ φεύγων ἀξιοῖ, ἀλλ’ ὑπὲρ αὐτῶν ὧν ἂν ἡ δίωξις ᾖ. ταύτην δ’ ἀνάγκη τῇ τοῦ διώκοντος λήξει δηλοῦσθαι, ἣν ἐγὼ τούτῳ ψευδομαρτυρίων εἴληχα. μὴ δὴ τοῦτ’ ἀφεὶς περὶ ὧν οὐκ ἀγωνίζεται λεγέτω· μηδ’ ὑμεῖς ἐᾶτε, ἂν ἄρ’ οὗτος ἀναισχυντῇ.", "st": "45.50"}, {"sp": "N", "t": "οἴομαι τοίνυν αὐτὸν οὐδὲν οὐδαμῇ δίκαιον ἔχοντα λέγειν ἥξειν καὶ ἐπὶ τοῦτο, ὡς ἄτοπον ποιῶ, παραγραφὴν ἡττημένος, τοὺς διαθήκην μαρτυρήσαντας διώκων, καὶ τοὺς δικαστὰς τοὺς τότε φήσειν διὰ τοὺς ἀφεῖναι μεμαρτυρηκότας ἀποψηφίσασθαι μᾶλλον ἢ διὰ τοὺς διαθήκην μαρτυρήσαντας. ἐγὼ δ’, ὦ ἄνδρες Ἀθηναῖοι, νομίζω πάντας ὑμᾶς εἰδέναι, ὅτι οὐχ ἧττον τὰ πεπραγμέν’ εἰώθατε σκοπεῖν ἢ τὰς ὑπὲρ τούτων παραγραφάς· περὶ δὴ τῶν πραγμάτων αὐτῶν τὰ ψευδῆ καταμαρτυρήσαντες οὗτοί μου, ἀσθενεῖς τοὺς περὶ τῆς παραγραφῆς ἐποίησαν λόγους.", "st": "45.51"}, {"sp": "N", "t": "χωρὶς δὲ τούτων ἄτοπον, πάντων τὰ ψευδῆ μαρτυρησάντων, τίς μάλιστ’ ἔβλαψεν ἀποφαίνειν, ἀλλ’ οὐχ ὡς αὐτὸς ἕκαστος ἀληθῆ μεμαρτύρηκε δεικνύναι. οὐ γάρ, ἂν ἕτερον δείξῃ δεινότερ’ εἰργασμένον, ἀποφεύγειν αὐτῷ προσήκει, ἀλλ’ ἂν αὐτὸς ὡς ἀληθῆ μεμαρτύρηκεν ἀποφήνῃ.", "st": "45.52"}, {"sp": "N", "t": "ἐφ’ ᾧ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, μάλιστ’ ἀπολωλέναι δίκαιός ἐστιν οὑτοσὶ Στέφανος, τοῦτ’ ἀκούσατέ μου. δεινὸν μὲν γάρ ἐστιν εἰ καὶ καθ’ ὅτου τις οὖν τὰ ψευδῆ μαρτυρεῖ, πολλῷ δὲ δεινότερον καὶ πλείονος ὀργῆς ἄξιον εἰ κατὰ τῶν συγγενῶν· οὐ γὰρ τοὺς γεγραμμένους νόμους ὁ τοιοῦτος ἄνθρωπος μόνον, ἀλλὰ καὶ τὰ τῆς φύσεως οἰκεῖ’ ἀναιρεῖ.", "st": "45.53"}, {"sp": "N", "t": "τοῦτο τοίνυν ἐπιδειχθήσεται πεποιηκὼς οὗτος. ἔστι γὰρ ἡ τούτου μήτηρ καὶ ὁ τῆς ἐμῆς γυναικὸς πατὴρ ἀδελφοί, ὥστε τὴν μὲν γυναῖκα τὴν ἐμὴν ἀνεψιὰν εἶναι τούτῳ, τοὺς δὲ παῖδας τοὺς ἐκείνης καὶ τοὺς ἐμοὺς ἀνεψιαδοῦς. ἆρ’ οὖν δοκεῖ ποτ’ ἂν ὑμῖν οὗτος, εἴ τι δι’ ἔνδειαν εἶδε ποιούσας ὧν οὐ χρὴ τὰς αὑτοῦ συγγενεῖς, ὅπερ ἤδη πολλοὶ πεποιήκασι, παρ’ αὑτοῦ προῖκ’ ἐπιδοὺς ἐκδοῦναι, ὃς ὑπὲρ τοῦ μηδ’ ἃ προσήκει κομίσασθαι ταύτας τὰ ψευδῆ μαρτυρεῖν ἠθέλησεν, καὶ περὶ πλείονος ἐποιήσατο τὸν Φορμίωνος πλοῦτον ἢ τὰ τῆς συγγενείας ἀναγκαῖα; ἀλλὰ μὴν ὅτι ταῦτ’ ἀληθῆ λέγω,", "st": "45.54"}, {"sp": "N", "t": "λαβὲ τὴν μαρτυρίαν τὴν Δεινίου καὶ ἀναγίγνωσκε, καὶ κάλει Δεινίαν.", "st": "45.55"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "45.55"}, {"sp": "N", "t": "Δεινίας Θεομνήστου Ἀθμονεὺς μαρτυρεῖ τὴν θυγατέρα ⟨τὴν⟩ αὑτοῦ ἐκδοῦναι Ἀπολλοδώρῳ κατὰ τοὺς νόμους γυναῖκα ἔχειν, καὶ μηδεπώποτε παραγενέσθαι μηδὲ αἰσθέσθαι ὅτι Ἀπολλόδωρος ἀφῆκε τῶν ἐγκλημάτων ἁπάντων Φορμίωνα.", "st": "45.55"}, {"sp": "N", "t": "ὅμοιός γ’ ὁ Δεινίας, ὦ ἄνδρες δικασταί, τούτῳ, ὃς ὑπὲρ τῆς θυγατρὸς καὶ τῶν θυγατριδῶν καὶ ἐμοῦ τοῦ κηδεστοῦ διὰ τὴν συγγένειαν οὐδὲ τἀληθῆ μαρτυρεῖν ἐθέλει κατὰ τούτου. ἀλλ’ οὐχ οὑτοσὶ Στέφανος, οὐκ ὤκνησε καθ’ ἡμῶν τὰ ψευδῆ μαρτυρεῖν, οὐδ’, εἰ μηδένα τῶν ἄλλων, τὴν αὑτοῦ μητέρα ᾐσχύνθη τοῖς ἀπ’ ἐκείνης οἰκείοις τῆς ἐσχάτης ἐνδείας αἴτιος γενόμενος.", "st": "45.56"}, {"sp": "N", "t": "ὃ τοίνυν ἔπαθον δεινότατον καὶ ἐφ’ ᾧ μάλιστ’ ἐξεπλάγην ὅτ’ ἠγωνιζόμην, ὦ ἄνδρες δικασταί, τοῦθ’ ὑμῖν εἰπεῖν βούλομαι· τήν τε γὰρ τούτου πονηρίαν ἔτι μᾶλλον ὑμεῖς ὄψεσθε, καὶ ἐγὼ τῶν γεγενημένων ἀποδυράμενος τὰ πλεῖστα πρὸς ὑμᾶς ὡσπερεὶ ῥᾴων ἔσομαι. τὴν γὰρ μαρτυρίαν ἣν ᾤμην εἶναι καὶ δι’ ἧς ἦν ὁ πλεῖστος ἔλεγχός μοι, ταύτην οὐχ ηὗρον ἐνοῦσαν ἐν τῷ ἐχίνῳ.", "st": "45.57"}, {"sp": "N", "t": "τότε μὲν δὴ τῷ κακῷ πληγεὶς οὐδὲν ἄλλ’ εἶχον ποιῆσαι πλὴν ὑπολαμβάνειν τὴν ἀρχὴν ἠδικηκέναι με καὶ τὸν ἐχῖνον κεκινηκέναι. νῦν δ’ ἀφ’ ὧν ὕστερον πέπυσμαι, πρὸς αὐτῷ τῷ διαιτητῇ Στέφανον τουτονὶ αὐτὴν ὑφῃρημένον εὑρίσκω, πρὸς μαρτυρίαν τιν’ ἵν’ ἐξορκώσαιμι, ἀναστάντος ἐμοῦ. καὶ ὅτι ταῦτ’ ἀληθῆ λέγω, πρῶτον μὲν ὑμῖν μαρτυρήσουσιν τῶν τούτοις παρόντων οἱ ἰδόντες.", "st": "45.58"}, {"sp": "N", "t": "οὐ γὰρ ἐξομνύναι ’θελήσειν αὐτοὺς οἴομαι. ἐὰν δ’ ἄρα τοῦτο ποιήσωσιν ὑπ’ ἀναιδείας, πρόκλησιν ὑμῖν ἀναγνώσεται, ἐξ ἧς τούτους τ’ ἐπιορκοῦντας ἐπ’ αὐτοφώρῳ λήψεσθε, καὶ τοῦτον ὁμοίως ὑφῃρημένον τὴν μαρτυρίαν εἴσεσθε. καίτοι ὅστις, ὦ ἄνδρες Ἀθηναῖοι, κακῶν ἀλλοτρίων κλέπτης ὑπέμεινεν ὀνομασθῆναι, τί ἂν ἡγεῖσθε ποιῆσαι τοῦτον ὑπὲρ αὑτοῦ;", "st": "45.59"}, {"sp": "N", "t": "λέγε τὴν μαρτυρίαν [εἶτα τὴν πρόκλησιν ταύτην].", "st": "45.60"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "45.60"}, {"sp": "N", "t": "μαρτυροῦσι φίλοι εἶναι καὶ ἐπιτήδειοι Φορμίωνι, καὶ παρεῖναι πρὸς τῷ διαιτητῇ Τεισίᾳ, ὅτε ἦν ἀπόφασις τῆς διαίτης Ἀπολλοδώρῳ πρὸς Φορμίωνα, καὶ εἰδέναι τὴν μαρτυρίαν ὑφῃρημένον Στέφανον, ἣν αἰτιᾶται αὐτὸν Ἀπολλόδωρος ὑφελέσθαι.", "st": "45.60"}, {"sp": "N", "t": "ἢ μαρτυρεῖτε, ἢ ἐξομόσασθε.", "st": "45.60"}, {"sp": "N", "t": "ΕΞΩΜΟΣΙΑ.", "st": "45.60"}, {"sp": "N", "t": "οὐκ ἄδηλον ἦν, ὦ ἄνδρες δικασταί, ὅτι τοῦτ’ ἔμελλον ποιήσειν, προθύμως ἐξομεῖσθαι. ἵνα τοίνυν παραχρῆμ’ ἐξελεγχθῶσιν ἐπιωρκηκότες, λαβέ μοι ταύτην τὴν μαρτυρίαν καὶ τὴν πρόκλησιν. ἀναγίγνωσκε.", "st": "45.61"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ. ΠΡΟΚΛΗΣΙΣ.", "st": "45.61"}, {"sp": "N", "t": "μαρτυροῦσι παρεῖναι ὅτε Ἀπολλόδωρος προὐκαλεῖτο Στέφανον παραδοῦναι τὸν παῖδα τὸν ἀκόλουθον εἰς βάσανον περὶ τῆς ὑφαιρέσεως τοῦ γραμματείου, καὶ γράμματα ἦν ἕτοιμος γράφειν Ἀπολλόδωρος καθ’ ὅ τι ἔσται ἡ βάσανος. ταῦτα δὲ προκαλουμένου Ἀπολλοδώρου οὐκ ἐθελῆσαι παραδοῦναι Στέφανον, ἀλλ’ ἀποκρίνασθαι Ἀπολλοδώρῳ δικάζεσθαι, εἰ βούλοιτο, εἴ τί φησιν ἀδικεῖσθαι ὑφ’ ἑαυτοῦ.", "st": "45.61"}, {"sp": "N", "t": "τίς ἂν οὖν ὑπὲρ τοιαύτης αἰτίας, ὦ ἄνδρες δικασταί, εἴπερ ἐπίστευεν αὑτῷ, οὐκ ἐδέξατο τὴν βάσανον; οὐκοῦν τῷ φεύγειν τὴν βάσανον ὑφῃρημένος ἐξελέγχεται. ἆρ’ οὖν ἂν ὑμῖν αἰσχυνθῆναι δοκεῖ τὴν τοῦ τὰ ψευδῆ μαρτυρεῖν δόξαν ὁ τὴν τοῦ κλέπτης φανῆναι μὴ φυγών; ἢ δεηθέντος ὀκνῆσαι τὰ ψευδῆ μαρτυρεῖν, ὃς ἃ μηδεὶς ἐκέλευεν ἐθελοντὴς πονηρὸς ἦν;", "st": "45.62"}, {"sp": "N", "t": "δικαίως τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, τούτων ἁπάντων δοὺς ἂν δίκην, πολὺ μᾶλλον ἂν εἰκότως διὰ τἄλλα κολασθείη παρ’ ὑμῖν. σκοπεῖτε δέ, τὸν βίον ὃν βεβίωκεν ἐξετάζοντες. οὗτος γάρ, ἡνίκα μὲν συνέβαινεν εὐτυχεῖν Ἀριστολόχῳ τῷ τραπεζίτῃ, ἴσα βαίνων ἐβάδιζεν ὑποπεπτωκὼς ἐκείνῳ, καὶ ταῦτ’ ἴσασι πολλοὶ τῶν ἐνθάδ’ ὄντων ὑμῶν.", "st": "45.63"}, {"sp": "N", "t": "ἐπειδὴ δ’ ἀπώλετ’ ἐκεῖνος καὶ τῶν ὄντων ἐξέστη, οὐχ ἥκισθ’ ὑπὸ τούτου καὶ τῶν τοιούτων διαφορηθείς, τῷ μὲν υἱεῖ τῷ τούτου πολλῶν πραγμάτων ὄντων οὐ παρέστη πώποτε, οὐδ’ ἐβοήθησεν, ἀλλ’ Ἀπόληξις καὶ Σόλων καὶ πάντες ἄνθρωποι μᾶλλον βοηθοῦσι· Φορμίωνα δὲ πάλιν ἑόρακεν καὶ τούτῳ γέγονεν οἰκεῖος, ἐξ Ἀθηναίων ἁπάντων τοῦτον ἐκλεξάμενος, καὶ ὑπὲρ τούτου πρεσβευτὴς μὲν ᾤχετ’ εἰς Βυζάντιον πλέων, ἡνίκ’ ἐκεῖνοι τὰ πλοῖα τὰ τούτου κατέσχον, τὴν δὲ δίκην ἔλεγεν τὴν πρὸς τοὺς Καλχηδονίους, τὰ ψευδῆ δ’ ἐμοῦ φανερῶς οὕτως καταμεμαρτύρηκεν.", "st": "45.64"}, {"sp": "N", "t": "εἶθ’ ὃς εὐτυχούντων ἐστὶ κόλαξ, κἂν ἀτυχῶσι, τῶν αὐτῶν τούτων προδότης, καὶ τῶν μὲν ἄλλων πολιτῶν πολλῶν καὶ καλῶν κἀγαθῶν ὄντων μηδενὶ μηδ’ ἐξ ἴσου χρῆται, τοῖς δὲ τοιούτοις ἐθελοντὴς ὑποπίπτει, καὶ μήτ’ εἴ τινα τῶν οἰκείων ἀδικήσει μήτ’ εἰ παρὰ τοῖς ἄλλοις φαύλην δόξαν ἕξει ταῦτα ποιῶν μήτ’ ἄλλο μηδὲν σκοπεῖ, πλὴν ὅπως τι πλέον ἕξει, τοῦτον οὐ μισεῖν ὡς κοινὸν ἐχθρὸν τῆς φύσεως ὅλης τῆς ἀνθρωπίνης προσήκει; ἔγωγ’ ἂν φαίην.", "st": "45.65"}, {"sp": "N", "t": "ταῦτα μέντοι τὰ τοσαύτην ἔχοντ’ αἰσχύνην, ὦ ἄνδρες Ἀθηναῖοι, ἐπὶ τῷ τὴν πόλιν φεύγειν καὶ τὰ ὄντ’ ἀποκρύπτεσθαι προῄρηται πράττειν, ἵν’ ἐργασίας ἀφανεῖς διὰ τῆς τραπέζης ποιῆται, καὶ μήτε χορηγῇ μήτε τριηραρχῇ μήτ’ ἄλλο μηδὲν ὧν προσήκει ποιῇ. καὶ κατείργασται τοῦτο. τεκμήριον δέ· ἔχων γὰρ οὐσίαν τοσαύτην ὥσθ’ ἑκατὸν μνᾶς ἐπιδοῦναι τῇ θυγατρί, οὐδ’ ἡντινοῦν ἑώραται λῃτουργίαν ὑφ’ ὑμῶν λῃτουργῶν, οὐδὲ τὴν ἐλαχίστην. καίτοι πόσῳ κάλλιον φιλοτιμούμενον ἐξετάζεσθαι καὶ προθυμούμενον εἰς ἃ δεῖ τῇ πόλει, ἢ κολακεύοντα καὶ τὰ ψευδῆ μαρτυροῦντα; ἀλλ’ ἐπὶ τῷ κερδαίνειν πᾶν ἂν οὗτος ποιήσειε.", "st": "45.66"}, {"sp": "N", "t": "καὶ μήν, ὦ ἄνδρες Ἀθηναῖοι, μᾶλλον ἄξιον ὀργίλως ἔχειν τοῖς μετ’ εὐπορίας πονηροῖς ἢ τοῖς μετ’ ἐνδείας. τοῖς μὲν γὰρ ἡ τῆς χρείας ἀνάγκη φέρει τινὰ συγγνώμην παρὰ τοῖς ἀνθρωπίνως λογιζομένοις· οἱ δ’ ἐκ περιουσίας, ὥσπερ οὗτος, πονηροὶ οὐδεμίαν πρόφασιν δικαίαν ἔχοιεν ἂν εἰπεῖν, ἀλλ’ αἰσχροκερδίᾳ καὶ πλεονεξίᾳ καὶ ὕβρει καὶ τῷ τὰς αὑτῶν συστάσεις κυριωτέρας τῶν νόμων ἀξιοῦν εἶναι ταῦτα φανήσονται πράττοντες. ὑμῖν δ’ οὐδὲν τούτων συμφέρει, ἀλλὰ τὸν ἀσθενῆ παρὰ τοῦ πλουσίου δίκην, ἂν ἀδικῆται, δύνασθαι λαβεῖν. ἔσται δὲ τοῦτο, ἐὰν κολάζητε τοὺς φανερῶς οὕτως ἐξ εὐπορίας πονηρούς.", "st": "45.67"}, {"sp": "N", "t": "οὐ τοίνυν οὐδ’ ἃ πέπλασται οὗτος καὶ βαδίζει παρὰ τοὺς τοίχους ἐσκυθρωπακώς, σωφροσύνης ἄν τις ἡγήσαιτ’ εἰκότως εἶναι σημεῖα, ἀλλὰ μισανθρωπίας. ἐγὼ γάρ, ὅστις αὐτῷ μηδενὸς συμβεβηκότος δεινοῦ, μηδὲ τῶν ἀναγκαίων σπανίζων, ἐν ταύτῃ τῇ σχέσει διάγει τὸν βίον, τοῦτον ἡγοῦμαι συνεορακέναι καὶ λελογίσθαι παρ’ αὑτῷ, ὅτι τοῖς μὲν ἁπλῶς, ὡς πεφύκασι, βαδίζουσι καὶ φαιδροῖς καὶ προσέλθοι τις ἂν καὶ δεηθείη καὶ ἐπαγγείλειεν οὐδὲν ὀκνῶν, τοῖς δὲ πεπλασμένοις καὶ σκυθρωποῖς ὀκνήσειέ τις ἂν προσελθεῖν πρῶτον.", "st": "45.68"}, {"sp": "N", "t": "οὐδὲν οὖν ἄλλ’ ἢ πρόβλημα τοῦ τρόπου τὸ σχῆμα τοῦτ’ ἔστι, καὶ τὸ τῆς διανοίας ἄγριον καὶ πικρὸν ἐνταῦθα δηλοῖ. σημεῖον δέ· τοσούτων γὰρ ὄντων τὸ πλῆθος Ἀθηναίων, πράττων πολὺ βέλτιον ἢ σὲ προσῆκον ἦν, τῷ πώποτ’ εἰσήνεγκας, ἢ τίνι συμβέβλησαί πω, ἢ τίν’ εὖ πεποίηκας;", "st": "45.69"}, {"sp": "N", "t": "οὐδέν’ ἂν εἰπεῖν ἔχοις· ἀλλὰ τοκίζων καὶ τὰς τῶν ἄλλων συμφορὰς καὶ χρείας εὐτυχήματα σαυτοῦ νομίζων, ἐξέβαλες μὲν τὸν ἀφῄρησαι δὲ τὴν σαυτοῦ πενθερὰν ταῦτ’ ἀφ’ ὧν ἔζη, ἀοίκητον δὲ τὸν Ἀρχεδήμου παῖδα τὸ σαυτοῦ μέρος πεποίηκας. οὐδεὶς δὲ πώποθ’ οὕτω πικρῶς οὐδ’ ὑπερήμερον εἰσέπραξεν ὡς σὺ τοὺς ὀφείλοντας τοὺς τόκους. εἶθ’ ὃν ὁρᾶτ’ ἐπὶ πάντων οὕτως ἄγριον καὶ μιαρόν, τοῦτον ὑμεῖς ἠδικηκότ’ ἐπ’ αὐτοφώρῳ λαβόντες οὐ τιμωρήσεσθε; δείν’ ἄρ’, ὦ ἄνδρες δικασταί, ποιήσετε καὶ οὐχὶ δίκαια.", "st": "45.70"}, {"sp": "N", "t": "ἄξιον τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, καὶ Φορμίωνι τῷ παρασχομένῳ τουτονὶ νεμεσῆσαι τοῖς πεπραγμένοις, τὴν ἀναίδειαν τοῦ τρόπου καὶ τὴν ἀχαριστίαν ἰδόντας. οἶμαι γὰρ ἅπαντας ὑμᾶς εἰδέναι, ὅτι τοῦτον, ἡνίκ’ ὤνιος ἦν, εἰ συνέβη μάγειρον ἤ τινος ἄλλης τέχνης δημιουργὸν πρίασθαι, τὴν τοῦ δεσπότου τέχνην ἂν μαθὼν πόρρω τῶν νῦν παρόντων ἦν ἀγαθῶν.", "st": "45.71"}, {"sp": "N", "t": "ἐπειδὴ δ’ ὁ πατὴρ ὁ ἡμέτερος τραπεζίτης ὢν ἐκτήσατ’ αὐτὸν καὶ γράμματ’ ἐπαίδευσεν καὶ τὴν τέχνην ἐδίδαξεν καὶ χρημάτων ἐποίησε κύριον πολλῶν, εὐδαίμων γέγονεν, τὴν τύχην, ᾗ πρὸς ἡμᾶς ἀφίκετο, ἀρχὴν λαβὼν πάσης τῆς νῦν παρούσης εὐδαιμονίας.", "st": "45.72"}, {"sp": "N", "t": "οὐκοῦν δεινόν, ὦ γῆ καὶ θεοί, καὶ πέρᾳ δεινοῦ, τοὺς Ἕλληνα μὲν ἀντὶ βαρβάρου ποιήσαντας, γνώριμον δ’ ἀντ’ ἀνδραπόδου, τοσούτων δ’ ἀγαθῶν ἡγεμόνας, τούτους περιορᾶν ἐν ταῖς ἐσχάταις ἀπορίαις ὄντας ἔχοντα καὶ πλουτοῦντα, καὶ εἰς τοῦθ’ ἥκειν ἀναιδείας ὥστε, ἧς παρ’ ἡμῶν τύχης μετέσχε, ταύτης ἡμῖν μὴ τολμᾶν μεταδοῦναι.", "st": "45.73"}, {"sp": "N", "t": "ἀλλ’ αὐτὸς μὲν οὐκ ὤκνησε τὴν δέσποιναν γῆμαι καὶ ἣ τὰ καταχύσματ’ αὐτοῦ κατέχεε τόθ’ ἡνίκ’ ἐωνήθη, ταύτῃ συνοικεῖν, οὐδὲ προῖκα πέντε τάλανθ’ αὑτῷ γράψαι, χωρὶς ὧν οὔσης τῆς μητρὸς κυρίας οὗτος ἐγκρατὴς γέγονεν πολλῶν χρημάτων (τί γὰρ αὐτὸν οἴεσθ’ εἰς τὰς διαθήκας ἐγγράψαι “καὶ τἄλλα, ὅσα ἐστίν, Ἀρχίππῃ δίδωμι;”) τὰς δ’ ἡμετέρας θυγατέρας μελλούσας δι’ ἔνδειαν ἀνεκδότους ἔνδον γηράσκειν περιορᾷ.", "st": "45.74"}, {"sp": "N", "t": "καὶ εἰ μὲν πένης οὗτος ἦν, ἡμεῖς δ’ εὐποροῦντες ἐτυγχάνομεν, καὶ συνέβη τι παθεῖν, οἷα πολλά, ἐμοί, οἱ παῖδες ἂν οἱ τούτου τῶν ἐμῶν θυγατέρων ἐπεδικάζοντο, οἱ τοῦ δούλου τῶν τοῦ δεσπότου· θεῖοι γάρ εἰσιν αὐταῖς διὰ τὸ τὴν μητέρα τὴν ἐμὴν τοῦτον λαβεῖν· ἐπειδὴ δ’ ἀπόρως ἡμεῖς ἔχομεν, τηνικαῦτ’ οὐ συνεκδώσει ταύτας, ἀλλὰ λέγει καὶ λογίζεται τὸ πλῆθος ὧν ἐγὼ χρημάτων ἔχω.", "st": "45.75"}, {"sp": "N", "t": "καὶ γὰρ τοῦτ’ ἀτοπώτατον πάντων. ὧν μὲν ἀπεστέρηκεν ἡμᾶς χρημάτων, οὐδέπω καὶ τήμερον ἠθέλησεν ὑποσχεῖν τὸν λόγον, ἀλλὰ μὴ εἰσαγωγίμους εἶναι τὰς δίκας παραγράφεται· ἃ δὲ τῶν πατρῴων ἐνειμάμην ἐγώ, ταῦτα λογίζεται. καὶ τοὺς μὲν ἄλλους ἄν τις ἴδοι τοὺς οἰκέτας ὑπὸ τῶν δεσποτῶν ἐξεταζομένους· οὗτος δ’ αὖ τοὐναντίον τὸν δεσπότην ὁ δοῦλος ἐξετάζει, ὡς δῆτα πονηρὸν καὶ ἄσωτον ἐκ τούτων ἐπιδείξων.", "st": "45.76"}, {"sp": "N", "t": "ἐγὼ δ’, ὦ ἄνδρες Ἀθηναῖοι, τῆς μὲν ὄψεως τῇ φύσει καὶ τῷ ταχέως βαδίζειν καὶ λαλεῖν μέγα, οὐ τῶν εὐτυχῶς πεφυκότων ἐμαυτὸν κρίνω· ἐφ’ οἷς γὰρ οὐδὲν ὠφελούμενος λυπῶ τινας, ἔλαττον ἔχω πολλαχοῦ· τῷ μέντοι μέτριος κατὰ πάσας τὰς εἰς ἐμαυτὸν δαπάνας εἶναι πολὺ τούτου καὶ τοιούτων ἑτέρων εὐτακτότερον ζῶν ἂν φανείην.", "st": "45.77"}, {"sp": "N", "t": "τὰ δ’ εἰς τὴν πόλιν καὶ ὅσ’ εἰς ὑμᾶς, ὡς δύναμαι λαμπρότατα, ὡς ὑμεῖς σύνιστε, ποιῶ· οὐ γὰρ ἀγνοῶ τοῦθ’ ὅτι τοῖς μὲν γένει πολίταις ὑμῖν ἱκανόν ἐστι λῃτουργεῖν ὡς οἱ νόμοι προστάττουσι, τοὺς δὲ ποιητοὺς ἡμᾶς ὡς ἀποδιδόντας χάριν, οὕτω προσήκει φαίνεσθαι λῃτουργοῦντας. μὴ οὖν μοι ταῦτ’ ὀνείδιζε, ἐφ’ οἷς ἐπαίνου τύχοιμ’ ἂν δικαίως.", "st": "45.78"}, {"sp": "N", "t": "ἀλλὰ τίν’, ὦ Φορμίων, τῶν πολιτῶν ἑταιρεῖν, ὥσπερ σύ, μεμίσθωμαι; δεῖξον. τίνα τῆς πόλεως, ἧς αὐτὸς ἠξιώθην, καὶ τῆς ἐν αὐτῇ παρρησίας ἀπεστέρηκα, ὥσπερ σὺ τοῦτον ὃν κατῄσχυνας; τίνος γυναῖκα διέφθαρκα, ὥσπερ σὺ πρὸς πολλαῖς ἄλλαις ταύτην, ᾗ τὸ μνῆμ’ ᾠκοδόμησεν ὁ θεοῖς ἐχθρὸς οὗτος πλησίον τοῦ τῆς δεσποίνης, ἀνηλωκὼς πλέον ἢ τάλαντα δύο; καὶ οὐκ ᾐσθάνετο, ὅτι οὐχὶ τοῦ τάφου μνημεῖον ἔσται τὸ οἰκοδόμημα τοιοῦτον ὄν, ἀλλὰ τῆς ἀδικίας ἧς τὸν ἄνδρ’ ἠδίκηκεν ἐκείνη διὰ τοῦτον.", "st": "45.79"}, {"sp": "N", "t": "εἶτα τοιαῦτα ποιῶν καὶ τηλικαύτας μαρτυρίας ἐξενηνοχὼς τῆς ὕβρεως τῆς σαυτοῦ σύ, τὸν ἄλλου του βίον ἐξετάζειν τολμᾷς; μεθ’ ἡμέραν εἶ σὺ σώφρων, τὴν δὲ νύκτ’ ἐφ’ οἷς θάνατος ἡ ζημία, ταῦτα ποιεῖς. πονηρός, ὦ ἄνδρες Ἀθηναῖοι, πονηρὸς οὗτος ἄνωθεν ἐκ τοῦ Ἀνακείου καὶ ἄδικος. σημεῖον δέ· εἰ γὰρ ἦν δίκαιος, πένης ἂν ἦν τὰ τοῦ δεσπότου διοικήσας. νῦν δὲ τοσούτων χρημάτων τὸ πλῆθος κύριος καταστὰς ὥστε τοσαῦτα λαθεῖν ἀπ’ αὐτῶν κλέψας ὅσα νῦν κέκτηται, οὐκ ὀφείλειν ταῦτα, ἀλλὰ πατρῷ’ ἔχειν ἡγεῖται.", "st": "45.80"}, {"sp": "N", "t": "καίτοι πρὸς θεῶν, εἰ κλέπτην σ’ ἀπῆγον ὡς ἐπ’ αὐτοφώρῳ εἰληφώς, τὴν οὐσίαν ἣν ἔχεις, εἴ πως οἷόν τ’ ἦν, ἐπιθείς σοι, εἶτά σ’ ἠξίουν, εἰ μὴ φὴς ὑφῃρημένος ταῦτ’ ἔχειν, ἀνάγειν ὅθεν εἴληφας, εἰς τίν’ ἂν αὔτ’ ἀνήγαγες; οὔτε γάρ σοι πατὴρ παρέδωκεν, οὔθ’ ηὗρες, οὔτε λαβών ποθεν ἄλλοθεν ἦλθες ὡς ἡμᾶς· βάρβαρος γὰρ ἐωνήθης. εἶθ’ ᾧ δημοσίᾳ προσῆκεν ἐπὶ τοῖς εἰργασμένοις τεθνάναι, σύ, τὸ σῶμα σεσῳκὼς καὶ πόλιν ἐκ τῶν ἡμετέρων σαυτῷ κτησάμενος καὶ παῖδας ἀδελφοὺς τοῖς σεαυτοῦ δεσπόταις ἀξιωθεὶς ποιήσασθαι, παρεγράψω μὴ εἰσαγώγιμον εἶναι τὴν δίκην τῶν ἐγκαλουμένων χρημάτων ὑφ’ ἡμῶν;", "st": "45.81"}, {"sp": "N", "t": "εἶτα κακῶς ἡμᾶς ἔλεγες καὶ τὸν ἡμέτερον πατέρ’ ἐξήταζες ὅστις ἦν; ἐφ’ οἷς τίς οὐκ ἄν, ὦ ἄνδρες Ἀθηναῖοι, χαλεπῶς ἤνεγκεν; ἐγὼ γάρ, εἰ πάντων τῶν ἄλλων ὑμῶν ἔλαττον προσήκει μοι φρονεῖν, τούτου γε μεῖζον οἶμαι, καὶ τούτῳ γ’ εἰ μηδενὸς τῶν ἄλλων ἔλαττον, ἐμοῦ γ’ ἔλαττον· ὄντων γὰρ ἡμῶν τοιούτων ὁποίους τινὰς ἂν [καὶ] σὺ κατασκευάσῃς τῷ λόγῳ, σὺ δοῦλος ἦσθα.", "st": "45.82"}, {"sp": "N", "t": "τάχα τοίνυν ἂν ἴσως καὶ τοῦτό τις αὐτῶν εἴποι, ὡς ἀδελφὸς ὢν ἐμὸς Πασικλῆς οὐδὲν ἐγκαλεῖ τῶν αὐτῶν τούτῳ πραγμάτων. ἐγὼ δ’, ὦ ἄνδρες Ἀθηναῖοι, καὶ περὶ Πασικλέους, παραιτησάμενος καὶ δεηθεὶς ὑμῶν συγγνώμην ἔχειν, εἰ προεληλυθὼς εἰς τοῦθ’ ὥσθ’ ὑπὸ τῶν ἐμαυτοῦ δούλων ὑβρισθεὶς οὐ δύναμαι κατασχεῖν, ἃ τέως οὐδὲ τῶν ἄλλων λεγόντων ἀκούειν ἐδόκουν, ἐρῶ καὶ οὐ σιωπήσομαι.", "st": "45.83"}, {"sp": "N", "t": "ἐγὼ γὰρ ὁμομήτριον μὲν ἀδελφὸν ἐμαυτοῦ Πασικλέα νομίζω, ὁμοπάτριον δ’ οὐκ οἶδα, δέδοικα μέντοι μὴ τῶν Φορμίωνος ἁμαρτημάτων εἰς ἡμᾶς ἀρχὴ Πασικλῆς ᾖ. ὅταν γὰρ τῷ δούλῳ συνδικῇ τὸν ἀδελφὸν ἀτιμῶν, καὶ παραπεπτωκὼς θαυμάζῃ τούτους ὑφ’ ὧν αὐτῷ θαυμάζεσθαι προσῆκεν, τίν’ ἔχει δικαίαν ταῦθ’ ὑποψίαν; ἄνελ’ οὖν ἐκ μέσου μοι Πασικλέα, καὶ σὸς μὲν υἱὸς ἀντὶ δεσπότου καλείσθω, ἐμὸς δ’ ἀντίδικος (βούλεται γὰρ) ἀντ’ ἀδελφοῦ.", "st": "45.84"}, {"sp": "N", "t": "ἐγὼ δὲ τούτῳ μὲν χαίρειν λέγω, οὓς δ’ ὁ πατήρ μοι παρέδωκε βοηθοὺς καὶ φίλους, εἰς τούτους ἥκω, εἰς ὑμᾶς, ὦ ἄνδρες δικασταί. καὶ δέομαι καὶ ἀντιβολῶ καὶ ἱκετεύω, μὴ ὑπερίδητέ με καὶ τὰς θυγατέρας δι’ ἔνδειαν τοῖς ἐμαυτοῦ δούλοις καὶ τοῖς τούτου κόλαξιν ἐπίχαρτον γενόμενον. οὑμὸς ὑμῖν πατὴρ χιλίας ἔδωκεν ἀσπίδας, καὶ πολλὰ χρήσιμον αὑτὸν παρέσχε, καὶ πέντε τριήρεις ἐθελοντὴς ἐπιδοὺς καὶ παρ’ αὑτοῦ πληρώσας ἐτριηράρχησε τριηραρχίας. καὶ ταῦτα, οὐκ ὀφείλειν ὑμᾶς νομίζων χάριν ἡμῖν, ὑπομιμνῄσκω (ἡμεῖς γὰρ ὀφείλομεν ὑμῖν), ἀλλ’ ἵνα μὴ λάθω τι παθὼν τούτων ἀνάξιον· οὐδὲ γὰρ ὑμῖν ἂν γένοιτο καλόν.", "st": "45.85"}, {"sp": "N", "t": "πολλὰ δ’ ἔχων εἰπεῖν περὶ ὧν ὕβρισμαι, οὐχ ἱκανὸν τὸ ὕδωρ ὁρῶ μοι. ὡς οὖν μάλιστ’ ἂν ἅπαντας ὑμᾶς ἡγοῦμαι γνῶναι τὴν ὑπερβολὴν ὧν ἠδικήμεθ’ ἡμεῖς, φράσω· εἰ σκέψαιτο πρὸς ἑαυτὸν ἕκαστος ὑμῶν τίν’ οἴκοι κατέλιπεν οἰκέτην, εἶθ’ ὑπὸ τούτου πεπονθόθ’ ἑαυτὸν θείη ταὔθ’ ἅπερ ἡμεῖς ὑπὸ τούτου. μὴ γὰρ εἰ Σύρος ἢ Μάνης ἢ τίς ἕκαστος ἐκείνων, οὗτος δὲ Φορμίων· ἀλλὰ τὸ πρᾶγμα ταὐτό· δοῦλοι μὲν ἐκεῖνοι, δοῦλος δ’ οὗτος ἦν, δεσπόται δ’ ὑμεῖς, δεσπότης δ’ ἦν ἐγώ.", "st": "45.86"}, {"sp": "N", "t": "ἣν τοίνυν ὑμῶν ἂν ἕκαστος δίκην ἀξιώσειε λαβεῖν, ταύτην νομίζετε κἀμοὶ προσήκειν νῦν· καὶ τὸν ἀφῃρημένον τῷ μαρτυρῆσαι τὰ ψευδῆ καὶ ὑπὲρ τῶν νόμων καὶ ὑπὲρ τῶν ὅρκων οὓς ὀμωμοκότες δικάζετε, τιμωρήσασθε καὶ παράδειγμα ποιήσατε τοῖς ἄλλοις, μνημονεύοντες πάνθ’ ὅσ’ ἀκηκόαθ’ ἡμῶν, καὶ φυλάττοντες, ἐὰν παράγειν ἐπιχειρῶσιν ὑμᾶς, πρὸς ἕκαστον ἀπαντῶντες· ἐὰν μὴ φῶσιν ἅπαντα μεμαρτυρηκέναι, “τί οὖν ἐν τῷ γραμματείῳ γέγραπται; τί οὖν οὐ τότ’ ἀπηλείφου;”", "st": "45.87"}, {"sp": "N", "t": "“τίς ἡ παρὰ τοῖς ἄρχουσιν ἀντιγραφή;” ἐὰν μεμαρτυρηκέναι τὸν μὲν ἐπιτροπευθῆναι κατὰ διαθήκας, τὸν δ’ ἐπιτροπεῦσαι, τὸν δ’ ἔχειν, “ποίας; ἐν αἷς τί γέγραπται;” ταῦτ’ ἐρωτᾶτε· ἃ γὰρ οὗτοι μεμαρτυρήκασιν, οὐδεὶς ἐκείνων προσμεμαρτύρηκεν. ἐὰν δ’ ὀδύρωνται, τὸν πεπονθότ’ ἐλεινότερον τῶν δωσόντων δίκην ἡγεῖσθε. ταῦτα γὰρ ἂν ποιῆτε, ἐμοί τε βοηθήσετε, καὶ τούτους τῆς ἄγαν κολακείας ἐπισχήσετε, καὶ αὐτοὶ τὰ εὔορκ’ ἔσεσθ’ ἐψηφισμένοι.", "st": "45.88"}, {"sp": "HDR", "t": "Κατὰ Στεφάνου ψευδομαρτυριῶν Βʹ", "st": "46"}, {"sp": "N", "t": "ὅτι μὲν οὐκ ἀπορήσειν ἔμελλε Στέφανος οὑτοσὶ ὅ τι ἀπολογήσεται περὶ τῆς μαρτυρίας, παράγων τῷ λόγῳ ὡς οὐ πάντα μεμαρτύρηκε τὰ ἐν τῷ γραμματείῳ γεγραμμένα, καὶ ἐξαπατῶν ὑμᾶς, καὶ αὐτὸς σχεδόν τι ὑπενόουν, ὦ ἄνδρες δικασταί. πανοῦργός τε γάρ ἐστιν, καὶ οἱ γράφοντες καὶ οἱ συμβουλεύοντες ὑπὲρ Φορμίωνος πολλοί· ἅμα τ’ εἰκός ἐστι τοὺς ἐγχειροῦντας τὰ ψευδῆ μαρτυρεῖν καὶ τὴν ἀπολογίαν εὐθέως ὑπὲρ αὐτῶν μελετᾶν.", "st": "46.1"}, {"sp": "N", "t": "ὅτι δ’ ἐν τοσούτῳ λόγῳ οὐδαμοῦ μάρτυρας παρέσχετο ὑμῖν, ὡς ἢ διατιθεμένῳ τῷ πατρὶ τῷ ἐμῷ παρεγένετό που αὐτὸς ταύτην τὴν διαθήκην, ὥστ’ εἰδέναι ταῦτα ὅτι ἀντίγραφά ἐστιν ὧν ὁ πατήρ μου διέθετο, ἢ ἀνοιχθὲν εἶδε τὸ γραμματεῖον ὅ φασι διαθέμενον ἐκεῖνον καταλιπεῖν, ταῦτα συμμέμνησθέ μοι.", "st": "46.2"}, {"sp": "N", "t": "ἀλλὰ μὴν ὁπότε μεμαρτύρηκεν ἀντίγραφα εἶναι τῶν διαθηκῶν τῶν Πασίωνος τὰ ἐν τῷ γραμματείῳ γεγραμμένα, τὰς δὲ διαθήκας μὴ ἔχει ἐπιδεῖξαι μήθ’ ὡς ὁ πατὴρ διέθετο ἡμῶν μήθ’ ὡς αὐτὸς εἶδεν παραγενόμενος αὐτὰς διατιθεμένου τοῦ πατρός, πῶς οὐ περιφανῶς οὗτος ἐξελέγχεται τὰ ψευδῆ μεμαρτυρηκώς;", "st": "46.3"}, {"sp": "N", "t": "εἰ τοίνυν πρόκλησίν φησιν εἶναι καὶ μὴ μαρτυρίαν, οὐκ ἀληθῆ λέγει. ἅπαντα γὰρ ὅσα παρέχονται εἰς τὸ δικαστήριον προκαλούμενοι ἀλλήλους οἱ ἀντίδικοι, διὰ μαρτυρίας παρέχονται. οὐ γὰρ ἂν εἰδείηθ’ ὑμεῖς εἴτ’ ἐστὶν ἀληθῆ εἴτε ψευδῆ ἅ φασιν ἑκάτεροι, εἰ μή τις καὶ τοὺς μάρτυρας παρέχοιτο. ὅταν δὲ παράσχηται, τούτοις πιστεύοντες ὑποδίκοις οὖσιν ψηφίζεσθε ἐκ τῶν λεγομένων καὶ μαρτυρουμένων ἃ ἂν ὑμῖν δοκῇ δίκαια εἶναι.", "st": "46.4"}, {"sp": "N", "t": "βούλομαι τοίνυν καὶ τὴν μαρτυρίαν ἐξελέγξαι, ὅτι οὐ πρόκλησίς ἐστιν, καὶ ὡς ἔδει μαρτυρεῖν αὐτούς, εἴπερ ἐγίγνετο ἡ πρόκλησις, ὡς οὐκ ἐγίγνετο. “μαρτυροῦσι παρεῖναι πρὸς τῷ διαιτητῇ Τεισίᾳ, ὅτε προὐκαλεῖτο Φορμίων Ἀπολλόδωρον ἀνοίγειν τὸ γραμματεῖον, ὃ παρεῖχεν Ἀμφίας ὁ Κηφισοφῶντος κηδεστής, Ἀπολλόδωρον δ’ οὐκ ἐθέλειν ἀνοίγειν.” οὕτω μὲν ἂν μαρτυροῦντες ἐδόκουν ἀληθῆ μαρτυρεῖν· ἀντίγραφα δὲ τῶν διαθηκῶν τῶν Πασίωνος μαρτυρεῖν εἶναι τὰ ἐν τῷ γραμματείῳ ὃ παρείχετο Φορμίων, μήτε παραγενομένους ἐκείνῳ διατιθεμένῳ μήτ’ εἰδότας εἰ διέθετο, πῶς οὐ περιφανῶς ἀναισχυντία δοκεῖ ὑμῖν εἶναι;", "st": "46.5"}, {"sp": "N", "t": "ἀλλὰ μὴν εἰ φησὶ Φορμίωνος λέγοντος πιστεύειν ταῦτ’ ἀληθῆ εἶναι, τοῦ αὐτοῦ ἀνδρός ἐστιν πιστεύειν τε λέγοντι τούτῳ ταῦτα καὶ κελεύοντι μαρτυρεῖν. οἱ δέ γε νόμοι οὐ ταῦτα λέγουσιν, ἀλλ’ ἃ ἂν εἰδῇ τις καὶ οἷς ἂν παραγένηται πραττομένοις, ταῦτα μαρτυρεῖν κελεύουσιν ἐν γραμματείῳ γεγραμμένα, ἵνα μήτ’ ἀφελεῖν ἐξῇ μηδὲν μήτε προσθεῖναι τοῖς γεγραμμένοις.", "st": "46.6"}, {"sp": "N", "t": "ἀκοὴν δ’ οὐκ ἐῶσι ζῶντος μαρτυρεῖν, ἀλλὰ τεθνεῶτος, τῶν δὲ ἀδυνάτων καὶ ὑπερορίων ἐκμαρτυρίαν γεγραμμένην ἐν τῷ γραμματείῳ· καὶ ἀπὸ τῆς αὐτῆς ἐπισκήψεως τήν τε μαρτυρίαν καὶ ἐκμαρτυρίαν ἀγωνίζεσθαι ἅμα, ἵν’ ἐὰν μὲν ἀναδέχηται ὁ ἐκμαρτυρήσας, ἐκεῖνος ὑπόδικος ᾖ τῶν ψευδομαρτυρίων, ἐὰν δὲ μὴ ἀναδέχηται, οἱ μαρτυρήσαντες τὴν ἐκμαρτυρίαν.", "st": "46.7"}, {"sp": "N", "t": "στέφανος τοίνυν οὑτοσί, οὔτ’ εἰδὼς διαθήκας καταλιπόντα τὸν πατέρα ἡμῶν, οὔτε παραγενόμενος πώποτε διατιθεμένῳ τῷ πατρὶ ἡμῶν, ἀκούσας δὲ Φορμίωνος, μεμαρτύρηκεν ἀκοὴν τὰ ψευδῆ τε καὶ παρὰ τὸν νόμον. καὶ ταῦθ’ ὅτι ἀληθῆ λέγω, αὐτὸν ὑμῖν τὸν νόμον ἀναγνώσεται.", "st": "46.8"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "46.8"}, {"sp": "N", "t": "ἀκοὴν εἶναι μαρτυρεῖν τεθνεῶτος, ἐκμαρτυρίαν δὲ ὑπερορίου καὶ ἀδυνάτου.", "st": "46.8"}, {"sp": "N", "t": "ὡς τοίνυν καὶ παρ’ ἕτερον νόμον μεμαρτύρηκεν, ἐπιδεῖξαι ὑμῖν βούλομαι, ἵνα εἰδῆτε ὅτι μεγάλων ἀδικημάτων οὐκ ἔχων καταφυγὴν ὁ Φορμίων, πρόφασιν λαβὼν λόγῳ τὴν πρόκλησιν, ἔργῳ αὐτὸς αὑτῷ μεμαρτύρηκε προστησάμενος τούτους, δι’ ὧν οἱ μὲν δικασταὶ ἐξηπατήθησαν ὡς ἀληθῆ τούτων μαρτυρούντων, ἐγὼ δὲ ἀπεστερήθην ὧν ὁ πατήρ μοι κατέλιπεν χρημάτων καὶ τοῦ δίκην λαβεῖν περὶ ὧν ἀδικοῦμαι. μαρτυρεῖν γὰρ οἱ νόμοι οὐκ ἐῶσιν αὐτὸν αὑτῷ οὔτ’ ἐπὶ ταῖς γραφαῖς οὔτ’ ἐπὶ ταῖς δίκαις οὔτ’ ἐν ταῖς εὐθύναις. ὁ τοίνυν Φορμίων αὐτὸς αὑτῷ μεμαρτύρηκεν, ὁπότε φασὶν οὗτοι ἀκούσαντες ἐκείνου ταῦτα μεμαρτυρηκέναι.", "st": "46.9"}, {"sp": "N", "t": "ἵνα δὲ εἰδῆτε ἀκριβῶς, αὐτὸν τὸν νόμον μοι ἀνάγνωθι.", "st": "46.10"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "46.10"}, {"sp": "N", "t": "τοῖν ἀντιδίκοιν ἐπάναγκες εἶναι ἀποκρίνασθαι ἀλλήλοις τὸ ἐρωτώμενον, μαρτυρεῖν δὲ μή.", "st": "46.10"}, {"sp": "N", "t": "σκέψασθε τοίνυν τουτονὶ τὸν νόμον, ὃς κελεύει ὑποδίκους εἶναι τῶν ψευδομαρτυρίων καὶ κατ’ αὐτὸ τοῦτο, ὅτι μαρτυρεῖ παρὰ τὸν νόμον.", "st": "46.10"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "46.10"}, {"sp": "N", "t": "ἔστω δὲ καὶ ὑπόδικος τῶν ψευδομαρτυρίων ὁ μαρτυρήσας αὐτοῦ τούτου, ὅτι μαρτυρεῖ παρὰ τὸν νόμον· καὶ ὁ προβαλόμενος κατὰ ταὐτά.", "st": "46.10"}, {"sp": "N", "t": "ἔτι τοίνυν κἂν ἀπὸ τοῦ γραμματείου γνοίη τις, ἐν ᾧ ἡ μαρτυρία γέγραπται, ὅτι τὰ ψευδῆ μεμαρτύρηκεν. λελευκωμένον τε γάρ ἐστιν καὶ οἴκοθεν κατεσκευασμένον. καίτοι τοὺς μὲν τὰ πεπραγμένα μαρτυροῦντας προσήκει οἴκοθεν τὰς μαρτυρίας κατεσκευασμένας μαρτυρεῖν, τοὺς δὲ τὰς προκλήσεις μαρτυροῦντας, τοὺς ἀπὸ ταὐτομάτου προσστάντας, ἐν μάλθῃ γεγραμμένην τὴν μαρτυρίαν, ἵνα, ἐάν τι προσγράψαι ἢ ἀπαλεῖψαι βουληθῇ, ῥᾴδιον ᾖ.", "st": "46.11"}, {"sp": "N", "t": "οὐκοῦν κατὰ μὲν ταῦτα πάντα ἐξελέγχεται τὰ ψευδῆ μεμαρτυρηκὼς καὶ παρὰ τὸν νόμον· βούλομαι δ’ ὑμῖν καὶ αὐτὸ τοῦτο ἐπιδεῖξαι, ὡς οὔτε διέθετο ὁ πατὴρ ἡμῶν διαθήκην οὐδεμίαν οὔθ’ οἱ νόμοι ἐῶσιν. εἰ γάρ τις ἔροιτο ὑμᾶς, καθ’ ὁποίους νόμους δεῖ πολιτεύεσθαι ἡμᾶς, δῆλον ὅτι ἀποκρίναισθ’ ἂν κατὰ τοὺς κειμένους. ἀλλὰ μὴν οἵ γε νόμοι ἀπαγορεύουσι “μηδὲ νόμον ἐξεῖναι ἐπ’ ἀνδρὶ θεῖναι, ἂν μὴ τὸν αὐτὸν ἐφ’ ἅπασιν Ἀθηναίοις”.", "st": "46.12"}, {"sp": "N", "t": "οὐκοῦν ὁ μὲν νόμος οὑτοσὶ τοῖς αὐτοῖς νόμοις πολιτεύεσθαι ἡμᾶς κελεύει καὶ οὐκ ⟨ἄλλους⟩ ἄλλοις. ὁ δὲ πατὴρ ἐτελεύτησεν ἐπὶ Δυσνικήτου ἄρχοντος, ὁ δὲ Φορμίων Ἀθηναῖος ἐγένετο ἐπὶ Νικοφήμου ἄρχοντος, δεκάτῳ ἔτει ὕστερον ἢ ὁ πατὴρ ἡμῶν ἀπέθανεν. πῶς ἂν οὖν μὴ εἰδὼς ὁ πατὴρ αὐτὸν Ἀθηναῖον ἐσόμενον, ἔδωκεν ἂν τὴν ἑαυτοῦ γυναῖκα, καὶ προὐπηλάκισε μὲν ἂν ἡμᾶς, κατεφρόνησε δ’ ἂν τῆς δωρεᾶς ἧς παρ’ ὑμῶν ἔλαβεν, παρεῖδε δ’ ἂν τοὺς νόμους; πότερα δὲ κάλλιον ἦν αὐτῷ ζῶντι πρᾶξαι ταῦτα, εἴπερ ἐβούλετο, ἢ ἀποθανόντα διαθήκας καταλιπεῖν, ἃς οὐ κύριος ἦν;", "st": "46.13"}, {"sp": "N", "t": "ἀλλὰ μὴν αὐτῶν τῶν νόμων ἀκούσαντες γνώσεσθε, ὡς οὐ κύριος ἦν διαθέσθαι. λέγε τὸν νόμον.", "st": "46.14"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "46.14"}, {"sp": "N", "t": "ὅσοι μὴ ἐπεποίηντο, ὥστε μήτε ἀπειπεῖν μήτ’ ἐπιδικάσασθαι, ὅτε Σόλων εἰσῄει τὴν ἀρχήν, τὰ ἑαυτοῦ διαθέσθαι εἶναι ὅπως ἂν ἐθέλῃ, ἂν μὴ παῖδες ὦσι γνήσιοι ἄρρενες, ἂν μὴ μανιῶν ἢ γήρως ἢ φαρμάκων ἢ νόσου ἕνεκα, ἢ γυναικὶ πειθόμενος, ὑπὸ τούτων του παρανοῶν, ἢ ὑπ’ ἀνάγκης ἢ ὑπὸ δεσμοῦ καταληφθείς.", "st": "46.14"}, {"sp": "N", "t": "τοῦ μὲν νόμου τοίνυν ἀκηκόατε, ὃς οὐκ ἐᾷ διαθήκας διαθέσθαι, ἐὰν παῖδες ὦσι γνήσιοι. οὗτοι δέ φασι ταῦτα διαθέσθαι τὸν πατέρα, ὡς δὲ παρεγένοντο οὐκ ἔχουσιν ἐπιδεῖξαι. ἄξιον δὲ καὶ τόδε ἐνθυμηθῆναι, ὅτι ὅσοι μὴ ἐπεποίηντο ἀλλ’ ἦσαν πεφυκότες γνήσιοι, τούτοις ὁ νόμος δίδωσιν, ἐὰν ἄπαιδες ὦσιν, διαθέσθαι τὰ ἑαυτῶν. ὁ τοίνυν πατὴρ ἡμῶν ἐπεποίητο ὑπὸ τοῦ δήμου πολίτης, ὥστε οὐδὲ κατὰ τοῦτο ἐξῆν αὐτῷ διαθέσθαι διαθήκην, ἄλλως τε καὶ περὶ τῆς γυναικός, ἧς οὐδὲ κύριος ἐκ τῶν νόμων ἦν, παῖδές τε ἦσαν αὐτῷ.", "st": "46.15"}, {"sp": "N", "t": "σκέψασθε δὲ καὶ διότι οὐδ’ ἂν ἄπαις τις ᾖ, κύριός ἐστι τὰ αὑτοῦ διαθέσθαι, ἐὰν μὴ εὖ φρονῇ· νοσοῦντα δὲ ἢ φαρμακῶντα ἢ γυναικὶ πειθόμενον ἢ ὑπὸ γήρως ἢ ὑπὸ μανιῶν ἢ ὑπὸ ἀνάγκης τινὸς καταληφθέντα ἄκυρον κελεύουσιν εἶναι οἱ νόμοι. σκοπεῖτε δή, εἰ δοκοῦσιν ὑμῖν εὖ φρονοῦντος ἀνδρὸς εἶναι αἱ διαθῆκαι, ἅς φασι διαθέσθαι οὗτοι τὸν πατέρα.", "st": "46.16"}, {"sp": "N", "t": "μὴ πρὸς ἄλλο δέ τι παράδειγμα σκέψησθε ἢ πρὸς τὴν μίσθωσιν, εἰ δοκεῖ ὑμῖν ἀκόλουθον εἶναι τῷ τὴν τέχνην μὴ ἐξουσίαν δοῦναι εἰ μὴ ἐν τῷ αὐτῷ ἡμῖν ἐργάζεσθαι, τούτῳ τὴν γυναῖκα δοῦναι τὴν αὑτοῦ καὶ τῶν παίδων ἐᾶσαι κοινωνὸν αὑτῷ γενέσθαι. καὶ μὴ θαυμάζετε, εἰ τἄλλα σκευωρουμένους αὐτοὺς τὰ ἐν τῇ μισθώσει τοῦτο παρέλαθεν. ἴσως μὲν γὰρ οὐδὲ προσεῖχον ἄλλῳ οὐδενὶ ἢ τῷ τὰ χρήματα ἀποστερῆσαι καὶ τῷ προσοφείλοντα τὸν πατέρα ἐγγράψαι· εἶτα δὲ οὐδὲ ἐδόκουν ἐμὲ οὕτω δεινὸν ἔσεσθαι ὥστε ταῦτα ἀκριβῶς ἐξετάσαι.", "st": "46.17"}, {"sp": "N", "t": "σκέψασθε τοίνυν καὶ τοὺς νόμους, παρ’ ὧν κελεύουσι τὰς ἐγγύας ποιεῖσθαι, ἵν’ εἰδῆτε καὶ ἐκ τούτων ὡς κατεσκευασμένης διαθήκης ψευδὴς μάρτυς γέγονε Στέφανος οὑτοσί.", "st": "46.18"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "46.18"}, {"sp": "N", "t": "ἣν ἂν ἐγγυήσῃ ἐπὶ δικαίοις δάμαρτα εἶναι ἢ πατὴρ ἢ ἀδελφὸς ὁμοπάτωρ ἢ πάππος ὁ πρὸς πατρός, ἐκ ταύτης εἶναι παῖδας γνησίους. ἐὰν δὲ μηδεὶς ᾖ τούτων, ἐὰν μὲν ἐπίκληρός τις ᾖ, τὸν κύριον ἔχειν, ἐὰν δὲ μὴ ᾖ, ὅτῳ ἂν ἐπιτρέψῃ, τοῦτον κύριον εἶναι.", "st": "46.18"}, {"sp": "N", "t": "οὗτος μὲν τοίνυν ὁ νόμος οὓς ἐποίησεν κυρίους εἶναι, ἀκηκόατε· ὅτι δ’ οὐδεὶς ἦν τούτων τῇ μητρί, οἱ ἀντίδικοί μοι αὐτοὶ μεμαρτυρήκασιν. εἰ γὰρ ἦν, παρείχοντ’ ἄν. ἢ μάρτυρας μὲν ψευδεῖς οἴεσθ’ ἂν παρασχέσθαι καὶ διαθήκας οὐκ οὔσας, ἀδελφὸν δὲ ἢ πάππον ἢ πατέρα οὐκ ἄν, εἴπερ ἦν δυνατὸν ἕνεκα χρημάτων; ὁπότε τοίνυν μηδεὶς φαίνεται ζῶν τούτων, τότε ἀνάγκη ἐπίκληρον τὴν μητέρα ἡμῶν εἶναι. τῆς τοίνυν ἐπικλήρου σκοπεῖτε τίνας κελεύουσιν οἱ νόμοι κυρίους εἶναι.", "st": "46.19"}, {"sp": "N", "t": "λέγε τὸν νόμον.", "st": "46.20"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "46.20"}, {"sp": "N", "t": "καὶ ἐὰν ἐξ ἐπικλήρου τις γένηται καὶ ἅμα ἡβήσῃ ἐπὶ δίετες, κρατεῖν τῶν χρημάτων, τὸν δὲ σῖτον μετρεῖν τῇ μητρί.", "st": "46.20"}, {"sp": "N", "t": "οὐκοῦν ὁ μὲν νόμος κελεύει τοὺς παῖδας ἡβήσαντας κυρίους τῆς μητρὸς εἶναι, τὸν δὲ σῖτον μετρεῖν τῇ μητρί. ἐγὼ δὲ φαίνομαι στρατευόμενος καὶ τριηραρχῶν ὑμῖν, ὅτε οὗτος συνῴκησεν τῇ μητρί.", "st": "46.20"}, {"sp": "N", "t": "ἀλλὰ μὴν ὅτι ἐγὼ μὲν ἀπεδήμουν τριηραρχῶν, ἐτετελευτήκει δὲ ὁ πατὴρ πάλαι, ὅτε οὗτος ἔγημε, τὰς δὲ θεραπαίνας αὐτὸν ἐξῄτουν καὶ ἠξίουν περὶ αὐτοῦ τούτου βασανίζεσθαι αὐτάς, εἰ ταῦτ’ ἀληθῆ ἐστι, καὶ ὡς προὐκαλούμην, λαβέ μοι τὴν μαρτυρίαν.", "st": "46.21"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "46.21"}, {"sp": "N", "t": "μαρτυροῦσι παρεῖναι ὅτε προὐκαλεῖτο Ἀπολλόδωρος Φορμίωνα, ὅτε ἠξίου παραδοῦναι Ἀπολλόδωρος Φορμίωνα τὰς θεραπαίνας εἰς βάσανον, εἰ μή φησι Φορμίων καὶ πρότερον διεφθαρκέναι τὴν μητέρα τὴν ἐμήν, πρὶν οὗ ἀποφαίνει Φορμίων γῆμαι ἐγγυησάμενος αὐτὴν παρὰ Πασίωνος. ταῦτα δὲ προκαλουμένου Ἀπολλοδώρου οὐκ ἠθέλησε Φορμίων παραδοῦναι τὰς θεραπαίνας.", "st": "46.21"}, {"sp": "N", "t": "τὸν τοίνυν νόμον ἐπὶ τούτοις ἀνάγνωθι, ὃς κελεύει ἐπιδικασίαν εἶναι τῶν ἐπικλήρων ἁπασῶν, καὶ ξένων καὶ ἀστῶν, καὶ περὶ μὲν τῶν πολιτῶν τὸν ἄρχοντα εἰσάγειν καὶ ἐπιμελεῖσθαι, περὶ δὲ τῶν μετοίκων τὸν πολέμαρχον, καὶ ἀνεπίδικον μὴ ἐξεῖναι ἔχειν μήτε κλῆρον μήτε ἐπίκληρον.", "st": "46.22"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "46.22"}, {"sp": "N", "t": "κληροῦν δὲ τὸν ἄρχοντα κλήρων καὶ ἐπικλήρων, ὅσοι εἰσὶ μῆνες, πλὴν τοῦ σκιροφοριῶνος. ἀνεπίδικον δὲ κλῆρον μὴ ἔχειν.", "st": "46.22"}, {"sp": "N", "t": "οὐκοῦν αὐτόν, εἴπερ ἐβούλετο ὀρθῶς διαπράττεσθαι, λαχεῖν ἔδει τῆς ἐπικλήρου, εἴτε κατὰ δόσιν αὐτῷ προσῆκεν εἴτε κατὰ γένος, εἰ μὲν ὡς ὑπὲρ ἀστῆς, πρὸς τὸν ἄρχοντα, εἰ δὲ ὡς ὑπὲρ ξένης, πρὸς τὸν πολέμαρχον, καὶ τότε, εἴπερ τι λέγειν εἶχε δίκαιον, πείσαντα ὑμῶν τοὺς λαχόντας μετὰ τῶν νόμων καὶ τῆς ψήφου κύριον εἶναι, καὶ μὴ αὐτὸν αὑτῷ νόμους ἰδίους θέμενον διαπράξασθαι ἃ ἐβούλετο.", "st": "46.23"}, {"sp": "N", "t": "σκέψασθε δὴ καὶ τονδὶ τὸν νόμον, ὃς κελεύει τὴν διαθήκην, ἣν ἂν παίδων ὄντων γνησίων ὁ πατὴρ διαθῆται ἐὰν ἀποθάνωσιν οἱ παῖδες πρὶν ἡβῆσαι, κυρίαν εἶναι.", "st": "46.24"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "46.24"}, {"sp": "N", "t": "ὅ τι ἂν γνησίων ὄντων υἱέων ὁ πατὴρ διαθῆται ἐὰν ἀποθάνωσιν οἱ υἱεῖς πρὶν ἐπὶ δίετες ἡβᾶν, τὴν τοῦ πατρὸς διαθήκην κυρίαν εἶναι.", "st": "46.24"}, {"sp": "N", "t": "οὐκοῦν ὁπότε ζῶσιν, ἄκυρος μὲν ἡ διαθήκη ἐστίν, ἥν φασιν οὗτοι τὸν πατέρα καταλιπεῖν, παρὰ πάντας δὲ τοὺς νόμους μεμαρτύρηκε Στέφανος οὑτοσὶ τὰ ψευδῆ, ὡς ἀντίγραφά ἐστι τῆς διαθήκης τῆς Πασίωνος· πῶς γὰρ σὺ οἶσθα, καὶ ποῦ παραγενόμενος διατιθεμένῳ τῷ πατρί; κακοτεχνῶν δὲ φαίνει περὶ τὰς δίκας, τὰ ψευδῆ μὲν αὐτὸς μαρτυρῶν ἑτοίμως, κλέπτων δὲ τὰς ἀληθεῖς μαρτυρίας, ἐξαπατῶν δὲ τοὺς δικαστάς, συνιστάμενος δ’ ἐπὶ ταῖς δίκαις. οἱ δὲ νόμοι καὶ περὶ τῶν τοιούτων γραφὴν πεποιήκασιν.", "st": "46.25"}, {"sp": "N", "t": "καί μοι ἀνάγνωθι τὸν νόμον.", "st": "46.26"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "46.26"}, {"sp": "N", "t": "ἐάν τις συνιστῆται, ἢ συνδεκάζῃ τὴν ἡλιαίαν ἢ τῶν δικαστηρίων τι τῶν Ἀθήνησιν ἢ τὴν βουλὴν ἐπὶ δωροδοκίᾳ χρήματα διδοὺς ἢ δεχόμενος, ἢ ἑταιρείαν συνιστῇ ἐπὶ καταλύσει τοῦ δήμου, ἢ συνήγορος ὢν λαμβάνῃ χρήματα ἐπὶ ταῖς δίκαις ταῖς ἰδίαις ἢ δημοσίαις, τούτων εἶναι τὰς γραφὰς πρὸς τοὺς θεσμοθέτας.", "st": "46.26"}, {"sp": "N", "t": "ἡδέως ἂν τοίνυν ὑμᾶς ἐροίμην ἐπὶ τούτοις ἅπασι, κατὰ ποίους νόμους ὀμωμοκότες δικάζετε, πότερα κατὰ τοὺς τῆς πόλεως ἢ καθ’ οὓς Φορμίων αὑτῷ νομοθετεῖ. ἐγὼ μὲν τοίνυν τούτους παρέχομαι ὑμῖν, καὶ ἐξελέγχω αὐτοὺς ἀμφοτέρους παραβεβηκότας, Φορμίωνα μὲν ἐξ ἀρχῆς ἀδικήσαντα ἡμᾶς καὶ ἀποστερήσαντα τὰ χρήματα, ἃ ὁ πατὴρ ἡμῖν κατέλιπεν καὶ ἐμίσθωσε τούτῳ μετὰ τῆς τραπέζης καὶ τοῦ ἐργαστηρίου, Στέφανον δὲ τουτονὶ τὰ ψευδῆ μεμαρτυρηκότα καὶ παρὰ τὸν νόμον.", "st": "46.27"}, {"sp": "N", "t": "ἄξιον τοίνυν, ὦ ἄνδρες δικασταί, καὶ τόδε ἐνθυμηθῆναι, ὅτι διαθήκης οὐδεὶς πώποτε ἀντίγραφα ἐποιήσατο, ἀλλὰ συγγραφῶν μέν, ἵνα εἰδῶσι καὶ μὴ παραβαίνωσι, διαθηκῶν δὲ οὔ. τούτου γὰρ ἕνεκα ⟨κατασεσημασμένας⟩ καταλείπουσιν οἱ διατιθέμενοι, ἵνα μηδεὶς εἰδῇ ἃ διατίθενται. πῶς οὖν ὑμεῖς ἴστε ὅτι ἀντίγραφά ἐστιν τῶν διαθηκῶν τῶν Πασίωνος τὰ ἐν τῷ γραμματείῳ γεγραμμένα;", "st": "46.28"}, {"sp": "N", "t": "δέομαι οὖν ὑμῶν ἁπάντων, ὦ ἄνδρες δικασταί, καὶ ἱκετεύω βοηθῆσαι μὲν ἐμοί, τιμωρήσασθαι δὲ τοὺς ἑτοίμως οὕτως τὰ ψευδῆ μαρτυροῦντας, ὑπέρ τε ὑμῶν αὐτῶν καὶ ἐμοῦ καὶ τοῦ δικαίου καὶ τῶν νόμων.", "st": "46.28"}, {"sp": "HDR", "t": "Κατὰ Εὐέργου καὶ Μνησιβούλου ψευδομαρτυριῶν", "st": "47"}, {"sp": "N", "t": "καλῶς μοι δοκοῦσιν οἱ νόμοι ἔχειν, ὦ ἄνδρες δικασταί, οἱ ὑπόλοιπον ἀγῶνα ἀποδόντες ταῖς δίκαις ⟨τὸν⟩ τῶν ψευδομαρτυρίων, ἵνα, εἴ τις μάρτυρας τὰ ψευδῆ μαρτυροῦντας παρασχόμενος ἢ προκλήσεις μὴ γενομένας ἢ μαρτυρίας παρὰ τὸν νόμον μαρτυρηθείσας ἐξηπάτησεν τοὺς δικαστάς, μηδὲν αὐτῷ πλέον γένηται, ἀλλ’ ἐπισκηψάμενος ταῖς μαρτυρίαις ὁ ἀδικηθεὶς καὶ εἰσελθὼν ὡς ὑμᾶς καὶ ἐπιδείξας περὶ τοῦ πράγματος τοὺς μάρτυρας τὰ ψευδῆ μεμαρτυρηκότας, παρά τε τούτων δίκην λάβῃ καὶ τὸν προβαλόμενον ὑπόδικον ἔχῃ τῶν κακοτεχνιῶν.", "st": "47.1"}, {"sp": "N", "t": "καὶ διὰ τοῦτο τῷ μὲν διώκοντι ἐλάττω ἐποίησαν τὰ ἐπιτίμια, ἐὰν ἡττηθῇ, ἵνα μὴ διὰ τὸ πλῆθος ἀποτρέπωνται διώκειν τοὺς μάρτυρας τῶν ψευδομαρτυρίων οἱ ἀδικούμενοι, τῷ δὲ φεύγοντι μεγάλας ἐπέθηκαν τιμωρίας, ἐὰν ἁλῶσιν καὶ δόξωσιν ὑμῖν τὰ ψευδῆ μεμαρτυρηκέναι.", "st": "47.2"}, {"sp": "N", "t": "δικαίως, ὦ ἄνδρες δικασταί. ὑμεῖς γὰρ εἰς τοὺς μάρτυρας βλέψαντες, καὶ πιστεύσαντες οἷς ἂν οὗτοι μαρτυρήσωσιν, ψηφίζεσθε· ἵνα οὖν μήθ’ ὑμεῖς ἐξαπατᾶσθε μήθ’ οἱ εἰσιόντες εἰς ὑμᾶς ἀδικῶνται, διὰ ταῦτα αὐτοὺς ὑποδίκους ἐποίησεν ὁ νομοθέτης. δέομαι δὲ ὑμῶν καὶ ἐγὼ μετ’ εὐνοίας μου ἀκροάσασθαι περὶ τοῦ πράγματος ἐξ ἀρχῆς ἅπαντα, ἵνα ἐκ τούτων εἰδῆτε ὅσα ἐγώ τε ἠδικήθην καὶ ἐξηπατήθησαν οἱ δικασταὶ καὶ οὗτοι τὰ ψευδῆ ἐμαρτύρησαν.", "st": "47.3"}, {"sp": "N", "t": "μάλιστα μὲν οὖν ἂν ἐβουλόμην μὴ ἔχειν πράγματα· εἰ δ’ οὖν ἀναγκάζοι τις, πρὸς τοιούτους ἡδύ ἐστιν εἰσιέναι οἳ μὴ ἀγνῶτές εἰσιν ὑμῖν. νῦν δὲ πλείων μοι λόγος ἔσται ἐξελέγχοντι τὸν τρόπον αὐτῶν ἢ τὴν μαρτυρίαν ψευδῆ οὖσαν. περὶ μὲν γὰρ τῆς μαρτυρίας, ὅτι ψευδῆ μεμαρτυρήκασιν, αὐτοί μοι δοκοῦσιν ἔργῳ ἐξελέγχειν αὐτήν, καὶ οὐκ ἄλλους με δεῖ μάρτυρας παρασχέσθαι ἢ αὐτοὺς τούτους·", "st": "47.4"}, {"sp": "N", "t": "ἐξὸν γὰρ αὐτοῖς ἀπηλλάχθαι πραγμάτων καὶ μὴ κινδυνεύειν εἰσιόντας εἰς ὑμᾶς, ἔργῳ βεβαιώσαντας ὡς ἀληθής ἐστιν ἡ μαρτυρία, οὐκ ἠθελήκασιν παραδοῦναι τὴν ἄνθρωπον, ἣν μεμαρτυρήκασιν προκαλέσασθαι πρὸς τῷ διαιτητῇ Πυθοδώρῳ ἐκ Κηδῶν παραδιδόναι ἕτοιμον εἶναι Θεόφημον, ἠξίουν δ’ ἐγὼ παραλαμβάνειν, ὡς οἱ μάρτυρες ὑμῖν οἱ τότε παραγενόμενοι ἐμαρτύρησαν ἐν τῷ δικαστηρίῳ, καὶ νῦν δὲ μαρτυρήσουσιν. καὶ Θεόφημος αὐτοῖς ὡς ἀληθῆ μεμαρτυρηκόσιν οὐκ ἐπεσκήψατο, οὐδ’ ἐπεξέρχεται τῶν ψευδομαρτυρίων.", "st": "47.5"}, {"sp": "N", "t": "σχεδὸν μὲν οὖν μοι καὶ αὐτοὶ ὁμολογοῦσιν ἐν τῇ μαρτυρίᾳ ἐθέλειν με παραλαμβάνειν τὴν ἄνθρωπον, Θεόφημον δὲ ἀναβάλλεσθαι κελεύειν, ἐμὲ δὲ οὐκ ἐθέλειν. ἣν δ’ ἐγὼ μὲν ἠξίωσα παραλαμβάνειν, Θεόφημος δὲ προὐκαλέσατο παραδοῦναι, ὡς οὗτοί φασιν, τὸ δὲ σῶμα οὐδεὶς εἶδε παρόν, οὔτε τότε πρὸς τῷ διαιτητῇ οὔτε ὕστερον πρὸς τῷ δικαστηρίῳ οὔτε ἄλλοθι οὐδαμοῦ παραδιδόμενον, ἐμαρτύρησαν δὲ οἱ μάρτυρες οὗτοι ὡς ἐθέλοι παραδοῦναι Θεόφημος καὶ πρόκλησιν προκαλοῖτο,", "st": "47.6"}, {"sp": "N", "t": "ᾠήθησαν δὲ οἱ δικασταὶ ἀληθῆ εἶναι τὴν μαρτυρίαν, φεύγειν δ’ ἐμὲ τὸν ἔλεγχον ⟨τὸν⟩ ἐκ τῆς ἀνθρώπου περὶ τῆς αἰκείας, ὁπότερος ἡμῶν ἦρξεν χειρῶν ἀδίκων (τοῦτο γάρ ἐστιν ἡ αἴκεια), πῶς οὐκ ἀναγκαῖόν ἐστιν τούτους τοὺς μάρτυρας τὰ ψευδῆ μεμαρτυρηκέναι, οἵ γε οὐδὲ νῦν πω τολμῶσι τὸ σῶμα τῆς ἀνθρώπου παραδοῦναι, καθὰ ἔφασαν προκαλέσασθαι τὸν Θεόφημον καὶ ἐμαρτύρησαν αὐτῷ, καὶ τὴν μὲν μαρτυρίαν ἔργῳ βεβαιῶσαι ὡς ἀληθής ἐστιν, καὶ τοὺς μάρτυρας ἀπηλλάχθαι τοῦ ἀγῶνος παραδόντας τὸ σῶμα τῆς ἀνθρώπου,", "st": "47.7"}, {"sp": "N", "t": "τὴν δὲ ἄνθρωπον περὶ τῆς αἰκείας βασανίζεσθαι, ἐφ’ ᾗ ἐγὼ διώκω δίκῃ τὸν Θεόφημον, ἐπειδὴ τότε οὐ παρέσχεν, καὶ τὸν ἔλεγχον ἐξ ὧν ὁ Θεόφημος ἔλεγεν τότε ἐξαπατῶν τοὺς δικαστάς, ἐκ τούτων γίγνεσθαι; ἔφη γὰρ ἐν τῇ δίκῃ τῆς αἰκείας τοὺς μὲν μάρτυρας τοὺς παραγενομένους καὶ μαρτυροῦντας τὰ γενόμενα ἐν γραμματείῳ κατὰ τὸν νόμον ψευδεῖς εἶναι καὶ ὑπ’ ἐμοῦ παρεσκευασμένους, τὴν δ’ ἄνθρωπον τὴν παραγενομένην ἐρεῖν τἀληθῆ, οὐκ ἐκ γραμματείου μαρτυροῦσαν, ἀλλ’ ἐκ τῆς ἰσχυροτάτης μαρτυρίας, βασανιζομένην, ὁπότερος ἦρξε χειρῶν ἀδίκων.", "st": "47.8"}, {"sp": "N", "t": "ἃ δή, λόγῳ τότε καταχρώμενος καὶ μάρτυρας παρεχόμενος τούτων, ἠπάτα τοὺς δικαστάς, νῦν ἐξελέγχεται ψευδῆ ὄντα· τὸ γὰρ σῶμα τῆς ἀνθρώπου οὐ τολμᾷ παραδοῦναι, ὃ μεμαρτυρήκασιν αὐτὸν ἐθέλειν παραδοῦναι, ἀλλὰ μᾶλλον προῄρηται τὸν ἀδελφὸν καὶ τὸν κηδεστὴν ψευδομαρτυρίων ἀγωνίζεσθαι ἢ παραδοῦναι τὸ σῶμα τῆς ἀνθρώπου καὶ δικαίως ἀπηλλάχθαι, καὶ μὴ διὰ λόγων καὶ δεήσεως, ἐὰν δύνωνται ἐξαπατήσαντες ὑμᾶς ἀποφεύγειν,", "st": "47.9"}, {"sp": "N", "t": "πολλάκις ἐμοῦ προκαλεσαμένου καὶ ἐξαιτήσαντος τὴν ἄνθρωπον καὶ τότε ἀξιοῦντος παραλαμβάνειν καὶ μετὰ τὴν δίκην, καὶ ὅτε ἐξέτινον αὐτοῖς, καὶ ἐφ’ ᾗ ἐγὼ δίκῃ τὸν Θεόφημον διώκω τῆς αἰκείας, καὶ ἐν τῇ ἀνακρίσει τῶν ψευδομαρτυρίων, καὶ τούτων οὐ προσποιουμένων, ἀλλὰ λόγῳ μὲν μαρτυρούντων τὰ ψευδῆ, ἔργῳ δὲ οὐ παραδιδόντων τὴν ἄνθρωπον· εὖ γὰρ ᾔδεσαν ὅτι βασανιζομένης αὐτῆς ἐξελεγχθήσονται ἀδικοῦντες, οὐκ ἀδικούμενοι. ὡς δὲ ταῦτα ἀληθῆ λέγω, τούτων ὑμῖν ἀναγνώσεται τὰς μαρτυρίας.", "st": "47.10"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "47.10"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν πολλάκις προκαλεσαμένῳ καὶ ἀξιοῦντι παραλαβεῖν τὴν ἄνθρωπον οὐδεὶς παρεδίδου, μεμαρτύρηται ὑμῖν. ἵνα δὲ καὶ ἐκ τεκμηρίων εἰδῆτε ὅτι ψευδῆ μεμαρτυρήκασιν, δηλώσω ὑμῖν. οὗτοι γάρ, εἴπερ ἀληθῆ ἦν ἅ φασιν προκαλέσασθαι τὸν Θεόφημον καὶ παραδιδόναι τὸ σῶμα τῆς ἀνθρώπου, οὐκ ἂν δήπου δύο μόνους μάρτυρας ἐποιήσαντο κηδεστὴν καὶ ἀδελφόν, τἀληθῆ μαρτυροῦντας, ἀλλὰ καὶ ἄλλους ἂν πολλούς.", "st": "47.11"}, {"sp": "N", "t": "ἡ μὲν γὰρ δίαιτα ἐν τῇ ἡλιαίᾳ ἦν (οἱ γὰρ τὴν Οἰνῇδα καὶ τὴν Ἐρεχθῇδα διαιτῶντες ἐνταῦθα κάθηνται)· τῶν δὲ τοιούτων προκλήσεων, ὅταν τις τὸ σῶμα παραδιδῷ κομίσας, πολλοὶ προσίστανται ἐπακούοντες τῶν λεγομένων, ὥστε οὐκ ἂν ἠπόρησαν μαρτύρων, εἴπερ καὶ ὁπωστιοῦν ἀληθὴς ἦν ἡ μαρτυρία.", "st": "47.12"}, {"sp": "N", "t": "μεμαρτυρήκασι τοίνυν, ὦ ἄνδρες δικασταί, ἐν τῇ αὐτῇ μαρτυρίᾳ, ὡς ἐγὼ οὐκ ἐθέλοιμι ἀναβαλέσθαι, ὁ δὲ Θεόφημος κελεύοι, ἵνα μοι παραδοίη τὴν ἄνθρωπον. ὡς δὲ οὐκ ἀληθὲς τοῦτ’ ἔστιν, ἐγὼ ὑμᾶς διδάξω. εἰ μὲν γὰρ ἐγὼ τὸν Θεόφημον ταύτην τὴν πρόκλησιν προὐκαλούμην ἣν μεμαρτυρήκασιν αὐτῷ,", "st": "47.13"}, {"sp": "N", "t": "ἀξιῶν αὐτὸν τὴν ἄνθρωπον παραδοῦναι, εἰκότως ἄν μοι τούτους τοὺς λόγους ἀπεκρίνατο, ἀναβαλέσθαι κελεύων τὴν δίαιταν εἰς τὴν ὑστέραν σύνοδον, ἵνα κομίσῃ τὴν ἄνθρωπον καὶ παραδῷ μοι· νῦν δὲ σὲ αὐτὸν μεμαρτυρήκασιν, ὦ Θεόφημε, ἐθέλειν παραδιδόναι τὴν ἄνθρωπον, καὶ ἐμὲ μὴ ’θέλειν παραλαβεῖν. πῶς οὖν σὺ κύριος μὲν ὢν τῆς ἀνθρώπου, μέλλων δὲ προκαλεῖσθαι ταύτην τὴν πρόκλησιν ἣν μεμαρτυρήκασί σοι, καταφεύγων δὲ εἰς τὴν ἄνθρωπον περὶ τοῦ δικαίου,", "st": "47.14"}, {"sp": "N", "t": "ἄλλου δέ σοι οὐδενὸς ὄντος μάρτυρος ὡς ἐπλήγης ὑπ’ ἐμοῦ ἄρχοντος χειρῶν ἀδίκων, οὐχ ἧκες ἔχων τὴν ἄνθρωπον πρὸς τὸν διαιτητὴν καὶ παρεδίδους τὸ σῶμα παρούσης τῆς ἀνθρώπου, κύριός γε ὢν αὐτῆς; ἀλλὰ τὴν μὲν πρόκλησιν φὴς προκαλέσασθαι, τὴν δὲ ἄνθρωπον οὐδεὶς εἶδεν, δι’ ἧς ἐξηπάτησας τοὺς δικαστάς, ψευδεῖς μάρτυρας παρασχόμενος ὡς ἐθέλων παραδοῦναι.", "st": "47.15"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν σοι τότε οὐ παρῆν ἡ ἄνθρωπος, ἀλλὰ πρότερον ἐσημάνθησαν οἱ ἐχῖνοι, ὕστερον ἔστιν ὅπου ἤγαγες τὴν ἄνθρωπον εἰς τὴν ἀγορὰν ἢ εἰς τὸ δικαστήριον; εἰ γὰρ μὴ τότε σοι παρεγένετο, ὕστερον δήπου ἔδει παραδιδόναι, καὶ μάρτυρας ποιεῖσθαι ὡς ἐθέλεις ἐν τῇ ἀνθρώπῳ τὸν ἔλεγχον γίγνεσθαι, καθάπερ προὐκαλέσω, προκλήσεώς τε ἐμβεβλημένης σοι καὶ μαρτυρίας ὡς ἤθελες παραδιδόναι τὴν ἄνθρωπον. μέλλων τοίνυν εἰσιέναι τὴν δίκην ἔστιν ὅπου τὴν ἄνθρωπον εἰσήγαγες πρὸς τὸ δικαστήριον;", "st": "47.16"}, {"sp": "N", "t": "καίτοι ἔδει αὐτόν, εἴπερ ἀληθῆ ἦν ἅ φασιν αὐτὸν προκαλεῖσθαι, κληρουμένων τῶν δικαστηρίων κομίσαντα τὴν ἄνθρωπον, λαβόντα τὸν κήρυκα, κελεύειν ἐμέ, εἰ βουλοίμην, βασανίζειν, καὶ μάρτυρας τοὺς δικαστὰς εἰσιόντας ποιεῖσθαι ὡς ἕτοιμός ἐστιν παραδοῦναι. νυνὶ δὲ λόγῳ ἐξαπατήσας, ψευδεῖς μαρτυρίας παρασχόμενος, οὐδέπω καὶ νῦν τολμᾷ τὴν ἄνθρωπον παραδοῦναι, πολλάκις ἐμοῦ προκαλεσαμένου καὶ ἐξαιτήσαντος, ὡς οἱ μάρτυρες ὑμῖν οἱ παραγενόμενοι μεμαρτυρήκασιν. καί μοι ἀνάγνωθι πάλιν τὰς μαρτυρίας.", "st": "47.17"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "47.17"}, {"sp": "N", "t": "βούλομαι δ’ ὑμῖν, ὦ ἄνδρες δικασταί, καὶ τὴν δίκην διηγήσασθαι, ὅθεν ἐγένετό μοι πρὸς Θεόφημον, ἵνα εἰδῆτε ὅτι οὐ μόνον ἐμοῦ ἀδίκως κατεδικάσατο, ἐξαπατήσας τοὺς δικαστάς, ἀλλὰ καὶ τῆς βουλῆς ἅμα τῶν πεντακοσίων τῇ αὐτῇ ψήφῳ, καὶ ἄκυρα μὲν ἐποίησεν τὰ δικαστήρια τὰ ὑμέτερα, ἄκυρα δὲ τὰ ψηφίσματα καὶ τοὺς νόμους, ἀπίστους δὲ τὰς ἀρχὰς κατέστησεν ὑμῖν καὶ τὰ γράμματα τὰ ἐν ταῖς στήλαις. ὃν δὲ τρόπον, ἐγὼ ὑμᾶς περὶ ἑνὸς ἑκάστου διδάξω.", "st": "47.18"}, {"sp": "N", "t": "ἐμοὶ γὰρ πρὸς Θεόφημον συμβόλαιον μὲν οὐδὲν πώποτε πρότερον ἐν τῷ βίῳ ἐγένετο, οὐδ’ αὖ κῶμος ἢ ἔρως ἢ πότος, ὥστε διαφερόμενον περί τινος πλεονεκτήματος ἢ παροξυνόμενον ὑπὸ ἡδονῆς τινὸς ἐλθεῖν ἐπὶ τὴν οἰκίαν τὴν τούτου. ψηφισμάτων δὲ ὑμετέρων δήμου καὶ βουλῆς καὶ νόμου ἐπιτάξαντος, εἰσέπραξα τοῦτον ὀφείλοντα τῇ πόλει σκεύη τριηρικά. δι’ ὅτι δέ, ἐγὼ ὑμῖν διηγήσομαι.", "st": "47.19"}, {"sp": "N", "t": "ἔτυχεν ἔκπλους ὢν τριήρων καὶ βοήθεια ἀποστελλομένη διὰ τάχους. σκεύη οὖν ἐν τῷ νεωρίῳ οὐχ ὑπῆρχεν ταῖς ναυσίν, ἀλλ’ ἔχοντες οἱ ὀφείλοντες οὐκ ἀπεδίδοσαν· πρὸς δὲ τούτοις οὐδ’ ἐν τῷ Πειραιεῖ ὄντα ἄφθονα ὀθόνια καὶ στυππεῖον καὶ σχοινία, οἷς κατασκευάζεται τριήρης, ὥστε πρίασθαι. γράφει οὖν Χαιρέδημος τὸ ψήφισμα τουτί, ἵνα εἰσπραχθῇ τὰ σκεύη ταῖς ναυσὶ καὶ σᾶ γένηται τῇ πόλει. καί μοι ἀνάγνωθι τὸ ψήφισμα.", "st": "47.20"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑ.", "st": "47.20"}, {"sp": "N", "t": "τούτου τοίνυν τοῦ ψηφίσματος γεγενημένου, ἡ μὲν ἀρχὴ ἐπεκλήρωσεν καὶ παρέδωκε τοὺς ὀφείλοντας τὰ σκεύη τῇ πόλει[, οἱ δὲ τῶν νεωρίων ἐπιμεληταὶ] τοῖς τριηράρχοις τοῖς ἐκπλέουσιν τότε καὶ τοῖς ἐπιμεληταῖς τοῖς ἐν ταῖς συμμορίαις. ὁ δὲ νόμος ὁ τοῦ Περιάνδρου ἠνάγκαζεν καὶ προσέταττεν παραλαβεῖν τοὺς ὀφείλοντας τὰ σκεύη, καθ’ ὃν αἱ συμμορίαι συνετάχθησαν. πρὸς δὲ τούτοις ἕτερον ψήφισμα δήμου ἠνάγκαζε τὸ πρὸς μέρος ἡμῖν διδόναι τῶν ὀφειλόντων ἕκαστον εἰσπράξασθαι.", "st": "47.21"}, {"sp": "N", "t": "ἔτυχον δὴ ἐγὼ μὲν τριηραρχῶν καὶ ἐπιμελητὴς ὢν τῆς συμμορίας, Δημοχάρης δὲ ὁ Παιανιεὺς ἐν τῇ συμμορίᾳ ὢν καὶ ὀφείλων τῇ πόλει σκεύη μετὰ Θεοφήμου τουτουί, συντριήραρχος γενόμενος. γεγραμμένους οὖν αὐτοὺς ἀμφοτέρους ἐν τῇ στήλῃ ὀφείλοντας τὰ σκεύη τῇ πόλει ἡ ἀρχὴ παραλαβοῦσα παρὰ τῆς προτέρας ἀρχῆς, ἡμῖν παρέδωκεν κατά τε τὸν νόμον καὶ τὰ ψηφίσματα.", "st": "47.22"}, {"sp": "N", "t": "ἐξ ἀνάγκης οὖν ἦν μοι παραλαβεῖν, ἐπεὶ ἐν τῷ πρόσθε χρόνῳ πολλὰς τριηραρχίας τετριηραρχηκὼς ὑμῖν οὐδεπώποτε ἔλαβον σκεύη ἐκ τοῦ νεωρίου, ἀλλ’ αὐτὸς ἰδίᾳ παρεσκεύαζον, ὁπότε δέοι, ἵνα ὡς ἐλάχιστα πράγματα ἔχοιμι πρὸς τὴν πόλιν· τότε δὲ κατά τε τὰ ψηφίσματα καὶ τὸν νόμον ἠναγκαζόμην παραλαμβάνειν.", "st": "47.23"}, {"sp": "N", "t": "ὡς δὲ ταῦτα ἀληθῆ λέγω, τούτων ὑμῖν μάρτυρας παρέξομαι τό τε ψήφισμα καὶ τὸν νόμον, ἔπειτα τὴν ἀρχὴν αὐτὴν τὴν παραδοῦσαν καὶ εἰσαγαγοῦσαν εἰς τὸ δικαστήριον, εἶτα τοὺς ἐκ τῆς συμμορίας, ἧς ἦν ἐπιμελητὴς καὶ τριήραρχος. καί μοι ἀνάγνωθι.", "st": "47.24"}, {"sp": "N", "t": "ΝΟΜΟΣ. ΨΗΦΙΣΜΑ. ΜΑΡΤΥΡΙΑΙ.", "st": "47.24"}, {"sp": "N", "t": "ὡς μὲν τοίνυν πολλή μοι ἀνάγκη ἦν παραλαβεῖν τοὺς ὀφείλοντας τῇ πόλει, τοῦ τε νόμου ἀκούετε καὶ τῶν ψηφισμάτων· ὡς δὲ καὶ παρέλαβον παρὰ τῆς ἀρχῆς, ὁ παραδοὺς ὑμῖν μεμαρτύρηκεν. σκέψασθαι οὖν ὑμᾶς εἰκός ἐστιν ἐξ ἀρχῆς, ὦ ἄνδρες δικασταί, τοῦτο πρῶτον, πότερον ἐγὼ ἠδίκουν ὁ ἀναγκαζόμενος εἰσπρᾶξαι τὸν Θεόφημον, ἢ Θεόφημος, ὃς ὀφείλων τῇ πόλει τὰ σκεύη πολὺν χρόνον οὐκ ἀπεδίδου.", "st": "47.25"}, {"sp": "N", "t": "ἐὰν γὰρ καθ’ ἕκαστον σκοπῆτε, εὑρήσετε τὸν Θεόφημον ἅπαντα ἀδικοῦντα, καὶ ταῦτα οὐχ ὑπ’ ἐμοῦ μόνον λόγῳ εἰρημένα, ἀλλὰ καὶ ὑπὸ τῆς βουλῆς καὶ τοῦ δικαστηρίου ψήφῳ κεκριμένα. ἐπειδὴ γὰρ παρέλαβον αὐτὸν παρὰ τῆς ἀρχῆς, προσελθὼν αὐτῷ πρῶτον μὲν ἀπῄτουν τὰ σκεύη· ὡς δὲ τοῦτό μου εἰπόντος οὐκ ἀπεδίδου, ὕστερον αὐτῷ περιτυχὼν περὶ τὸν Ἑρμῆν τὸν πρὸς τῇ πυλίδι προσεκαλεσάμην πρός τε τοὺς ἀποστολέας καὶ πρὸς τοὺς τῶν νεωρίων ἐπιμελητάς· οὗτοι γὰρ εἰσῆγον τότε τὰς διαδικασίας εἰς τὸ δικαστήριον περὶ τῶν σκευῶν.", "st": "47.26"}, {"sp": "N", "t": "ὡς δὲ ἀληθῆ λέγω, τούτων ὑμῖν μάρτυρας τοὺς κλητεύσαντας παρέξομαι.", "st": "47.27"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "47.27"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν προσεκλήθη ὑπ’ ἐμοῦ, οἱ κλητῆρές μοι μεμαρτυρήκασιν· ὡς δὲ εἰσήχθη εἰς τὸ δικαστήριον, λαβέ μοι τὴν μαρτυρίαν τῶν ἀποστολέων καὶ τῆς ἀρχῆς.", "st": "47.27"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "47.27"}, {"sp": "N", "t": "ὃν μὲν τοίνυν ᾤμην πράγματα παρέξειν μοι Δημοχάρην τὸν Παιανιέα, πρὶν μὲν εἰσαχθῆναι εἰς τὸ δικαστήριον ἦν ἀηδής, ἐπειδὴ δὲ εἰσήχθη καὶ ἑάλω, ἀπέδωκεν τὸ καθ’ ἑαυτὸν μέρος τῶν σκευῶν. ὃν δ’ οὐκ ἂν ᾠήθην εἰς τοσοῦτον πονηρίας ἐλθεῖν ὥστε τολμῆσαι ἄν ποτε τὴν πόλιν ἀποστερῆσαι τὰ σκεύη, εἰς τοσοῦτο δικῶν καὶ πραγμάτων προβέβηκεν. καὶ παρὼν μὲν πρὸς τῷ δικαστηρίῳ, ὅτε εἰσήγετο, οὐδαμοῦ ἠντεδίκησεν, οὐδὲ ἀπεγράψατο διαδικασίαν πρὸς οὐδένα, εἴ τινά φησιν ἕτερον ἔχειν τὰ σκεύη καὶ μὴ προσήκειν αὑτῷ ἀποδοῦναι, ἀλλ’ εἴασεν καθ’ αὑτοῦ ψῆφον ἐπαχθῆναι·", "st": "47.28"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἀπῆλθεν ἐκ τοῦ δικαστηρίου, οὐδὲν μᾶλλον ἀπεδίδου, ἀλλ’ ᾤετο ἐν μὲν τῷ παρόντι αὐτὸς ἐκποδὼν γενόμενος ἡσυχίαν ἕξειν, ἕως ⟨ἂν⟩ ἐγώ τε ἐκπλεύσω καὶ αἱ νῆες καὶ χρόνος ἐγγένηται, καὶ ἐμέ, ἃ οὗτος ὤφειλεν σκεύη τῇ πόλει, ἀναγκασθήσεσθαι ἀποδοῦναι ἥκοντα ἐνθάδε ἢ τῷ διαδόχῳ, ὃς ἂν ἔλθῃ ἐκ τῆς συμμορίας ἐπὶ τὴν ναῦν. τί γὰρ ἂν καὶ ἀντέλεγον αὐτῷ ψηφίσματα καὶ νόμους παρεχομένῳ, ὡς προσῆκεν ἐμὲ εἰσπρᾶξαι τὰ σκεύη;", "st": "47.29"}, {"sp": "N", "t": "ὁ δὲ Θεόφημος χρόνου ἐγγεγενημένου, ὁπότε αὐτὸν ἥκων ἀπαιτοίην, ἔμελλε φήσειν ἀποδεδωκέναι, καὶ τούτοις τεκμηρίοις καταχρήσεσθαι ὡς ἀποδέδωκεν, τῷ καιρῷ, τῇ χρείᾳ, ὡς οὐκ ἠλίθιος ἦν οὐδ’ αὖ φίλος αὐτῷ γενόμενος οὐδεπώποτε ὥστ’ ἐπισχεῖν· ὥστε τί ἄν ποτε βουλόμενος ἐγώ, τριηραρχῶν μὲν τῇ πόλει, ἐπιμελητὴς δὲ ὢν τῆς συμμορίας, ψηφισμάτων δὲ τοιούτων καὶ νόμου ὄντος, περὶ τὴν εἴσπραξιν ἐπέσχον ἂν τούτῳ;", "st": "47.30"}, {"sp": "N", "t": "ταύτην τὴν διάνοιαν ἔχων ὁ Θεόφημος τότε μὲν οὐκ ἀπεδίδου τὰ σκεύη, ἀλλ’ ἐκποδὼν ἦν, ὕστερον δὲ ᾤετό με ἀποστερήσειν, πρὸς δὲ τούτοις εἰς ὅρκον καταφυγὼν ῥᾳδίως ἐπιορκήσειν, ὅπερ καὶ ἄλλοις πεποίηκεν. δεινὴ γὰρ ἡ πλεονεξία τοῦ τρόπου περὶ τὰ διάφορα, ὡς ἐγὼ ἔργῳ ὑμῖν ἐπιδείξω. ταῦτα γὰρ τὰ σκεύη ὀφείλων ὁ Θεόφημος τῇ πόλει εἰς Ἀφαρέα ἀνέφερεν λόγῳ, ἔργῳ δὲ οὐκ ἀπεγράψατο πρὸς αὐτὸν διαδικασίαν, εὖ εἰδὼς ὅτι ἐλεγχθήσεται ψευδόμενος, ἐὰν εἰσέλθῃ εἰς δικαστήριον.", "st": "47.31"}, {"sp": "N", "t": "ὁ γὰρ Ἀφαρεὺς ἐξήλεγχεν αὐτὸν τιμὴν λογισάμενον αὑτῷ τῶν σκευῶν καὶ λαβόντα παρ’ αὑτοῦ, ὅτε παρελάμβανεν τὴν τριηραρχίαν. νῦν δέ φησι Δημοχάρει παραδοῦναι, καὶ δικάζεται τοῖς παιδίοις τοῖς Δημοχάρους τετελευτηκότος τοῦ Δημοχάρους. ὅτε δ’ ἔζη ὁ Δημοχάρης, οὐκ ἀπεγράψατο πρὸς αὐτὸν διαδικασίαν ὁ Θεόφημος, εἰσπραττόμενος ὑπ’ ἐμοῦ τὰ σκεύη, ἀλλ’ ἐβούλετο ἐπὶ προφάσει χρόνου ἐγγενομένου ἀποστερῆσαι τὴν πόλιν τὰ σκεύη. ὡς δ’ ἀληθῆ λέγω, ἀναγνώσεται τὰς μαρτυρίας.", "st": "47.32"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "47.32"}, {"sp": "N", "t": "ταῦτα τοίνυν ἐγὼ πάντα ἐνθυμούμενος, καὶ ἀκούων τὸν Θεόφημον τῶν πεπλησιακότων οἷος εἴη περὶ τὰ διάφορα, καὶ οὐκ ἀπολαμβάνων τὰ σκεύη παρ’ αὐτοῦ, προσῄειν πρός τε τοὺς ἀποστολέας καὶ τὴν βουλήν [καὶ τὸν δῆμον], λέγων ὅτι οὐκ ἀποδίδωσί μοι τὰ σκεύη ὁ Θεόφημος, ἃ ὦφλεν ἐν τῷ δικαστηρίῳ. προσῇσαν δὲ καὶ οἱ ἄλλοι τριήραρχοι τῇ βουλῇ, ὅσοι μὴ παρελάμβανον παρὰ τῶν ὀφειλόντων τὰ σκεύη. καὶ πολλῶν λόγων γενομένων ἀποκρίνεται ἡμῖν ἡ βουλὴ ψηφίσματι, ὃ ἀναγνώσεται ὑμῖν, εἰσπράττεσθαι τρόπῳ ᾧ ἂν δυνώμεθα.", "st": "47.33"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑ.", "st": "47.33"}, {"sp": "N", "t": "γενομένου τοίνυν τοῦ ψηφίσματος τούτου ἐν τῇ βουλῇ, καὶ οὐδενὸς γραφομένου παρανόμων, ἀλλὰ κυρίου ὄντος, προσελθὼν Εὐέργῳ τουτῳὶ τῷ ἀδελφῷ τοῦ Θεοφήμου, ἐπειδὴ τὸν Θεόφημον οὐχ οἷός τε ἦν ἰδεῖν, ἔχων τὸ ψήφισμα πρῶτον μὲν ἀπῄτησα τὰ σκεύη καὶ ἐκέλευσα αὐτὸν φράσαι τῷ Θεοφήμῳ, ἔπειτα διαλιπὼν ἡμέρας τινάς, ὡς οὐκ ἀπεδίδου τὰ σκεύη, ἀλλ’ ἐχλεύαζέ με, παραλαβὼν μάρτυρας ἠρόμην αὐτὸν πότερα νενεμημένος εἴη πρὸς τὸν ἀδελφὸν ἢ κοινὴ ἡ οὐσία εἴη αὐτοῖς.", "st": "47.34"}, {"sp": "N", "t": "ἀποκριναμένου δέ μοι Εὐέργου ὅτι νενεμημένος εἴη καὶ χωρὶς οἰκοίη ὁ Θεόφημος, αὐτὸς δὲ παρὰ τῷ πατρί, πυθόμενος οὗ ᾤκει ὁ Θεόφημος, λαβὼν παρὰ τῆς ἀρχῆς ὑπηρέτην ἦλθον ἐπὶ τὴν οἰκίαν τοῦ Θεοφήμου. καταλαβὼν δὲ αὐτὸν οὐκ ἔνδον ὄντα, ἐκέλευσα τὴν ἄνθρωπον τὴν ὑπακούσασαν μετελθεῖν αὐτὸν ὅπου εἴη, ταύτην ἣν μεμαρτυρήκασιν οὗτοι προκαλέσασθαι τὸν Θεόφημον παραδοῦναι, ἐγὼ δὲ ἐξαιτῶν οὐ δύναμαι παραλαβεῖν, ἵν’ ὑμεῖς τὴν ἀλήθειαν πύθησθε, ὁπότερος ἦρξεν χειρῶν ἀδίκων.", "st": "47.35"}, {"sp": "N", "t": "ὡς δὲ ἀφικνεῖται ὁ Θεόφημος μετελθούσης αὐτὸν τῆς ἀνθρώπου, ἀπῄτουν αὐτὸν τὸ διάγραμμα τῶν σκευῶν, λέγων ὅτι ἤδη περὶ ἀναγωγὴν εἴην, καὶ ἐδείκνυον τὸ ψήφισμα τῆς βουλῆς. ὡς δὲ ταῦτά μου λέγοντος οὐκ ἀπεδίδου, ἀλλὰ ἠπείλει καὶ ἐλοιδορεῖτο, ἐκέλευσα τὸν παῖδα καλέσαι εἴ τινας ἴδοι τῶν πολιτῶν παριόντας ἐκ τῆς ὁδοῦ, ἵνα μάρτυρές μοι εἴησαν τῶν λεγομένων,", "st": "47.36"}, {"sp": "N", "t": "καὶ ἠξίουν πάλιν τὸν Θεόφημον ἢ αὐτὸν ἀκολουθεῖν πρὸς τοὺς ἀποστολέας καὶ τὴν βουλήν, καὶ εἰ μή φησιν ὀφείλειν, ἐκείνους πείθειν τοὺς παραδόντας καὶ ἀναγκάζοντας εἰσπράττειν, ἢ ἀποδιδόναι τὰ σκεύη· εἰ δὲ μή, ἐνέχυρα ἔφην λήψεσθαι κατά τε τοὺς νόμους καὶ τὰ ψηφίσματα. οὐδὲν δ’ ἐθέλοντος αὐτοῦ τῶν δικαίων ποιεῖν, ἦγον τὴν ἄνθρωπον ἑστηκυῖαν ἐπὶ τῇ θύρᾳ, τὴν μετελθοῦσαν αὐτόν.", "st": "47.37"}, {"sp": "N", "t": "καὶ ὁ Θεόφημός με ἀφῃρεῖτο, καὶ ἐγὼ τὴν μὲν ἄνθρωπον ἀφῆκα, εἰς δὲ τὴν οἰκίαν εἰσῄειν, ἵνα ἐνέχυρόν τι λάβοιμι τῶν σκευῶν· ἔτυχεν γὰρ ἡ θύρα ἀνεῳγμένη, ὡς ἦλθεν ὁ Θεόφημος, καὶ ἔτι ἔμελλεν εἰσιέναι· καὶ ἐπεπύσμην αὐτὸν ὅτι οὐκ εἴη γεγαμηκώς. εἰσιόντος δέ μου παίει πὺξ ὁ Θεόφημος τὸ στόμα, καὶ ἐγὼ ἐπιμαρτυράμενος τοὺς παρόντας ἠμυνάμην.", "st": "47.38"}, {"sp": "N", "t": "ὡς οὖν ἀληθῆ λέγω, καὶ ἦρξεν χειρῶν ἀδίκων ὁ Θεόφημος, οὐκ ἄλλοθεν δεῖν οἶμαι τὸν ἔλεγχον γενέσθαι ἢ ἐκ τῆς ἀνθρώπου, ἣν μεμαρτυρήκασιν οὗτοι οἱ μάρτυρες ὡς ἤθελεν ὁ Θεόφημος παραδιδόναι. ταύτῃ δὲ τῇ μαρτυρίᾳ πρότερος εἰσελθὼν εἰς τὸ δικαστήριον, οὐ παραγραφομένου ἐμοῦ οὐδ’ ὑπομνυμένου διὰ τὸ καὶ πρότερόν ποτε ἐφ’ ἑτέρας δίκης ταῦτά με βλάψαι, ἐξηπάτησεν τοὺς δικαστὰς λέγων, οὓς μὲν ἐγὼ παρειχόμην μάρτυρας, τὰ ψευδῆ μαρτυρεῖν, τὴν δὲ ἄνθρωπον ἐρεῖν τὰς ἀληθείας βασανιζομένην.", "st": "47.39"}, {"sp": "N", "t": "οἷς δὲ τότε κατεχρῶντο λόγοις, νῦν αὐτοῖς ἐξελέγχονται ὑπεναντία ποιοῦντες· τὴν γὰρ ἄνθρωπον οὐ δύναμαι παραλαβεῖν πολλάκις ἐξαιτήσας, ὡς μεμαρτύρηται ὑμῖν. ἐπειδὴ τοίνυν τὴν ἄνθρωπον οὐ παραδιδόασιν, ἣν αὐτοὶ ἔφασαν προκαλέσασθαι, βούλομαι ὑμῖν καὶ τοὺς μάρτυρας παρασχέσθαι, οἳ εἶδόν με πρότερον πληγέντα ὑπὸ τοῦ Θεοφήμου (ἡ δὲ αἴκεια τοῦτ’ ἔστιν, ὃς ἂν ἄρξῃ χειρῶν ἀδίκων πρότερος) ἄλλως τε καὶ κατὰ τὸν νόμον καὶ κατὰ τὰ ψηφίσματα τὰ ὑμέτερα εἰσπράττοντα. καί μοι ἀνάγνωθι τὰ ψηφίσματα καὶ τὴν μαρτυρίαν.", "st": "47.40"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑΤΑ. ΜΑΡΤΥΡΙΑ.", "st": "47.40"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν ἀφῃρέθην τὰ ἐνέχυρα ὑπὸ τοῦ Θεοφήμου καὶ συνεκόπην, ἐλθὼν εἰς τὴν βουλὴν τάς τε πληγὰς ἔδειξα καὶ ἃ πεπονθὼς ἦν εἶπον, καὶ ὅτι εἰσπράττων τῇ πόλει τὰ σκεύη. ἀγανακτήσασα δ’ ἡ βουλὴ ἐφ’ οἷς ἐγὼ ἐπεπόνθειν, καὶ ἰδοῦσά με ὡς διεκείμην, καὶ ἡγησαμένη ὑβρίσθαι οὐκ ἐμέ, ἀλλ’ ἑαυτὴν καὶ τὸν δῆμον τὸν ψηφισάμενον καὶ τὸν νόμον τὸν ἀναγκάσαντα εἰσπράττειν τὰ σκεύη,", "st": "47.41"}, {"sp": "N", "t": "ἐκέλευεν εἰσαγγέλλειν με, καὶ τοὺς πρυτάνεις προγράφειν αὐτῷ τὴν κρίσιν ἐπὶ δύο ἡμέρας ὡς ἀδικοῦντι καὶ διακωλύοντι τὸν ἀπόστολον, διότι τὰ σκεύη οὐκ ἀπεδίδου καὶ τὰ ἐνέχυρα ἀφείλετο καὶ ἐμὲ συνέκοψεν τὸν εἰσπράττοντα καὶ ὑπηρετοῦντα τῇ πόλει. γενομένης τοίνυν τῆς κρίσεως τῷ Θεοφήμῳ ἐν τῇ βουλῇ κατὰ τὴν εἰσαγγελίαν ἣν ἐγὼ εἰσήγγειλα, καὶ ἀποδοθέντος λόγου ἑκατέρῳ, καὶ κρύβδην διαψηφισαμένων τῶν βουλευτῶν, ἑάλω ἐν τῷ βουλευτηρίῳ καὶ ἔδοξεν ἀδικεῖν.", "st": "47.42"}, {"sp": "N", "t": "καὶ ἐπειδὴ ἐν τῷ διαχειροτονεῖν ἦν ἡ βουλὴ πότερα δικαστηρίῳ παραδοίη ἢ ζημιώσειε ταῖς πεντακοσίαις, ὅσου ἦν κυρία κατὰ τὸν νόμον, δεομένων τούτων ἁπάντων καὶ ἱκετευόντων καὶ τίνα οὐ προσπεμπόντων; καὶ τὸ διάγραμμα τῶν σκευῶν ἀποδιδόντων εὐθὺς ἐν τῇ βουλῇ, καὶ περὶ τῶν πληγῶν φασκόντων ἐπιτρέψειν ᾧ ἂν κελεύσω Ἀθηναίων, συνεχώρησα ὥστε τῷ Θεοφήμῳ πέντε καὶ εἴκοσι δραχμῶν προστιμηθῆναι.", "st": "47.43"}, {"sp": "N", "t": "καὶ ταῦτα ὡς ἀληθῆ λέγω, ὑμῶν τε δέομαι ὅσοι ἐβούλευον ἐπ’ Ἀγαθοκλέους ἄρχοντος φράζειν τοῖς παρακαθημένοις, καὶ ὅσους ἐδυνάμην ἐγὼ ἐξευρεῖν τῶν τότε βουλευόντων, μάρτυρας ὑμῖν παρέξομαι.", "st": "47.44"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "47.44"}, {"sp": "N", "t": "ἐγὼ μὲν τοίνυν οὕτως, ὦ ἄνδρες δικασταί, ἐπιεικὴς ἐγενόμην πρὸς τούτους. καίτοι τό γε ψήφισμα δημοσίαν τὴν οὐσίαν ἐκέλευσεν εἶναι, οὐ μόνον ὃς ἂν ἔχων σκεύη μὴ ἀποδιδῷ τῇ πόλει, ἀλλὰ καὶ ὃς ἂν ἰδίᾳ κτησάμενος μὴ πωλῇ· τοιαύτη γὰρ ἡ ἀπορία οὖσα συνέβαινεν τότε ἐν τῇ πόλει σκευῶν. καί μοι ἀνάγνωθι τὸ ψήφισμα.", "st": "47.44"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑ.", "st": "47.44"}, {"sp": "N", "t": "καταπλεύσας τοίνυν, ὦ ἄνδρες δικασταί, ὡς οὐδενὶ ἤθελεν ἐπιτρέπειν ὁ Θεόφημος περὶ τῶν πληγῶν ὧν τότε ἔλαβον ὑπ’ αὐτοῦ, προσεκαλεσάμην αὐτὸν καὶ ἔλαχον αὐτῷ δίκην τῆς αἰκείας. ἀντιπροσκαλεσαμένου δὲ κἀκείνου ἐμὲ καὶ διαιτητῶν ἐχόντων τὰς δίκας, ἐπειδὴ ἡ ἀπόφασις ἦν τῆς δίκης, ὁ μὲν Θεόφημος παρεγράφετο καὶ ὑπώμνυτο, ἐγὼ δὲ πιστεύων ἐμαυτῷ μηδὲν ἀδικεῖν εἰσῄειν εἰς ὑμᾶς.", "st": "47.45"}, {"sp": "N", "t": "παρασχόμενος δὲ ἐκεῖνος ταύτην τὴν μαρτυρίαν, ἣν ἄλλος μὲν οὐδεὶς μεμαρτύρηκεν, ὁ δὲ ἀδελφὸς καὶ ὁ κηδεστής, ὡς ἐθέλοι τὴν ἄνθρωπον παραδοῦναι, καὶ προσποιούμενος ἄκακος εἶναι, ἐξηπάτησεν τοὺς δικαστάς. δέομαι δὲ ὑμῶν νυνὶ δικαίαν δέησιν, ἅμα μὲν δικάσαι περὶ τῆς μαρτυρίας, πότερα ψευδής ἐστιν ἢ ἀληθής, ἅμα δὲ περὶ τοῦ πράγματος ἐξ ἀρχῆς σκέψασθαι.", "st": "47.46"}, {"sp": "N", "t": "ἐγὼ μὲν τοίνυν, εἰς ἃ οὗτος κατέφυγεν τότε δίκαια, ἐκ τούτων οἴομαι δεῖν τὸν ἔλεγχον γενέσθαι, ἐκ τῆς ἀνθρώπου βασανιζομένης, ὁπότερος ἦρξεν χειρῶν ἀδίκων· τοῦτο γάρ ἐστιν ἡ αἴκεια. καὶ τοὺς μάρτυρας διὰ τοῦτο διώκω τῶν ψευδομαρτυρίων, ὅτι ἐμαρτύρησαν ἐθέλειν παραδιδόναι τὸν Θεόφημον τὴν ἄνθρωπον, οὐδαμοῦ τὸ σῶμα παραδιδόντος οὔτε τότε πρὸς τῷ διαιτητῇ οὔτε ὕστερον, πολλάκις ἐμοῦ ἐξαιτήσαντος.", "st": "47.47"}, {"sp": "N", "t": "διπλῆν οὖν αὐτοὺς δεῖ δίκην δοῦναι, ὅτι τε ἐξηπάτησαν τοὺς δικαστὰς ψευδεῖς μαρτυρίας παρασχόμενοι, κηδεστοῦ καὶ ἀδελφοῦ, καὶ ὅτι ἐμὲ ἠδίκησαν, λῃτουργοῦντα μὲν ὑμῖν προθύμως, ποιοῦντα δὲ τὰ προσταττόμενα, ὑπηρετοῦντα δὲ τοῖς νόμοις καὶ τοῖς ψηφίσμασιν τοῖς ὑμετέροις. ὡς δὲ οὐκ ἐγὼ μόνος παρέλαβον παρὰ τῆς ἀρχῆς τοῦτον εἰσπράξασθαι σκεύη ὀφείλοντα τῇ πόλει, ἀλλὰ καὶ ἄλλοι τῶν τριηράρχων ἑτέρους εἰσεπράξαντο οὓς παρέλαβον, ἀνάγνωθί μοι αὐτῶν τὰς μαρτυρίας.", "st": "47.48"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "47.48"}, {"sp": "N", "t": "βούλομαι τοίνυν, ὦ ἄνδρες δικασταί, καὶ ἃ πέπονθα ὑπ’ αὐτῶν διηγήσασθαι ὑμῖν. ἐπειδὴ γὰρ ὦφλον αὐτοῖς τὴν δίκην ἐφ’ ᾗ τοὺς μάρτυρας τούτους διώκω τὰ ψευδῆ μεμαρτυρηκότας, προσελθὼν τῷ Θεοφήμῳ μελλούσης μοι ἤδη ἐξήκειν τῆς ὑπερημερίας, ἐδεήθην αὐτοῦ ἐπισχεῖν μοι ὀλίγον χρόνον, λέγων τὰς ἀληθείας, ὅτι πεπορισμένου τοῦ ἀργυρίου ὃ ἔμελλον αὐτῷ ἐκτίνειν συμβέβηκέ μοι τριηραρχία,", "st": "47.49"}, {"sp": "N", "t": "καὶ ἀποστέλλειν διὰ τάχους δεῖ τὴν τριήρη, καὶ ὁ στρατηγὸς Ἀλκίμαχος αὑτῷ παρασκευάζειν κελεύοι ταύτην τὴν ναῦν· τὸ οὖν ἀργύριον τὸ πεπορισμένον τῷ Θεοφήμῳ ἀποδοῦναι ἐνταῦθα κατεχρησάμην. ἐδεόμην δ’ αὐτοῦ ἀναβαλέσθαι τὴν ὑπερημερίαν, ἕως ἂν τὴν ναῦν ἀποστείλω. ὁ δὲ ῥᾳδίως μοι καὶ ἀκάκως ἀποκρίνεται· “οὐδὲν κωλύει”, ἔφη· “ἀλλ’ ἐπειδὰν τὴν ναῦν ἀποστείλῃς, πόριζε καὶ ἐμοί.”", "st": "47.50"}, {"sp": "N", "t": "ἀποκριναμένου δέ μοι ταῦτα τοῦ Θεοφήμου καὶ ἀναβαλομένου τὴν ὑπερημερίαν, καὶ μάλιστά μου πιστεύσαντος τῇ τε ἐπισκήψει τῶν ψευδομαρτυρίων καὶ τῷ μὴ ἐθέλειν αὐτὸν παραδοῦναι τὴν ἄνθρωπον, ὡς οὐδὲν ἂν νεωτερίσαντος περὶ τἀμά, ἐγὼ μὲν τὴν τριήρη ἀποστείλας, οὐ πολλαῖς ἡμέραις ὕστερον πορίσας τὸ ἀργύριον, προσελθὼν αὐτῷ ἐκέλευον ἐπὶ τὴν τράπεζαν ἀκολουθοῦντα κομίζεσθαι τὴν καταδίκην. ὡς δὲ ταῦτα ἀληθῆ λέγω, τούτων ὑμῖν ἀναγνώσεται τὰς μαρτυρίας.", "st": "47.51"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "47.51"}, {"sp": "N", "t": "ὁ δὲ Θεόφημος ἀντὶ τοῦ τὴν καταδίκην ἀπολαβεῖν ἀκολουθήσας ἐπὶ τὴν τράπεζαν, ἐλθών μου τὰ πρόβατα λαμβάνει ποιμαινόμενα πεντήκοντα μαλακὰ καὶ τὸν ποιμένα μετ’ αὐτῶν καὶ πάντα τὰ ἀκόλουθα τῇ ποίμνῃ, ἔπειτα παῖδα διάκονον ὑδρίαν χαλκῆν ἀποφέροντα ἀλλοτρίαν ᾐτημένην, πολλοῦ ἀξίαν. καὶ ταῦτα ἔχουσιν οὐκ ἐξήρκεσεν αὐτοῖς·", "st": "47.52"}, {"sp": "N", "t": "ἀλλ’ ἐπεισελθόντες εἰς τὸ χωρίον (γεωργῶ δὲ πρὸς τῷ ἱπποδρόμῳ, καὶ οἰκῶ ἐνταῦθα ἐκ μειρακίου) πρῶτον μὲν ἐπὶ τοὺς οἰκέτας ᾖξαν, ὡς δὲ οὗτοι διαφεύγουσιν αὐτοὺς καὶ ἄλλος ἄλλῃ ἀπεχώρησαν, ἐλθόντες πρὸς τὴν οἰκίαν καὶ ἐκβαλόντες τὴν θύραν τὴν εἰς τὸν κῆπον φέρουσαν Εὔεργός τε οὑτοσὶ ὁ ἀδελφὸς ὁ Θεοφήμου καὶ Μνησίβουλος ὁ κηδεστὴς αὐτοῦ, οἷς οὐδεμίαν δίκην ὠφλήκειν οὐδὲ προσῆκεν αὐτοὺς ἅπτεσθαι τῶν ἐμῶν οὐδενός, εἰσελθόντες ἐπὶ τὴν γυναῖκά μου καὶ τὰ παιδία ἐξεφορήσαντο ὅσα ἔτι ὑπόλοιπά μοι ἦν σκεύη ἐν τῇ οἰκίᾳ.", "st": "47.53"}, {"sp": "N", "t": "ᾤοντο μὲν γὰρ οὐ τοσαῦτα μόνον λήψεσθαι, ἀλλὰ πολλῷ πλείω· τὴν γὰρ οὖσάν μοι ποτὲ κατασκευὴν τῆς οἰκίας καταλήψεσθαι· ἀλλ’ ὑπὸ τῶν λῃτουργιῶν καὶ τῶν εἰσφορῶν καὶ τῆς πρὸς ὑμᾶς φιλοτιμίας τὰ μὲν ἐνέχυρα κεῖται αὐτῶν, τὰ δὲ πέπραται. ὅσα δ’ ἦν ἔτι ὑπόλοιπα, πάντα λαβόντες ᾤχοντο.", "st": "47.54"}, {"sp": "N", "t": "πρὸς δὲ τούτοις, ὦ ἄνδρες δικασταί, ἔτυχεν ἡ γυνή μου μετὰ τῶν παιδίων ἀριστῶσα ἐν τῇ αὐλῇ, καὶ μετ’ αὐτῆς τιτθή τις ἐμὴ γενομένη πρεσβυτέρα, ἄνθρωπος εὔνους καὶ πιστὴ καὶ ἀφειμένη ἐλευθέρα ὑπὸ τοῦ πατρὸς τοῦ ἐμοῦ. συνῴκησεν δὲ ἀνδρί, ἐπειδὴ ἀφείθη ἐλευθέρα· ὡς δὲ οὗτος ἀπέθανεν καὶ αὐτὴ γραῦς ἦν καὶ οὐκ ἦν αὐτὴν ὁ θρέψων, ἐπανῆκεν ὡς ἐμέ.", "st": "47.55"}, {"sp": "N", "t": "ἀναγκαῖον οὖν ἦν μὴ περιιδεῖν ἐνδεεῖς ὄντας μήτε τιτθὴν γενομένην μήτε παιδαγωγόν· ἅμα δὲ καὶ τριηραρχῶν ἐξέπλεον, ὥστε καὶ τῇ γυναικὶ βουλομένῃ ἦν τοιαύτην οἰκουρὸν μετ’ αὐτῆς με καταλιπεῖν. ἀριστώντων δὲ ἐν τῇ αὐλῇ, ὡς ἐπεισπηδῶσιν οὗτοι καὶ καταλαμβάνουσιν αὐτὰς καὶ ἥρπαζον τὰ σκεύη, αἱ μὲν ἄλλαι θεράπαιναι (ἐν τῷ πύργῳ γὰρ ἦσαν, οὗπερ διαιτῶνται) ὡς ἤκουσαν κραυγῆς, κλείουσι τὸν πύργον, καὶ ἐνταῦθα μὲν οὐκ εἰσῆλθον, τὰ δ’ ἐκ τῆς ἄλλης οἰκίας ἐξέφερον σκεύη,", "st": "47.56"}, {"sp": "N", "t": "ἀπαγορευούσης τῆς γυναικὸς μὴ ἅπτεσθαι αὐτοῖς, καὶ λεγούσης ὅτι αὑτῆς εἴη ἐν τῇ προικὶ τετιμημένα καὶ ὅτι “τὰ πρόβατα ἔχετε πεντήκοντα καὶ τὸν παῖδα καὶ τὸν ποιμένα, πλείονος ἄξια ἢ κατεδικάσασθε·” ἀπήγγειλε γάρ τις αὐτοῖς τῶν γειτόνων κόψας τὴν θύραν. ἔτι δὲ ἔφη τὸ ἀργύριον αὐτοῖς κείμενον εἶναι ἐπὶ τῇ τραπέζῃ· ἠκηκόει γὰρ ἐμοῦ· “κἂν περιμείνητε”, ἔφη, “ἢ μετέλθῃ τις ὑμῶν αὐτόν, ἔχοντες ἄπιτε τὸ ἀργύριον ἤδη· τὰ δὲ σκεύη ἐᾶτε, καὶ μηδὲν τῶν ἐμῶν φέρετε, ἄλλως τε καὶ ἔχοντες ἄξια τῆς καταδίκης.”", "st": "47.57"}, {"sp": "N", "t": "ταῦτα δὲ λεγούσης τῆς γυναικὸς οὐχ ὅπως ἐπέσχον, ἀλλὰ καὶ τῆς τιτθῆς τὸ κυμβίον λαβούσης παρακείμενον αὐτῇ, ἐξ οὗ ἔπινεν, καὶ ἐνθεμένης εἰς τὸν κόλπον, ἵνα μὴ οὗτοι λάβοιεν, ἐπειδὴ εἶδεν ἔνδον ὄντας αὐτούς, κατιδόντες αὐτὴν οὕτω διέθεσαν ἀφαιρούμενοι τὸ κυμβίον Θεόφημος καὶ Εὔεργος ἁδελφὸς αὐτοῦ οὑτοσί,", "st": "47.58"}, {"sp": "N", "t": "ὥστε ὕφαιμοι μὲν οἱ βραχίονες καὶ οἱ καρποὶ τῶν χειρῶν αὐτῆς ἐγένοντο ἀποστρεφομένης τὼ χεῖρε καὶ ἑλκομένης ὑπὸ τούτων ἀφαιρουμένων τὸ κυμβίον, ἀμυχὰς δ’ ἐν τῷ τραχήλῳ εἶχεν ἀγχομένη, πελιὸν δὲ τὸ στῆθος. εἰς τοῦτο δ’ ἦλθον πονηρίας ὥστε, ἕως ἀφείλοντο τὸ κυμβίον ἐκ τοῦ κόλπου αὐτῆς, οὐκ ἐπαύσαντο ἄγχοντες καὶ τύπτοντες τὴν γραῦν.", "st": "47.59"}, {"sp": "N", "t": "ἀκούοντες δὲ οἱ θεράποντες τῶν γειτόνων τῆς κραυγῆς καὶ ὁρῶντες τὴν οἰκίαν πορθουμένην τὴν ἐμήν, οἱ μὲν ἀπὸ τῶν τεγῶν τῶν ἑαυτῶν ἐκαλίστρουν τοὺς παριόντας, οἱ δὲ καὶ εἰς τὴν ἑτέραν ὁδὸν ἐλθόντες καὶ ἰδόντες Ἁγνόφιλον παριόντα ἐκέλευσαν παραγενέσθαι. προσελθὼν δὲ ὁ Ἁγνόφιλος προσκληθεὶς ὑπὸ τοῦ θεράποντος τοῦ Ἀνθεμίωνος, ὅς ἐστί μοι γείτων, εἰς μὲν τὴν οἰκίαν οὐκ εἰσῆλθεν (οὐ γὰρ ἡγεῖτο δίκαιον εἶναι μὴ παρόντος γε τοῦ κυρίου), ἐν δὲ τῷ τοῦ Ἀνθεμίωνος χωρίῳ ὢν ἑώρα τά τε σκεύη ἐκφερόμενα καὶ Εὔεργον καὶ Θεόφημον ἐξιόντας ἐκ τῆς ἐμῆς οἰκίας.", "st": "47.60"}, {"sp": "N", "t": "οὐ μόνον τοίνυν, ὦ ἄνδρες δικασταί, λαβόντες μου τὰ σκεύη ᾤχοντο, ἀλλὰ καὶ τὸν υἱὸν ἦγον ὡς οἰκέτην, ἕως τῶν γειτόνων ἀπαντήσας αὐτοῖς Ἑρμογένης εἶπεν ὅτι υἱός μου εἴη. ὡς δὲ ταῦτα ἀληθῆ λέγω, ἀναγνώσεται ὑμῖν τὰς μαρτυρίας.", "st": "47.61"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "47.61"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν μοι ἀπηγγέλθη εἰς Πειραιᾶ τὰ γεγενημένα ὑπὸ τῶν γειτόνων, ἐλθὼν εἰς ἀγρὸν τούτους μὲν οὐκέτι καταλαμβάνω, ἰδὼν δὲ τὰ ἐκ τῆς οἰκίας ἐκπεφορημένα καὶ τὴν γραῦν ὡς διέκειτο, καὶ ἀκούων τῆς γυναικὸς τὰ γενόμενα, προσελθὼν τῷ Θεοφήμῳ τῇ ὑστεραίᾳ ἕωθεν ἐν τῇ πόλει μάρτυρας ἔχων ἐκέλευον αὐτὸν πρῶτον μὲν τὴν καταδίκην ἀπολαμβάνειν καὶ ἀκολουθεῖν ἐπὶ τὴν τράπεζαν, ἔπειτα τὴν ἄνθρωπον θεραπεύειν ἣν συνέκοψαν, καὶ ἰατρὸν εἰσάγειν ὃν αὐτοὶ βούλοιντο.", "st": "47.62"}, {"sp": "N", "t": "ταῦτα δέ μου λέγοντος καὶ διαμαρτυρομένου, κακά με πολλὰ εἰπόντες ὁ μὲν Θεόφημος ἠκολούθει μόλις, διατριβὰς ἐμποιῶν καὶ φάσκων βούλεσθαι καὶ αὐτός τινας παραλαβεῖν μάρτυρας (ταῦτα δ’ ἔλεγεν τεχνάζων τοῦ χρόνον ἐγγενέσθαι), ὁ δ’ Εὔεργος οὑτοσὶ εὐθὺς ἐκ τῆς πόλεως μεθ’ ἑτέρων ὁμοίων αὑτῷ ἐλθὼν εἰς ἀγρόν, τὰ ὑπόλοιπα σκεύη, εἴ τινα τῇ προτεραίᾳ ἐν τῷ πύργῳ ἦν καὶ οὐκ ἔτυχεν ἔξω ὄντα, ἐπειδὴ δ’ ἐγὼ ἦλθον, διὰ τὴν χρείαν κατηνέχθη, ἐκβαλὼν τὴν θύραν ἥνπερ καὶ τῇ προτεραίᾳ ἐξέβαλον κακῶς ἐνεστηκυῖαν, ᾤχετό μου λαβὼν τὰ σκεύη· ᾧ οὔτε δίκην ὠφλήκειν, οὔτε συμβόλαιον ἦν μοι πρὸς αὐτὸν οὐδέν.", "st": "47.63"}, {"sp": "N", "t": "ἐκτίνοντος δέ μου τῷ Θεοφήμῳ, ᾧ ὠφλήκειν τὴν δίκην, ἐπειδὴ ἐξέτινον πολλῶν παρόντων μαρτύρων χιλίας μὲν καὶ ἑκατὸν δραχμὰς ⟨τὴν καταδίκην, ὀγδοήκοντα δὲ καὶ ἑκατὸν δραχμὰς⟩ καὶ τρεῖς καὶ δύ’ ὀβολὼ τὴν ἐπωβελίαν, τριάκοντα δὲ τὰ πρυτανεῖα (τῶν γὰρ ἄλλων οὐδὲν αὐτῷ ἐπιτιμίων ὦφλον), λαβὼν τοίνυν παρ’ ἐμοῦ ἐπὶ τῇ τραπέζῃ χιλίας τριακοσίας δέκα τρεῖς δύ’ ὀβολὼ τὸ σύμπαν κεφάλαιον, ἀπαιτοῦντος ἐμοῦ τά τε πρόβατα καὶ τὰ ἀνδράποδα καὶ τὰ σκεύη ἃ ἡρπάκει μου, οὐκ ἔφη ἀποδώσειν μοι, εἰ μή τις αὐτὸν ἀφήσει καὶ τοὺς μετ’ αὐτοῦ τῶν ἐγκλημάτων καὶ τοὺς μάρτυρας τῶν ψευδομαρτυρίων.", "st": "47.64"}, {"sp": "N", "t": "ταῦτα δὲ ἀποκριναμένου αὐτοῦ μάρτυρας μὲν ἐποιησάμην τῆς ἀποκρίσεως τοὺς παρόντας, τὴν δὲ δίκην ἐξέτεισα, ὑπερήμερον γὰρ οὐκ ᾤμην δεῖν ἐμαυτὸν εἶναι. τὸν δ’ Εὔεργον οὐδ’ ᾔδειν εἰσεληλυθότα μου εἰς τὴν οἰκίαν ταύτῃ τῇ ἡμέρᾳ, ἀλλ’ αὐτίκα ἡ δίκη ἐξετέτειστο, καὶ εἶχεν ὁ Θεόφημος τά τε πρόβατα καὶ τὰ ἀνδράποδα καὶ τὰ σκεύη τὰ τῇ προτεραίᾳ περιγενόμενα, καὶ ἄγγελος ἦλθέ μοι λιθοκόπος τις, τὸ πλησίον μνῆμα ἐργαζόμενος, ὅτι πάλιν οἴχεται Εὔεργος τὰ ὑπόλοιπα σκεύη ἐκφορήσας ἐκ τῆς οἰκίας· πρὸς ὃν οὐδέν μοι πρᾶγμα ἦν.", "st": "47.65"}, {"sp": "N", "t": "ὡς οὖν ἀληθῆ λέγω, καὶ ὅτι τῇ μὲν προτεραίᾳ εἰλήφεσάν μου τὰ ἐνέχυρα, τῇ δ’ ὑστεραίᾳ ἐκομίσαντο τὸ ἀργύριον παρ’ ἐμοῦ (καίτοι πῶς ἄν, εἰ μὴ πεπορισμένον τε ἦν καὶ ἐπηγγέλκειν αὐτοῖς, εὐθὺς ἂν ἀπέλαβον;) καὶ πάλιν αὐθημερὸν εἰσεληλύθεσαν εἰς τὴν οἰκίαν ἐκτίνοντος τὴν δίκην, τούτων ὑμῖν ἀναγνώσεται τὰς μαρτυρίας.", "st": "47.66"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "47.66"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν, ὦ ἄνδρες δικασταί, ἐπαγγείλαντός μου αὐτῷ θεραπεύειν τὴν ἄνθρωπον ἣν συνέκοψαν καὶ ἰατρὸν εἰσάγειν οὐκ ἐφρόντιζον, ἐγὼ αὐτὸς εἰσήγαγον ἰατρὸν ᾧ πολλὰ ἔτη ἐχρώμην, ὃς ἐθεράπευεν αὐτὴν ἀρρωστοῦσαν, καὶ ἐπέδειξα ὡς εἶχεν, εἰσαγαγὼν μάρτυρας. ἀκούσας δὲ τοῦ ἰατροῦ ὅτι οὐδὲν ἔτι εἴη ἡ ἄνθρωπος, πάλιν ἑτέρους μάρτυρας παραλαβὼν τήν τε ἄνθρωπον ἐπέδειξα ὡς εἶχεν, καὶ ἐπήγγειλα τούτοις θεραπεύειν. ἕκτῃ τοίνυν ἡμέρᾳ ὕστερον ἢ οὗτοι εἰσῆλθον εἰς τὴν οἰκίαν, ἐτελεύτησεν ἡ τιτθή. ὡς δὲ ἀληθῆ ταῦτα λέγω, τούτων ὑμῖν ἀναγνώσεται τὰς μαρτυρίας.", "st": "47.67"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "47.67"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν ἐτελεύτησεν, ἦλθον ὡς τοὺς ἐξηγητάς, ἵνα εἰδείην ὅ τι με χρὴ ποιεῖν περὶ τούτων, καὶ διηγησάμην αὐτοῖς ἅπαντα τὰ γενόμενα, τήν τε ἄφιξιν τὴν τούτων καὶ τὴν εὔνοιαν τῆς ἀνθρώπου, καὶ ὡς εἶχον αὐτὴν ἐν τῇ οἰκίᾳ, καὶ ὡς διὰ τὸ κυμβίον, οὐκ ἀφιεῖσα, τελευτήσειεν. ἀκούσαντες δέ μου οἱ ἐξηγηταὶ ταῦτα, ἤροντό με πότερον ἐξηγήσωνταί μοι μόνον ἢ καὶ συμβουλεύσωσιν·", "st": "47.68"}, {"sp": "N", "t": "ἀποκριναμένου δέ μου αὐτοῖς ἀμφότερα, εἶπόν μοι “ἡμεῖς τοίνυν σοι τὰ μὲν νόμιμα ἐξηγησόμεθα, τὰ δὲ σύμφορα παραινέσομεν· πρῶτον μὲν ἐπενεγκεῖν δόρυ ἐπὶ τῇ ἐκφορᾷ, καὶ προαγορεύειν ἐπὶ τῷ μνήματι, εἴ τις προσήκων ἐστὶν τῆς ἀνθρώπου, ἔπειτα τὸ μνῆμα φυλάττειν ἐπὶ τρεῖς ἡμέρας. τάδε δὲ συμβουλεύομέν σοι, ἐπειδὴ αὐτὸς μὲν οὐ παρεγένου, ἡ δὲ γυνὴ καὶ τὰ παιδία, ἄλλοι δέ σοι μάρτυρες οὐκ εἰσίν, ὀνομαστὶ μὲν μηδενὶ προαγορεύειν, τοῖς δεδρακόσι δὲ καὶ κτείνασιν, εἶτα πρὸς τὸν βασιλέα μὴ λαγχάνειν.”", "st": "47.69"}, {"sp": "N", "t": "“οὐδὲ γὰρ ἐν τῷ νόμῳ ἔστι σοι· οὐ γάρ ἐστιν ἐν γένει σοι ἡ ἄνθρωπος, οὐδὲ θεράπαινα, ἐξ ὧν σὺ λέγεις· οἱ δὲ νόμοι τούτων κελεύουσιν τὴν δίωξιν εἶναι· ὥστ’ εἰ διομεῖ ἐπὶ Παλλαδίῳ αὐτὸς καὶ ἡ γυνὴ καὶ τὰ παιδία καὶ καταράσεσθε αὑτοῖς καὶ τῇ οἰκίᾳ, χείρων τε δόξεις πολλοῖς εἶναι, καὶ ἐὰν μὲν ἀποφύγῃ σε, ἐπιωρκηκέναι, ἐὰν δὲ ἕλῃς, φθονήσει. ἀλλ’ ὑπὲρ σεαυτοῦ καὶ τῆς οἰκίας ἀφοσιωσάμενος ὡς ῥᾷστα τὴν συμφορὰν φέρειν, ἄλλῃ δὲ εἴ πῃ βούλει, τιμωροῦ.”", "st": "47.70"}, {"sp": "N", "t": "ταῦτα ἀκούσας ἐγὼ τῶν ἐξηγητῶν, καὶ τοὺς νόμους ἐπισκεψάμενος τοὺς τοῦ Δράκοντος ἐκ τῆς στήλης, ἐβουλευόμην μετὰ τῶν φίλων ὅ τι χρή με ποιεῖν. συμβουλευόντων δέ μοι ταὐτά, ἃ μὲν ὑπὲρ τῆς οἰκίας προσῆκεν μοι πρᾶξαι καὶ ἃ ἐξηγήσαντό μοι οἱ ἐξηγηταί, ἐποίησα, ἃ δ’ ἐκ τῶν νόμων οὐκέτι μοι προσῆκεν, ἡσυχίαν εἶχον.", "st": "47.71"}, {"sp": "N", "t": "κελεύει γὰρ ὁ νόμος, ὦ ἄνδρες δικασταί, τοὺς προσήκοντας ἐπεξιέναι μέχρι ἀνεψιαδῶν (καὶ ἐν τῷ ὅρκῳ διορίζεται ὅ τι προσήκων ἐστίν), κἂν οἰκέτης ᾖ, τούτων τὰς ἐπισκήψεις εἶναι. ἐμοὶ δὲ οὔτε γένει προσῆκεν ἡ ἄνθρωπος οὐδέν, εἰ μὴ ὅσον τιτθὴ γενομένη, οὐδ’ αὖ θεράπαινά γε· ἀφεῖτο γὰρ ὑπὸ τοῦ πατρὸς τοῦ ἐμοῦ ἐλευθέρα καὶ χωρὶς ᾤκει καὶ ἄνδρα ἔσχεν.", "st": "47.72"}, {"sp": "N", "t": "ψεύσασθαι δὲ πρὸς ὑμᾶς καὶ διομόσασθαι αὐτὸς καὶ τὸν υἱὸν καὶ τὴν γυναῖκα οὐκ ἂν ἐτόλμησα, οὐδ’ ἂν εἰ εὖ ᾔδειν ὅτι αἱρήσοιμι αὐτούς· οὐ γὰρ οὕτως τούτους μισῶ, ὡς ἐμαυτὸν φιλῶ. ἵνα δὲ μὴ λόγῳ μόνον ἀκούσητέ μου, αὐτὸν ὑμῖν τὸν νόμον ἀναγνώσομαι.", "st": "47.73"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "47.73"}, {"sp": "N", "t": "πολλαχόθεν μὲν οὖν οἶμαι, ὦ ἄνδρες δικασταί, καταφανῆ ὑμῖν τὴν μαρτυρίαν εἶναι ὡς ψευδής ἐστιν, οὐχ ἥκιστα δ’ ἐκ τῶν πεπραγμένων αὐτοῖς ῥᾴδιον γνῶναι. οὗτοι γὰρ ᾤοντο, ὦ ἄνδρες δικασταί, ἐμέ, εἰ πολλά μου λάβοιεν ἐνέχυρα, ἅσμενον ἀφήσειν με τοὺς μάρτυρας τῶν ψευδομαρτυρίων, ὥστε ἀπολαβεῖν με τὰ ἐνέχυρα.", "st": "47.74"}, {"sp": "N", "t": "καὶ ἐπειδὴ ἐδεήθην αὐτοῦ ἀναβαλέσθαι μοι τὴν ὑπερημερίαν, ἅσμενος ἤκουσεν, ἵνα ὑπερήμερος αὐτῷ γενοίμην καὶ ἐκφορήσαιτό μου ὡς πλεῖστα. καὶ διὰ τοῦτο ἀκάκως καὶ ταχύ μοι ὡμολόγησεν, ἵνα πιθανὸς γένηται καὶ μὴ καταφανὴς ἐπιβουλεύων, ἡγούμενος οὐκ εἶναι αὑτῷ δι’ ἄλλου τρόπου τοὺς μάρτυρας ἀφεθῆναι τῶν ψευδομαρτυρίων ἢ διὰ τοῦ ἐξαπατῆσαι καὶ λαβεῖν με ὑπερήμερον καὶ ἐκφορήσασθαι ὡς πλεῖστα· οὐ γὰρ ὅσα ἔχουσί μου ᾤετο λήψεσθαι, ἀλλὰ πολλῷ πλείω.", "st": "47.75"}, {"sp": "N", "t": "καὶ τὸν μὲν ἄλλον χρόνον ἀνέμενεν ὡς οὐ διὰ ταχέων με ποριοῦντα αὐτῷ τὸ ἀργύριον, βουλόμενος ὑπ’ αὐτοὺς τοὺς ἀγῶνας τῶν ψευδομαρτυρίων τὴν ἐνεχυρασίαν μου ποιήσασθαι· ἐπειδὴ δὲ ἐπήγγειλα αὐτῷ κομίσασθαι τὴν δίκην, ἐλθών μου τά τε σκεύη καὶ τοὺς οἰκέτας καὶ τὰ πρόβατα ἔλαβεν ἀντὶ τοῦ ἀπολαβεῖν. γεωργῶ δὲ πρὸς τῷ ἱπποδρόμῳ, ὥστε οὐ πόρρω ἔδει αὐτὸν ἐλθεῖν.", "st": "47.76"}, {"sp": "N", "t": "ὅτι δ’ ἀληθῆ λέγω, μέγα τεκμήριον ὑμῖν ἔστω· τῇ ὑστεραίᾳ γὰρ ἐκομίσατο τὸ ἀργύριον τῆς δίκης ἢ τὰ ἐνέχυρα ἔλαβεν. καίτοι πῶς ἄν, εἰ μὴ πεπορισμένον ἦν, εὐθὺς ἀπέλαβε τὸ ἀργύριον χιλίας τριακοσίας δέκα τρεῖς δύ’ ὀβολώ; καὶ τὰ ἐνέχυρά μοι οὐκ ἀπεδίδου, ἀλλ’ ἔτι καὶ νῦν ἔχει ὡς ὑπερημέρου ὄντος. ὅτι δ’ οὐκ ἦν αὐτῷ ὑπερήμερος, ἀνάγνωθί μοι τὸν νόμον καὶ τὴν μαρτυρίαν, ὃς κελεύει κύρια εἶναι ὅ τι ἂν ἕτερος ἑτέρῳ ὁμολογήσῃ, ὥστε οὐκέτι ἦν αὐτῷ δήπου ὑπερήμερος.", "st": "47.77"}, {"sp": "N", "t": "ΝΟΜΟΣ. ΜΑΡΤΥΡΙΑ.", "st": "47.77"}, {"sp": "N", "t": "ὡς μὲν τοίνυν ὡμολόγησε καὶ ἀνεβάλετό μοι τὴν ὑπερημερίαν, μεμαρτύρηται ὑμῖν· ὡς δὲ ἐτριηράρχουν, ὁ συντριήραρχός μοι μεμαρτύρηκεν, καὶ ὡς ἡ ναῦς στρατηγὶς κατεσκευάσθη Ἀλκιμάχῳ. ὥστ’ οὐκ ἦν αὐτῷ δήπου ὑπερήμερος ἀναβαλομένῳ μοι, ἔτι δὲ καὶ ἐκτίνων. ἀλλὰ δεινὴ ἡ πλεονεξία τοῦ τρόπου, ὦ ἄνδρες δικασταί, περὶ τὸ πλέον καὶ τὸ ἔλαττον. καὶ εὖ ᾔδεσαν ὅτι, εἰ μὲν τὴν ἄνθρωπον παραδώσουσιν, ἐξελεγχθήσονται ψευδῆ ἐγκαλέσαντες, εἰ δὲ μὴ παραδώσουσιν ἣν ἐμαρτύρησαν ὡς οὗτος ἤθελε παραδιδόναι, ψευδομαρτυρίων ἁλώσονται.", "st": "47.78"}, {"sp": "N", "t": "δέομαι δ’ ὑμῶν, ὦ ἄνδρες δικασταί, εἴ τις ἄρα τῶν τότε δικαζόντων τυγχάνει ὢν ἐν τῷ δικαστηρίῳ, τοῖς αὐτοῖς χρήσασθαι ἤθεσιν οἷσπερ καὶ τότε, καὶ εἰ μὲν ἡ μαρτυρία πιστὴ ὑμῖν ἔδοξεν εἶναι καὶ ἐγὼ φεύγειν τὸν ἔλεγχον τὸν ἐκ τῆς ἀνθρώπου, νῦν ἐξελεγχομένων αὐτῶν ψευδῆ μεμαρτυρηκότων καὶ οὐ παραδιδόντων τὴν ἄνθρωπον βοηθῆσαί μοι, εἰ δ’ ἐμοὶ ὠργίσθητε ὅτι ἐνεχυράσων ἦλθον ἐπὶ τὴν οἰκίαν τὴν τοῦ Θεοφήμου, καὶ τούτοις νῦν ὀργισθῆναι ὅτι ἐπὶ τὴν ἐμὴν ἦλθον.", "st": "47.79"}, {"sp": "N", "t": "καὶ ἐγὼ μὲν ὑπὸ νόμων καὶ ψηφισμάτων ἀναγκαζόμενος, πρόνοιαν ἐποιησάμην τοῦ μήτε ἐπὶ τὸν πατέρα τὸν τούτου εἰσελθεῖν μήτε ἐπὶ τὴν μητέρα, μήτε τῶν τοῦ ἀδελφοῦ λαβεῖν μηδέν, ἀλλ’ οὗ αὐτὸς ᾤκει ὁ Θεόφημος· καὶ ἐπειδὴ οὐ κατέλαβον αὐτὸν ἔνδον, οὐχ ἁρπάσας ᾠχόμην οὐδέν, ἀλλὰ μετελθεῖν ἐκέλευσα αὐτόν, καὶ παρόντος, οὐκ ἀπόντος, τὴν ἐνεχυρασίαν ἐποιησάμην, καὶ ἀφαιρούμενος ἀφῆκα, καὶ ἀνῆλθον ἐπὶ τὴν βουλὴν τοὺς κυρίους, καὶ εἰσαγγείλας καὶ ἑλὼν ἐν τῇ βουλῇ, ἀποχρῆν ἡγησάμην τὰ μὲν σκεύη ἀπολαβεῖν ἁπλᾶ, περὶ δὲ τῶν πληγῶν ἐπιτρέψαι, τῷ δὲ τιμήματι συγχωρῆσαι·", "st": "47.80"}, {"sp": "N", "t": "ὥστε ἐγὼ μὲν οὕτω πρᾶος περὶ τούτους ἦν, οὗτοι δὲ οὕτως ἀσελγεῖς καὶ βδελυροὶ ὥστ’ ἐπὶ τὴν γυναῖκα καὶ τὰ παιδία εἰσελθεῖν, ἔχοντες μὲν τὰ πρόβατα καὶ τοὺς οἰκέτας, πλείονος ἄξια ἢ κατεδικάσαντο, ἀναβαλόμενοι δὲ τὴν ὑπερημερίαν, ἐπαγγείλαντος δ’ ἐμοῦ κομίζεσθαι αὐτοῖς τὴν δίκην, ὡς μεμαρτύρηται ὑμῖν, καὶ εἰσελθόντες εἰς τὴν οἰκίαν τά τε σκεύη ἐκφορῆσαι τήν τε τιτθὴν συγκόψαι, γραῦν γυναῖκα, ἕνεκα κυμβίου, καὶ ταῦτα πάντα ἔτι ἔχειν καὶ μὴ ἀποδιδόναι ἐκτετεικότος ἐμοῦ τὴν δίκην, χιλίας τριακοσίας δέκα τρεῖς δύ’ ὀβολώ.", "st": "47.81"}, {"sp": "N", "t": "εἰ δέ τις ἀγνοήσας αὐτοὺς τότε ἀκάκους ἡγήσατο καὶ ἀπράγμονας εἶναι, βούλομαι ὑμῖν περὶ αὐτῶν τὰς μαρτυρίας ἀναγνῶναι, ἃς μεμαρτυρήκασί μοι οἱ ὑπὸ τούτων ἠδικημένοι (λόγῳ μὲν γὰρ διηγήσασθαι οὐκ ἂν ἱκανόν μοι γένοιτο τὸ ὕδωρ), ἵν’ ἐκ τούτων ἁπάντων σκεψάμενοι, τῶν τε λεχθέντων καὶ τῶν μαρτυρουμένων, ὁσίαν καὶ δικαίαν ὑπὲρ ὑμῶν αὐτῶν τιθῆσθε τὴν ψῆφον. λέγε τὰς μαρτυρίας.", "st": "47.82"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "47.82"}, {"sp": "HDR", "t": "Κατὰ Ὀλυμπιοδώρου βλάβης", "st": "48"}, {"sp": "N", "t": "ἀναγκαῖον ἴσως ἐστίν, ὦ ἄνδρες δικασταί, καὶ τοὺς μὴ εἰωθότας μηδὲ δυναμένους ⟨εἰπεῖν⟩ εἰσιέναι εἰς δικαστήριον, ἐπειδὰν ὑπό τινος ἀδικῶνται, ἄλλως τε καὶ ὑφ’ ὧν ἥκιστα προσῆκεν [ἀδικεῖσθαι], οἷον καὶ ἐμοὶ νυνὶ συμβαίνει. οὐ βουλόμενος γάρ, ὦ ἄνδρες δικασταί, ἀγωνίζεσθαι πρὸς Ὀλυμπιόδωρον οἰκεῖον ὄντα καὶ ἀδελφὴν τούτου ἔχων, ἠνάγκασμαι διὰ τὸ μεγάλ’ ἀδικεῖσθαι ὑπὸ τούτου.", "st": "48.1"}, {"sp": "N", "t": "εἰ μὲν οὖν μὴ ἀδικούμενος, ὦ ἄνδρες δικασταί, ἀλλὰ ψεῦδός τι ἐγκαλῶν Ὀλυμπιοδώρῳ τούτων τι ἐποίουν, ἢ τοῖς ἐπιτηδείοις τοῖς ἐμοῖς καὶ Ὀλυμπιοδώρου μὴ ἐθέλων ἐπιτρέπειν, ἢ ἄλλου τινὸς τῶν δικαίων ἀφιστάμενος, εὖ ἴστε ὅτι πάνυ ἂν ᾐσχυνόμην καὶ ἐνόμιζον ἂν ἐμαυτὸν φαῦλον εἶναι ἄνθρωπον· νῦν δ’ οὔτε μικρὰ ἐλαττούμενος ὑπὸ Ὀλυμπιοδώρου, οὔτε διαλλακτὴν οὐδένα φεύγων, οὔτ’ αὖ μὰ τὸν Δία τὸν μέγιστον ἑκών, ἀλλ’ ὡς οἷόν τε μάλιστα ἄκων, ἠνάγκασμαι ὑπὸ τούτου ἀγωνίζεσθαι ταύτην τὴν δίκην.", "st": "48.2"}, {"sp": "N", "t": "δέομαι οὖν ὑμῶν, ὦ ἄνδρες δικασταί, ἀκούσαντας ἀμφοτέρων ἡμῶν καὶ αὐτοὺς δοκιμαστὰς τοῦ πράγματος γενομένους μάλιστα μὲν διαλλάξαντας ἀποπέμψαι καὶ εὐεργέτας ἡμῶν ἀμφοτέρων ὑμᾶς γενέσθαι, ἐὰν δ’ ἄρα μὴ ἐπιτυγχάνητε τούτου, ἐκ τῶν ὑπολοίπων τῷ τὰ δίκαια λέγοντι, τούτῳ τὴν ψῆφον ὑμᾶς προσθέσθαι. πρῶτον μὲν οὖν μαρτυρίας ἀναγνώσεται ὅτι οὐκ ἐγὼ αἴτιός εἰμι τοῦ εἰς τὸ δικαστήριον εἰσιέναι, ἀλλ’ οὗτος αὐτός. λέγε τὰς μαρτυρίας.", "st": "48.3"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "48.3"}, {"sp": "N", "t": "ὅτι μὲν οὖν, ὦ ἄνδρες δικασταί, καὶ μέτρια καὶ προσήκοντα προὐκαλούμην Ὀλυμπιόδωρον, μεμαρτύρηται ὑπὸ τῶν παραγενομένων. οὐκ ἐθέλοντος δὲ τούτου οὐδ’ ὁτιοῦν ποιεῖν τῶν δικαίων, ἀναγκαῖόν ἐστιν πρὸς ὑμᾶς λέγειν περὶ ὧν ἀδικοῦμαι ὑπὸ Ὀλυμπιοδώρου. ἔστιν δὲ βραχὺς ὁ λόγος.", "st": "48.4"}, {"sp": "N", "t": "ἦν γάρ, ὦ ἄνδρες δικασταί, Κόμων Ἁλαιεύς, οἰκεῖος ἡμέτερος. οὗτος ὁ Κόμων ἐτελεύτησεν ἄπαις ὀλίγον πάνυ χρόνον ἀρρωστήσας, ἐβίω δὲ πολλὰ ἔτη, καὶ ἦν πρεσβύτερος ὅτε ἐτελεύτα. καὶ ἐγὼ ἐπειδὴ ᾐσθόμην ὅτι οὐχ οἷός τέ ἐστιν περιγενέσθαι, μετεπεμψάμην τουτονὶ Ὀλυμπιόδωρον, ὅπως ἂν παρῇ καὶ συνεπιμελῆται μεθ’ ἡμῶν ἁπάντων ὧν προσῆκεν. καὶ Ὀλυμπιόδωρος οὑτοσί, ὦ ἄνδρες δικασταί, ἐπειδὴ ἦλθεν ὡς ἐμὲ καὶ τὴν ἀδελφὴν τὴν ἑαυτοῦ, ἐμὴν δὲ γυναῖκα, μεθ’ ἡμῶν ἅπαντα διῴκει.", "st": "48.5"}, {"sp": "N", "t": "ὄντων δ’ ἡμῶν περὶ ταύτην τὴν πραγματείαν, ἐξαίφνης λόγον μοι προσφέρει Ὀλυμπιόδωρος οὑτοσί, ὅτι καὶ ἡ μήτηρ αὐτοῦ προσήκουσα εἴη τῷ Κόμωνι τῷ τετελευτηκότι, καὶ ὅτι δίκαιον εἴη καὶ αὑτὸν τὸ μέρος λαβεῖν ἁπάντων ὧν ὁ Κόμων κατέλιπεν. καὶ ἐγώ, ὦ ἄνδρες δικασταί, συνειδὼς ὅτι ἐψεύδετο καὶ ἀναισχυντεῖν ἐπεχείρει, καὶ ὅτι οὐδεὶς ἦν ἄλλος τῷ Κόμωνι γένει ἐγγυτέρω ἐμοῦ, τὸ μὲν πρῶτον ὡς οἷόν τε μάλιστα ὠργίσθην καὶ ἠγανάκτησα ἐπὶ τῇ ἀναισχυντίᾳ τοῦ λόγου, ἔπειτα δὲ ἐλογισάμην πρὸς ἐμαυτὸν ὅτι οὐκ ἐν καιρῷ ὀργιζοίμην, καὶ τούτῳ ἀπεκρινάμην ὅτι ἐν μὲν τῷ παρόντι προσήκει θάπτειν τὸν τετελευτηκότα καὶ τἄλλα ποιεῖν τὰ νομιζόμενα, ἐπειδὰν δὲ τούτων ἁπάντων ἐπιμεληθῶμεν, τόθ’ ἡμῖν αὐτοῖς διαλεξόμεθα.", "st": "48.6"}, {"sp": "N", "t": "καὶ οὗτος, ὦ ἄνδρες δικασταί, προσωμολόγησεν ταῦτα καὶ καλῶς μ’ ἔφη λέγειν. ἐπειδὴ δὲ ἀπηλλάγημεν καὶ ἐποιήσαμεν ἅπαντα τὰ νομιζόμενα, καθ’ ἡσυχίαν ἤδη παρακαλέσαντες τοὺς οἰκείους ἅπαντας διελεγόμεθα ἡμῖν αὐτοῖς περὶ ὧν οὗτος ἠξίου ἑαυτῷ εἶναι. ὅσα μὲν οὖν, ὦ ἄνδρες δικασταί, ἡμεῖς πρὸς ἡμᾶς αὐτοὺς διηνέχθημεν περὶ τούτων διαλεγόμενοι, τι ἂν ἐγὼ ταῦτα διηγούμενος ἢ ὑμῖν πράγματα παρέχοιμι ἢ ἐμαυτῷ [ἐνοχλοίην];", "st": "48.7"}, {"sp": "N", "t": "τὸ δὲ τέλος ὃ ἐγένετο, τοῦθ’ ὑμᾶς ἀναγκαίως ἔχει ἀκοῦσαι. αὐτὸς γὰρ ἐγὼ ἐδίκασα τούτῳ καὶ οὗτος ἐμοὶ τὰ ἡμίσεα ἑκάτερον ἡμῶν λαβεῖν ὧν κατέλιπε Κόμων, καὶ μηδεμίαν ἀηδίαν εἶναι περαιτέρω. καὶ προειλόμην, ὦ ἄνδρες δικασταί, ἑκὼν μεταδοῦναι τούτῳ μᾶλλον ἢ εἰς δικαστήριον εἰσιὼν κινδυνεύειν πρὸς οἰκεῖον ὄντα τοῦτον καὶ εἰπεῖν τι ἀηδές, ἀδελφὸν ὄντα τῆς ἐμῆς γυναικὸς καὶ θεῖον τῶν ἐμῶν παίδων, καὶ ὑπὸ τούτου ἀκοῦσαί τι ἀνεπιτήδειον.", "st": "48.8"}, {"sp": "N", "t": "ταῦτα πάντα ἐνθυμούμενος συνεχώρησα αὐτῷ. καὶ μετὰ ταῦτα συνθήκας ἐγράψαμεν πρὸς ἡμᾶς αὐτοὺς περὶ ἁπάντων, καὶ ὅρκους ἰσχυροὺς ὠμόσαμεν ἀλλήλοις, ἦ μὴν τά τε ὑπάρχοντα φανερὰ ὄντα καλῶς καὶ δικαίως διαιρήσεσθαι καὶ μηδ’ ὁτιοῦν πλεονεκτήσειν τὸν ἕτερον τοῦ ἑτέρου ὧν κατέλιπεν Κόμων, καὶ τἄλλα πάντα κοινῇ ζητήσειν, καὶ πράξειν μετ’ ἀλλήλων βουλευόμενοι ὅ τι ἂν ἀεὶ δέῃ.", "st": "48.9"}, {"sp": "N", "t": "ὑπενοοῦμεν γάρ, ὦ ἄνδρες δικασταί, ἥξειν τινὰς ἀμφισβητήσοντας τῶν τοῦ Κόμωνος καὶ ἑτέρους· οἷον καὶ ὁ ἐμὸς ἀδελφὸς ⟨ὁ⟩ ὁμοπάτριος, ὁμομήτριος δ’ οὔ, ὃς ἀπεδήμει, καὶ εἰ δή τις ἄλλος ἐβούλετ’ ἀμφισβητεῖν, οὐκ ἦν ἡμῖν κωλύειν· οἱ γὰρ νόμοι κελεύουσι τὸν βουλόμενον ἀμφισβητεῖν. ταῦτα δὴ πάντα προνοούμενοι ἐγράψαμεν τὰς συνθήκας καὶ ὅρκους ὠμόσαμεν, ὅπως ἂν μήτε ἑκόντι μήτε ἄκοντι μηδετέρῳ ἐξουσία ἡμῶν γένηται μηδ’ ὁτιοῦν ἰδίᾳ πρᾶξαι, ἀλλὰ κοινῇ βουλευόμενοι μεθ’ ἡμῶν αὐτῶν ἅπαντα πράττωμεν.", "st": "48.10"}, {"sp": "N", "t": "καὶ μάρτυρας ἐποιησάμεθα περὶ τούτων πρῶτον μὲν τοὺς θεοὺς οὓς ὠμόσαμεν ἀλλήλοις, καὶ τοὺς οἰκείους τοὺς ἡμετέρους αὐτῶν, ἔπειτ’ Ἀνδροκλείδην Ἀχαρνέα, παρ’ ᾧ κατεθέμεθα τὰς συνθήκας. βούλομαι οὖν, ὦ ἄνδρες δικασταί, τόν τε νόμον ἀναγνῶναι, καθ’ ὃν τὰς συνθήκας ἐγράψαμεν πρὸς ἡμᾶς αὐτούς, καὶ μαρτυρίαν τοῦ ἔχοντος τὰς συνθήκας. λέγε τὸν νόμον πρῶτον.", "st": "48.11"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "48.11"}, {"sp": "N", "t": "ἀναγίγνωσκε δὴ καὶ τὴν μαρτυρίαν τὴν Ἀνδροκλείδου.", "st": "48.11"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "48.11"}, {"sp": "N", "t": "ἐπειδὴ δὲ ὠμόσαμεν ἀλλήλοις καὶ αἱ συνθῆκαι ἦσαν κείμεναι παρὰ τῷ Ἀνδροκλείδῃ, διεῖλον ἐγὼ δύο μερίδας, ὦ ἄνδρες δικασταί. καὶ ἡ μὲν ἑτέρα ἦν μερὶς ἡ οἰκία ἐν ᾗ ᾤκει αὐτὸς ὁ Κόμων, καὶ τἀνδράποδα οἱ σακχυφάνται, ἡ δ’ ἑτέρα ἦν μερὶς οἰκία ἑτέρα καὶ τἀνδράποδα οἱ φαρμακοτρίβαι. ἀργύριον δὲ εἴ τι κατέλιπεν ὁ Κόμων φανερὸν ἐπὶ τῇ τραπέζῃ τῇ Ἡρακλείδου, τοῦθ’ ἅπαν σχεδόν τι ἀνηλώθη εἴς τε τὴν ταφὴν καὶ τἄλλα τὰ νομιζόμενα καὶ εἰς τὴν οἰκοδομίαν τοῦ μνήματος.", "st": "48.12"}, {"sp": "N", "t": "διελὼν δ’ ἐγὼ τὰς δύο ταύτας μερίδας, ἔδωκα αἵρεσιν τουτῳὶ Ὀλυμπιοδώρῳ ὁποτέραν βούλεται τῶν μερίδων λαβεῖν, καὶ οὗτος εἵλετο τοὺς φαρμακοτρίβας καὶ τὴν οἰκίσκην· ἐγὼ δ’ ἔλαβον τοὺς σακχυφάντας καὶ τὴν οἰκίαν τὴν ἑτέραν. καὶ ταῦτ’ ἔστιν ἃ ἑκάτερος ἡμῶν εἶχεν.", "st": "48.13"}, {"sp": "N", "t": "ἐν δὲ τῇ μερίδι τῇ τουτουὶ Ὀλυμπιοδώρου ἦν εἷς τῶν φαρμακοτριβῶν, ὃν μάλιστα ἐνόμιζεν πιστὸν ἑαυτῷ εἶναι ὁ Κόμων· ὄνομα δὲ τῷ ἀνθρώπῳ ἐστὶν Μοσχίων. οὗτος ὁ οἰκέτης σχεδόν τι ᾔδει τά τε ἄλλα τὰ τοῦ Κόμωνος ἅπαντα, καὶ δὴ τὸ ἀργύριον οὗ ἦν, τὸ ἔνδον κείμενον τῷ Κόμωνι.", "st": "48.14"}, {"sp": "N", "t": "καὶ δὴ καὶ ἔλαθεν τὸν Κόμωνα, πρεσβύτερόν τε ὄντα καὶ πεπιστευκότα αὐτῷ, ὑφαιρούμενος τὸ ἀργύριον οὗτος ὁ οἰκέτης ὁ Μοσχίων. καὶ πρῶτον μὲν ὑφαιρεῖται αὐτοῦ χιλίας δραχμὰς χωρίς που κειμένας τοῦ ἄλλου ἀργυρίου, ἔπειτα ἑτέρας ἑβδομήκοντα μνᾶς. καὶ ταῦτα ποιῶν ἐλάνθανεν τὸν Κόμωνα. καὶ τὸ ἀργύριον τοῦτο ἅπαν εἶχεν αὐτὸς δι’ ἑαυτοῦ ὁ ἄνθρωπος.", "st": "48.15"}, {"sp": "N", "t": "οὐ πολλῷ δὲ χρόνῳ ὕστερον, ὦ ἄνδρες δικασταί, ἢ ἡμεῖς διειλόμεθα τὰς μερίδας, ὑποψία τις ἐγένετο καὶ αἴσθησις περὶ τἀνθρώπου τούτου· ἐκ δὲ ταύτης τῆς ὑποψίας ἐδόκει ἐμοὶ καὶ τουτῳὶ Ὀλυμπιοδώρῳ βασανίζειν τὸν ἄνθρωπον. καὶ ὁ ἄνθρωπος, ὦ ἄνδρες δικασταί, αὐτὸς αὑτοῦ κατεῖπε, πρὶν βασανίζεσθαι, ὅτι χιλίας δραχμὰς ὑφείλετο τοῦ Κόμωνος, καὶ ἔφη εἶναι παρ’ ἑαυτῷ ὅσον μὴ ἦν ἀνηλωμένον· περὶ δὲ τοῦ πλείονος ἀργυρίου οὐδ’ ὁτιοῦν εἶπεν ἐν τῷ τότε χρόνῳ· καὶ ἀποδίδωσιν περὶ ἑξακοσίας τινὰς δραχμάς.", "st": "48.16"}, {"sp": "N", "t": "καὶ τούτου τοῦ ἀργυρίου, οὗ ἀπέδωκεν ὁ ἄνθρωπος, καλῶς καὶ δικαίως κατὰ τοὺς ὅρκους οὓς ὠμόσαμεν ἡμεῖς καὶ κατὰ τὰς συνθήκας τὰς κειμένας παρὰ τῷ Ἀνδροκλείδῃ τὸ μὲν ἥμισυ ἐγὼ ἔλαβον, τὸ δ’ ἥμισυ οὑτοσὶ Ὀλυμπιόδωρος.", "st": "48.17"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα οὐ πολλῷ χρόνῳ ὕστερον ἐκ ταύτης τῆς ὑποψίας τῆς πρὸς τὸν οἰκέτην περὶ τοῦ ἀργυρίου οὗ ἀπέδωκεν, ἔδησεν τὸν ἄνθρωπον καὶ ἐβασάνισεν αὐτὸς ἐφ’ ἑαυτοῦ, ἡμᾶς δὲ οὐ παρεκάλεσεν, ὀμωμοκὼς κοινῇ ζητήσειν καὶ πράξειν μετ’ ἐμοῦ πάντα. καὶ ὁ ἄνθρωπος, ὦ ἄνδρες δικασταί, κατατεινόμενος ὑπὸ τῆς βασάνου προσωμολόγησε καὶ τὰς ἑβδομήκοντα μνᾶς εἰληφέναι ὑφελόμενος Κόμωνος, καὶ ἀποδίδωσιν ἅπαν τὸ ἀργύριον τοῦτο Ὀλυμπιοδώρῳ τουτῳί.", "st": "48.18"}, {"sp": "N", "t": "ἐγὼ δ’, ὦ ἄνδρες δικασταί, ἐπειδὴ ἐπυθόμην περὶ τῆς βασάνου τοῦ ἀνθρώπου καὶ ὅτι ἀποδεδωκὼς εἴη τὸ ἀργύριον, ἐνόμιζόν μοι ἀποδώσειν τοῦτον τὸ ἥμισυ τοῦ ἀργυρίου, ὥσπερ καὶ τὸ πρότερον ἀπὸ τῶν χιλίων δραχμῶν ἀπέδωκε. καὶ εὐθὺς μὲν οὐ πάνυ τι ἠνώχλουν τούτῳ, ἡγούμενος αὐτὸν τοῦτο γνώσεσθαι καὶ διοικήσειν καὶ ἐμοὶ καὶ ἑαυτῷ, ὅπως ἑκάτερος ἡμῶν ἕξει τὰ δίκαια κατὰ τοὺς ὅρκους καὶ τὰς συνθήκας τὰς πρὸς ἡμᾶς αὐτοὺς περὶ τοῦ ἰσομοιρεῖν ἁπάντων ὧν Κόμων ἦν καταλελοιπώς·", "st": "48.19"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἐνδιέτριβεν καὶ οὐδὲν ἐποίει, διελεγόμην τουτῳὶ Ὀλυμπιοδώρῳ, καὶ ἠξίουν ἀπολαμβάνειν τὸ ἐμαυτοῦ μέρος τοῦ ἀργυρίου. οὑτοσὶ δὲ Ὀλυμπιόδωρος ἀεί τι προὐφασίζετο καὶ ἀναβολὰς ἐποιεῖτο. καὶ ἐν τούτῳ τῷ καιρῷ ἕτεροί τινες ἔλαχον τοῦ κλήρου τοῦ Κόμωνος, καὶ ὁ Κάλλιππος ἐπεδήμησεν ἐκ τῆς ἀποδημίας, ὁ ἐμὸς ἀδελφὸς ὁ ὁμοπάτριος· καὶ οὗτος ἔλαχεν εὐθὺς τοῦ ἡμικληρίου.", "st": "48.20"}, {"sp": "N", "t": "καὶ τουτῳὶ Ὀλυμπιοδώρῳ πρόφασις καὶ αὕτη ἐγένετο πρὸς τὸ μὴ ἀποδιδόναι μοι τὸ ἀργύριον, ἐπειδὴ πολλοὶ ἦσαν οἱ ἀμφισβητοῦντες, καὶ ἔφη χρῆναί με περιμεῖναι, ἕως ἂν οἱ ἀγῶνες γένωνται. καὶ ἐμοὶ ἀνάγκη ἦν ταῦτα συγχωρεῖν, καὶ συνεχώρησα.", "st": "48.21"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ἐβουλευόμεθα καὶ ἐγὼ καὶ οὑτοσὶ Ὀλυμπιόδωρος κοινῇ, ὥσπερ καὶ ὠμόσαμεν, ὅντινα τρόπον ἄριστα καὶ ἀσφαλέστατα προσοισόμεθα πρὸς τοὺς ἀμφισβητοῦντας. καὶ ἔδοξεν ἡμῖν, ὦ ἄνδρες δικασταί, τουτονὶ μὲν Ὀλυμπιόδωρον τοῦ κλήρου ὅλου ἀμφισβητεῖν, ἐμὲ δὲ τοῦ ἡμικληρίου, ἐπειδὴ καὶ Κάλλιππος ὁ ἀδελφὸς ὁ ἐμὸς τοῦ ἡμικληρίου μόνον ἠμφεσβήτει.", "st": "48.22"}, {"sp": "N", "t": "καὶ ἐπειδὴ ἀνεκρίθησαν πρὸς τῷ ἄρχοντι ἅπασαι αἱ ἀμφισβητήσεις καὶ ἔδει ἀγωνίζεσθαι ἐν τῷ δικαστηρίῳ, ἀπαράσκευοι ἦμεν τὸ παράπαν πρὸς τὸ ἤδη ἀγωνίζεσθαι ἐγὼ καὶ Ὀλυμπιόδωρος οὑτοσὶ διὰ τὸ ἐξαίφνης ἐπιπεπτωκέναι ἡμῖν πολλοὺς τοὺς ἀμφισβητοῦντας· ἐκ δὲ τῶν ὑπαρχόντων ἐσκοποῦμεν κοινῇ, εἴ πως ἀναβολή τις γένοιτο ἐν τῷ παρόντι, ὥστε παρασκευάσασθαι ἡμᾶς καθ’ ἡσυχίαν πρὸς τὸν ἀγῶνα.", "st": "48.23"}, {"sp": "N", "t": "καὶ κατὰ τύχην τινὰ καὶ δαίμονα ὑμεῖς ἐπείσθητε ὑπὸ τῶν ῥητόρων εἰς Ἀκαρνανίαν στρατιώτας ἐκπέμπειν, καὶ ἔδει καὶ τουτονὶ Ὀλυμπιόδωρον στρατεύεσθαι, καὶ ᾤχετο μετὰ τῶν ἄλλων στρατευόμενος. καὶ συνεβεβήκει, ὡς ᾠόμεθα ἡμεῖς, αὕτη καλλίστη ἀναβολή, δημοσίᾳ τούτου ἀποδημοῦντος στρατευομένου.", "st": "48.24"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἐκάλει ὁ ἄρχων εἰς τὸ δικαστήριον ἅπαντας τοὺς ἀμφισβητοῦντας κατὰ τὸν νόμον, ὑπωμοσάμεθα ἡμεῖς τουτονὶ Ὀλυμπιόδωρον δημοσίᾳ ἀπεῖναι στρατευόμενον. ὑπομοθέντος δὲ τούτου ἀνθυπωμόσαντο οἱ ἀντίδικοι, καὶ διαβάλλοντες Ὀλυμπιόδωρον τουτονί, ὕστεροι ἡμῶν λέγοντες, ἔπεισαν τοὺς δικαστὰς ψηφίσασθαι τῆς δίκης ἕνεκα ἀπεῖναι τουτονὶ καὶ οὐ δημοσίᾳ.", "st": "48.25"}, {"sp": "N", "t": "ψηφισαμένων δὲ ταῦτα τῶν δικαστῶν διέγραψεν ὁ ἄρχων Πυθόδοτος κατὰ τὸν νόμον τὴν τουτουὶ Ὀλυμπιοδώρου ἀμφισβήτησιν. διαγραφείσης δὲ ταύτης, ἐξ ἀνάγκης καὶ ἐμοὶ ἦν ἐκλιπεῖν τὴν τοῦ ἡμικληρίου ἀμφισβήτησιν. γενομένων δὲ τούτων ἐπεδίκασεν ὁ ἄρχων τοῖς ἀντιδίκοις τοῖς ἡμετέροις τὸν κλῆρον τὸν Κόμωνος· ταῦτα γὰρ οἱ νόμοι αὐτὸν ἠνάγκαζον ποιεῖν.", "st": "48.26"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἐπεδικάσαντο, εὐθὺς εἰς Πειραιᾶ ἐλθόντες παρελάμβανον πάντα ὅσα ἡμῶν εἶχεν ἑκάτερος νειμάμενος ἐν τῇ μερίδι. κἀγὼ μὲν ἐπιδημῶν αὐτὸς παρέδωκα (ἀνάγκη γὰρ ἦν πείθεσθαι τοῖς νόμοις), τὰ δὲ Ὀλυμπιοδώρου, ἀποδημοῦντος τούτου, ἅπαντα ᾤχοντο λαβόντες, πλὴν τοῦ ἀργυρίου οὗ εἶχεν αὐτὸς παρὰ τοῦ ἀνθρώπου τοῦ οἰκέτου, ὃν ἐβασάνισεν· οὐ γὰρ εἶχον ὅπου ἐπιλάβοιντο τοῦ ἀργυρίου.", "st": "48.27"}, {"sp": "N", "t": "καὶ τὰ μὲν πραχθέντα ταῦτ’ ἦν ἐν τῇ ἀποδημίᾳ τῇ Ὀλυμπιοδώρου, καὶ τῆς κοινωνίας τῆς πρὸς τοῦτον ταῦτα ἐγὼ ἀπέλαυσα. ἐπειδὴ δὲ ἐπεδήμησεν οὗτος καὶ οἱ ἄλλοι στρατιῶται, ἠγανάκτει Ὀλυμπιόδωρος οὑτοσί, ὦ ἄνδρες δικασταί, ἐπὶ τοῖς συμβεβηκόσι, καὶ ἡγεῖτο δεινὰ πεπονθέναι. ἐπειδὴ δὲ μεστὸς ἐγένετο ἀγανακτῶν, ἐσκοποῦμεν πάλιν καὶ ἐβουλευόμεθα κοινῇ ἐγὼ καὶ Ὀλυμπιόδωρος οὑτοσί, ὅντινα τρόπον τούτων τι πάλιν κομιούμεθα.", "st": "48.28"}, {"sp": "N", "t": "καὶ ἐδόκει ἡμῖν βουλευομένοις προσκαλεῖσθαι τοὺς ἐπιδεδικασμένους κατὰ τὸν νόμον, καὶ ἐκ τῶν ὑπαρχόντων ἀσφαλέστατον εἶναι μὴ ἐν τῷ αὐτῷ ἡμᾶς ἀμφοτέρους τὸν κίνδυνον ποιεῖσθαι πρὸς τοὺς ἀμφισβητοῦντας, ἀλλὰ χωρὶς ἑκάτερον, καὶ τουτονὶ μὲν Ὀλυμπιόδωρον ὅλου τοῦ κλήρου λαχεῖν, ὥσπερ τὸ πρότερον, καὶ ἀγωνίζεσθαι καθ’ αὑτόν, ἐμὲ δὲ τοῦ ἡμικληρίου, ἐπειδὴ καὶ Κάλλιππος ὁ ἀδελφὸς ὁ ἐμὸς τοῦ ἡμικληρίου μόνον ἠμφεσβήτει,", "st": "48.29"}, {"sp": "N", "t": "ὅπως, ἐὰν μὲν Ὀλυμπιόδωρος οὑτοσὶ ἐπιτύχῃ τοῦ ἀγῶνος, ἐγὼ κατὰ τὰς συνθήκας καὶ τοὺς ὅρκους πάλιν τὸ μέρος λάβοιμι παρὰ τούτου, ἐὰν δ’ ἄρα ἀποτύχῃ καὶ τὰ ἕτερα ψηφίσωνται οἱ δικασταί, οὗτος παρ’ ἐμοῦ [τὰ μέρη] καλῶς καὶ δικαίως ἀπολαμβάνοι, ὥσπερ ὠμόσαμεν ἀλλήλοις καὶ συνεθέμεθα. ἐπειδὴ δὲ ταῦτ’ ἐβουλευσάμεθα καὶ ἐδόκει ἀσφαλέστατ’ εἶναι καὶ ἐμοὶ καὶ Ὀλυμπιοδώρῳ, προσεκλήθησαν ἅπαντες οἱ ἔχοντες τὰ τοῦ Κόμωνος κατὰ τὸν νόμον. καί μοι ἀνάγνωθι τὸν νόμον, καθ’ ὃν ἡ πρόσκλησις ἐγένετο.", "st": "48.30"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "48.30"}, {"sp": "N", "t": "κατὰ τὸν νόμον τοῦτον, ὦ ἄνδρες δικασταί, ἡ πρόσκλησις ἐγένετο, καὶ τὰς ἀμφισβητήσεις ἀντεγραψάμεθα, ὃν τρόπον τουτῳὶ ἐδόκει Ὀλυμπιοδώρῳ. καὶ μετὰ ταῦτα ὁ ἄρχων ἀνέκρινε πᾶσιν ἡμῖν τοῖς ἀμφισβητοῦσιν, καὶ ἀνακρίνας εἰσήγαγεν εἰς τὸ δικαστήριον. καὶ οὑτοσὶ Ὀλυμπιόδωρος ἠγωνίζετο πρῶτος, καὶ ἔλεγεν ὅ τι ἐβούλετο, καὶ μαρτυρίας παρείχετο ἃς ἐδόκει τούτῳ· κἀγώ, ὦ ἄνδρες δικασταί, σιωπῇ ἐκαθήμην ἐπὶ τοῦ ἑτέρου βήματος. τοῦτον δὲ τὸν τρόπον κατασκευασθέντος τοῦ ἀγῶνος ἐνίκησεν ῥᾳδίως.", "st": "48.31"}, {"sp": "N", "t": "νικήσας δὲ καὶ διαπραξαμένων ἅπαντα ὅσα ἐβουλήθημεν ἐν τῷ δικαστηρίῳ, καὶ ἀπολαβὼν παρὰ τῶν πρότερον ἐπιδικασαμένων ὅσα ἦσαν ἐκεῖνοι παρ’ ἡμῶν εἰληφότες, ταῦτα δὴ πάντα ἔχων καὶ τὸ ἀργύριον ὃ ἔλαβεν παρὰ τοῦ ἀνθρώπου τοῦ βασανισθέντος, οὐδ’ ὁτιοῦν ἠθέληκεν τῶν δικαίων πρός με ποιῆσαι, ἀλλ’ ἔχει αὐτὸς ἅπαντα, ὀμωμοκὼς καὶ συνθήκας πρός με ποιησάμενος ἦ μὴν ἰσομοιρήσειν. καὶ αἱ συνθῆκαι αὗται ἔτι καὶ νῦν κεῖνται παρὰ τῷ Ἀνδροκλείδῃ, καὶ μεμαρτύρηκεν αὐτὸς πρὸς ὑμᾶς.", "st": "48.32"}, {"sp": "N", "t": "βούλομαι δὲ καὶ περὶ τῶν ἄλλων ἁπάντων ὧν εἴρηκα μαρτυρίας ὑμῖν παρασχέσθαι, πρώτιστον μὲν τὸ ἐξ ἀρχῆς ὅτι ἐγὼ καὶ οὗτος ἡμῖν αὐτοῖς δικάσαντες ἐνειμάμεθα τὸ ἴσον ἑκάτερος τῆς φανερᾶς οὐσίας ἧς Κόμων κατέλιπεν. καί μοι λαβὲ ταύτην τὴν μαρτυρίαν πρῶτον, ἔπειτα τὰς ἄλλας ἁπάσας ἀναγίγνωσκε.", "st": "48.33"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "48.33"}, {"sp": "N", "t": "λαβὲ δή μοι καὶ τὴν πρόκλησιν, ἣν προὐκαλεσάμην αὐτὸν περὶ τοῦ ἀργυρίου οὗ ἔλαβεν παρὰ τοῦ ἀνθρώπου τοῦ βασανισθέντος.", "st": "48.34"}, {"sp": "N", "t": "ΠΡΟΚΛΗΣΙΣ.", "st": "48.34"}, {"sp": "N", "t": "ἀναγίγνωσκε δὲ καὶ τὴν ἑτέραν μαρτυρίαν, ὅτι, ἐπειδὴ ἐπεδικάσαντο οἱ ἀντίδικοι ἡμῶν, ἅπαντα παρέλαβον ὅσα ἡμεῖς εἴχομεν, πλὴν τῶν χρημάτων ὧν εἶχεν Ὀλυμπιόδωρος παρὰ τοῦ βασανισθέντος ἀνθρώπου.", "st": "48.34"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "48.34"}, {"sp": "N", "t": "ὃν μὲν τρόπον, ὦ ἄνδρες δικασταί, ἐξ ἀρχῆς διενειμάμεθα τὴν Κόμωνος οὐσίαν τὴν φανερὰν ἐγὼ καὶ Ὀλυμπιόδωρος, καὶ λόγῳ ἀκηκόατε καὶ μεμαρτύρηται ὑμῖν, καὶ ὡς οὗτος τὸ ἀργύριον ἔλαβεν παρὰ τοῦ ἀνθρώπου τοῦ οἰκέτου, καὶ ὅτι οἱ ἐπιδικασάμενοι ἔλαβον ὅσα ἡμεῖς εἴχομεν, ἕως οὑτοσὶ πάλιν ἐνίκησεν ἐν τῷ δικαστηρίῳ.", "st": "48.35"}, {"sp": "N", "t": "ἃ δὲ λέγων οὐκ ἀποδίδωσίν μοι οὐδ’ ἐθέλει τῶν δικαίων οὐδ’ ὁτιοῦν ποιεῖν, τούτοις ἤδη προσέχετε τὸν νοῦν, ὦ ἄνδρες δικασταί, ἵνα μὴ αὐτίκα ἐξαπατήσωσιν ὑμᾶς οἱ ῥήτορες, οὓς οὑτοσὶ παρεσκεύασται ἐπ’ ἐμέ. λέγει μὲν οὗτος οὐδέποτε ταὐτά, ἀλλ’ ὅ τι ἂν τύχῃ ἀεί, καὶ περιιὼν προφάσεις ἀτόπους τινὰς καὶ ὑπονοίας καὶ αἰτίας ψευδεῖς ἐπιφέρει, καὶ περὶ τὸ πρᾶγμα ὅλον ἄδικός ἐστιν ἄνθρωπος.", "st": "48.36"}, {"sp": "N", "t": "πλεῖστοι δὲ αὐτοῦ ἀκηκόασιν λέγοντος, οἱ μὲν ὅτι τὸ παράπαν οὐκ ἔλαβε τὸ ἀργύριον παρὰ τοῦ ἀνθρώπου· ἐπειδὰν δὲ τοῦτο ἐξελέγχηται, πάλιν λέγει ὅτι παρὰ τοῦ αὑτοῦ ἀνθρώπου ἔχει τὸ ἀργύριον, καὶ οὐ μεταδώσει ἐμοὶ οὔτε τοῦ ἀργυρίου οὔτε τῶν ἄλλων οὐδενὸς ὧν κατέλιπε Κόμων.", "st": "48.37"}, {"sp": "N", "t": "ἐπειδὰν δέ τις αὐτὸν τῶν ἐπιτηδείων τῶν τούτου καὶ τῶν ἐμῶν ἐρωτᾷ, διὰ τί οὐκ ἀποδώσει ὀμωμοκὼς ἰσομοιρήσειν καὶ τῶν συνθηκῶν ἔτι νυνὶ κειμένων, φησί με παραβεβηκέναι τὰς συνθήκας, καὶ δεινὰ πεπονθέναι ὑπ’ ἐμοῦ, καὶ διατελέσαι μέ φησιν ὑπεναντία καὶ λέγοντα καὶ πράττοντα ἑαυτῷ. καὶ ἃ μὲν προφασίζεται, ταῦτ’ ἔστιν.", "st": "48.38"}, {"sp": "N", "t": "ἃ μὲν οὖν, ὦ ἄνδρες δικασταί, οὗτος λέγει, ὑπόνοιαι πλασταί εἰσιν καὶ προφάσεις ἄδικοι καὶ πονηρίαι ἐπὶ τῷ ἀποστερῆσαι ἃ προσήκει αὐτὸν ἀποδοῦναι ἐμοί. ἃ δὲ ἐγὼ ἐρῶ πρὸς ὑμᾶς, ὅτι οὗτος ψεύδεται, ταῦτα δὲ ὑπόνοια οὐδεμία ἔσται, φανερῶς δὲ ἐπιδείξω τὴν τούτου ἀναισχυντίαν, τεκμήρια λέγων ἀληθινὰ καὶ πᾶσι γνώριμα, καὶ μάρτυρας παρεχόμενος περὶ ἁπάντων.", "st": "48.39"}, {"sp": "N", "t": "πρῶτον μὲν οὖν, ὦ ἄνδρες δικασταί, λέγω ὅτι οὗτος διὰ τοῦτο τοῖς οἰκείοις καὶ τοῖς ἐπιτηδείοις τοῖς ἑαυτοῦ καὶ τοῖς ἐμοῖς, τοῖς εἰδόσιν ἀκριβῶς ἅπαντα ταῦτα τὰ πράγματα ὡς ἔχει καὶ παρηκολουθηκόσιν ἐξ ἀρχῆς, οὐκ ἠθέλησεν ἐπιτρέψαι· ἀκριβῶς [γὰρ] ᾔδει ὅτι εὐθὺς παραχρῆμα ὑπ’ αὐτῶν ἐξελεγχθήσεται, ἐάν τι ψεύδηται· νυνὶ δ’ ἴσως ἡγεῖται ψευδόμενος ἐν ὑμῖν λήσειν.", "st": "48.40"}, {"sp": "N", "t": "πάλιν λέγω ὅτι οὐκ ἀκόλουθόν ἐστιν ὑπεναντία μὲν πράττειν σοι, ὦ Ὀλυμπιόδωρε, ἐμέ, κοινῇ δὲ ἀναλίσκειν μετὰ σοῦ εἰς ὅ τι ἀεὶ δέοι, οὐδὲ ἐκλιπεῖν τὴν ἀμφισβήτησιν αὐτὸν ἑκόντα, ὅτε ἀπεδήμεις σύ, ἐπειδὴ καὶ ἡ σὴ διεγράφη δόξαντός σου ἕνεκα τῆς δίκης ἀπεῖναι καὶ οὐ δημοσίᾳ. ἐξῆν γὰρ ἔμοιγε τοῦ ἡμικληρίου ἐπιδικάσασθαι ἐμαυτῷ· οὐδεὶς γάρ μοι ἀνθρώπων ἀντέλεγεν, ἀλλὰ συνεχώρουν αὐτοὶ οἱ ἀντίδικοι.", "st": "48.41"}, {"sp": "N", "t": "ἀλλὰ ταῦτα ποιήσας εὐθὺς ἂν ἦν ἐπιωρκηκώς· ὤμοσα γὰρ καὶ συνεθέμην πρὸς σὲ κοινῇ πράξειν ἅπαντα, ὅ τι ἂν δοκῇ ἐμοὶ καὶ σοὶ βουλευομένοις βέλτιστον εἶναι. ὥστε ὑπεραβέλτεροί εἰσιν αἱ προφάσεις καὶ αἰτίαι, δι’ ἃς οὐδέν μοι φὴς ποιήσειν τῶν δικαίων.", "st": "48.42"}, {"sp": "N", "t": "ἔτι πρὸς τούτοις ἡγεῖ ἄν μ’ ἐπιτρέπειν σοι, Ὀλυμπιόδωρε, ἐν τῷ τελευταίῳ ἀγῶνι τῷ περὶ τοῦ κλήρου, ἢ ἃ ἔλεγες πρὸς τοὺς δικαστάς, εἰκῇ οὑτωσὶ λέγειν, ἢ περὶ ὧν τὰς μαρτυρίας παρέσχου, οὕτως ἂν παρασχέσθαι, εἰ μὴ μετὰ σοῦ κοινῇ συνηγωνιζόμην;", "st": "48.43"}, {"sp": "N", "t": "οὗτος γάρ, ὦ ἄνδρες δικασταί, τά τε ἄλλα ἔλεγεν ὅ τι ἐβούλετο ἐν τῷ δικαστηρίῳ, καὶ κατεχρήσατο πρὸς τοὺς δικαστὰς ὅτι ἐγὼ τὴν οἰκίαν, ἣν ἔλαβον ἐν τῇ μερίδι τῇ ἐμαυτοῦ, μεμισθωμένος εἴην παρ’ αὐτοῦ, καὶ τὸ ἀργύριον ὃ ἔλαβον, τὸ ἥμισυ τὸ ἀπὸ τῶν χιλίων δραχμῶν τῶν παρὰ τοῦ οἰκέτου, ὅτι ἐδανεισάμην παρὰ τούτου. καὶ οὐ μόνον ἔλεγεν ταῦτα, ἀλλὰ καὶ μαρτυρίας παρείχετο περὶ τούτων. κἀγὼ οὐδ’ ὁτιοῦν ἀντέλεγον τούτοις, οὐδ’ ἤκουσέ μου φωνὴν οὐδεὶς ἀνθρώπων, ὅτε οὗτος ἠγωνίζετο, οὔτε μικρὰν οὔτε μεγάλην, ἀλλὰ προσωμολόγουν ἀληθῆ εἶναι πάντα ὅσα οὗτος ἐβούλετο λέγειν. κοινῇ γὰρ ἠγωνιζόμην μετὰ σοῦ, ὥσπερ ἔδοξεν ἐμοὶ καὶ σοί.", "st": "48.44"}, {"sp": "N", "t": "ἐπεὶ εἰ μή ἐστιν ταῦτα ἀληθῆ ἃ λέγω, διὰ τί οὐκ ἐπεσκηψάμην ἐγὼ τότε τοῖς μάρτυσιν τοῖς ταῦτα μαρτυροῦσιν, ἀλλ’ ἡσυχίαν εἶχον πολλήν; ἢ διὰ τί σύ, Ὀλυμπιόδωρε, οὐδεπώποτέ μοι ἔλαχες ἐνοικίου δίκην τῆς οἰκίας ἧς ἔφασκες μισθῶσαί μοι ὡς σαυτοῦ οὖσαν, οὐδὲ τοῦ ἀργυρίου οὗ ἔλεγες πρὸς τοὺς δικαστὰς ὅτι ἐδάνεισάς μοι, τούτων οὐδὲν ἐποίησας; ὥστε πῶς ἂν μᾶλλον ἄνθρωπος ἐξελέγχοιτο ψευδόμενος καὶ ὑπεναντία λέγων αὐτὸς αὑτῷ καὶ αἰτιώμενος τὰ οὐδεπώποτε γενόμενα;", "st": "48.45"}, {"sp": "N", "t": "ὃ δὲ πάντων μέγιστόν ἐστιν, ὦ ἄνδρες δικασταί, ᾧ καὶ γνώσεσθε τουτονὶ ὅτι ἄδικός ἐστιν καὶ πλεονέκτης ἄνθρωπος· ἐχρῆν γὰρ αὐτόν, εἴ τι ἀληθὲς ἦν ὧν λέγει, πρότερον ταῦτα λέγειν καὶ ἐπιδεικνύειν, πρὶν τὸν ἀγῶνα γενέσθαι καὶ διαπειραθῆναι τῶν δικαστῶν ὅ τι γνώσονται, καὶ παραλαβόντα πολλοὺς μάρτυρας ἀξιοῦν ἀναιρεῖσθαι τὰς συνθήκας παρὰ τοῦ Ἀνδροκλείδου ὡς παραβαίνοντος ἐμοῦ καὶ τἀναντία πράττοντος ἑαυτῷ καὶ οὐκέτι κυρίων οὐσῶν τῶν συνθηκῶν ἐμοὶ καὶ τούτῳ, καὶ τῷ Ἀνδροκλείδῃ τῷ ἔχοντι τὰς συνθήκας διαμαρτύρασθαι, ὅτι αὐτῷ οὐδέν ἐστιν ἔτι πρᾶγμα πρὸς τὰς συνθήκας ταύτας.", "st": "48.46"}, {"sp": "N", "t": "ταῦτα ἐχρῆν αὐτόν, ὦ ἄνδρες δικασταί, εἴπερ τι ἦν ἀληθὲς ὧν λέγει, καὶ μόνον προσιόντα τῷ Ἀνδροκλείδῃ διαμαρτύρεσθαι καὶ μετὰ μαρτύρων πολλῶν, ἵν’ αὐτῷ πολλοὶ ἦσαν οἱ συνειδότες. ὅτι δὲ τούτων οὐδὲν πώποτε ἐποίησεν, αὐτοῦ ὑμῖν τοῦ Ἀνδροκλείδου, παρ’ ᾧ εἰσιν αἱ συνθῆκαι κείμεναι μαρτυρίαν ἀναγνώσεται. λέγε τὴν μαρτυρίαν.", "st": "48.47"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "48.47"}, {"sp": "N", "t": "ἕτερον δ’, ὦ ἄνδρες δικασταί, σκέψασθε ὃ διαπέπρακται. ἐγὼ γὰρ τοῦτον προὐκαλεσάμην καὶ ἠξίωσα ἀκολουθῆσαι ὡς Ἀνδροκλείδην, παρ’ ᾧ κεῖνται αἱ συνθῆκαι, καὶ κοινῇ ἐκγραψαμένους ἡμᾶς τὰς συνθήκας πάλιν σημήνασθαι, τὰ δὲ ἀντίγραφα ἐμβαλέσθαι εἰς τὸν ἐχῖνον, ὅπως ἂν μηδεμία ὑποψία ᾖ, ἀλλ’ ὑμεῖς ἅπαντα καλῶς καὶ δικαίως ἀκούσαντες γνῶτε ὅ τι ἂν ὑμῖν δικαιότατον δοκῇ εἶναι.", "st": "48.48"}, {"sp": "N", "t": "ταῦτα ἐμοῦ προκαλουμένου οὐκ ἠθέλησεν τούτων οὐδὲν ποιῆσαι, ἀλλ’ οὕτω πεφιλοσόφηκεν ὥστε μὴ εἶναι ὑμᾶς ἀκοῦσαι τῶν συνθηκῶν ἐκ τῶν κοινῶν γραμμάτων. καὶ ὅτι ταῦτα προὐκαλούμην, τούτων ὑμῖν μαρτυρίαν ἀναγνώσεται ὧν ἐναντίον προὐκαλούμην. λέγε τὴν μαρτυρίαν.", "st": "48.49"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "48.49"}, {"sp": "N", "t": "πῶς ἂν οὖν μᾶλλον καταφανὴς γένοιτο ἄνθρωπος, ὅτι δικαίως μὲν οὐδὲν βούλεται πρός με πράττειν, ἀποστερήσειν δ’ οἴεται ἃ προσήκει ἐμοὶ λαβεῖν, προφάσεις λέγων καὶ ἐγκλήματα ἐγκαλῶν, τὰς δὲ συνθήκας, ἅς φησί με παραβεβηκέναι, οὐκ ᾠήθη δεῖν ὑμᾶς ἀκοῦσαι; ἐγὼ δὲ τότε μὲν ἐναντίον τῶν μαρτύρων τῶν παραγενομένων προὐκαλεσάμην, νυνὶ δὲ καὶ ὑμῶν ἐναντίον τῶν δικαστῶν πάλιν προκαλοῦμαι, καὶ ἀξιῶ συγχωρεῖν αὐτὸν καὶ ἐγὼ συγχωρῶ ἀνοιχθῆναι τὰς συνθήκας ἐνταυθὶ ἐπὶ τοῦ δικαστηρίου, καὶ ἀκοῦσαι ὑμᾶς, καὶ πάλιν σημανθῆναι ἐναντίον ὑμῶν.", "st": "48.50"}, {"sp": "N", "t": "Ἀνδροκλείδης δὲ οὑτοσὶ πάρεστιν. ἐγὼ γὰρ αὐτῷ ἐπήγγειλα ἥκειν ἔχοντι τὰς συνθήκας. καὶ συγχωρῶ, ὦ ἄνδρες δικασταί, ἐν τῷ τούτου λόγῳ ἢ ἐν τῷ προτέρῳ ἢ ἐν τῷ ὑστέρῳ ἀνοιχθῆναι· οὐδὲν γάρ μοι διαφέρει. ὑμᾶς δὲ βούλομαι ἀκοῦσαι τὰς συνθήκας καὶ τοὺς ὅρκους, οὓς ὠμόσαμεν ἀλλήλοις ἐγὼ καὶ Ὀλυμπιόδωρος οὑτοσί. καὶ εἰ μὲν συγχωρεῖ, ἔστω ταῦτα, καὶ ὑμεῖς ἀκούετε, ἐπειδὰν τούτῳ δοκῇ· ἐὰν δὲ μὴ ’θέλῃ ταῦτα ποιεῖν, οὐκ ἤδη καταφανὴς ἔσται, ὦ ἄνδρες δικασταί, ὅτι ἀναισχυντότατός ἐστιν ἀνθρώπων ἁπάντων, καὶ δικαίως οὐδ’ ἂν ὁτιοῦν ἀποδέχοισθε τούτου ὡς ὑγιές τι λέγοντος;", "st": "48.51"}, {"sp": "N", "t": "ἀλλὰ τί ταῦτα σπουδάζω; οὐδὲ γὰρ αὐτὸς ἀγνοεῖ ταῦτα οὗτος, ὅτι ἀδικεῖ μὲν ἐμέ, ἀδικεῖ δὲ τοὺς θεοὺς οὓς ὤμοσεν, καὶ ἐπιορκεῖ. ἀλλὰ διέφθαρται, ὦ ἄνδρες δικασταί, καὶ παραφρονεῖ. ἀνιῶμαι μὲν οὖν καὶ αἰσχύνομαι, ὦ ἄνδρες δικασταί, οἷς μέλλω λέγειν πρὸς ὑμᾶς, ἐξ ἀνάγκης δέ μοί ἐστιν εἰπεῖν, ὅπως ἂν ὑμεῖς οἱ τὴν ψῆφον ἔχοντες ἀκούσαντες ἅπαντα, βουλεύσησθε ὅ τι ἂν ὑμῖν δοκῇ βέλτιστον εἶναι περὶ ἡμῶν.", "st": "48.52"}, {"sp": "N", "t": "ὧν δὲ μέλλω λέγειν, οὗτος αἴτιός ἐστιν οὐκ ἐθέλων ἐν τοῖς οἰκείοις περὶ τούτων πρός με διαλύσασθαι, ἀλλ’ ἀναισχυντῶν. Ὀλυμπιόδωρος γὰρ οὑτοσί, ὦ ἄνδρες δικασταί, γυναῖκα μὲν ἀστὴν κατὰ τοὺς νόμους τοὺς ὑμετέρους οὐδεπώποτε ἔγημεν, οὐδ’ εἰσὶν αὐτῷ παῖδες οὐδὲ ἐγένοντο, ἑταίραν δὲ λυσάμενος ἔνδον ἔχει, καὶ αὕτη ἐστὶν ἡ λυμαινομένη ἅπαντας ἡμᾶς καὶ ποιοῦσα τουτονὶ περαιτέρω μαίνεσθαι.", "st": "48.53"}, {"sp": "N", "t": "πῶς γὰρ οὐ μαίνεται ὅστις οἴεται δεῖν, ἃ μὲν ὡμολόγησεν καὶ συνέθετο ἑκὼν πρὸς ἑκόντα καὶ ὤμοσεν, τούτων μὲν μηδ’ ὁτιοῦν ποιεῖν, καὶ ταῦτα ἐμοῦ σπουδάζοντος οὐχ ὑπὲρ ἐμαυτοῦ μόνον, ἀλλὰ καὶ ὑπὲρ τῆς τούτου ἀδελφῆς ⟨τῆς⟩ ὁμοπατρίας καὶ ὁμομητρίας, ἣ ἐμοὶ συνοικεῖ, καὶ ὑπὲρ τῆς τούτου ἀδελφιδῆς, θυγατρὸς δὲ ἐμῆς; αὗται γάρ εἰσιν αἱ ἀδικούμεναι οὐχ ἧττον ἐμοῦ, ἀλλὰ καὶ μᾶλλον.", "st": "48.54"}, {"sp": "N", "t": "πῶς γὰρ οὐκ ἀδικοῦνται ἢ πῶς οὐ δεινὰ πάσχουσιν, ἐπειδὰν ὁρῶσι τὴν μὲν τούτου ἑταίραν περαιτέρω τοῦ καλῶς ἔχοντος καὶ χρυσία πολλὰ ἔχουσαν καὶ ἱμάτια καλά, καὶ ἐξόδους λαμπρὰς ἐξιοῦσαν, καὶ ὑβρίζουσαν ἐκ τῶν ἡμετέρων, αὐταὶ δὲ καταδεεστέρως περὶ ταῦτα ἔχωσιν ἅπαντα, πῶς οὐκ ἐκεῖναι μᾶλλον ἔτι ἀδικοῦνται ἢ ἐγώ; οὗτος δὲ πῶς οὐ καταφανῶς μαίνεται καὶ παραφρονεῖ, τοιαῦτα περὶ αὑτοῦ βουλευόμενος; ἵνα δὲ μὴ φάσκῃ, ὦ ἄνδρες δικασταί, ἐπὶ διαβολῇ ταῦτα λέγειν με τοῦ ἀγῶνος ἕνεκα τουτουί, μαρτυρίαν ὑμῖν ἀναγνώσεται τῶν τούτου οἰκείων καὶ ἐμῶν.", "st": "48.55"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "48.55"}, {"sp": "N", "t": "Ὀλυμπιόδωρος μὲν οὑτοσὶ τοιοῦτός ἐστιν ἄνθρωπος, οὐ μόνον ἄδικος, ἀλλὰ καὶ μελαγχολᾶν δοκῶν ἅπασιν τοῖς οἰκείοις καὶ τοῖς γνωρίμοις τῇ προαιρέσει τοῦ βίου, καὶ ὅπερ Σόλων ὁ νομοθέτης λέγει, παραφρονῶν ὡς οὐδεὶς πώποτε παρεφρόνησεν ἀνθρώπων, γυναικὶ πειθόμενος πόρνῃ. καὶ ἄκυρά γε ταῦτα πάντα ἐνομοθέτησεν εἶναι ὁ Σόλων, ὅ τι ἄν τις γυναικὶ πειθόμενος πράττῃ, ἄλλως τε καὶ τοιαύτῃ.", "st": "48.56"}, {"sp": "N", "t": "περὶ μὲν οὖν τούτων καλῶς ὁ νομοθέτης ἐπεμελήθη, ἐγὼ δὲ ὑμῶν δέομαι, καὶ οὐ μόνον ἐγώ, ἀλλὰ καὶ ἡ ἐμὴ γυνή, Ὀλυμπιοδώρου δὲ τουτουὶ ἀδελφή, καὶ ἡ θυγάτηρ ἡ ἐμή, Ὀλυμπιοδώρου δὲ τουτουὶ ἀδελφιδῆ, ἱκετεύομεν ὑμᾶς καὶ ἀντιβολοῦμεν, ὦ ἄνδρες δικασταί, ἅπαντες ἡμεῖς (νομίσατε γὰρ ἐκείνας ἐνθάδε παρεῖναι)", "st": "48.57"}, {"sp": "N", "t": "μάλιστα μὲν τουτονὶ Ὀλυμπιόδωρον πεῖσαι μὴ ἀδικεῖν ἡμᾶς, ἐὰν δ’ ἄρα μὴ ’θέλῃ πείθεσθαι, ὑμᾶς μεμνημένους ἁπάντων τῶν εἰρημένων ψηφίζεσθαι ὅ τι ἂν ὑμῖν δοκῇ βέλτιστον καὶ δικαιότατον εἶναι. καὶ ταῦτα ποιοῦντες τά τε δίκαια γνώσεσθε καὶ τὰ συμφέροντα ἡμῖν ἅπασιν, οὐχ ἥκιστα δὲ Ὀλυμπιοδώρῳ αὐτῷ τουτῳί.", "st": "48.58"}, {"sp": "HDR", "t": "Πρὸς Τιμόθεον ὑπὲρ χρέως", "st": "49"}, {"sp": "N", "t": "μηδενὶ ὑμῶν ἄπιστον γενέσθω, ὦ ἄνδρες δικασταί, εἰ Τιμόθεος ὀφείλων ἀργύριον τῷ πατρὶ τῷ ἐμῷ φεύγει νῦν ὑπ’ ἐμοῦ ταύτην τὴν δίκην. ἀλλ’ ἐπειδὰν ὑμᾶς ἀναμνήσω τόν τε καιρὸν ἐν ᾧ τὸ συμβόλαιον ἐγένετο, καὶ τὰ συμβάντα τούτῳ ἐν ἐκείνῳ τῷ χρόνῳ, καὶ εἰς ὅσην ἀπορίαν κατέστη οὗτος, τότε ἡγήσεσθε τὸν μὲν πατέρα τὸν ἐμὸν βέλτιστον γενέσθαι περὶ Τιμόθεον, τοῦτον δὲ οὐ μόνον ἀχάριστον εἶναι, ἀλλὰ καὶ ἀδικώτατον πάντων ἀνθρώπων,", "st": "49.1"}, {"sp": "N", "t": "ὅς γε τυχὼν παρὰ τοῦ πατρὸς τοῦ ἐμοῦ ὅσων ἐδεήθη καὶ λαβὼν ἀργύριον ἀπὸ τῆς τραπέζης, ἐν πολλῇ ἀπορίᾳ ὢν κἀν κινδύνοις τοῖς μεγίστοις καθεστηκὼς περὶ τῆς ψυχῆς, οὐ μόνον οὐκ ἀπέδωκε χάριν, ἀλλὰ καὶ τὸ δοθὲν ἀποστερεῖ με. καίτοι σφαλέντος μὲν τούτου ἀπώλλυτο καὶ τῷ πατρὶ τῷ ἐμῷ τὸ συμβόλαιον· οὔτε γὰρ ἐπ’ ἐνεχύρῳ οὔτε μετὰ μαρτύρων ἔδωκεν· σωθέντος δὲ ἐπὶ τούτῳ ἐγίγνετο, ὁπότε βούλοιτο εὐπορήσας ἡμῖν ἀποδοῦναι.", "st": "49.2"}, {"sp": "N", "t": "ἀλλ’ ὅμως, ὦ ἄνδρες δικασταί, οὐ περὶ πλείονος ἐποιήσατο ὁ πατὴρ περιουσίαν χρημάτων μᾶλλον ἢ οὐ Τιμοθέῳ ὑπηρετῆσαι ὧν ἐδεήθη αὐτοῦ, ἐν ἀπορίᾳ ὄντι. ᾤετο μὲν οὖν, ὦ ἄνδρες δικασταί, ὁ πατήρ, εἰ σωθείη Τιμόθεος τότε ἐξ ἐκείνων τῶν κινδύνων καὶ ἀφίκοιτο οἴκαδε παρὰ βασιλέως, εὐπορωτέρου γενομένου τούτου ἢ ὡς τότε διέκειτο, οὐ μόνον τὰ ἑαυτοῦ κομιεῖσθαι, ἀλλὰ καὶ ἄλλου εἴ του δέοιτο πρὸς Τιμόθεον πρᾶξαι ὑπάρξειν αὑτῷ.", "st": "49.3"}, {"sp": "N", "t": "ἐπειδὴ δὲ οὐχ ὡς ἐκεῖνος ᾠήθη συμβέβηκεν, ἀλλ’ ἃ μετὰ χάριτος ἔλαβεν Τιμόθεος ἀπὸ τῆς τραπέζης δεηθεὶς τοῦ πατρὸς τοῦ ἐμοῦ, ταῦτα δι’ ἔχθρας καὶ δίκης τετελευτηκότος ἐκείνου ἐξελεγχθεὶς μὲν ὡς ὀφείλει οἴεται δεῖν ἀποδοῦναι, ἐὰν δὲ δύνηται ὑμᾶς πεῖσαι ὡς οὐκ ὀφείλει, ἐξαπατήσας τῷ λόγῳ, ἀποστερῆσαι ἡμᾶς τῶν χρημάτων, ἀναγκαῖόν μοι δοκεῖ εἶναι ἐξ ἀρχῆς ἅπαντα διηγήσασθαι ὑμῖν, τά τε ὀφειλόμενα, καὶ εἰς ὅ τι ἕκαστον αὐτῶν κατεχρήσατο, καὶ τοὺς χρόνους ἐν οἷς τὸ συμβόλαιον ἐγένετο.", "st": "49.4"}, {"sp": "N", "t": "θαυμάσῃ δὲ μηδεὶς ὑμῶν εἰ ἀκριβῶς ἴσμεν· οἱ γὰρ τραπεζῖται εἰώθασιν ὑπομνήματα γράφεσθαι ὧν τε διδόασιν χρημάτων καὶ εἰς ὅ τι καὶ ὧν ἄν τις τιθῆται, ἵνα ᾖ αὐτοῖς γνώριμα τά τε ληφθέντα καὶ τὰ τεθέντα πρὸς τοὺς λογισμούς.", "st": "49.5"}, {"sp": "N", "t": "ἐπὶ Σωκρατίδου γὰρ ἄρχοντος μουνιχιῶνος μηνὸς μέλλων ἐκπλεῖν τὸν ὕστερον ἔκπλουν Τιμόθεος οὑτοσί, περὶ ἀναγωγὴν ἤδη ὢν ἐν τῷ Πειραιεῖ, προσδεηθεὶς ἀργυρίου, προσελθὼν τῷ πατρὶ τῷ ἐμῷ ἐν τῷ λιμένι, ἐκέλευσεν αὐτὸν χρῆσαι χιλίας τριακοσίας πεντήκοντα μίαν δύ’ ὀβολώ· τοσούτου γὰρ ἔφη προσδεῖσθαι· καὶ δοῦναι ἐκέλευσεν Ἀντιμάχῳ τῷ ταμίᾳ τῷ ἑαυτοῦ, ὃς τούτῳ διῴκει τότε πάντα.", "st": "49.6"}, {"sp": "N", "t": "καὶ ὁ μὲν δανεισάμενος τὸ ἀργύριον παρὰ τοῦ πατρὸς τοῦ ἐμοῦ Τιμόθεος ἦν καὶ κελεύσας δοῦναι Ἀντιμάχῳ τῷ ταμίᾳ τῷ ἑαυτοῦ, ὁ δὲ λαβὼν τὸ ἀργύριον ἀπὸ τῆς τραπέζης παρὰ Φορμίωνος Αὐτόνομος, ὅσπερ Ἀντιμάχῳ διετέλει γραμματεύων τὸν ἅπαντα χρόνον.", "st": "49.7"}, {"sp": "N", "t": "δοθέντος τοίνυν τοῦ ἀργυρίου τούτου ἐγράψατο μὲν ὀφείλοντα τὸν κελεύσαντα χρῆσαι Τιμόθεον, ὑπόμνημα δὲ ἐγράψατο, ᾧ τε οὗτος ἐκέλευσε δοῦναι, Ἀντιμάχῳ, καὶ ὃν ὁ Ἀντίμαχος συνέπεμψεν ἐπὶ τὴν τράπεζαν ληψόμενον τὸ ἀργύριον, τὸν Αὐτόνομον, τὰς χιλίας τριακοσίας δραχμὰς καὶ πεντήκοντα καὶ μίαν καὶ δύ’ ὀβολώ. τὸ μὲν τοίνυν πρῶτον χρέως, ὃ ἐκπλέων ἔλαβεν στρατηγῶν τὸ ὕστερον, τοσοῦτον ὀφείλει.", "st": "49.8"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἀπεχειροτονήθη μὲν ὑφ’ ὑμῶν στρατηγὸς διὰ τὸ μὴ περιπλεῦσαι Πελοπόννησον, ἐπὶ κρίσει δὲ παρεδέδοτο εἰς τὸν δῆμον αἰτίας τῆς μεγίστης τυχών, ἐφειστήκει δὲ αὐτῷ Καλλίστρατος καὶ Ἰφικράτης, τῷ τε πράττειν καὶ εἰπεῖν δυνάμενοι, οὕτω δὲ διέθεσαν ὑμᾶς κατηγοροῦντες τούτου αὐτοί τε καὶ οἱ συναγορεύοντες αὐτοῖς,", "st": "49.9"}, {"sp": "N", "t": "ὥστε Ἀντίμαχον μὲν ταμίαν ὄντα καὶ πιστότατα διακείμενον τούτῳ κρίναντες ἐν τῷ δήμῳ ἀπεκτείνατε καὶ τὴν οὐσίαν αὐτοῦ ἐδημεύσατε, αὐτὸν δὲ τοῦτον ἐξαιτουμένων τῶν ἐπιτηδείων καὶ οἰκείων αὐτοῦ ἁπάντων, ἔτι δὲ καὶ Ἀλκέτου καὶ Ἰάσονος, συμμάχων ὄντων ὑμῖν, μόλις μὲν ἐπείσθητε ἀφεῖναι, στρατηγοῦντα δὲ αὐτὸν ἐπαύσατε,—", "st": "49.10"}, {"sp": "N", "t": "ἐν τοιαύταις δὲ ὢν διαβολαῖς καὶ ἀπορίᾳ χρημάτων πολλῇ (ἡ μὲν γὰρ οὐσία ὑπόχρεως ἦν ἅπασα, καὶ ὅροι αὐτῆς ἕστασαν, καὶ ἄλλοι ἐκράτουν· ὁ μὲν ἐν πεδίῳ ἀγρὸς ἀποτίμημα τῷ παιδὶ τῷ Εὐμηλίδου καθειστήκει, ἑξήκοντα δὲ τριηράρχοις τοῖς συνεκπλεύσασιν αὐτῷ ἑπτὰ μνῶν ἑκάστῳ ἡ ἄλλη οὐσία ὑπέκειτο, ἃς οὗτος αὐτοὺς στρατηγῶν ἠνάγκασε τοῖς ναύταις τροφὴν διαδοῦναι·", "st": "49.11"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἀποχειροτονηθεὶς ἐν τῷ λόγῳ ἀπήνεγκεν ἐκ τῶν στρατιωτικῶν χρημάτων αὐτὸς δεδωκὼς εἰς τὰς ναῦς τὰς ἑπτὰ μνᾶς ταύτας τότε, φοβούμενος μὴ καταμαρτυρήσωσιν αὑτοῦ οἱ τριήραρχοι καὶ ἐξελέγχηται ψευδόμενος, δάνεισμα ποιεῖται ἰδίᾳ παρ’ ἑκάστου αὐτῶν τὰς ἑπτὰ μνᾶς καὶ ὑποτίθησιν αὐτοῖς τὴν οὐσίαν, ἃς νῦν αὐτοὺς ἀποστερεῖ καὶ τοὺς ὅρους ἀνέσπακεν),", "st": "49.12"}, {"sp": "N", "t": "πανταχόθεν δὲ ἀπορούμενος, καὶ ἐν ἀγῶνι τῷ μεγίστῳ καθεστηκὼς περὶ τοῦ σώματος διὰ τὸ συμβεβηκέναι τῇ πόλει τοιαῦτα πράγματα, ἄμισθον μὲν τὸ στράτευμα καταλελύσθαι ἐν Καλαυρείᾳ, πολιορκεῖσθαι δὲ τοὺς περὶ Πελοπόννησον συμμάχους ὑπὸ Λακεδαιμονίων, κατηγορούντων δὲ τοῦτον αἴτιον εἶναι τῆς παρούσης ἀτυχίας Ἰφικράτους καὶ Καλλιστράτου, ἔτι δὲ τῶν ἀφικνουμένων ἀπὸ στρατεύματος ἀπαγγελλόντων ἐν τῷ δήμῳ τὴν παροῦσαν ἔνδειαν καὶ ἀπορίαν, τὰ δὲ καὶ δι’ ἐπιστολῶν ἑκάστου πυνθανομένου παρὰ τῶν οἰκείων καὶ ἐπιτηδείων ὡς διέκειντο (ὧν ἀκούοντες ὑμεῖς ἐν τῷ δήμῳ τότε ἀναμνήσθητε πῶς ἕκαστος περὶ αὐτοῦ τὴν γνώμην εἶχεν·", "st": "49.13"}, {"sp": "N", "t": "οὐ γὰρ ἀγνοεῖτε τὰ λεγόμενα), μέλλων τοίνυν καταπλεῖν ἐπὶ τὴν κρίσιν, ἐν Καλαυρείᾳ δανείζεται χιλίας δραχμὰς παρὰ Ἀντιφάνους τοῦ Λαμπτρέως, ὃς ἐπέπλει ταμίας Φιλίππῳ τῷ ναυκλήρῳ, ἵνα διαδοίη τοῖς Βοιωτίοις τριηράρχοις, καὶ παραμένωσιν ἕως ἂν αὐτῷ ἡ κρίσις γένηται, καὶ μὴ καταλυθεισῶν πρότερον τῶν Βοιωτίων τριήρων καὶ διαπελθόντων τῶν στρατιωτῶν μᾶλλον αὐτῷ ὀργίζησθε ὑμεῖς.", "st": "49.14"}, {"sp": "N", "t": "οἱ μὲν γὰρ πολῖται ἠνείχοντο κακοπαθοῦντες καὶ παρέμενον· οἱ δὲ Βοιωτοὶ οὐκ ἔφασαν παραμενεῖν, εἰ μή τις αὐτοῖς τὴν καθ’ ἡμέραν τροφὴν δώσει. τότε οὖν ἀναγκαζόμενος δανείζεται τὰς χιλίας δραχμὰς παρὰ τοῦ Ἀντιφάνους, ὃς ἐπέπλει ταμιεύων Φιλίππῳ τῷ ναυκλήρῳ, καὶ δίδωσι τῷ Βοιωτίῳ ἄρχοντι τῶν νεῶν.", "st": "49.15"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἀφίκετο δεῦρο, ἀπῄτουν αὐτὸν ὅ τε Φίλιππος καὶ Ἀντιφάνης τὰς χιλίας δραχμὰς ἃς ἐδανείσατο ἐν Καλαυρείᾳ, καὶ ἠγανάκτουν ὅτι οὐ ταχὺ ἀπελάμβανον. φοβούμενος δὲ οὗτος τοὺς ἐχθροὺς τοὺς ἑαυτοῦ, μὴ πύθοιντο ὅτι, ἃς ἐν τῷ λόγῳ ἀπήνεγκεν χιλίας δραχμὰς δεδωκὼς εἰς τὰς Βοιωτίας ναῦς ἐκ τῶν στρατιωτικῶν χρημάτων,", "st": "49.16"}, {"sp": "N", "t": "ταύτας Φίλιππος δανείσας ἀποστερεῖται, καὶ ἅμα δεδιὼς τὸν Φίλιππον, μὴ καταμαρτυροίη αὑτοῦ ἐν τῷ ἀγῶνι, προσελθὼν τῷ πατρὶ τῷ ἐμῷ ἐδεήθη ἀπαλλάξαι τὸν Φίλιππον καὶ χρῆσαι αὑτῷ τὰς χιλίας δραχμάς, ἵνα ἀποδοίη Φιλίππῳ. ὁρῶν δὲ ὁ πατὴρ ὁ ἐμὸς τό τε μέγεθος τοῦ ἀγῶνος ἡλίκον ἦν τούτῳ, καὶ ὡς ἠπορεῖτο οὗτος, καὶ ἐλεῶν αὐτόν, προσαγαγὼν πρὸς τὴν τράπεζαν ἐκέλευσεν ἀποδοῦναι Φιλίππῳ χιλίας δραχμὰς τὸν Φορμίωνα τὸν ἐπικαθήμενον ἐπὶ τῇ τραπέζῃ, καὶ γράψαι ὀφείλοντα Τιμόθεον.", "st": "49.17"}, {"sp": "N", "t": "καὶ ταῦτα ὅτι ἀληθῆ ἐστιν, τὸν δόντα τὸ ἀργύριον Φορμίωνα ὑμῖν μάρτυρα παρέξομαι, ἐπειδὰν καὶ περὶ τοῦ ἄλλου συμβολαίου διηγήσωμαι ὑμῖν, ἵνα τῇ αὐτῇ μαρτυρίᾳ περὶ ὅλου τοῦ χρέως ἀκούσαντες εἰδῆτε ὅτι ἀληθῆ λέγω. καλῶ δ’ ὑμῖν καὶ τὸν Ἀντιφάνην τὸν δανείσαντα τὸ ἀργύριον τούτῳ, τὰς χιλίας δραχμάς, ἐν Καλαυρείᾳ, καὶ παρόντα ὅτε ἀπέλαβε Φίλιππος τὸ ἀργύριον παρὰ τοῦ πατρὸς τοῦ ἐμοῦ ἐνθάδε.", "st": "49.18"}, {"sp": "N", "t": "τοῦ μὲν γὰρ μαρτυρίαν με ἐμβαλέσθαι πρὸς τὸν διαιτητὴν παρεκρούσατο, φάσκων ἀεί μοι μαρτυρήσειν εἰς τὴν κυρίαν· ἐπειδὴ δὲ ἡ δίαιτα ἦν, προσκληθεὶς ἀπὸ τῆς οἰκίας (οὐ γὰρ ἦν φανερός), ἔλιπε τὴν μαρτυρίαν πεισθεὶς ὑπὸ τούτου. τιθέντος δέ μου αὐτῷ τὴν δραχμὴν τοῦ λιπομαρτυρίου κατὰ τὸν νόμον, ὁ διαιτητὴς οὐ κατεδιῄτα, ἀλλ’ ἀπιὼν ᾤχετο ἀποδιαιτήσας τούτου τὴν δίαιταν, ἑσπέρας ἤδη οὔσης.", "st": "49.19"}, {"sp": "N", "t": "νυνὶ δὲ τῷ Ἀντιφάνει εἴληχα βλάβης ἰδίαν δίκην, ὅτι μοι οὔτ’ ἐμαρτύρησεν οὔτ’ ἐξωμόσατο κατὰ τὸν νόμον. καὶ ἀξιῶ αὐτὸν ἀναβάντα εἰπεῖν ἐναντίον ὑμῶν διομοσάμενον, πρῶτον μὲν εἰ ἐδάνεισε Τιμοθέῳ ἐν Καλαυρείᾳ χιλίας δραχμάς, δεύτερον δ’ εἰ παρὰ τοῦ πατρὸς Φίλιππος ἀπέλαβεν ἐνθάδε τοῦτο τὸ ἀργύριον.", "st": "49.20"}, {"sp": "N", "t": "σχεδὸν μὲν οὖν καὶ αὐτὸς οὗτος ὡμολόγει πρὸς τῷ διαιτητῇ ἀποδοῦναι τῷ Φιλίππῳ τὸν πατέρα τὸν ἐμὸν τὰς χιλίας δραχμάς, οὐ μέντοι αὑτῷ γέ φησιν δανεῖσαι, ἀλλὰ τῷ Βοιωτίῳ ναυάρχῳ, καὶ ὑποθεῖναί φησιν αὐτὸν τούτου τοῦ ἀργυρίου χαλκόν. ὡς δὲ οὐκ ἀληθῆ ἔλεγεν, ἀλλ’ αὐτὸς δανεισάμενος ἀποστερεῖ, ἐγὼ ὑμᾶς διδάξω, ἐπειδὰν καὶ περὶ τῶν ἄλλων ὧν ὀφείλει καθ’ ἕκαστον ὑμῖν διηγήσωμαι.", "st": "49.21"}, {"sp": "N", "t": "ἀφικομένου γὰρ Ἀλκέτου καὶ Ἰάσονος ὡς τοῦτον ἐν τῷ μαιμακτηριῶνι μηνὶ τῷ ἐπ’ Ἀστείου ἄρχοντος ἐπὶ τὸν ἀγῶνα τὸν τούτου, βοηθησόντων αὐτῷ, καὶ καταγομένων εἰς τὴν οἰκίαν τὴν ἐν Πειραιεῖ τὴν ἐν τῇ Ἱπποδαμείᾳ ἑσπέρας ἤδη οὔσης, ἀπορούμενος ὑποδέξασθαι αὐτούς, πέμψας ὡς τὸν πατέρα τὸν ἐμὸν Αἰσχρίωνα τὸν ἀκόλουθον τὸν αὑτοῦ, ἐκέλευσεν αἰτήσασθαι στρώματα καὶ ἱμάτια καὶ φιάλας ἀργυρᾶς δύο, καὶ μνᾶν ἀργυρίου δανείσασθαι.", "st": "49.22"}, {"sp": "N", "t": "ἀκούσας δὲ ὁ πατὴρ ὁ ἐμὸς τοῦ Αἰσχρίωνος τοῦ ἀκολούθου τοῦ τούτου τούς τε ἀφιγμένους καὶ τὴν χρείαν εἰς ἣν ᾐτεῖτο, ἐφ’ ἅ τε ἦλθεν ἔχρησεν, καὶ τὴν μνᾶν τοῦ ἀργυρίου, ἣν ἐδανείζετο, ἐδάνεισεν. ἀπολελυμένῳ τοίνυν τῆς αἰτίας πολλὴ συνέβαινεν αὐτῷ μετὰ ταῦτα χρημάτων ἀπορία εἴς τε τὰς ἰδίας χρείας καὶ εἰς τὰς δημοσίας εἰσφοράς, ἃ ὁρῶν ὁ πατὴρ ὁ ἐμὸς οὐκ ἐτόλμα τοῦτον εὐθὺς ἀπαιτεῖν τὸ ἀργύριον·", "st": "49.23"}, {"sp": "N", "t": "οὔτε γὰρ ἂν τοῦτον εὐπορήσανθ’ ἡγεῖτο ἀδικῆσαι αὑτόν, οὔτ’ ἂν αὐτὸς ἀποροῦντα τοῦτον ἔχειν ὁπόθεν εἰσπράξειεν. ἐπειδὴ τοίνυν ἀπῆλθον ὅ τε Ἀλκέτας καὶ ὁ Ἰάσων, τὰ μὲν στρώματα καὶ τὰ ἱμάτια πάλιν ἀπήνεγκεν ὁ Αἰσχρίων ὁ ἀκόλουθος ὁ τούτου, τὰς δὲ φιάλας τὰς δύο οὐκ ἀπήνεγκεν, ἃς ᾐτήσατο ὅτεπερ καὶ τὰ στρώματα καὶ τὴν μνᾶν τοῦ ἀργυρίου ἐδανείσατο, ἀφικομένων ὡς τοῦτον Ἀλκέτου καὶ Ἰάσονος.", "st": "49.24"}, {"sp": "N", "t": "μέλλων τοίνυν ἀποδημεῖν ὡς βασιλέα, καὶ διαπραξάμενος ἐκπλεῦσαι ὡς βασιλεῖ στρατηγήσων τὸν ἐπ’ Αἴγυπτον πόλεμον, ἵνα μὴ δῷ ἐνθάδε λόγον καὶ εὐθύνας τῆς στρατηγίας, μεταπεμψάμενος τὸν πατέρα τὸν ἐμὸν εἰς τὸ Παράλιον τῶν τε προϋπηργμένων εἰς αὑτὸν ἐπῄνει,", "st": "49.25"}, {"sp": "N", "t": "καὶ ἐδεῖτο αὐτοῦ συστήσας Φιλώνδαν, ἄνδρα τὸ μὲν γένος Μεγαρέα, μετοικοῦντα δ’ Ἀθήνησιν, πιστῶς δὲ τούτῳ διακείμενον καὶ ὑπηρετοῦντα ἐν ἐκείνῳ τῷ χρόνῳ, ἐπειδὰν ἀφίκηται ἐκ Μακεδονίας ὁ Φιλώνδας, ὃν συνίστη οὗτος τῷ πατρὶ τῷ ἐμῷ, ἄγων ξύλα τὰ δοθέντα τούτῳ ὑπὸ Ἀμύντου, τὸ ναῦλον τῶν ξύλων παρασχεῖν καὶ ἐᾶσαι ἀνακομίσαι τὰ ξύλα εἰς τὴν οἰκίαν τὴν ἑαυτοῦ τὴν ἐν Πειραιεῖ· αὑτοῦ γὰρ εἶναι τὰ ξύλα.", "st": "49.26"}, {"sp": "N", "t": "ἅμα τε τῇ δεήσει εἶπε λόγον, ᾧ οὐκ ἀκόλουθα ποιεῖ τὰ ἔργα νυνί· ἔφη γάρ, κἂν μὴ τύχῃ ὧν ἐδεῖτο τοῦ πατρός, οὐκ ὀργισθήσεσθαι ὥσπερ ἂν ἄλλος τις ἀποτυχών, ἀλλ’ ὧν αὑτῷ δεηθέντι ὑπηρέτηκεν, τούτων, ἄν ποτε δύνηται, χάριν ἀποδώσειν. ἀκούσας δὲ ὁ πατὴρ ὁ ἐμὸς ταῦτα ἥσθη τε τοῖς λόγοις, καὶ ἐπῄνει τοῦτον ὅτι μέμνηται εὖ παθών, καὶ ὅσα αὐτοῦ ἐδεῖτο ὑπέσχετο ποιήσειν.", "st": "49.27"}, {"sp": "N", "t": "καὶ οὗτος μὲν μετὰ ταῦτα τὴν ἀναγωγὴν ἐποιεῖτο ὡς τοὺς στρατηγοὺς τοὺς βασιλέως, ὁ δὲ Φιλώνδας, ᾧ συνέστησεν τὸν πατέρα τὸν ἐμόν, ἐπειδὰν ἀφίκηται ἄγων τὰ ξύλα, τὸ ναῦλον παρασχεῖν, εἰς τὴν Μακεδονίαν τὴν πορείαν ἐποιεῖτο. καὶ οὗτοι οἱ χρόνοι ἦσαν περὶ θαργηλιῶνα μῆνα ἐπ’ Ἀστείου ἄρχοντος.", "st": "49.28"}, {"sp": "N", "t": "τῷ δ’ ὑστέρῳ ἔτει ἀφικομένου τοῦ Φιλώνδου ἐκ τῆς Μακεδονίας ἄγοντος τὰ ξύλα, ἀποδημοῦντος τούτου παρὰ βασιλεῖ, καὶ προσελθόντος τῷ πατρὶ τῷ ἐμῷ καὶ κελεύοντος τὸ ναῦλον τῶν ξύλων παρασχεῖν, ἵνα διαλύσῃ τὸν ναύκληρον, καθάπερ οὗτος ἐδεήθη ὅτε ἐξέπλει τοῦ πατρὸς καὶ συνέστησε τὸν Φιλώνδαν, προσαγαγὼν πρὸς τὴν τράπεζαν ὁ πατὴρ ἐκέλευσε δοῦναι Φορμίωνα τὸ ναῦλον τῶν ξύλων, χιλίας ἑπτακοσίας πεντήκοντα.", "st": "49.29"}, {"sp": "N", "t": "καὶ ἠρίθμησε τὸ ἀργύριον Φορμίων· καὶ ἐγράψατο μὲν ὀφείλοντα Τιμόθεον (οὗτος γὰρ ἦν ὁ δεηθεὶς τοῦ πατρὸς παρασχεῖν τὸ ναῦλον τῶν ξύλων, καὶ τούτου ἦν), ὑπόμνημα δ’ ἐγράψατο τήν τε χρείαν εἰς ἣν ἐλήφθη τὸ ἀργύριον καὶ τὸ ὄνομα τοῦ λαβόντος. καὶ οὗτος ὁ χρόνος ἦν Ἀλκισθένους ἄρχοντος, ὁ ὕστερος ἐνιαυτὸς ἢ οὗτος ἀνήγετο ὡς βασιλέα.", "st": "49.30"}, {"sp": "N", "t": "ὑπὸ δὲ τὸν αὐτὸν χρόνον τοῦτον καὶ Τιμοσθένης ὁ Αἰγιλιεὺς ἀφικνεῖται κατ’ ἐμπορίαν ἰδίαν ἀποδημῶν. ἐπιτήδειος δὲ ὢν Φορμίωνι καὶ κοινωνὸς ὁ Τιμοσθένης, ὅτ’ ἐξέπλει, δίδωσιν ἀποθεῖναι τῷ Φορμίωνι μετ’ ἄλλων χρημάτων καὶ φιάλας λυκιουργεῖς δύο. ἀπὸ τύχης δὲ ὁ παῖς ταύτας τὰς φιάλας, οὐκ εἰδὼς ὅτι ἀλλότριαι ἦσαν, δίδωσι τῷ Αἰσχρίωνι τῷ ἀκολούθῳ τῷ τούτου, ὅτ’ ἐπέμφθη ὡς τὸν πατέρα τὸν ἐμὸν ὑπὸ τούτου, καὶ ᾐτεῖτο τὰ στρώματα καὶ τὰ ἱμάτια καὶ τὰς φιάλας, καὶ τὴν μνᾶν τοῦ ἀργυρίου ἐδανείσατο, ἀφικομένων ὡς τοῦτον Ἀλκέτου καὶ Ἰάσονος.", "st": "49.31"}, {"sp": "N", "t": "ἀπαιτοῦντος δὲ τοῦ Τιμοσθένους τὰς φιάλας τὸν Φορμίωνα, ἐπειδὴ ἧκεν, ἀποδημοῦντος Τιμοθέου παρὰ βασιλεῖ, πείθει αὐτὸν ὁ πατὴρ ὁ ἐμὸς τιμὴν ἀπολαβεῖν τῶν φιαλῶν, ὅσον ἦγον αἱ φιάλαι, διακοσίας τριάκοντα ἑπτά. καὶ τῷ μὲν Τιμοσθένει τιμὴν ἀπέδωκεν τῶν φιαλῶν, τοῦτον δὲ ἐγράψατο αὑτῷ ὀφείλοντα, πρὸς τὸ ἄλλο χρέως ὃ οὗτος αὐτῷ ὤφειλεν, ὃ ἀπέτεισεν τῷ Τιμοσθένει τῶν φιαλῶν.", "st": "49.32"}, {"sp": "N", "t": "καὶ ταῦτα πάντα ὅτι ἀληθῆ λέγω, τούτων ὑμῖν ἀναγνώσεται τὰς μαρτυρίας, πρῶτον μὲν τῶν δόντων τὸ ἀργύριον οἷς οὗτος ἐκέλευσεν ἀπὸ τῆς τραπέζης καὶ ἐπικαθημένων τότε, ἔπειτα τοῦ ἀπολαβόντος τὴν τιμὴν τῶν φιαλῶν.", "st": "49.33"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "49.33"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν οὐ ψεύδομαι πρὸς ὑμᾶς περὶ ὧν εἶπον, τῶν μαρτυριῶν ἀναγιγνωσκομένων ἀκηκόατε. ὅτι δέ μοι καὶ αὐτὸς οὗτος ὡμολόγει τὰ ξύλα τὰ κομισθέντα ὑπὸ Φιλώνδου εἰς τὴν οἰκίαν τὴν ἑαυτοῦ ἀνακομισθῆναι τὴν ἐν Πειραιεῖ, τούτων ὑμῖν ἀναγνώσεται τὴν μαρτυρίαν.", "st": "49.33"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "49.33"}, {"sp": "N", "t": "ὡς μὲν τοίνυν τούτου ἦν τὰ ξύλα ἃ ἤγαγεν ὁ Φιλώνδας, αὐτός μοι μεμαρτύρηκεν· ὡμολόγει γὰρ αὐτὰ πρὸς τῷ διαιτητῇ ἀνακομισθῆναι εἰς τὴν οἰκίαν τὴν ἑαυτοῦ τὴν ἐν Πειραιεῖ, ὡς μεμαρτύρηται ὑμῖν ὑπὸ τῶν ἀκουόντων. ἔτι δὲ καὶ ἐκ τεκμηρίων πειράσομαι ἐγὼ ὑμᾶς διδάξαι ὅτι ἀληθῆ λέγω.", "st": "49.34"}, {"sp": "N", "t": "οἴεσθε γάρ, ὦ ἄνδρες δικασταί, τὸν πατέρα τὸν ἐμόν, εἰ μὴ Τιμοθέου ἦν τὰ ξύλα καὶ ἐδεήθη οὗτος αὐτοῦ συστήσας τὸν Φιλώνδαν, ὅτε ἀνήγετο ὡς τοὺς στρατηγοὺς τοὺς βασιλέως, παρασχεῖν τὸ ναῦλον, ἐᾶσαι ἄν ποτε ὑποκειμένων αὐτῷ τῶν ξύλων τοῦ ναύλου ἀνακομίσαι τὸν Φιλώνδαν τὰ ξύλα ἐκ τοῦ λιμένος, ἀλλ’ οὐκ ἂν παρακαταστήσαντά τινα τῶν οἰκετῶν φυλάττειν καὶ τιμὴν λαμβάνειν τῶν πωλουμένων ξύλων, ἕως ἐκομίσατο τὰ ἑαυτοῦ, εἴπερ Φιλώνδου ἦν τὰ ξύλα καὶ ἐμπορίας ἕνεκα ἤχθη;", "st": "49.35"}, {"sp": "N", "t": "ἔπειτα πρὸς τούτοις τίνι ὑμῶν εἰκὸς δοκεῖ εἶναι, μὴ κελεύσαντος τούτου τὸ ναῦλον παρασχεῖν τῶν ξύλων τῶν δοθέντων τούτῳ ὑπὸ Ἀμύντου, πιστεῦσαι τὸν πατέρα τὸν ἐμὸν Φιλώνδᾳ καὶ ἐᾶσαι ἀνακομίσαι τὰ ξύλα ἐκ τοῦ λιμένος εἰς τὴν οἰκίαν τὴν τούτου; ἢ πῶς οἷόν τ’ ἐστὶν τὸν μὲν Φιλώνδαν ἐμπορίας ἕνεκα ἀγαγεῖν τὰ ξύλα, ὡς οὗτός φησιν, καταχρήσασθαι δὲ τοῦτον ἥκοντα εἰς τὴν οἰκοδομίαν τὴν αὑτοῦ τοῖς ξύλοις τούτοις;", "st": "49.36"}, {"sp": "N", "t": "σκέψασθε δὲ κἀκεῖνο, ὅτι πολλοὶ καὶ χρηστοὶ τῶν πολιτῶν οἰκεῖοι ὄντες τούτῳ ἐπεμελοῦντο τῶν τούτου, ἀποδημοῦντος παρὰ βασιλεῖ Τιμοθέου· ὧν οὐδεὶς τετόλμηκεν μαρτυρῆσαι τούτῳ ἢ ὡς οὐκ ἔλαβεν ὁ Φιλώνδας τὸ ναῦλον τῶν ξύλων ἀπὸ τῆς τραπέζης ἢ ὡς λαβὼν ἀπέδωκεν, οὐδ’ αὖ ὡς αὐτῶν τις διέλυσε τὸ ναῦλον ὑπὲρ τῶν ξύλων ὧν ἤγαγεν ὁ Φιλώνδας, δοθέντων τούτῳ παρ’ Ἀμύντου· ἡγοῦνται γὰρ περὶ πλείονος αὑτοῖς εἶναι καλοὶ κἀγαθοὶ δοκεῖν εἶναι μᾶλλον ἢ Τιμοθέῳ χαρίσασθαι τὰ ψευδῆ μαρτυροῦντες.", "st": "49.37"}, {"sp": "N", "t": "οὐ μέντοι οὐδὲ τούτου γ’ ἔφασαν καταμαρτυρῆσαι ἂν τἀληθῆ· οἰκεῖον γὰρ αὑτοῖς εἶναι. ὅπου τοίνυν μηδεὶς τετόλμηκε τῶν οἰκείων τούτῳ μαρτυρῆσαι καὶ ἐπιμελομένων τῶν τούτου, ὅτε ἀπεδήμει οὗτος παρὰ βασιλεῖ, ἢ ὡς οὐκ ἔλαβεν ὁ Φιλώνδας τὸ ναῦλον τῶν ξύλων ἀπὸ τῆς τραπέζης ἢ ὡς αὐτῶν τις διέλυσεν, πῶς οὐκ εἰκός ἐστιν ὑμᾶς ἡγεῖσθαί με τἀληθῆ λέγειν;", "st": "49.38"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ἐκεῖνό γε τολμήσει ⟨λέγειν⟩, ὡς ἄλλος τις διέλυσε τὸ ναῦλον ὑπὲρ τῶν ξύλων ὧν ἤγαγεν ὁ Φιλώνδας, ἢ ὁ πατὴρ ὁ ἐμός. ἐὰν δὲ καταχρῆται τῷ λόγῳ, ἀξιοῦτε αὐτὸν καὶ τὴν μαρτυρίαν παρασχέσθαι ὑμῖν τοῦ ἀποδόντος τὸ ναῦλον ὑπὲρ τῶν ξύλων. αὐτὸς μὲν γὰρ ὁμολογεῖται ἀποδημεῖν παρὰ βασιλεῖ, τὸν δὲ Φιλώνδαν, ὃν ἔπεμψεν ἐπὶ τὰ ξύλα καὶ συνέστησε τῷ πατρὶ τῷ ἐμῷ, τεθνηκότα κατέλαβες ἥκων παρὰ βασιλέως.", "st": "49.39"}, {"sp": "N", "t": "ἀναγκαῖον δὴ τῶν ἄλλων οἰκείων καὶ ἐπιτηδείων, οὓς κατέλιπες ἀποδημεῖν μέλλων συνεπιμελεῖσθαι τῶν σαυτοῦ, εἰδέναι τινὰ ὅθεν τὸ ναῦλον τῶν ξύλων πορίσας ὁ Φιλώνδας τῷ ναυκλήρῳ διέλυσεν, εἰ μὴ φὴς τὸν πατέρα τὸν ἐμὸν συστῆσαι αὐτῷ, μηδὲ λαβεῖν τὸν Φιλώνδαν παρὰ τοῦ πατρὸς τοῦ ἐμοῦ τὸ ναῦλον τῶν ξύλων.", "st": "49.40"}, {"sp": "N", "t": "μαρτυρίαν τοίνυν οὐδενὸς ἔχεις παρασχέσθαι τῶν οἰκείων τῶν σαυτοῦ, ὡς οὐκ ἐλήφθη σοῦ ἀποδημοῦντος τὸ ναῦλον τῶν ξύλων ἀπὸ τῆς τραπέζης, ἀλλὰ δυοῖν θάτερον, ἢ οὐδενὶ χρῇ τῶν οἰκείων οὐδὲ πιστεύεις τῶν σαυτοῦ οὐδενί, ἢ εἰδὼς ἀκριβῶς τὸν Φιλώνδαν λαβόντα τὸ ναῦλον τῶν ξύλων παρὰ τοῦ πατρὸς τοῦ ἐμοῦ, ᾧπερ αὐτὸν συνέστησας ὅτε ἐξέπλεις, οἴει δεῖν ἀποστερήσας ἡμᾶς, ἐὰν δύνῃ, πλεονεκτεῖν.", "st": "49.41"}, {"sp": "N", "t": "ἐγὼ τοίνυν, ὦ ἄνδρες δικασταί, πρὸς τῇ μαρτυρίᾳ, ἣν παρέσχημαι ὑμῖν μαρτυροῦντας τοὺς δόντας τὸ ἀργύριον οἷς οὗτος ἐκέλευσεν καὶ καθημένους ἐπὶ τῇ τραπέζῃ τότε, καὶ πίστιν ἠθέλησα ἐπιθεῖναι, ἣν ἀναγνώσεται ὑμῖν.", "st": "49.42"}, {"sp": "N", "t": "ΟΡΚΟΣ.", "st": "49.42"}, {"sp": "N", "t": "οὐ τοίνυν, ὦ ἄνδρες δικασταί, γράψας μοι ὁ πατὴρ κατέλιπεν τὰ χρέα μόνον, ἀλλὰ καὶ ἔλεγεν ἀρρωστῶν ὅ τι ὀφείλοιτο αὐτῷ ἕκαστον, καὶ παρ’ ᾧ, καὶ εἰς ὅ τι ἐλήφθη τὸ ἀργύριον, καὶ τῷ ἀδελφῷ τῷ ἐμῷ. καὶ ὡς ταῦτ’ ἀληθῆ λέγω, ἀνάγνωθί μοι τὴν μαρτυρίαν τοῦ ἀδελφοῦ.", "st": "49.42"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "49.42"}, {"sp": "N", "t": "ὡς μὲν τοίνυν κατελείφθη ὀφείλων Τιμόθεος ἡμῖν τὸ ἀργύριον ὑπὸ τοῦ πατρός, οὗ δικάζομαι αὐτῷ, καὶ γίγνεται ἐμὸν τὸ μέρος, ὅ τε ἀδελφός μοι μεμαρτύρηκεν καὶ ὁ Φορμίων ὁ δοὺς τὸ ἀργύριον, κἀγὼ τούτων πίστιν ἠθέλησα ἐπιθεῖναι. προκαλεσαμένου δὲ τούτου πρὸς τῷ διαιτητῇ καὶ κελεύοντος ἐνεγκεῖν τὰ γράμματα ἀπὸ τῆς τραπέζης καὶ ἀντίγραφα αἰτοῦντος, πέμψαντος Φρασιηρίδην ἐπὶ τὴν τράπεζαν, τῷ τε Φρασιηρίδῃ ἐξενέγκας ἔδωκα ζητεῖν τὰ γράμματα καὶ ἐκγράφεσθαι ὅσα οὗτος ὤφειλε, καὶ ὡς ὡμολόγει λαβεῖν οὗτος τὰ ἀντίγραφα, ἀνάγνωθί μοι τὴν μαρτυρίαν.", "st": "49.43"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "49.43"}, {"sp": "N", "t": "πρὸς τοίνυν τὸν διαιτητὴν κομίσαντός μου τὰ γράμματα, παρὼν ὁ Φορμίων καὶ ὁ Εὐφραῖος, οἱ δόντες τὸ ἀργύριον οἷς ἐκέλευσεν οὗτος, ἐξήλεγχον αὐτὸν ἐν οἷς τε χρόνοις ἕκαστον ἐδανείσατο, καὶ ὅστις ἔλαβε τὸ ἀργύριον, καὶ εἰς ἃ κατεχρήσατο. ὁ δὲ τὰς μὲν χιλίας καὶ τριακοσίας καὶ πεντήκοντα καὶ μίαν καὶ δύ’ ὀβολώ, ἃς πρώτας ἐδανείσατο τοῦ μουνιχιῶνος μηνὸς μέλλων ἐκπλεῖν ἐπὶ Σωκρατίδου ἄρχοντος, ἃς καὶ ἐκέλευσε δοῦναι Ἀντιμάχῳ τῷ ταμίᾳ τῷ ἑαυτοῦ, ἰδίᾳ ἔφη δανεῖσαι τὸν πατέρα Ἀντιμάχῳ καὶ οὐκ αὐτὸς λαβεῖν.", "st": "49.44"}, {"sp": "N", "t": "καὶ ὡς μὲν ἀληθῆ λέγει, οὐδένα μάρτυρα παρέσχηται, λόγῳ δὲ καταχρῆται, ἵνα μὴ αὐτὸς δοκῇ ἀποστερεῖν ἀλλ’ Ἀντίμαχος δανείσασθαι. καίτοι, ὦ ἄνδρες δικασταί, μέγα ὑμῖν ἐρῶ τεκμήριον ὅτι οὐκ Ἀντιμάχῳ ἐδάνεισεν ὁ πατὴρ τοῦτο τὸ ἀργύριον, ἀλλὰ Τιμοθέῳ περὶ ἀναγωγὴν ὄντι. πότερα γὰρ ἂν οἴεσθε ῥᾷον εἶναι τῷ πατρὶ δημευθέντων τῶν Ἀντιμάχου ἐνεπισκήψασθαι ἐν τῇ οὐσίᾳ τῇ ἐκείνου ἐνοφειλόμενον αὑτῷ τοῦτο τὸ ἀργύριον, εἴπερ Ἀντιμάχῳ ἐδάνεισεν,", "st": "49.45"}, {"sp": "N", "t": "ἢ ἀναμένειν ὁπότε παρὰ τούτου κομιεῖσθαι ἔμελλεν εὐπορήσαντος, ὃς οὐ πολλὰς ἐλπίδας σωτηρίας περὶ αὑτοῦ εἶχεν ἐν ἐκείνῳ τῷ χρόνῳ; καὶ μὴν ἐνεπισκηψάμενός γε οὔτ’ ἂν παρακαταβολῆς ἠπόρησεν οὔτ’ ἂν ἠπιστήθη ὑφ’ ὑμῶν (πάντες γὰρ ἴστε τὸν πατέρα τὸν ἐμὸν οὐ τῶν δημοσίων ἀδίκως ἐπιθυμοῦντα, ἀλλὰ τῶν αὑτοῦ ὑμῖν, ὅ τι κελεύσαιτε, προθύμως ἀναλίσκοντα),", "st": "49.46"}, {"sp": "N", "t": "εἶτα καὶ ἐπιτηδείου ὄντος αὐτῷ Καλλιστράτου, ὅσπερ ἐδήμευσεν τὰ Ἀντιμάχου, ὥστε μηδὲν ἐναντιοῦσθαι. ὥστε τί ἄν ποτε βουλόμενος ὁ πατὴρ ἐβούλετο Τιμόθεον χρήστην ἐγγράψας ἡμῖν καταλιπεῖν, εἴπερ μὴ ὤφειλεν τοῦτο τὸ ἀργύριον, μᾶλλον ἢ οὐκ ἐκ τῶν Ἀντιμάχου δημευθέντων ἐνεπισκηψάμενος κομίσασθαι;", "st": "49.47"}, {"sp": "N", "t": "περὶ δὲ τῶν χιλίων δραχμῶν, ἃς ἐδανείσατο παρὰ τοῦ Ἀντιφάνους ἐν Καλαυρείᾳ, ἵνα διαδοίη τοῖς Βοιωτίοις τριηράρχοις, μέλλων καταπλεῖν ἐπὶ τὴν κρίσιν, ἃς καὶ ἀπέδωκεν Φιλίππῳ τῷ ναυκλήρῳ ἐνθάδε λαβὼν παρὰ τοῦ πατρὸς τοῦ ἐμοῦ, τὸν Βοιώτιον ναύαρχόν φησι δανείσασθαι, καὶ ὑποθεῖναι τούτου τοῦ ἀργυρίου τῷ πατρὶ τῷ ἐμῷ χαλκόν.", "st": "49.48"}, {"sp": "N", "t": "ὡς δ’ οὐκ ἀληθῆ λέγει, μέγα ὑμῖν ἐρῶ τεκμήριον. πρῶτον μὲν γὰρ ἐν Καλαυρείᾳ οὗτος φαίνεται δανεισάμενος τὰς χιλίας δραχμὰς καὶ οὐχ ὁ Βοιώτιος ναύαρχος, ἔπειτα ἀπαιτῶν ὁ Φίλιππος ἐνθάδε τοῦτον τὰς χιλίας δραχμὰς καὶ οὐ τὸν Βοιώτιον ναύαρχον, καὶ ἀποδοὺς οὗτος, ἀλλ’ οὐχ ὁ Βοιώτιος ναύαρχος· προσῆκεν γὰρ τῷ μὲν Βοιωτίῳ ἄρχοντι παρὰ τούτου τὴν τροφὴν τοῖς ἐν ταῖς ναυσὶν λαμβάνειν· ἐκ γὰρ τῶν κοινῶν συντάξεων ἡ μισθοφορία ἦν τῷ στρατεύματι· τὰ δὲ χρήματα σὺ ἅπαντα ἐξέλεξας ἐκ τῶν συμμάχων, καὶ σὲ ἔδει αὐτῶν λόγον ἀποδοῦναι.", "st": "49.49"}, {"sp": "N", "t": "εἶτα καταλυθεισῶν τῶν Βοιωτίων νεῶν καὶ διαπελθόντων τῶν στρατιωτῶν τῷ μὲν Βοιωτίῳ ναυάρχῳ οὐδεὶς κίνδυνος ὑπ’ Ἀθηναίων ἦν, οὐδ’ ἐν ἀγῶνι καθειστήκει οὐδενί· σὺ δ’ ἐν τῷ μεγίστῳ· περίφοβος δὲ ὢν ἡγοῦ σοι μεγάλην ἐπικουρίαν ἀπολογίας ἔσεσθαι, ἐὰν παραμείνωσιν αἱ Βοιώτιαι τριήρεις, ἕως ἄν σοι ἡ κρίσις γένηται. ἔπειτα καὶ ἐκ τίνος ἂν φιλίας ποτὲ ἐδάνεισεν ὁ πατὴρ ὁ ἐμὸς τῷ Βοιωτίῳ ναυάρχῳ τὰς χιλίας δραχμάς, ὃν οὐκ ἐγίγνωσκεν;", "st": "49.50"}, {"sp": "N", "t": "ἀλλὰ γὰρ ὑποθέσθαι φησὶν αὐτὸν χαλκόν. πόσον τινὰ καὶ ποδαπόν; καὶ πόθεν γενόμενον τὸν χαλκὸν τοῦτον τῷ Βοιωτίῳ ναυάρχῳ; πότερα κατ’ ἐμπορίαν ἀχθέντα ἢ ἀπ’ αἰχμαλώτων γενόμενον; εἶτα τίνες ἦσαν οἱ ἐνέγκαντες τὸν χαλκὸν ὡς τὸν πατέρα τὸν ἐμόν; μισθωτοὶ ἢ οἰκέται;", "st": "49.51"}, {"sp": "N", "t": "ἢ τίς ὁ παραλαβὼν τῶν οἰκετῶν τῶν ἡμετέρων; χρῆν γὰρ αὐτόν, εἰ μὲν οἰκέται ἤνεγκαν, τοὺς κομίσαντας παραδιδόναι, εἰ δὲ μισθωτοί, τὸν ὑποδεξάμενον καὶ ἀποστησάμενον τὸν χαλκὸν τῶν οἰκετῶν τῶν ἡμετέρων, τοῦτον ἐξαιτεῖν· οὐ γὰρ δήπου ἄνευ γε σταθμοῦ ἔμελλεν οὔτε ὁ ὑποτιθέμενος ⟨παραλήψεσθαι⟩ οὔθ’ ὁ ὑποτιθεὶς τὸν χαλκὸν παραδώσειν, οὐδ’ αὖ ὁ πατὴρ ἔμελλεν αὐτὸς οὔτε οἴσειν τὸν χαλκὸν οὔτε στήσεσθαι, ἀλλ’ οἰκέται ἦσαν αὐτῷ, οἳ τὰ ἐνέχυρα τῶν δανεισμάτων παρελάμβανον.", "st": "49.52"}, {"sp": "N", "t": "θαυμάζω δ’ ἔγωγε καὶ τίνος ἕνεκ’ ἄν ποτε ὑπετίθει τὸν χαλκὸν τῷ πατρὶ τῷ ἐμῷ ὁ Βοιώτιος ναύαρχος, Φιλίππῳ ὀφείλων χιλίας δραχμάς. πότερον ὡς Φίλιππος οὐκ ἂν ἡδέως τόκον ἐλάμβανεν, εἴπερ ἀσφαλῶς ἦν αὐτῷ τὸ ἀργύριον δεδανεισμένον καὶ ἐπ’ ἐνεχύρῳ; ἢ ὡς οὐκ ἦν τῷ Φιλίππῳ ἀργύριον; ὥστε τι ἔδει τοῦ πατρὸς τοῦ ἐμοῦ δεηθῆναι δανεῖσαι τὰς χιλίας δραχμὰς τὸν Βοιώτιον ναύαρχον καὶ ἀποδοῦναι Φιλίππῳ μᾶλλον ἢ οὐ τὸν χαλκὸν ὑποθεῖναι τῷ Φιλίππῳ;", "st": "49.53"}, {"sp": "N", "t": "ἀλλ’ οὔτε ὁ χαλκὸς ὑπετέθη, ὦ ἄνδρες δικασταί, οὔτε ὁ Βοιώτιος ναύαρχος ἐδανείσατο τὰς χιλίας δραχμὰς παρὰ τοῦ πατρὸς τοῦ ἐμοῦ, ἀλλὰ Τιμόθεος οὑτοσὶ ἐν ἀπορίᾳ ὢν πολλῇ· τὴν δὲ χρείαν, εἰς ἣν κατεχρήσατο τῷ ἀργυρίῳ, εἴρηκα ὑμῖν. ἀντὶ δὲ τοῦ χάριν ἀποδοῦναι ὧν ἐπιστεύθη καὶ ἔλαβεν παρὰ τοῦ πατρὸς τοῦ ἐμοῦ, οἴεται δεῖν καὶ τὰ ἀρχαῖα, ἂν δύνηται, ἀποστερῆσαι.", "st": "49.54"}, {"sp": "N", "t": "περὶ μὲν τοίνυν τῶν φιαλῶν καὶ τῆς μνᾶς τοῦ ἀργυρίου, ἣν ἐδανείσατο παρὰ τοῦ πατρὸς πέμψας τὸν ἀκόλουθον τὸν ἑαυτοῦ Αἰσχρίωνα τῆς νυκτὸς ὡς τὸν πατέρα τὸν ἐμόν, ἠρόμην αὐτὸν πρὸς τῷ διαιτητῇ εἰ ἔτι δοῦλος εἴη ὁ Αἰσχρίων, καὶ ἠξίουν αὐτὸν ἐν τῷ δέρματι τὸν ἔλεγχον διδόναι. ἀποκριναμένου δέ μοι τούτου ὅτι ἐλεύθερος εἴη, τῆς μὲν ἐξαιτήσεως ἐπέσχον, μαρτυρίαν δ’ αὐτὸν ἠξίουν ἐμβαλέσθαι τοῦ Αἰσχρίωνος ὡς ἐλευθέρου ὄντος.", "st": "49.55"}, {"sp": "N", "t": "ὁ δὲ οὔτε ὡς ἐλευθέρου ὄντος τοῦ Αἰσχρίωνος μαρτυρίαν παρέσχετο, οὔθ’ ὡς δοῦλον τὸν Αἰσχρίωνα παραδοὺς ἐκ τοῦ σώματος τὸν ἔλεγχον ἠξίου γενέσθαι, φοβούμενος, ἐὰν μὲν μαρτυρίαν παράσχηται ὡς ἐλευθέρου ὄντος, μὴ ἐπισκηψάμενος ἐγὼ τῶν ψευδομαρτυρίων καὶ ἐξελέγξας τὰ ψευδῆ μεμαρτυρηκότα τὸν Αἰσχρίωνα ἐπὶ τόνδε τῶν κακοτεχνιῶν ἔλθοιμι κατὰ τὸν νόμον, εἰ δ’ αὖ βασανίζειν παραδώσει, μὴ τὰς ἀληθείας κατείποι ὁ Αἰσχρίων.", "st": "49.56"}, {"sp": "N", "t": "καίτοι καλὸν ἦν αὐτῷ, εἰ τῶν ἄλλων λημμάτων τοῦ ἀργυρίου μάρτυρας μὴ εἶχεν παρασχέσθαι, τοῦτό γε ἐξελέγξαι ἐκ τοῦ Αἰσχρίωνος, ὡς οὐκ ἐλήφθησαν αἱ φιάλαι οὐδ’ ἡ μνᾶ τοῦ ἀργυρίου, οὐδὲ ἐπέμφθη ὁ Αἰσχρίων ὑπὸ τούτου ὡς τὸν πατέρα τὸν ἐμόν, καὶ τεκμηρίῳ τούτῳ καταχρήσασθαι πρὸς ὑμᾶς ὅτι ἐγὼ καὶ τἄλλα ψεύδομαι περὶ ὧν ἐγκαλῶ αὐτῷ, ὅπου γε ὅν φημι λαβεῖν οἰκέτην ὄντα τούτου τὰς φιάλας καὶ τὴν μνᾶν τοῦ ἀργυρίου, οὗτος βασανιζόμενος οὐ φαίνεται λαβών.", "st": "49.57"}, {"sp": "N", "t": "εἰ τοίνυν τοῦτο ἰσχυρὸν ἦν ἂν τούτῳ πρὸς ὑμᾶς τεκμήριον ὅτι ἐξεδίδου τὸν Αἰσχρίωνα, ὃν πεμφθῆναί φημι ὑπὸ τούτου καὶ λαβεῖν τὰς φιάλας παρὰ τοῦ πατρὸς τοῦ ἐμοῦ καὶ τὴν μνᾶν τοῦ ἀργυρίου δανείσασθαι, κἀμοὶ γενέσθω τεκμήριον πρὸς ὑμᾶς ὅτι συνειδώς με ἀληθῆ ἐγκαλοῦντα οὐ τολμᾷ τὸν Αἰσχρίωνα παραδοῦναι.", "st": "49.58"}, {"sp": "N", "t": "ἀπολογίαν τοίνυν ποιήσεται ὅτι ἐν τοῖς γράμμασιν τοῖς τραπεζιτικοῖς ἐπὶ Ἀλκισθένους ἄρχοντος ἦν ἐγγεγραμμένος τό τε ναῦλον τῶν ξύλων εἰληφὼς καὶ τὴν τιμὴν τῶν φιαλῶν, ὃ ἀπέτεισεν Τιμοσθένει ὑπὲρ τούτου ὁ πατήρ, καὶ ὅτι αὐτὸς ἐν τούτῳ τῷ χρόνῳ οὐκ ἐπεδήμει, ἀλλὰ παρὰ βασιλεῖ ἦν. περὶ δὴ τούτου σαφῶς ὑμᾶς βούλομαι διδάξαι, ἵν’ ἀκριβῶς εἰδῆτε ὃν τρόπον ἔχει τὰ γράμματα τὰ ἀπὸ τῆς τραπέζης.", "st": "49.59"}, {"sp": "N", "t": "οὗτος γὰρ ἐν μὲν τῷ θαργηλιῶνι μηνὶ ἐπ’ Ἀστείου ἄρχοντος, μέλλων ἀνάγεσθαι ὡς βασιλέα, συνέστησεν τὸν Φιλώνδαν τῷ πατρὶ τῷ ἐμῷ· τοῦ δὲ ὑστέρου ἐνιαυτοῦ, ἐπὶ Ἀλκισθένους ἄρχοντος, ἀφικνεῖται ὁ Φιλώνδας ἄγων τὰ ξύλα ἐκ τῆς Μακεδονίας, καὶ ἔλαβεν τὸ ναῦλον τῶν ξύλων παρὰ τοῦ πατρὸς τοῦ ἐμοῦ, ἀποδημοῦντος τούτου παρὰ βασιλεῖ. ἐγράψαντο οὖν, ὅτε ἐδίδοσαν τὸ ἀργύριον, ὀφείλοντα τοῦτον, οὐχ ὅτε συνέστησε τὸν Φιλώνδαν τῷ πατρὶ τῷ ἐμῷ ἐπιδημῶν.", "st": "49.60"}, {"sp": "N", "t": "ὅτε μὲν γὰρ συνέστησεν, οὐδέπω τὰ ξύλα ἧκεν, ἀλλ’ ἔμελλεν ἐπ’ αὐτὰ ὁ Φιλώνδας τὴν πορείαν ποιεῖσθαι· ὅτε δὲ ἦλθεν τὰ ξύλα ἄγων, οὗτος μὲν ἀπεδήμει, ὁ δὲ Φιλώνδας ἔλαβεν τὸ ναῦλον τῶν ξύλων καθάπερ οὗτος ἐκέλευσε, καὶ ἀνεκομίσθη εἰς τὴν οἰκίαν τὴν ἐν Πειραιεῖ τὴν τούτου τὰ ξύλα. ὅτι δὲ οὐκ εὐπορῶν οὗτος ἐξέπλει ἐνθένδε, ἴστε μὲν καὶ αὐτοὶ ὅσοις αὐτοῦ ἡ οὐσία ὡρισμένη ἦν, οὓς νῦν ἀποστερεῖ· ἵνα δὲ εἰδῆτε ὅτι καὶ ἄνευ ἐνεχύρων ὤφειλέ τισι τῶν πολιτῶν, οὐκ ἔχων ὑποθεῖναι τὰ ἄξια, ἀνάγνωθί μοι τὴν μαρτυρίαν.", "st": "49.61"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "49.61"}, {"sp": "N", "t": "περὶ δὲ τῶν φιαλῶν, ἃς ᾐτήσατο μὲν ἐν τῷ μαιμακτηριῶνι μηνὶ ὁ Αἰσχρίων ὁ ἀκόλουθος ⟨ὁ⟩ τούτου ἐπ’ Ἀστείου ἄρχοντος, ἐπιδημοῦντος τούτου, ὅτε ὑπεδέξατο Ἀλκέτην καὶ Ἰάσονα, γεγραμμένου δὲ τὴν τιμὴν ὀφείλοντος τούτου ἐπὶ Ἀλκισθένους ἄρχοντος, τέως μὲν ᾤετο αὐτὸν ἀποίσειν τὰς φιάλας, ἃς ᾐτήσατο, ὁ πατήρ· ἐπειδὴ δὲ οὗτος μὲν ἀπῆλθε, τὰς δὲ φιάλας οὐκ ἀπενηνόχει, οὐδ’ ἦσαν αἱ φιάλαι τοῦ Τιμοσθένους κείμεναι παρὰ τῷ Φορμίωνι, ἥκων δ’ ἀπῄτει τὰς φιάλας ὁ θέμενος, ἀπέτεισε τιμὴν τῶν φιαλῶν τῷ Τιμοσθένει, ἐγράψατο δὲ ὁ πατὴρ αὑτῷ τοῦτον ὀφείλοντα πρὸς τὸ ἄλλο χρέως.", "st": "49.62"}, {"sp": "N", "t": "ὥστ’ ἐὰν ταύτῃ ἀπολογίᾳ καταχρῆται, ὅτι οὐκ ἐπεδήμει ἐν τοῖς χρόνοις ἐν οἷς γέγραπται τὴν τιμὴν τῶν φιαλῶν ὀφείλων, ὑποβάλλετε αὐτῷ ὅτι “ἔλαβες μὲν ἐπιδημῶν· ἐπειδὴ δὲ οὐκ ἀπέφερες, ἀπεδήμεις δέ, οὐκ ἦσαν δὲ αἱ φιάλαι ἃς ὁ θέμενος ἀπῄτει, ἐγράφης τὴν τιμὴν αὐτῶν ὀφείλων, ὃ ἀπετείσθη τῶν φιαλῶν.”", "st": "49.63"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία, φήσει ἴσως, ἔδει τὸν πατέρα τὸν ἐμὸν ἀπαιτεῖν αὐτὸν τὰς φιάλας. ἀλλ’ ἑώρα σε ὡς ἠποροῦ. κᾆτα περὶ μὲν τοῦ ἄλλου χρέως σοι ἐπίστευεν, καὶ ἡγεῖτο, ἐπειδὰν ἔλθῃς, ἀπολήψεσθαι παρὰ σοῦ εὐπορήσαντος, περὶ δὲ τῶν φιαλῶν σοι ἀπιστήσειν ἔμελλεν; καὶ ὑπέσχετο μὲν δεομένου σου τὸ ναῦλον τῶν ξύλων παρασχήσειν, ὅτε ἀνήγου πρὸς βασιλέα· ἕνεκα δὲ τῶν φιαλῶν, δυοῖν οὐσῶν, ἀπιστήσειν σοι ἔμελλε; καὶ τὸ μὲν ἄλλο χρέως σε οὐκ ἀπῄτει, ἀπορούμενον ὁρῶν, τὰς δὲ φιάλας ἔμελλεν;", "st": "49.64"}, {"sp": "N", "t": "βούλομαι τοίνυν ὑμῖν καὶ περὶ τῆς προκλήσεως τοῦ ὅρκου εἰπεῖν, ἣν ἐγὼ τοῦτον προὐκαλεσάμην καὶ οὗτος ἐμέ. ἐμβαλομένου γὰρ ἐμοῦ ὅρκον εἰς τὸν ἐχῖνον, ἠξίου οὗτος καὶ αὐτὸς ὀμόσας ἀπηλλάχθαι. ἐγὼ δ’ εἰ μὲν μὴ περιφανῶς αὐτὸν ᾔδη πολλοὺς καὶ μεγάλους ὅρκους ἐπιωρκηκότα καὶ πόλεσι καὶ ἰδιώταις, ἔδωκα ἂν αὐτῷ τόνδε τὸν ὅρκον· νῦν δέ μοι ἐδόκει, μαρτύρων μὲν ὄντων ἐμοὶ ὡς ἔλαβον τὸ ἀργύριον ἀπὸ τῆς τραπέζης οἷς οὗτος ἐκέλευσεν δοῦναι, περιφανῶν δὲ τεκμηρίων, δεινὸν εἶναι τὸν ὅρκον δοῦναι τούτῳ, ὃς οὐχ ὅπως εὐορκήσει πρόνοιαν ποιήσεται, ἀλλ’ οὐδὲ τῶν ἱερῶν αὐτῶν ἕνεκα τοῦ πλεονεκτήματος ἀπέσχηται.", "st": "49.65"}, {"sp": "N", "t": "τὰ μὲν οὖν καθ’ ἕκαστα πόλλ’ ἂν εἴη λέγειν, ὧν ἐπιώρκηκεν οὗτος ῥᾳδίως· οὓς δὲ περιφανέστατα καὶ ὑμεῖς αὐτῷ πάντες σύνιστε ὅρκους ἐπιωρκηκότι, τούτους ἀναμνήσω ὑμᾶς. ἴστε γὰρ τοῦτον ἐν τῷ δήμῳ ὀμόσαντα καὶ ἐπαρασάμενον αὑτῷ ἐξώλειαν, εἰ μὴ γράψοιτο Ἰφικράτην ξενίας, καὶ καθιερώσαντα τὴν οὐσίαν τὴν ἑαυτοῦ. ὀμόσας δὲ ταῦτα καὶ ὑποσχόμενος ἐν τῷ δήμῳ, οὐ πολλῷ χρόνῳ ὕστερον ἕνεκα τοῦ συμφέροντος αὑτῷ ἔδωκεν τῷ υἱεῖ τῷ ἐκείνου τὴν θυγατέρα.", "st": "49.66"}, {"sp": "N", "t": "ὃς οὖν οὔτε ὑμᾶς ᾐσχύνθη ἐξαπατῆσαι ὑποσχόμενος, νόμων ὄντων, ἐάν τις τὸν δῆμον ὑποσχόμενος ἐξαπατήσῃ, εἰσαγγελίαν εἶναι περὶ αὐτοῦ, οὔτε τοὺς θεοὺς ὀμόσας καὶ ἐπαρασάμενος ἑαυτῷ ἔδεισεν, οὓς ἐπιώρκησεν, πῶς οὐκ εἰκὸς ἐμὲ τούτῳ μὴ ἐθέλειν ὅρκον δοῦναι; οὔπω τοίνυν πολὺς χρόνος ἐστὶν ἐξ ὅτου ἐν τῷ δήμῳ πάλιν διωμόσατο μὴ εἶναι αὑτῷ ἐφόδια τῷ γήρᾳ ἱκανά, τοσαύτην οὐσίαν κεκτημένος· οὕτως ἄπληστος καὶ αἰσχροκερδὴς ὁ τρόπος αὐτοῦ ἐστιν.", "st": "49.67"}, {"sp": "N", "t": "ἡδέως δ’ ἂν ἔγωγε πυθοίμην ὑμῶν εἰ ὀργίζεσθε τοῖς ἀνεσκευασμένοις τῶν τραπεζιτῶν. εἰ γὰρ ἐκείνοις ὀργίζεσθε δικαίως ὅτι ἀδικοῦσιν ὑμᾶς, πῶς οὐκ εἰκός ἐστιν βοηθεῖν τοῖς μηδὲν ἀδικοῦσιν; καὶ μὴν διὰ τούτους τοὺς ἄνδρας αἱ τράπεζαι ἀνασκευάζονται, ὅταν ἀπορούμενοι μὲν δανείζωνται καὶ οἴωνται διὰ τὴν δόξαν πιστεύεσθαι δεῖν, εὐπορήσαντες δὲ μὴ ἀποδιδῶσιν, ἀλλ’ ἀποστερῶσιν.", "st": "49.68"}, {"sp": "N", "t": "ὅσων μὲν τοίνυν, ὦ ἄνδρες δικασταί, ἐδυνάμην ὑμῖν μάρτυρας παρασχέσθαι, μεμαρτυρήκασί μοι· ἔτι δὲ καὶ ἐκ τεκμηρίων δεδήλωκα ὑμῖν ὡς ὀφείλει Τιμόθεος τὸ ἀργύριον τῷ πατρὶ τῷ ἐμῷ. δέομαι οὖν ὑμῶν συνεισπρᾶξαί μοι τοὺς ὀφείλοντας, ἅ μοι ὁ πατὴρ κατέλιπεν.", "st": "49.69"}], []);})();
